pi_agent_session_methods.text:
constructor(config) {
        this.agent = config.agent;
        this.sessionManager = config.sessionManager;
        this.settingsManager = config.settingsManager;
        this._scopedModels = config.scopedModels ?? [];
        this._resourceLoader = config.resourceLoader;
        this._customTools = config.customTools ?? [];
        this._cwd = config.cwd;
        this._modelRuntime = config.modelRuntime;
        this._extensionRunnerRef = config.extensionRunnerRef;
        this._initialActiveToolNames = config.initialActiveToolNames;
        this._allowedToolNames = config.allowedToolNames ? new Set(config.allowedToolNames) : undefined;
        this._excludedToolNames = config.excludedToolNames ? new Set(config.excludedToolNames) : undefined;
        this._baseToolsOverride = config.baseToolsOverride;
        this._sessionStartEvent = config.sessionStartEvent ?? { type: "session_start", reason: "startup" };
        // Always subscribe to agent events for internal handling
        // (session persistence, extensions, auto-compaction, retry logic)
        this._unsubscribeAgent = this.agent.subscribe(this._handleAgentEvent);
        this._installAgentToolHooks();
        this._installAgentNextTurnRefresh();
        this._buildRuntime({
            activeToolNames: this._initialActiveToolNames,
            includeAllExtensionTools: true,
        });
    }

async _getRequiredRequestAuth(model) {
        let result;
        try {
            result = await this._modelRuntime.getAuth(model);
        }
        catch (error) {
            const cause = error instanceof Error ? error.cause : undefined;
            if (cause instanceof Error && cause.message === "authHeader requires a resolved API key") {
                throw new Error(formatNoApiKeyFoundMessage(model.provider));
            }
            throw error;
        }
        if (result && (result.auth.apiKey || result.auth.headers)) {
            const requestModel = result.auth.baseUrl ? { ...model, baseUrl: result.auth.baseUrl } : model;
            return {
                model: requestModel,
                apiKey: result.auth.apiKey,
                headers: withoutDeletedHeaders(result.auth.headers),
                env: result.env,
            };
        }
        const isOAuth = this._modelRuntime.isUsingOAuth(model.provider);
        if (isOAuth) {
            throw new Error(`Authentication failed for "${model.provider}". ` +
                `Credentials may have expired or network is unavailable. ` +
                `Run '/login ${model.provider}' to re-authenticate.`);
        }
        throw new Error(formatNoApiKeyFoundMessage(model.provider));
    }

async _getSummarizationRequestAuth(model) {
        if (this.agent.streamFunction === streamSimple) {
            return this._getRequiredRequestAuth(model);
        }
        try {
            const result = await this._modelRuntime.getAuth(model);
            if (!result)
                return { model };
            const requestModel = result.auth.baseUrl ? { ...model, baseUrl: result.auth.baseUrl } : model;
            return {
                model: requestModel,
                apiKey: result.auth.apiKey,
                headers: withoutDeletedHeaders(result.auth.headers),
                env: result.env,
            };
        }
        catch {
            return { model };
        }
    }

_installAgentToolHooks() {
        this.agent.beforeToolCall = async ({ toolCall, args }) => {
            const runner = this._extensionRunner;
            if (!runner.hasHandlers("tool_call")) {
                return undefined;
            }
            try {
                return await runner.emitToolCall({
                    type: "tool_call",
                    toolName: toolCall.name,
                    toolCallId: toolCall.id,
                    input: args,
                });
            }
            catch (err) {
                if (err instanceof Error) {
                    throw err;
                }
                throw new Error(`Extension failed, blocking execution: ${String(err)}`);
            }
        };
        this.agent.afterToolCall = async ({ toolCall, args, result, isError }) => {
            const runner = this._extensionRunner;
            const hookResult = runner.hasHandlers("tool_result")
                ? await runner.emitToolResult({
                    type: "tool_result",
                    toolName: toolCall.name,
                    toolCallId: toolCall.id,
                    input: args,
                    content: result.content,
                    details: result.details,
                    isError,
                    usage: result.usage,
                })
                : undefined;
            const content = hookResult?.content ?? result.content ?? [];
            // Runs after the extension hook so images injected or replaced by extensions are normalized too.
            const normalizedContent = await normalizeToolResultImages(content, {
                autoResizeImages: this.settingsManager.getImageAutoResize(),
            });
            if (!hookResult && normalizedContent === content) {
                return undefined;
            }
            return {
                content: normalizedContent,
                details: hookResult?.details,
                isError: hookResult?.isError ?? isError,
                usage: hookResult?.usage,
            };
        };
    }

async _compactBeforeNextAssistantResponse(context) {
        const model = this.model;
        const settings = this.settingsManager.getCompactionSettings();
        if (!model ||
            model.contextWindow <= 0 ||
            !shouldCompact(estimateContextTokens(context.messages).tokens, model.contextWindow, settings)) {
            return context;
        }
        await this._runAutoCompaction("threshold", false);
        return {
            ...context,
            messages: this.agent.state.messages.slice(),
        };
    }

_installAgentNextTurnRefresh() {
        const previousPrepareNextTurnWithContext = this.agent.prepareNextTurnWithContext ??
            (this.agent.prepareNextTurn
                ? async (_turn, signal) => await this.agent.prepareNextTurn?.(signal)
                : undefined);
        this.agent.prepareNextTurnWithContext = async (turn, signal) => {
            const context = await this._compactBeforeNextAssistantResponse(turn.context);
            const previousSnapshot = await previousPrepareNextTurnWithContext?.({ ...turn, context }, signal);
            const nextContext = previousSnapshot?.context ?? context;
            return {
                ...previousSnapshot,
                context: {
                    ...nextContext,
                    systemPrompt: this._systemPromptOverride ?? this._baseSystemPrompt,
                    tools: this.agent.state.tools.slice(),
                },
                model: this.agent.state.model,
                thinkingLevel: this.agent.state.thinkingLevel,
            };
        };
    }

_getIdleWaitPromise() {
        if (!this._idleWaitPromise) {
            this._idleWaitPromise = new Promise((resolve) => {
                this._resolveIdleWait = resolve;
            });
        }
        return this._idleWaitPromise;
    }

_resolveIdleWaitIfIdle() {
        if (!this.isIdle || !this._resolveIdleWait) {
            return;
        }
        const resolve = this._resolveIdleWait;
        this._idleWaitPromise = undefined;
        this._resolveIdleWait = undefined;
        resolve();
    }

async _emitAgentSettled() {
        this._isAgentRunActive = false;
        try {
            await this._extensionRunner.emit({ type: "agent_settled" });
            this._emit({ type: "agent_settled" });
        }
        finally {
            this._resolveIdleWaitIfIdle();
        }
    }

_handleAgentEvent = async (event) => {
        // When a user message starts, check if it's from either queue and remove it BEFORE emitting
        // This ensures the UI sees the updated queue state
        if (event.type === "message_start" && event.message.role === "user") {
            this._overflowRecoveryAttempted = false;
            const messageText = contentText(event.message.content, "");
            if (messageText) {
                // Check steering queue first
                const steeringIndex = this._steeringMessages.indexOf(messageText);
                if (steeringIndex !== -1) {
                    this._steeringMessages.splice(steeringIndex, 1);
                    this._emitQueueUpdate();
                }
                else {
                    // Check follow-up queue
                    const followUpIndex = this._followUpMessages.indexOf(messageText);
                    if (followUpIndex !== -1) {
                        this._followUpMessages.splice(followUpIndex, 1);
                        this._emitQueueUpdate();
                    }
                }
            }
        }
        // Emit to extensions first
        await this._emitExtensionEvent(event);
        // Notify all listeners
        this._emit(event.type === "agent_end" ? { ...event, willRetry: this._willRetryAfterAgentEnd(event) } : event);
        // Handle session persistence
        if (event.type === "message_end") {
            // Check if this is a custom message from extensions
            if (event.message.role === "custom") {
                // Persist as CustomMessageEntry
                this.sessionManager.appendCustomMessageEntry(event.message.customType, event.message.content, event.message.display, event.message.details);
            }
            else if (event.message.role === "user" ||
                event.message.role === "assistant" ||
                event.message.role === "toolResult") {
                // Regular LLM message - persist as SessionMessageEntry
                this.sessionManager.appendMessage(event.message);
            }
            // Other message types (bashExecution, compactionSummary, branchSummary) are persisted elsewhere
            // Track assistant message for auto-compaction (checked on agent_end)
            if (event.message.role === "assistant") {
                this._lastAssistantMessage = event.message;
                const assistantMsg = event.message;
                if (assistantMsg.stopReason !== "error" && assistantMsg.stopReason !== "length") {
                    this._overflowRecoveryAttempted = false;
                }
                // Reset retry counter immediately on successful assistant response
                // This prevents accumulation across multiple LLM calls within a turn
                if (assistantMsg.stopReason !== "error" && this._retryAttempt > 0) {
                    this._emit({
                        type: "auto_retry_end",
                        success: true,
                        attempt: this._retryAttempt,
                    });
                    this._retryAttempt = 0;
                }
            }
        }
        // A turn ends after its assistant message and every tool result has been appended,
        // so this is the first point in the run where a context-only custom message can be
        // inserted without landing between a tool call and its result. Flushing after the
        // extension and listener dispatch above also picks up messages that turn_end
        // handlers queued.
        if (event.type === "turn_end") {
            this._flushPendingCustomMessages();
        }
    };

_willRetryAfterAgentEnd(event) {
        const settings = this.settingsManager.getRetrySettings();
        if (!settings.enabled || this._retryAttempt >= settings.maxRetries) {
            return false;
        }
        for (let i = event.messages.length - 1; i >= 0; i--) {
            const message = event.messages[i];
            if (message.role === "assistant") {
                return this._isRetryableError(message);
            }
        }
        return false;
    }

_findLastAssistantMessage() {
        const messages = this.agent.state.messages;
        for (let i = messages.length - 1; i >= 0; i--) {
            const msg = messages[i];
            if (msg.role === "assistant") {
                return msg;
            }
        }
        return undefined;
    }

_replaceMessageInPlace(target, replacement) {
        // Agent-core stores the finalized message object in its state before emitting message_end.
        // SessionManager persistence happens later in _handleAgentEvent() with event.message.
        // Mutating this object in place keeps agent state, later turn/agent events, listeners,
        // and the eventual SessionManager.appendMessage(event.message) persistence in sync.
        if (target === replacement) {
            return;
        }
        const targetRecord = target;
        for (const key of Object.keys(targetRecord)) {
            delete targetRecord[key];
        }
        Object.assign(targetRecord, replacement);
    }

async _emitExtensionEvent(event) {
        if (event.type === "agent_start") {
            this._turnIndex = 0;
            await this._extensionRunner.emit({ type: "agent_start" });
        }
        else if (event.type === "agent_end") {
            await this._extensionRunner.emit({ type: "agent_end", messages: event.messages });
        }
        else if (event.type === "turn_start") {
            const extensionEvent = {
                type: "turn_start",
                turnIndex: this._turnIndex,
                timestamp: Date.now(),
            };
            await this._extensionRunner.emit(extensionEvent);
        }
        else if (event.type === "turn_end") {
            const extensionEvent = {
                type: "turn_end",
                turnIndex: this._turnIndex,
                message: event.message,
                toolResults: event.toolResults,
            };
            await this._extensionRunner.emit(extensionEvent);
            this._turnIndex++;
        }
        else if (event.type === "message_start") {
            const extensionEvent = {
                type: "message_start",
                message: event.message,
            };
            await this._extensionRunner.emit(extensionEvent);
        }
        else if (event.type === "message_update") {
            const extensionEvent = {
                type: "message_update",
                message: event.message,
                assistantMessageEvent: event.assistantMessageEvent,
            };
            await this._extensionRunner.emit(extensionEvent);
        }
        else if (event.type === "message_end") {
            const extensionEvent = {
                type: "message_end",
                message: event.message,
            };
            const replacement = await this._extensionRunner.emitMessageEnd(extensionEvent);
            if (replacement) {
                // Untyped extension handlers can return messages with null/missing content;
                // normalize so it never enters agent state or session history.
                const normalized = (replacement.role === "user" ||
                    replacement.role === "assistant" ||
                    replacement.role === "toolResult" ||
                    replacement.role === "custom") &&
                    replacement.content == null
                    ? { ...replacement, content: [] }
                    : replacement;
                this._replaceMessageInPlace(event.message, normalized);
            }
        }
        else if (event.type === "tool_execution_start") {
            const extensionEvent = {
                type: "tool_execution_start",
                toolCallId: event.toolCallId,
                toolName: event.toolName,
                args: event.args,
            };
            await this._extensionRunner.emit(extensionEvent);
        }
        else if (event.type === "tool_execution_update") {
            const extensionEvent = {
                type: "tool_execution_update",
                toolCallId: event.toolCallId,
                toolName: event.toolName,
                args: event.args,
                partialResult: event.partialResult,
            };
            await this._extensionRunner.emit(extensionEvent);
        }
        else if (event.type === "tool_execution_end") {
            const extensionEvent = {
                type: "tool_execution_end",
                toolCallId: event.toolCallId,
                toolName: event.toolName,
                result: event.result,
                isError: event.isError,
            };
            await this._extensionRunner.emit(extensionEvent);
        }
    }

subscribe(listener) {
        this._eventListeners.push(listener);
        // Return unsubscribe function for this specific listener
        return () => {
            const index = this._eventListeners.indexOf(listener);
            if (index !== -1) {
                this._eventListeners.splice(index, 1);
            }
        };
    }

dispose() {
        try {
            this.abortRetry();
            this.abortCompaction();
            this.abortBranchSummary();
            this.abortBash();
            this.agent.abort();
        }
        catch {
            // Dispose must succeed even if an abort hook throws.
        }
        this._extensionRunner.invalidate("This extension ctx is stale after session replacement or reload. Do not use a captured pi or command ctx after ctx.newSession(), ctx.fork(), ctx.switchSession(), or ctx.reload(). For newSession, fork, and switchSession, move post-replacement work into withSession and use the ctx passed to withSession. For reload, do not use the old ctx after await ctx.reload().");
        this._disconnectFromAgent();
        this._eventListeners = [];
        cleanupSessionResources(this.sessionId);
    }

getAllTools() {
        return Array.from(this._toolDefinitions.values()).map(({ definition, sourceInfo }) => ({
            name: definition.name,
            description: definition.description,
            parameters: definition.parameters,
            promptGuidelines: definition.promptGuidelines,
            sourceInfo,
        }));
    }

setActiveToolsByName(toolNames) {
        const tools = [];
        const validToolNames = [];
        for (const name of toolNames) {
            const tool = this._toolRegistry.get(name);
            if (tool) {
                tools.push(tool);
                validToolNames.push(name);
            }
        }
        this.agent.state.tools = tools;
        // Rebuild base system prompt with new tool set
        this._baseSystemPrompt = this._rebuildSystemPrompt(validToolNames);
        this.agent.state.systemPrompt = this._systemPromptOverride ?? this._baseSystemPrompt;
    }

get isCompacting() {
        return (this._autoCompactionAbortController !== undefined ||
            this._compactionAbortController !== undefined ||
            this._branchSummaryAbortController !== undefined);
    }

_normalizePromptSnippet(text) {
        if (!text)
            return undefined;
        const oneLine = text
            .replace(/[\r\n]+/g, " ")
            .replace(/\s+/g, " ")
            .trim();
        return oneLine.length > 0 ? oneLine : undefined;
    }

_normalizePromptGuidelines(guidelines) {
        if (!guidelines || guidelines.length === 0) {
            return [];
        }
        const unique = new Set();
        for (const guideline of guidelines) {
            const normalized = guideline.trim();
            if (normalized.length > 0) {
                unique.add(normalized);
            }
        }
        return Array.from(unique);
    }

_rebuildSystemPrompt(toolNames) {
        const validToolNames = toolNames.filter((name) => this._toolRegistry.has(name));
        const toolSnippets = {};
        const promptGuidelines = [];
        for (const name of validToolNames) {
            const snippet = this._toolPromptSnippets.get(name);
            if (snippet) {
                toolSnippets[name] = snippet;
            }
            const toolGuidelines = this._toolPromptGuidelines.get(name);
            if (toolGuidelines) {
                promptGuidelines.push(...toolGuidelines);
            }
        }
        const loaderSystemPrompt = this._resourceLoader.getSystemPrompt();
        const loaderAppendSystemPrompt = this._resourceLoader.getAppendSystemPrompt();
        const appendSystemPrompt = loaderAppendSystemPrompt.length > 0 ? loaderAppendSystemPrompt.join("\n\n") : undefined;
        const loadedSkills = this._resourceLoader.getSkills().skills;
        const loadedContextFiles = this._resourceLoader.getAgentsFiles().agentsFiles;
        this._baseSystemPromptOptions = {
            cwd: this._cwd,
            skills: loadedSkills,
            contextFiles: loadedContextFiles,
            customPrompt: loaderSystemPrompt,
            appendSystemPrompt,
            selectedTools: validToolNames,
            toolSnippets,
            promptGuidelines,
        };
        return buildSystemPrompt(this._baseSystemPromptOptions);
    }

async _runAgentPrompt(messages) {
        this._isAgentRunActive = true;
        try {
            await this.agent.prompt(messages);
            while (await this._handlePostAgentRun()) {
                await this.agent.continue();
            }
        }
        finally {
            this._systemPromptOverride = undefined;
            this._flushPendingBashMessages();
            this._flushPendingCustomMessages();
            await this._emitAgentSettled();
        }
    }

async _handlePostAgentRun() {
        const msg = this._lastAssistantMessage;
        this._lastAssistantMessage = undefined;
        if (!msg) {
            return false;
        }
        if (this._isRetryableError(msg) && (await this._prepareRetry(msg))) {
            return true;
        }
        if (msg.stopReason === "error" && this._retryAttempt > 0) {
            this._emit({
                type: "auto_retry_end",
                success: false,
                attempt: this._retryAttempt,
                finalError: msg.errorMessage,
            });
            this._retryAttempt = 0;
        }
        if (await this._checkCompaction(msg)) {
            return true;
        }
        // The agent loop drains both queues before emitting agent_end. Any messages
        // here were queued by agent_end extension handlers and need a continuation.
        return this.agent.hasQueuedMessages();
    }

async prompt(text, options) {
        const expandPromptTemplates = options?.expandPromptTemplates ?? true;
        const preflightResult = options?.preflightResult;
        let messages;
        try {
            // Handle extension commands first (execute immediately, even during streaming)
            // Extension commands manage their own LLM interaction via pi.sendMessage()
            if (expandPromptTemplates && text.startsWith("/")) {
                const handled = await this._tryExecuteExtensionCommand(text);
                if (handled) {
                    // Extension command executed, no prompt to send
                    preflightResult?.(true);
                    return;
                }
            }
            if (this._compactionAbortController !== undefined) {
                throw new Error("Cannot submit a prompt while compaction is in progress. Wait for compaction to finish and retry.");
            }
            // Emit input event for extension interception (before skill/template expansion)
            let currentText = text;
            let currentImages = options?.images;
            if (this._extensionRunner.hasHandlers("input")) {
                const inputResult = await this._extensionRunner.emitInput(currentText, currentImages, options?.source ?? "interactive", this.isStreaming ? options?.streamingBehavior : undefined);
                if (inputResult.action === "handled") {
                    preflightResult?.(true);
                    return;
                }
                if (inputResult.action === "transform") {
                    currentText = inputResult.text;
                    currentImages = inputResult.images ?? currentImages;
                }
            }
            // Expand skill commands (/skill:name args) and prompt templates (/template args)
            let expandedText = currentText;
            if (expandPromptTemplates) {
                expandedText = this._expandSkillCommand(expandedText);
                expandedText = expandPromptTemplate(expandedText, [...this.promptTemplates]);
            }
            // If streaming, queue via steer() or followUp() based on option
            if (this.isStreaming) {
                if (!options?.streamingBehavior) {
                    throw new Error("Agent is already processing. Specify streamingBehavior ('steer' or 'followUp') to queue the message.");
                }
                if (options.streamingBehavior === "followUp") {
                    await this._queueFollowUp(expandedText, currentImages);
                }
                else {
                    await this._queueSteer(expandedText, currentImages);
                }
                preflightResult?.(true);
                return;
            }
            // Flush any pending bash and custom messages before the new prompt
            this._flushPendingBashMessages();
            this._flushPendingCustomMessages();
            // Validate model
            if (!this.model) {
                throw new Error(formatNoModelSelectedMessage());
            }
            const hasConfiguredAuth = this._modelRuntime.hasConfiguredAuth(this.model.provider) ||
                (await this._modelRuntime.checkAuth(this.model.provider)) !== undefined;
            if (!hasConfiguredAuth) {
                const isOAuth = this._modelRuntime.isUsingOAuth(this.model.provider);
                if (isOAuth) {
                    throw new Error(`Authentication failed for "${this.model.provider}". ` +
                        `Credentials may have expired or network is unavailable. ` +
                        `Run '/login ${this.model.provider}' to re-authenticate.`);
                }
                throw new Error(formatNoApiKeyFoundMessage(this.model.provider));
            }
            // Check if we need to compact before sending (catches aborted responses).
            // The user's new prompt is sent below, so do not call agent.continue() here.
            const lastAssistant = this._findLastAssistantMessage();
            if (lastAssistant) {
                await this._checkCompaction(lastAssistant, false);
            }
            // Build messages array (custom message if any, then user message)
            messages = [];
            // Add user message
            const userContent = [{ type: "text", text: expandedText }];
            if (currentImages) {
                userContent.push(...currentImages);
            }
            messages.push({
                role: "user",
                content: userContent,
                timestamp: Date.now(),
            });
            // Inject any pending "nextTurn" messages as context alongside the user message
            for (const msg of this._pendingNextTurnMessages) {
                messages.push(msg);
            }
            this._pendingNextTurnMessages = [];
            // Emit before_agent_start extension event
            const result = await this._extensionRunner.emitBeforeAgentStart(expandedText, currentImages, this._baseSystemPrompt, this._baseSystemPromptOptions);
            // Add all custom messages from extensions
            if (result?.messages) {
                for (const msg of result.messages) {
                    messages.push({
                        role: "custom",
                        customType: msg.customType,
                        // Untyped extensions can pass null/missing content; normalize at ingestion.
                        content: msg.content ?? [],
                        display: msg.display,
                        details: msg.details,
                        timestamp: Date.now(),
                    });
                }
            }
            // Apply extension-modified system prompt, or reset to base
            if (result?.systemPrompt !== undefined) {
                this._systemPromptOverride = result.systemPrompt;
                this.agent.state.systemPrompt = result.systemPrompt;
            }
            else {
                // Ensure we're using the base prompt (in case previous turn had modifications)
                this._systemPromptOverride = undefined;
                this.agent.state.systemPrompt = this._baseSystemPrompt;
            }
        }
        catch (error) {
            preflightResult?.(false);
            throw error;
        }
        if (!messages) {
            return;
        }
        preflightResult?.(true);
        await this._runAgentPrompt(messages);
    }

async _tryExecuteExtensionCommand(text) {
        // Parse command name and args
        const spaceIndex = text.indexOf(" ");
        const commandName = spaceIndex === -1 ? text.slice(1) : text.slice(1, spaceIndex);
        const args = spaceIndex === -1 ? "" : text.slice(spaceIndex + 1);
        const command = this._extensionRunner.getCommand(commandName);
        if (!command)
            return false;
        // Get command context from extension runner (includes session control methods)
        const ctx = this._extensionRunner.createCommandContext();
        try {
            await command.handler(args, ctx);
            return true;
        }
        catch (err) {
            // Emit error via extension runner
            this._extensionRunner.emitError({
                extensionPath: `command:${commandName}`,
                event: "command",
                error: err instanceof Error ? err.message : String(err),
            });
            return true;
        }
    }

_expandSkillCommand(text) {
        if (!text.startsWith("/skill:"))
            return text;
        const spaceIndex = text.indexOf(" ");
        const skillName = spaceIndex === -1 ? text.slice(7) : text.slice(7, spaceIndex);
        const args = spaceIndex === -1 ? "" : text.slice(spaceIndex + 1).trim();
        const skill = this.resourceLoader.getSkills().skills.find((s) => s.name === skillName);
        if (!skill)
            return text; // Unknown skill, pass through
        try {
            const content = readFileSync(skill.filePath, "utf-8");
            const body = stripFrontmatter(content).trim();
            const skillBlock = `<skill name="${skill.name}" location="${skill.filePath}">\nReferences are relative to ${skill.baseDir}.\n\n${body}\n</skill>`;
            return args ? `${skillBlock}\n\n${args}` : skillBlock;
        }
        catch (err) {
            // Emit error like extension commands do
            this._extensionRunner.emitError({
                extensionPath: skill.filePath,
                event: "skill_expansion",
                error: err instanceof Error ? err.message : String(err),
            });
            return text; // Return original on error
        }
    }

async steer(text, images) {
        // Check for extension commands (cannot be queued)
        if (text.startsWith("/")) {
            this._throwIfExtensionCommand(text);
        }
        // Expand skill commands and prompt templates
        let expandedText = this._expandSkillCommand(text);
        expandedText = expandPromptTemplate(expandedText, [...this.promptTemplates]);
        await this._queueSteer(expandedText, images);
    }

async followUp(text, images) {
        // Check for extension commands (cannot be queued)
        if (text.startsWith("/")) {
            this._throwIfExtensionCommand(text);
        }
        // Expand skill commands and prompt templates
        let expandedText = this._expandSkillCommand(text);
        expandedText = expandPromptTemplate(expandedText, [...this.promptTemplates]);
        await this._queueFollowUp(expandedText, images);
    }

async _queueSteer(text, images) {
        this._steeringMessages.push(text);
        this._emitQueueUpdate();
        const content = [{ type: "text", text }];
        if (images) {
            content.push(...images);
        }
        this.agent.steer({
            role: "user",
            content,
            timestamp: Date.now(),
        });
    }

async _queueFollowUp(text, images) {
        this._followUpMessages.push(text);
        this._emitQueueUpdate();
        const content = [{ type: "text", text }];
        if (images) {
            content.push(...images);
        }
        this.agent.followUp({
            role: "user",
            content,
            timestamp: Date.now(),
        });
    }

_throwIfExtensionCommand(text) {
        const spaceIndex = text.indexOf(" ");
        const commandName = spaceIndex === -1 ? text.slice(1) : text.slice(1, spaceIndex);
        const command = this._extensionRunner.getCommand(commandName);
        if (command) {
            throw new Error(`Extension command "/${commandName}" cannot be queued. Use prompt() or execute the command when not streaming.`);
        }
    }

async sendCustomMessage(message, options) {
        const appMessage = {
            role: "custom",
            customType: message.customType,
            // Untyped extensions can pass null/missing content; normalize at ingestion.
            content: message.content ?? [],
            display: message.display,
            details: message.details,
            timestamp: Date.now(),
        };
        if (options?.deliverAs === "nextTurn") {
            this._pendingNextTurnMessages.push(appMessage);
        }
        else if (this.isStreaming && options?.triggerTurn !== false) {
            if (options?.deliverAs === "followUp") {
                this.agent.followUp(appMessage);
            }
            else {
                this.agent.steer(appMessage);
            }
        }
        else if (options?.triggerTurn) {
            await this._runAgentPrompt(appMessage);
        }
        else if (this.isStreaming) {
            // Appending now would put the message between an assistant tool call and its
            // result, which providers that validate message order reject on replay. Defer
            // to the end of the turn. Nothing is emitted yet: message events must not
            // describe messages the session tree does not contain.
            this._pendingCustomMessages.push(appMessage);
        }
        else {
            this._appendCustomMessage(appMessage);
        }
    }

_appendCustomMessage(appMessage) {
        this.agent.state.messages.push(appMessage);
        this.sessionManager.appendCustomMessageEntry(appMessage.customType, appMessage.content, appMessage.display, appMessage.details);
        this._emit({ type: "message_start", message: appMessage });
        this._emit({ type: "message_end", message: appMessage });
    }

_flushPendingCustomMessages() {
        if (this._pendingCustomMessages.length === 0)
            return;
        const pending = this._pendingCustomMessages;
        this._pendingCustomMessages = [];
        for (const appMessage of pending) {
            this._appendCustomMessage(appMessage);
        }
    }

async sendUserMessage(content, options) {
        // Normalize content to text string + optional images
        let text;
        let images;
        if (typeof content === "string") {
            text = content;
        }
        else {
            const textParts = [];
            images = [];
            for (const part of content) {
                if (part.type === "text") {
                    textParts.push(part.text);
                }
                else {
                    images.push(part);
                }
            }
            text = textParts.join("\n");
            if (images.length === 0)
                images = undefined;
        }
        await this.prompt(text, {
            expandPromptTemplates: options?.expandPromptTemplates ?? false,
            streamingBehavior: options?.deliverAs,
            images,
            source: "extension",
        });
    }

clearQueue() {
        const steering = [...this._steeringMessages];
        const followUp = [...this._followUpMessages];
        this._steeringMessages = [];
        this._followUpMessages = [];
        this.agent.clearAllQueues();
        this._emitQueueUpdate();
        return { steering, followUp };
    }

async abort() {
        this.abortRetry();
        this.abortCompaction();
        this.abortBranchSummary();
        this.agent.abort();
        await this.waitForIdle();
    }

async waitForIdle() {
        if (this.isIdle) {
            return;
        }
        await this._getIdleWaitPromise();
    }

async _emitModelSelect(nextModel, previousModel, source) {
        if (modelsAreEqual(previousModel, nextModel))
            return;
        await this._extensionRunner.emit({
            type: "model_select",
            model: nextModel,
            previousModel,
            source,
        });
    }

async setModel(model, options = {}) {
        if (!(await this._modelRuntime.checkAuth(model.provider))) {
            throw new Error(`No API key for ${model.provider}/${model.id}`);
        }
        const previousModel = this.model;
        const thinkingLevel = this._getThinkingLevelForModelSwitch(model);
        this.agent.state.model = model;
        this.sessionManager.appendModelChange(model.provider, model.id);
        if (options.persist) {
            this.settingsManager.setDefaultModelAndProvider(model.provider, model.id);
            this._addPersistedDefaultToNonEmptyScope(model);
        }
        // Apply thinking level for the new model.
        // Per-model thinking level overrides take priority over the global default.
        // Model persistence does not implicitly rewrite the global thinking default.
        this.setThinkingLevel(thinkingLevel);
        await this._emitModelSelect(model, previousModel, "set");
    }

_addPersistedDefaultToNonEmptyScope(model) {
        if (this._scopedModels.length === 0)
            return;
        if (this._scopedModels.some((scoped) => modelsAreEqual(scoped.model, model)))
            return;
        this._scopedModels = [...this._scopedModels, { model }];
        const enabledModels = this.settingsManager.getEnabledModels();
        if (!enabledModels?.length)
            return;
        const modelReference = `${model.provider}/${model.id}`;
        if (enabledModels.some((pattern) => pattern.toLowerCase() === modelReference.toLowerCase()))
            return;
        this.settingsManager.setEnabledModels([...enabledModels, modelReference]);
    }

async cycleModel(direction = "forward", options = {}) {
        if (this._scopedModels.length > 0) {
            return this._cycleScopedModel(direction, options);
        }
        return this._cycleAvailableModel(direction, options);
    }

async _cycleScopedModel(direction, options) {
        const availableIds = new Set(this._modelRuntime.getAvailableSnapshot().map((model) => `${model.provider}\0${model.id}`));
        const scopedModels = this._scopedModels.filter((scoped) => availableIds.has(`${scoped.model.provider}\0${scoped.model.id}`));
        if (scopedModels.length <= 1)
            return undefined;
        const currentModel = this.model;
        let currentIndex = scopedModels.findIndex((sm) => modelsAreEqual(sm.model, currentModel));
        if (currentIndex === -1)
            currentIndex = 0;
        const len = scopedModels.length;
        const nextIndex = direction === "forward" ? (currentIndex + 1) % len : (currentIndex - 1 + len) % len;
        const next = scopedModels[nextIndex];
        const thinkingLevel = this._getThinkingLevelForModelSwitch(next.model, next.thinkingLevel);
        // Apply model
        this.agent.state.model = next.model;
        this.sessionManager.appendModelChange(next.model.provider, next.model.id);
        if (options.persist) {
            this.settingsManager.setDefaultModelAndProvider(next.model.provider, next.model.id);
            this._addPersistedDefaultToNonEmptyScope(next.model);
        }
        // Apply thinking level for the new model.
        // - Explicit scoped model thinking level overrides defaults
        // - Per-model thinking level overrides take priority over the global default
        // setThinkingLevel clamps to model capabilities.
        // Model persistence does not implicitly rewrite the global thinking default.
        this.setThinkingLevel(thinkingLevel);
        await this._emitModelSelect(next.model, currentModel, "cycle");
        return { model: next.model, thinkingLevel: this.thinkingLevel, isScoped: true };
    }

async _cycleAvailableModel(direction, options) {
        const availableModels = this._modelRuntime.getAvailableSnapshot();
        if (availableModels.length <= 1)
            return undefined;
        const currentModel = this.model;
        let currentIndex = availableModels.findIndex((m) => modelsAreEqual(m, currentModel));
        if (currentIndex === -1)
            currentIndex = 0;
        const len = availableModels.length;
        const nextIndex = direction === "forward" ? (currentIndex + 1) % len : (currentIndex - 1 + len) % len;
        const nextModel = availableModels[nextIndex];
        const thinkingLevel = this._getThinkingLevelForModelSwitch(nextModel);
        this.agent.state.model = nextModel;
        this.sessionManager.appendModelChange(nextModel.provider, nextModel.id);
        if (options.persist) {
            this.settingsManager.setDefaultModelAndProvider(nextModel.provider, nextModel.id);
            this._addPersistedDefaultToNonEmptyScope(nextModel);
        }
        // Apply thinking level for the new model.
        // Model persistence does not implicitly rewrite the global thinking default.
        this.setThinkingLevel(thinkingLevel);
        await this._emitModelSelect(nextModel, currentModel, "cycle");
        return { model: nextModel, thinkingLevel: this.thinkingLevel, isScoped: false };
    }

setThinkingLevel(level, options = {}) {
        const availableLevels = this.getAvailableThinkingLevels();
        const effectiveLevel = availableLevels.includes(level) ? level : this._clampThinkingLevel(level, availableLevels);
        // Only persist if actually changing
        const previousLevel = this.agent.state.thinkingLevel;
        const isChanging = effectiveLevel !== previousLevel;
        this.agent.state.thinkingLevel = effectiveLevel;
        if (options.persist) {
            this.settingsManager.setDefaultThinkingLevel(level);
        }
        if (isChanging) {
            this.sessionManager.appendThinkingLevelChange(effectiveLevel);
            this._emit({ type: "thinking_level_changed", level: effectiveLevel });
            void this._extensionRunner.emit({
                type: "thinking_level_select",
                level: effectiveLevel,
                previousLevel,
            });
        }
    }

cycleThinkingLevel(options = {}) {
        if (!this.supportsThinking())
            return undefined;
        const levels = this.getAvailableThinkingLevels();
        const currentIndex = levels.indexOf(this.thinkingLevel);
        const nextIndex = (currentIndex + 1) % levels.length;
        const nextLevel = levels[nextIndex];
        this.setThinkingLevel(nextLevel, options);
        return nextLevel;
    }

_getThinkingLevelForModelSwitch(targetModel, explicitLevel) {
        if (explicitLevel !== undefined) {
            return explicitLevel;
        }
        // Per-model default takes priority when switching to a model that has one
        if (targetModel) {
            const perModel = this.settingsManager.getModelThinkingLevel(targetModel.provider, targetModel.id);
            if (perModel !== undefined) {
                return perModel;
            }
        }
        return this.settingsManager.getDefaultThinkingLevel() ?? this.thinkingLevel ?? DEFAULT_THINKING_LEVEL;
    }

async _runDefaultCompaction(preparation, requestModel, apiKey, headers, customInstructions, signal, env, reason) {
        return compact(preparation, requestModel, apiKey, headers, customInstructions, signal, this.thinkingLevel, this.agent.streamFunction, env, this.settingsManager.getRetrySettings(), this._summarizationRetryCallbacks({ source: "compaction", reason }), undefined);
    }

async compact(customInstructions) {
        await this.abort();
        this._compactionAbortController = new AbortController();
        this._emit({ type: "compaction_start", reason: "manual" });
        let fromExtension = false;
        try {
            if (!this.model) {
                throw new Error(formatNoModelSelectedMessage());
            }
            const { model: requestModel, apiKey, headers, env } = await this._getSummarizationRequestAuth(this.model);
            const pathEntries = this.sessionManager.getBranch();
            const settings = this.settingsManager.getCompactionSettings();
            const preparation = prepareCompaction(pathEntries, settings);
            if (!preparation) {
                // Check why we can't compact
                const lastEntry = pathEntries[pathEntries.length - 1];
                if (lastEntry?.type === "compaction") {
                    throw new Error("Already compacted");
                }
                throw new Error("Nothing to compact (session too small)");
            }
            let extensionCompaction;
            if (this._extensionRunner.hasHandlers("session_before_compact")) {
                const result = (await this._extensionRunner.emit({
                    type: "session_before_compact",
                    preparation,
                    branchEntries: pathEntries,
                    customInstructions,
                    reason: "manual",
                    willRetry: false,
                    signal: this._compactionAbortController.signal,
                }));
                if (result?.cancel) {
                    throw new Error("Compaction cancelled");
                }
                if (result?.compaction) {
                    extensionCompaction = result.compaction;
                    fromExtension = true;
                }
            }
            let summary;
            let firstKeptEntryId;
            let tokensBefore;
            let usage;
            let details;
            if (extensionCompaction) {
                // Extension provided compaction content
                summary = extensionCompaction.summary;
                firstKeptEntryId = extensionCompaction.firstKeptEntryId;
                tokensBefore = extensionCompaction.tokensBefore;
                usage = extensionCompaction.usage;
                details = extensionCompaction.details;
            }
            else {
                // Shared default summary generator, also used by automatic compaction.
                const result = await this._runDefaultCompaction(preparation, requestModel, apiKey, headers, customInstructions, this._compactionAbortController.signal, env, "manual");
                summary = result.summary;
                firstKeptEntryId = result.firstKeptEntryId;
                tokensBefore = result.tokensBefore;
                usage = result.usage;
                details = result.details;
            }
            if (this._compactionAbortController.signal.aborted) {
                throw new Error("Compaction cancelled");
            }
            this.sessionManager.appendCompaction(summary, firstKeptEntryId, tokensBefore, details, fromExtension, usage);
            const newEntries = this.sessionManager.getEntries();
            const sessionContext = this.sessionManager.buildSessionContext();
            this.agent.state.messages = sessionContext.messages;
            const estimatedTokensAfter = estimateMessagesTokens(sessionContext.messages);
            // Get the saved compaction entry for the extension event
            const savedCompactionEntry = newEntries.find((e) => e.type === "compaction" && e.summary === summary);
            if (this._extensionRunner && savedCompactionEntry) {
                await this._extensionRunner.emit({
                    type: "session_compact",
                    compactionEntry: savedCompactionEntry,
                    fromExtension,
                    reason: "manual",
                    willRetry: false,
                });
            }
            const compactionResult = {
                summary,
                firstKeptEntryId,
                tokensBefore,
                estimatedTokensAfter,
                usage,
                details,
            };
            // compaction_end listeners may submit queued prompts, so expose idle state before notifying them.
            this._clearManualCompactionState();
            this._emit({
                type: "compaction_end",
                reason: "manual",
                result: compactionResult,
                aborted: false,
                willRetry: false,
            });
            return compactionResult;
        }
        catch (error) {
            const message = error instanceof Error ? error.message : String(error);
            const aborted = message === "Compaction cancelled" || (error instanceof Error && error.name === "AbortError");
            const errorMessage = aborted ? undefined : `Compaction failed: ${message}`;
            this._clearManualCompactionState();
            this._emit({
                type: "compaction_end",
                reason: "manual",
                result: undefined,
                aborted,
                willRetry: false,
                errorMessage,
            });
            await this._emitSessionCompactFailed({
                reason: "manual",
                errorMessage,
                aborted,
                willRetry: false,
                fromExtension,
            });
            throw error;
        }
        finally {
            this._clearManualCompactionState();
        }
    }

async _checkCompaction(assistantMessage, skipAbortedCheck = true) {
        const settings = this.settingsManager.getCompactionSettings();
        if (!settings.enabled)
            return false;
        // Skip if message was aborted (user cancelled) - unless skipAbortedCheck is false
        if (skipAbortedCheck && assistantMessage.stopReason === "aborted")
            return false;
        const contextWindow = this.model?.contextWindow ?? 0;
        // Skip overflow check if the message came from a different model.
        // This handles the case where user switched from a smaller-context model (e.g. opus)
        // to a larger-context model (e.g. codex) - the overflow error from the old model
        // shouldn't trigger compaction for the new model.
        const sameModel = this.model && assistantMessage.provider === this.model.provider && assistantMessage.model === this.model.id;
        // Skip compaction checks if this assistant message is older than the latest
        // compaction boundary. This prevents a stale pre-compaction usage/error
        // from retriggering compaction on the first prompt after compaction.
        const compactionEntry = getLatestCompactionEntry(this.sessionManager.getBranch());
        const assistantIsFromBeforeCompaction = compactionEntry !== null && assistantMessage.timestamp <= new Date(compactionEntry.timestamp).getTime();
        if (assistantIsFromBeforeCompaction) {
            return false;
        }
        // Automatic cases 1 and 2: context overflow.
        // A length stop is recoverable when output ended below the model's original desired limit,
        // independent of the configured context size or any context-clamped provider request limit.
        const contextOverflow = sameModel && isContextOverflow(assistantMessage, contextWindow);
        const recoverableLength = sameModel && isRecoverableLength(assistantMessage, this.model?.maxTokens ?? 0);
        if (contextOverflow || recoverableLength) {
            const willRetry = assistantMessage.stopReason !== "stop";
            // Case 2: the response completed successfully. Compact, but do not retry because
            // agent.continue() cannot continue from a completed assistant response.
            if (!willRetry) {
                return await this._runAutoCompaction("overflow", false);
            }
            if (this._overflowRecoveryAttempted) {
                const errorMessage = contextOverflow
                    ? "Context overflow recovery failed after one compact-and-retry attempt. Try reducing context or switching to a larger-context model."
                    : "Truncated response recovery failed after one compact-and-retry attempt.";
                this._emit({
                    type: "compaction_end",
                    reason: "overflow",
                    result: undefined,
                    aborted: false,
                    willRetry: false,
                    errorMessage,
                });
                await this._emitSessionCompactFailed({
                    reason: "overflow",
                    errorMessage,
                    aborted: false,
                    willRetry: false,
                    fromExtension: false,
                });
                return false;
            }
            // Case 1: remove the failed or truncated message from agent state, compact, and
            // retry once. The message remains in session history but is excluded from retry context.
            this._overflowRecoveryAttempted = true;
            const messages = this.agent.state.messages;
            if (messages.length > 0 && messages[messages.length - 1].role === "assistant") {
                this.agent.state.messages = messages.slice(0, -1);
            }
            return await this._runAutoCompaction("overflow", willRetry);
        }
        // Case 3: threshold compaction without retry.
        // For error messages or all-zero usage messages, estimate from the last valid response.
        // This ensures sessions that hit persistent API errors (e.g. 529) or malformed zero-usage
        // responses can still compact and do not reset context accounting.
        let contextTokens;
        const directContextTokens = assistantMessage.usage ? calculateContextTokens(assistantMessage.usage) : 0;
        if (assistantMessage.stopReason === "error" || directContextTokens === 0) {
            const messages = this.agent.state.messages;
            const estimate = estimateContextTokens(messages);
            // Without provider usage, estimate.tokens is the pure message-size estimate.
            // Only usage-backed estimates need the stale pre-compaction check.
            if (estimate.lastUsageIndex !== null) {
                // Verify the usage source is post-compaction. Kept pre-compaction messages
                // have stale usage reflecting the old (larger) context and would falsely
                // trigger compaction right after one just finished.
                const usageMsg = messages[estimate.lastUsageIndex];
                if (compactionEntry &&
                    usageMsg.role === "assistant" &&
                    usageMsg.timestamp <= new Date(compactionEntry.timestamp).getTime()) {
                    return false;
                }
            }
            contextTokens = estimate.tokens;
        }
        else {
            contextTokens = directContextTokens;
        }
        if (shouldCompact(contextTokens, contextWindow, settings)) {
            return await this._runAutoCompaction("threshold", false);
        }
        return false;
    }

async _runAutoCompaction(reason, willRetry) {
        const settings = this.settingsManager.getCompactionSettings();
        let started = false;
        let fromExtension = false;
        try {
            if (!this.model) {
                return false;
            }
            const { model: requestModel, apiKey, headers, env } = await this._getSummarizationRequestAuth(this.model);
            const pathEntries = this.sessionManager.getBranch();
            const preparation = prepareCompaction(pathEntries, settings);
            if (!preparation) {
                return false;
            }
            this._emit({ type: "compaction_start", reason });
            this._autoCompactionAbortController = new AbortController();
            started = true;
            let extensionCompaction;
            if (this._extensionRunner.hasHandlers("session_before_compact")) {
                const extensionResult = (await this._extensionRunner.emit({
                    type: "session_before_compact",
                    preparation,
                    branchEntries: pathEntries,
                    customInstructions: undefined,
                    reason,
                    willRetry,
                    signal: this._autoCompactionAbortController.signal,
                }));
                if (extensionResult?.cancel) {
                    this._emit({
                        type: "compaction_end",
                        reason,
                        result: undefined,
                        aborted: true,
                        willRetry: false,
                    });
                    await this._emitSessionCompactFailed({
                        reason,
                        aborted: true,
                        willRetry: false,
                        fromExtension: false,
                    });
                    return false;
                }
                if (extensionResult?.compaction) {
                    extensionCompaction = extensionResult.compaction;
                    fromExtension = true;
                }
            }
            let summary;
            let firstKeptEntryId;
            let tokensBefore;
            let usage;
            let details;
            if (extensionCompaction) {
                // Extension provided compaction content
                summary = extensionCompaction.summary;
                firstKeptEntryId = extensionCompaction.firstKeptEntryId;
                tokensBefore = extensionCompaction.tokensBefore;
                usage = extensionCompaction.usage;
                details = extensionCompaction.details;
            }
            else {
                // Shared default summary generator, also used by manual compaction.
                const compactResult = await this._runDefaultCompaction(preparation, requestModel, apiKey, headers, undefined, this._autoCompactionAbortController.signal, env, reason);
                summary = compactResult.summary;
                firstKeptEntryId = compactResult.firstKeptEntryId;
                tokensBefore = compactResult.tokensBefore;
                usage = compactResult.usage;
                details = compactResult.details;
            }
            if (this._autoCompactionAbortController.signal.aborted) {
                this._emit({
                    type: "compaction_end",
                    reason,
                    result: undefined,
                    aborted: true,
                    willRetry: false,
                });
                await this._emitSessionCompactFailed({
                    reason,
                    aborted: true,
                    willRetry: false,
                    fromExtension,
                });
                return false;
            }
            this.sessionManager.appendCompaction(summary, firstKeptEntryId, tokensBefore, details, fromExtension, usage);
            const newEntries = this.sessionManager.getEntries();
            const sessionContext = this.sessionManager.buildSessionContext();
            this.agent.state.messages = sessionContext.messages;
            const estimatedTokensAfter = estimateMessagesTokens(sessionContext.messages);
            // Get the saved compaction entry for the extension event
            const savedCompactionEntry = newEntries.find((e) => e.type === "compaction" && e.summary === summary);
            if (this._extensionRunner && savedCompactionEntry) {
                await this._extensionRunner.emit({
                    type: "session_compact",
                    compactionEntry: savedCompactionEntry,
                    fromExtension,
                    reason,
                    willRetry,
                });
            }
            const result = {
                summary,
                firstKeptEntryId,
                tokensBefore,
                estimatedTokensAfter,
                usage,
                details,
            };
            this._emit({ type: "compaction_end", reason, result, aborted: false, willRetry });
            if (willRetry) {
                const messages = this.agent.state.messages;
                const lastMsg = messages[messages.length - 1];
                // The overflow response was persisted on message_end before _checkCompaction() removed it
                // from agent state. Rebuilding state from the new compaction can restore that kept entry,
                // leaving an assistant as the final message. agent.continue() rejects that state, so remove
                // the retriable error or truncated-length response again before continuing the interrupted turn.
                if (lastMsg?.role === "assistant" && (lastMsg.stopReason === "error" || lastMsg.stopReason === "length")) {
                    this.agent.state.messages = messages.slice(0, -1);
                }
                return true;
            }
            // Auto-compaction can complete while follow-up/steering/custom messages are waiting.
            // Continue once so queued messages are delivered.
            return this.agent.hasQueuedMessages();
        }
        catch (error) {
            const errorMessage = error instanceof Error ? error.message : "compaction failed";
            if (started) {
                const formattedErrorMessage = reason === "overflow"
                    ? `Context overflow recovery failed: ${errorMessage}`
                    : `Auto-compaction failed: ${errorMessage}`;
                this._emit({
                    type: "compaction_end",
                    reason,
                    result: undefined,
                    aborted: false,
                    willRetry: false,
                    errorMessage: formattedErrorMessage,
                });
                await this._emitSessionCompactFailed({
                    reason,
                    errorMessage: formattedErrorMessage,
                    aborted: false,
                    willRetry: false,
                    fromExtension,
                });
            }
            return false;
        }
        finally {
            this._autoCompactionAbortController = undefined;
            this._resolveIdleWaitIfIdle();
        }
    }

async bindExtensions(bindings) {
        if (bindings.uiContext !== undefined) {
            this._extensionUIContext = bindings.uiContext;
        }
        if (bindings.mode !== undefined) {
            this._extensionMode = bindings.mode;
        }
        if (bindings.commandContextActions !== undefined) {
            this._extensionCommandContextActions = bindings.commandContextActions;
        }
        if (bindings.abortHandler !== undefined) {
            this._extensionAbortHandler = bindings.abortHandler;
        }
        if (bindings.shutdownHandler !== undefined) {
            this._extensionShutdownHandler = bindings.shutdownHandler;
        }
        if (bindings.onError !== undefined) {
            this._extensionErrorListener = bindings.onError;
        }
        this._applyExtensionBindings(this._extensionRunner);
        await this._extensionRunner.emit(this._sessionStartEvent);
        await this.extendResourcesFromExtensions(this._sessionStartEvent.reason === "reload" ? "reload" : "startup");
    }

async extendResourcesFromExtensions(reason) {
        if (!this._extensionRunner.hasHandlers("resources_discover")) {
            return;
        }
        const { skillPaths, promptPaths, themePaths } = await this._extensionRunner.emitResourcesDiscover(this._cwd, reason);
        if (skillPaths.length === 0 && promptPaths.length === 0 && themePaths.length === 0) {
            return;
        }
        const extensionPaths = {
            skillPaths: this.buildExtensionResourcePaths(skillPaths),
            promptPaths: this.buildExtensionResourcePaths(promptPaths),
            themePaths: this.buildExtensionResourcePaths(themePaths),
        };
        this._resourceLoader.extendResources(extensionPaths);
        this._baseSystemPrompt = this._rebuildSystemPrompt(this.getActiveToolNames());
        this.agent.state.systemPrompt = this._baseSystemPrompt;
    }

buildExtensionResourcePaths(entries) {
        return entries.map((entry) => {
            const source = this.getExtensionSourceLabel(entry.extensionPath);
            const baseDir = entry.extensionPath.startsWith("<") ? undefined : dirname(entry.extensionPath);
            return {
                path: entry.path,
                metadata: {
                    source,
                    scope: "temporary",
                    origin: "top-level",
                    baseDir,
                },
            };
        });
    }

getExtensionSourceLabel(extensionPath) {
        if (extensionPath.startsWith("<")) {
            return `extension:${extensionPath.replace(/[<>]/g, "")}`;
        }
        const base = basename(extensionPath);
        const name = base.replace(/\.(ts|js)$/, "");
        return `extension:${name}`;
    }

_refreshCurrentModelFromRegistry() {
        const currentModel = this.model;
        if (!currentModel) {
            return;
        }
        const refreshedModel = this._modelRuntime.getModel(currentModel.provider, currentModel.id);
        if (!refreshedModel || refreshedModel === currentModel) {
            return;
        }
        this.agent.state.model = refreshedModel;
    }

_bindExtensionCore(runner) {
        const getCommands = () => {
            const extensionCommands = runner.getRegisteredCommands().map((command) => ({
                name: command.invocationName,
                description: command.description,
                source: "extension",
                sourceInfo: command.sourceInfo,
            }));
            const templates = this.promptTemplates.map((template) => ({
                name: template.name,
                description: template.description,
                source: "prompt",
                sourceInfo: template.sourceInfo,
            }));
            const skills = this._resourceLoader.getSkills().skills.map((skill) => ({
                name: `skill:${skill.name}`,
                description: skill.description,
                source: "skill",
                sourceInfo: skill.sourceInfo,
            }));
            return [...extensionCommands, ...templates, ...skills];
        };
        runner.bindCore({
            sendMessage: (message, options) => {
                this.sendCustomMessage(message, options).catch((err) => {
                    runner.emitError({
                        extensionPath: "<runtime>",
                        event: "send_message",
                        error: err instanceof Error ? err.message : String(err),
                    });
                });
            },
            sendUserMessage: (content, options) => {
                this.sendUserMessage(content, options).catch((err) => {
                    runner.emitError({
                        extensionPath: "<runtime>",
                        event: "send_user_message",
                        error: err instanceof Error ? err.message : String(err),
                    });
                });
            },
            appendEntry: (customType, data) => {
                const entryId = this.sessionManager.appendCustomEntry(customType, data);
                const entry = this.sessionManager.getEntry(entryId);
                if (entry) {
                    this._emit({ type: "entry_appended", entry });
                }
            },
            setSessionName: (name) => {
                this.setSessionName(name);
            },
            getSessionName: () => {
                return this.sessionManager.getSessionName();
            },
            setLabel: (entryId, label) => {
                this.sessionManager.appendLabelChange(entryId, label);
            },
            getActiveTools: () => this.getActiveToolNames(),
            getAllTools: () => this.getAllTools(),
            setActiveTools: (toolNames) => this.setActiveToolsByName(toolNames),
            refreshTools: () => this._refreshToolRegistry(),
            getCommands,
            setModel: async (model) => {
                if (!this._modelRuntime.hasConfiguredAuth(model.provider))
                    return false;
                await this.setModel(model);
                return true;
            },
            getThinkingLevel: () => this.thinkingLevel,
            setThinkingLevel: (level) => this.setThinkingLevel(level),
        }, {
            getModel: () => this.model,
            getScopedModels: () => this._scopedModels,
            isIdle: () => this.isIdle,
            isProjectTrusted: () => this.settingsManager.isProjectTrusted(),
            getSignal: () => this.agent.signal,
            abort: () => {
                if (this._extensionAbortHandler) {
                    this._extensionAbortHandler();
                    return;
                }
                void this.abort();
            },
            hasPendingMessages: () => this.pendingMessageCount > 0,
            shutdown: () => {
                this._extensionShutdownHandler?.();
            },
            getContextUsage: () => this.getContextUsage(),
            compact: (options) => {
                void (async () => {
                    try {
                        const result = await this.compact(options?.customInstructions);
                        options?.onComplete?.(result);
                    }
                    catch (error) {
                        const err = error instanceof Error ? error : new Error(String(error));
                        options?.onError?.(err);
                    }
                })();
            },
            getSystemPrompt: () => this.systemPrompt,
            getSystemPromptOptions: () => this._baseSystemPromptOptions,
        }, {
            registerProvider: (name, config) => {
                this._modelRuntime.registerProvider(name, config);
                this._refreshCurrentModelFromRegistry();
            },
            registerNativeProvider: (provider) => {
                this._modelRuntime.registerNativeProvider(provider);
                this._refreshCurrentModelFromRegistry();
            },
            unregisterProvider: (name) => {
                this._modelRuntime.unregisterProvider(name);
                this._refreshCurrentModelFromRegistry();
            },
        });
    }

_refreshToolRegistry(options) {
        const previousRegistryNames = new Set(this._toolRegistry.keys());
        const previousActiveToolNames = this.getActiveToolNames();
        const allowedToolNames = this._allowedToolNames;
        const excludedToolNames = this._excludedToolNames;
        const isAllowedTool = (name) => (!allowedToolNames || allowedToolNames.has(name)) && !excludedToolNames?.has(name);
        const registeredTools = this._extensionRunner.getAllRegisteredTools();
        const allCustomTools = [
            ...registeredTools,
            ...this._customTools.map((definition) => ({
                definition,
                sourceInfo: createSyntheticSourceInfo(`<sdk:${definition.name}>`, { source: "sdk" }),
            })),
        ].filter((tool) => isAllowedTool(tool.definition.name));
        const definitionRegistry = new Map(Array.from(this._baseToolDefinitions.entries())
            .filter(([name]) => isAllowedTool(name))
            .map(([name, definition]) => [
            name,
            {
                definition,
                sourceInfo: createSyntheticSourceInfo(`<builtin:${name}>`, { source: "builtin" }),
            },
        ]));
        for (const tool of allCustomTools) {
            definitionRegistry.set(tool.definition.name, {
                definition: tool.definition,
                sourceInfo: tool.sourceInfo,
            });
        }
        this._toolDefinitions = definitionRegistry;
        this._toolPromptSnippets = new Map(Array.from(definitionRegistry.values())
            .map(({ definition }) => {
            const snippet = this._normalizePromptSnippet(definition.promptSnippet);
            return snippet ? [definition.name, snippet] : undefined;
        })
            .filter((entry) => entry !== undefined));
        this._toolPromptGuidelines = new Map(Array.from(definitionRegistry.values())
            .map(({ definition }) => {
            const guidelines = this._normalizePromptGuidelines(definition.promptGuidelines);
            return guidelines.length > 0 ? [definition.name, guidelines] : undefined;
        })
            .filter((entry) => entry !== undefined));
        const runner = this._extensionRunner;
        const wrappedExtensionTools = wrapRegisteredTools(allCustomTools, runner);
        const wrappedBuiltInTools = wrapRegisteredTools(Array.from(this._baseToolDefinitions.values())
            .filter((definition) => isAllowedTool(definition.name))
            .map((definition) => ({
            definition,
            sourceInfo: createSyntheticSourceInfo(`<builtin:${definition.name}>`, { source: "builtin" }),
        })), runner);
        const toolRegistry = new Map(wrappedBuiltInTools.map((tool) => [tool.name, tool]));
        for (const tool of wrappedExtensionTools) {
            toolRegistry.set(tool.name, tool);
        }
        this._toolRegistry = toolRegistry;
        const nextActiveToolNames = (options?.activeToolNames ? [...options.activeToolNames] : [...previousActiveToolNames]).filter((name) => isAllowedTool(name));
        if (allowedToolNames) {
            for (const toolName of this._toolRegistry.keys()) {
                if (allowedToolNames.has(toolName)) {
                    nextActiveToolNames.push(toolName);
                }
            }
        }
        else if (options?.includeAllExtensionTools) {
            for (const tool of wrappedExtensionTools) {
                nextActiveToolNames.push(tool.name);
            }
        }
        else if (!options?.activeToolNames) {
            for (const toolName of this._toolRegistry.keys()) {
                if (!previousRegistryNames.has(toolName)) {
                    nextActiveToolNames.push(toolName);
                }
            }
        }
        this.setActiveToolsByName([...new Set(nextActiveToolNames)]);
    }

_buildRuntime(options) {
        const autoResizeImages = this.settingsManager.getImageAutoResize();
        const shellCommandPrefix = this.settingsManager.getShellCommandPrefix();
        const shellPath = this.settingsManager.getShellPath();
        const baseToolDefinitions = this._baseToolsOverride
            ? Object.fromEntries(Object.entries(this._baseToolsOverride).map(([name, tool]) => [
                name,
                createToolDefinitionFromAgentTool(tool),
            ]))
            : createAllToolDefinitions(this._cwd, {
                read: { autoResizeImages },
                bash: { commandPrefix: shellCommandPrefix, shellPath },
            });
        this._baseToolDefinitions = new Map(Object.entries(baseToolDefinitions).map(([name, tool]) => [name, tool]));
        const extensionsResult = this._resourceLoader.getExtensions();
        if (options.flagValues) {
            for (const [name, value] of options.flagValues) {
                extensionsResult.runtime.flagValues.set(name, value);
            }
        }
        this._extensionRunner = new ExtensionRunner(extensionsResult.extensions, extensionsResult.runtime, this._cwd, this.sessionManager, new ModelRegistry(this._modelRuntime));
        if (this._extensionRunnerRef) {
            this._extensionRunnerRef.current = this._extensionRunner;
        }
        this._bindExtensionCore(this._extensionRunner);
        this._applyExtensionBindings(this._extensionRunner);
        const defaultActiveToolNames = this._baseToolsOverride
            ? Object.keys(this._baseToolsOverride)
            : ["read", "bash", "edit", "write"];
        const baseActiveToolNames = options.activeToolNames ?? defaultActiveToolNames;
        this._refreshToolRegistry({
            activeToolNames: baseActiveToolNames,
            includeAllExtensionTools: options.includeAllExtensionTools,
        });
    }

async reload(options) {
        const oldRunner = this._extensionRunner;
        const previousFlagValues = oldRunner.getFlagValues();
        await emitSessionShutdownEvent(oldRunner, { type: "session_shutdown", reason: "reload" });
        oldRunner.invalidate();
        await this.settingsManager.reload();
        this.syncQueueModesFromSettings();
        resetApiProviders();
        await this._resourceLoader.reload();
        this._buildRuntime({
            activeToolNames: this.getActiveToolNames(),
            flagValues: previousFlagValues,
            includeAllExtensionTools: true,
        });
        const hasBindings = this._extensionUIContext ||
            this._extensionCommandContextActions ||
            this._extensionShutdownHandler ||
            this._extensionErrorListener;
        if (hasBindings) {
            await options?.beforeSessionStart?.();
            await this._extensionRunner.emit({ type: "session_start", reason: "reload" });
            await this.extendResourcesFromExtensions("reload");
        }
    }

_isRetryableError(message) {
        // Context overflow is handled by compaction, not retry.
        if (isContextOverflow(message, this.model?.contextWindow ?? 0))
            return false;
        return isRetryableAssistantError(message);
    }

_summarizationRetryCallbacks(source) {
        return {
            onRetryScheduled: (attempt, maxAttempts, delayMs, errorMessage) => {
                this._emit({
                    type: "summarization_retry_scheduled",
                    attempt,
                    maxAttempts,
                    delayMs,
                    errorMessage,
                });
            },
            onRetryAttemptStart: () => {
                this._emit({
                    type: "summarization_retry_attempt_start",
                    ...source,
                });
            },
            onRetryFinished: () => {
                this._emit({ type: "summarization_retry_finished" });
            },
        };
    }

async _prepareRetry(message) {
        const settings = this.settingsManager.getRetrySettings();
        if (!settings.enabled) {
            return false;
        }
        this._retryAttempt++;
        if (this._retryAttempt > settings.maxRetries) {
            // Preserve the completed attempt count so post-run handling can emit the final failure.
            this._retryAttempt--;
            return false;
        }
        const delayMs = settings.baseDelayMs * 2 ** (this._retryAttempt - 1);
        this._emit({
            type: "auto_retry_start",
            attempt: this._retryAttempt,
            maxAttempts: settings.maxRetries,
            delayMs,
            errorMessage: message.errorMessage || "Unknown error",
        });
        // Remove error message from agent state (keep in session for history)
        const messages = this.agent.state.messages;
        if (messages.length > 0 && messages[messages.length - 1].role === "assistant") {
            this.agent.state.messages = messages.slice(0, -1);
        }
        // Wait with exponential backoff (abortable)
        this._retryAbortController = new AbortController();
        try {
            await sleep(delayMs, this._retryAbortController.signal);
        }
        catch {
            // Aborted during sleep - emit end event so UI can clean up
            const attempt = this._retryAttempt;
            this._retryAttempt = 0;
            this._emit({
                type: "auto_retry_end",
                success: false,
                attempt,
                finalError: "Retry cancelled",
            });
            return false;
        }
        finally {
            this._retryAbortController = undefined;
        }
        return true;
    }

async executeBash(command, onChunk, options) {
        const abortController = new AbortController();
        this._bashAbortControllers.add(abortController);
        // Apply command prefix if configured (e.g., "shopt -s expand_aliases" for alias support)
        const prefix = this.settingsManager.getShellCommandPrefix();
        const shellPath = this.settingsManager.getShellPath();
        const resolvedCommand = prefix ? `${prefix}\n${command}` : command;
        try {
            const result = await executeBashWithOperations(resolvedCommand, this.sessionManager.getCwd(), options?.operations ?? createLocalBashOperations({ shellPath }), {
                onChunk: (delta) => {
                    onChunk?.(delta);
                    this._emit({ type: "bash_execution_update", id: options?.id, delta });
                },
                signal: abortController.signal,
            });
            this.recordBashResult(command, result, options);
            return result;
        }
        finally {
            this._bashAbortControllers.delete(abortController);
        }
    }

recordBashResult(command, result, options) {
        const bashMessage = {
            role: "bashExecution",
            command,
            output: result.output,
            exitCode: result.exitCode,
            cancelled: result.cancelled,
            truncated: result.truncated,
            fullOutputPath: result.fullOutputPath,
            timestamp: Date.now(),
            excludeFromContext: options?.excludeFromContext,
        };
        // If agent is streaming, defer adding to avoid breaking tool_use/tool_result ordering
        if (this.isStreaming) {
            // Queue for later - will be flushed on agent_end
            this._pendingBashMessages.push(bashMessage);
        }
        else {
            // Add to agent state immediately
            this.agent.state.messages.push(bashMessage);
            // Save to session
            this.sessionManager.appendMessage(bashMessage);
        }
    }

_flushPendingBashMessages() {
        if (this._pendingBashMessages.length === 0)
            return;
        for (const bashMessage of this._pendingBashMessages) {
            // Add to agent state
            this.agent.state.messages.push(bashMessage);
            // Save to session
            this.sessionManager.appendMessage(bashMessage);
        }
        this._pendingBashMessages = [];
    }

setSessionName(name) {
        this.sessionManager.appendSessionInfo(name);
        const event = { type: "session_info_changed", name: this.sessionManager.getSessionName() };
        this._emit(event);
        void this._extensionRunner.emit(event);
    }

async navigateTree(targetId, options = {}) {
        if (this.isStreaming) {
            throw new Error("Wait for the current response to finish before navigating the session tree.");
        }
        const oldLeafId = this.sessionManager.getLeafId();
        // No-op if already at target
        if (targetId === oldLeafId) {
            return { cancelled: false };
        }
        // Model required for summarization
        if (options.summarize && !this.model) {
            throw new Error("No model available for summarization");
        }
        const targetEntry = this.sessionManager.getEntry(targetId);
        if (!targetEntry) {
            throw new Error(`Entry ${targetId} not found`);
        }
        // Collect entries to summarize (from old leaf to common ancestor)
        const { entries: entriesToSummarize, commonAncestorId } = collectEntriesForBranchSummary(this.sessionManager, oldLeafId, targetId);
        // Prepare event data - mutable so extensions can override
        let customInstructions = options.customInstructions;
        let replaceInstructions = options.replaceInstructions;
        let label = options.label;
        const preparation = {
            targetId,
            oldLeafId,
            commonAncestorId,
            entriesToSummarize,
            userWantsSummary: options.summarize ?? false,
            customInstructions,
            replaceInstructions,
            label,
        };
        // Set up abort controller for summarization
        this._branchSummaryAbortController = new AbortController();
        try {
            let extensionSummary;
            let fromExtension = false;
            // Emit session_before_tree event
            if (this._extensionRunner.hasHandlers("session_before_tree")) {
                const result = (await this._extensionRunner.emit({
                    type: "session_before_tree",
                    preparation,
                    signal: this._branchSummaryAbortController.signal,
                }));
                if (result?.cancel) {
                    return { cancelled: true };
                }
                if (result?.summary && options.summarize) {
                    extensionSummary = result.summary;
                    fromExtension = true;
                }
                // Allow extensions to override instructions and label
                if (result?.customInstructions !== undefined) {
                    customInstructions = result.customInstructions;
                }
                if (result?.replaceInstructions !== undefined) {
                    replaceInstructions = result.replaceInstructions;
                }
                if (result?.label !== undefined) {
                    label = result.label;
                }
            }
            // Run default summarizer if needed
            let summaryText;
            let summaryDetails;
            let summaryUsage;
            if (options.summarize && entriesToSummarize.length > 0 && !extensionSummary) {
                const model = this.model;
                const { model: requestModel, apiKey, headers, env } = await this._getSummarizationRequestAuth(model);
                const branchSummarySettings = this.settingsManager.getBranchSummarySettings();
                const result = await generateBranchSummary(entriesToSummarize, {
                    model: requestModel,
                    apiKey,
                    headers,
                    env,
                    signal: this._branchSummaryAbortController.signal,
                    customInstructions,
                    replaceInstructions,
                    reserveTokens: branchSummarySettings.reserveTokens,
                    streamFn: this.agent.streamFunction,
                    retry: this.settingsManager.getRetrySettings(),
                    callbacks: this._summarizationRetryCallbacks({ source: "branchSummary" }),
                });
                if (result.aborted) {
                    return { cancelled: true, aborted: true };
                }
                if (result.error) {
                    throw new Error(result.error);
                }
                summaryText = result.summary;
                summaryUsage = result.usage;
                summaryDetails = {
                    readFiles: result.readFiles || [],
                    modifiedFiles: result.modifiedFiles || [],
                };
            }
            else if (extensionSummary) {
                summaryText = extensionSummary.summary;
                summaryDetails = extensionSummary.details;
                summaryUsage = extensionSummary.usage;
            }
            // Determine the new leaf position based on target type
            let newLeafId;
            let editorText;
            if (targetEntry.type === "message" && targetEntry.message.role === "user") {
                // User message: leaf = parent (null if root), text goes to editor
                newLeafId = targetEntry.parentId;
                editorText = contentText(targetEntry.message.content, "");
            }
            else if (targetEntry.type === "custom_message") {
                // Custom message: leaf = parent (null if root), text goes to editor
                newLeafId = targetEntry.parentId;
                editorText = contentText(targetEntry.content, "");
            }
            else {
                // Non-user message: leaf = selected node
                newLeafId = targetId;
            }
            // Switch leaf (with or without summary)
            // Summary is attached at the navigation target position (newLeafId), not the old branch
            let summaryEntry;
            if (summaryText) {
                // Create summary at target position (can be null for root)
                const summaryId = this.sessionManager.branchWithSummary(newLeafId, summaryText, summaryDetails, fromExtension, summaryUsage);
                summaryEntry = this.sessionManager.getEntry(summaryId);
                // Attach label to the summary entry
                if (label) {
                    this.sessionManager.appendLabelChange(summaryId, label);
                }
            }
            else if (newLeafId === null) {
                // No summary, navigating to root - reset leaf
                this.sessionManager.resetLeaf();
            }
            else {
                // No summary, navigating to non-root
                this.sessionManager.branch(newLeafId);
            }
            // Attach label to target entry when not summarizing (no summary entry to label)
            if (label && !summaryText) {
                this.sessionManager.appendLabelChange(targetId, label);
            }
            // Update agent state
            const sessionContext = this.sessionManager.buildSessionContext();
            this.agent.state.messages = sessionContext.messages;
            // Emit session_tree event
            await this._extensionRunner.emit({
                type: "session_tree",
                newLeafId: this.sessionManager.getLeafId(),
                oldLeafId,
                summaryEntry,
                fromExtension: summaryText ? fromExtension : undefined,
            });
            // Emit to custom tools
            return { editorText, cancelled: false, summaryEntry };
        }
        finally {
            this._branchSummaryAbortController = undefined;
            this._resolveIdleWaitIfIdle();
        }
    }

getUserMessagesForForking() {
        const entries = this.sessionManager.getEntries();
        const result = [];
        for (const entry of entries) {
            if (entry.type !== "message")
                continue;
            if (entry.message.role !== "user")
                continue;
            const text = contentText(entry.message.content, "");
            if (text) {
                result.push({ entryId: entry.id, text });
            }
        }
        return result;
    }

getSessionStats() {
        let userMessages = 0;
        let assistantMessages = 0;
        let toolResults = 0;
        let totalMessages = 0;
        let toolCalls = 0;
        const usageTotals = createUsageTotals();
        for (const entry of this.sessionManager.getEntries()) {
            if ((entry.type === "branch_summary" || entry.type === "compaction") && entry.usage) {
                addUsageToTotals(usageTotals, entry.usage);
            }
            if (entry.type !== "message")
                continue;
            totalMessages++;
            const message = entry.message;
            if (message.role === "user") {
                userMessages++;
            }
            else if (message.role === "toolResult") {
                toolResults++;
                if (message.usage) {
                    addUsageToTotals(usageTotals, message.usage);
                }
            }
            else if (message.role === "assistant") {
                assistantMessages++;
                const assistantMsg = message;
                if (Array.isArray(assistantMsg.content)) {
                    toolCalls += assistantMsg.content.filter((c) => c.type === "toolCall").length;
                }
                addUsageToTotals(usageTotals, assistantMsg.usage);
            }
        }
        return {
            sessionFile: this.sessionFile,
            sessionId: this.sessionId,
            userMessages,
            assistantMessages,
            toolCalls,
            toolResults,
            totalMessages,
            tokens: {
                input: usageTotals.input,
                output: usageTotals.output,
                cacheRead: usageTotals.cacheRead,
                cacheWrite: usageTotals.cacheWrite,
                total: usageTotals.input + usageTotals.output + usageTotals.cacheRead + usageTotals.cacheWrite,
            },
            cost: usageTotals.cost,
            contextUsage: this.getContextUsage(),
        };
    }

getContextUsage() {
        const model = this.model;
        if (!model)
            return undefined;
        const contextWindow = model.contextWindow ?? 0;
        if (contextWindow <= 0)
            return undefined;
        // After compaction, the last assistant usage reflects pre-compaction context size.
        // We can only trust usage from an assistant that responded after the latest compaction.
        // If no such assistant exists, context token count is unknown until the next LLM response.
        const branchEntries = this.sessionManager.getBranch();
        const latestCompaction = getLatestCompactionEntry(branchEntries);
        if (latestCompaction) {
            // Check if there's a valid assistant usage after the compaction boundary
            const compactionIndex = branchEntries.lastIndexOf(latestCompaction);
            let hasPostCompactionUsage = false;
            for (let i = branchEntries.length - 1; i > compactionIndex; i--) {
                const entry = branchEntries[i];
                if (entry.type === "message" && entry.message.role === "assistant") {
                    const assistant = entry.message;
                    if (assistant.stopReason !== "aborted" && assistant.stopReason !== "error") {
                        const contextTokens = calculateContextTokens(assistant.usage);
                        if (contextTokens > 0) {
                            hasPostCompactionUsage = true;
                            break;
                        }
                    }
                }
            }
            if (!hasPostCompactionUsage) {
                return { tokens: null, contextWindow, percent: null };
            }
        }
        const estimate = estimateContextTokens(this.messages);
        const percent = (estimate.tokens / contextWindow) * 100;
        return {
            tokens: estimate.tokens,
            contextWindow,
            percent,
        };
    }

async exportToHtml(outputPath, options = {}) {
        const themeName = [options.themeName, this.settingsManager.getTheme()].find((candidate) => candidate !== undefined && getThemeByName(candidate) !== undefined);
        // Create tool renderer if we have an extension runner (for custom tool HTML rendering)
        const toolRenderer = createToolHtmlRenderer({
            getToolDefinition: (name) => this.getToolDefinition(name),
            theme,
            cwd: this.sessionManager.getCwd(),
        });
        return await exportSessionToHtml(this.sessionManager, this.state, {
            outputPath,
            themeName,
            toolRenderer,
        });
    }

getLastAssistantText() {
        const lastAssistant = this.messages
            .slice()
            .reverse()
            .find((m) => {
            if (m.role !== "assistant")
                return false;
            const msg = m;
            // Skip aborted messages with no content
            if (msg.stopReason === "aborted" && msg.content.length === 0)
                return false;
            return true;
        });
        if (!lastAssistant)
            return undefined;
        let text = "";
        for (const content of lastAssistant.content) {
            if (content.type === "text") {
                text += content.text;
            }
        }
        return text.trim() || undefined;
    }

createReplacedSessionContext() {
        const context = Object.defineProperties({}, Object.getOwnPropertyDescriptors(this._extensionRunner.createCommandContext()));
        context.sendMessage = (message, options) => this.sendCustomMessage(message, options);
        context.sendUserMessage = (content, options) => this.sendUserMessage(content, options);
        return context;
    }

kimchi_acp_top.text:
import {
	AUTO_MODEL_DESCRIPTION,
	AUTO_MODEL_PROVIDER,
	isAutoRoutedModel,
	splitModelDisplayName,
} from "../../extensions/auto-model/constants.js"

import {
	availableModelRefs,
	findModelByRef,
	refFromModel,
	splitModelRef,
} from "../../extensions/model-catalog/ref-utils.js"

function regionAuthMethod(region: KimchiRegion): AuthMethod {
	return {
		id: `${KIMCHI_AGENT_AUTH_METHOD_ID}-${region.id}`,
		name: `Kimchi Login (${region.id.toUpperCase()})`,
		description: `Authenticate via browser to Kimchi (${region.label} region)`,
	}
}

function authMethodRegion(methodId: string): RegionId | undefined {
	if (methodId === KIMCHI_AGENT_AUTH_METHOD_ID) return resolveEndpoints().region
	const prefix = `${KIMCHI_AGENT_AUTH_METHOD_ID}-`
	if (!methodId.startsWith(prefix)) return undefined
	const suffix = methodId.slice(prefix.length)
	return isRegionId(suffix) ? suffix : undefined
}

function resolveCliPermissionMode(): PermissionMode | undefined {
	const { options } = getParsedCliArgs()
	if (options.plan) return "plan"
	if (options.auto) return "auto"
	if (options.yolo) return "yolo"
	return undefined
}

export interface RunAcpOptions {
	extensionFactories: InlineExtension[]
	agentDir: string
	/** Add the session-scoped MCP adapter after caller servers are known. */
	mcpExtensionFactory?: (options: KimchiMcpAdapterExtensionOptions) => ExtensionFactory
	/**
	 * Content of the `--append-system-prompt` CLI flag, forwarded verbatim to
	 * every session's DefaultResourceLoader. When a client also sends
	 * `_meta["kimchi.dev"].appendSystemPrompt`, meta content is appended after this.
	 */
	appendSystemPrompt?: string[]
	/** Override for tests. Defaults to the pi-coding-agent-backed factory. */
	sessionFactory?: AcpSessionFactory
	/** Override for tests. Defaults to {@link defaultSessionLister}. */
	sessionLister?: AcpSessionLister
	/** Override for tests. Defaults to {@link defaultSessionLoader}. */
	sessionLoader?: AcpSessionLoader
	/**
	 * Isolated MCP probe used by `_kimchi.dev/probe_mcp_server`. Injected so
	 * tests can stub it; production uses the upstream-adapter-backed probe.
	 */
	mcpProbe?: McpProbe
}

export class KimchiAcpAgent implements Agent {
	private sessions = new Map<string, SessionRecord>()
	private readonly commandsRefresher = createCommandsRefresher({
		sessions: () => this.sessions,
		broadcast: (sessionId) => this.scheduleAvailableCommandsUpdate(sessionId),
	})
	private readonly sessionFactory: AcpSessionFactory
	private readonly agentDir: string
	private readonly skillWatcher: SkillWatcher
	private readonly sessionLister: AcpSessionLister
	private readonly sessionLoader: AcpSessionLoader
	private readonly mcpProbe: McpProbe | undefined
	private readonly permissionsEnvFlag = process.env[PERMISSIONS_ENV_KEY]
	private clientCapabilities: ClientCapabilities | undefined
	// Track non-text prompt block types we've already warned about so a
	// misbehaving client that sends 1000 image blocks doesn't flood stderr.
	private warnedBlockTypes = new Set<string>()
	// In-flight loadSession calls, keyed by session id. Without this, two
	// concurrent loads of the same id both pass the `sessions.has()` guard, open
	// the JSONL twice, and the later registration overwrites (and leaks) the
	// earlier session record.
	private loadingSessions = new Map<string, Promise<LoadSessionResponse>>()
	private shutdownPromise: Promise<void> | undefined

	/**
	 * Resolve the initial permission mode for a session.
	 */
	private getInitialPermissionMode(session: AgentSession): PermissionModeState {
		const cwd = session.sessionManager.getCwd()
		const { loaded } = loadConfig({ cwd })
		return resolveInitialPermissionMode(
			session.sessionManager,
			this.permissionsEnvFlag,
			resolveCliPermissionMode(),
			loaded,
		)
	}

	constructor(
		private readonly conn: AgentSideConnection,
		options: RunAcpOptions,
	) {
		this.sessionFactory = options.sessionFactory ?? defaultSessionFactory(options)
		this.agentDir = options.agentDir
		this.sessionLister = options.sessionLister ?? defaultSessionLister(options)
		this.sessionLoader = options.sessionLoader ?? defaultSessionLoader(options)
		this.mcpProbe = options.mcpProbe
		this.skillWatcher = createSkillWatcher({
			agentDir: options.agentDir,
			getExtraSkillPaths: () => [...new Set(loadKimchiConfig().skillPaths ?? [])],
			requestRefresh: () => this.commandsRefresher.request(),
		})
	}

	async initialize(request: InitializeRequest): Promise<InitializeResponse> {
		setAcpClientInfo(request.clientInfo ?? { name: "unknown", version: "0.0.0" })

		this.clientCapabilities = request.clientCapabilities

		const modelRuntime = await ModelRuntime.create({
			authPath: join(this.agentDir, "auth.json"),
			modelsPath: join(this.agentDir, "models.json"),
		})
		const modelRegistry = new ModelRegistry(modelRuntime)
		const supportsImages = modelRegistry.getAvailable().some((m) => modelSupportsImages(m))

		// ACP Registry compliance: advertise at least one auth method. Agent Auth
		// (browser-based OAuth via local callback server) is always declared.
		// Terminal Auth (interactive `kimchi login`) is declared only when the
		// client advertises the terminal capability, per the auth-methods RFD:
		// "An Agent may advertise a terminal authentication method only when the
		// Client advertised the corresponding capability."
		const authMethods: AuthMethod[] = [
			{
				id: KIMCHI_AGENT_AUTH_METHOD_ID,
				name: "Kimchi Login",
				description: "Authenticate via browser to Kimchi",
			},
			// Region-pinned companions for clients that can pick a region.
			...selectableRegions().map(regionAuthMethod),
		]
		if (request.clientCapabilities?.auth?.terminal === true) {
			authMethods.push({
				id: "kimchi-terminal",
				name: "Log in from terminal",
				description: "Run Kimchi's interactive login flow",
				type: "terminal",
				args: ["login"],
			})
		}

		return {
			protocolVersion: PROTOCOL_VERSION,
			agentInfo: {
				name: "kimchi",
				version: getVersion(),
			},
			agentCapabilities: {
				loadSession: true,
				// Advertise logout support so clients know they can call
				// `unstable_logout` to clear stored credentials.
				auth: { logout: {} },
				// `list: {}` advertises support for session/list per spec
				// (SessionListCapabilities is `{ _meta? }` — empty object means
				// "supported"). loadSession remains the top-level flag because
				// the spec hasn't unified it under sessionCapabilities yet.
				sessionCapabilities: { list: {}, close: {} },
				promptCapabilities: { image: supportsImages, audio: false, embeddedContext: false },
				mcpCapabilities: { http: true, sse: false },
				// Extended capabilities
				_meta: {
					[CAPABILITIES_KEY]: {
						...ADVERTISED_CAPABILITIES,
						...(this.mcpProbe ? {} : { probe_mcp_server: false }),
					},
				},
			},
			authMethods,
		}
	}

	async listSessions(params: ListSessionsRequest): Promise<ListSessionsResponse> {
		// Cursor pagination is out of scope for v1: pi reads only JSONL headers,
		// so even four-digit session counts comfortably meet the 500ms NFR
		// (revisit only if real installs hit slowness). `additionalDirectories`
		// (@experimental) is honored when non-empty by the default lister.
		const piSessions = await this.sessionLister(params)
		// Dedupe by session id: the default lister merges results from multiple
		// roots (cwd + additionalDirectories), and the same session can surface
		// twice when a client passes its cwd as one of the additional roots.
		// Keep first occurrence so cwd-listed entries win.
		const seen = new Set<string>()
		const sessions: ReturnType<typeof toAcpSessionInfo>[] = []
		for (const s of piSessions) {
			if (seen.has(s.id)) continue
			seen.add(s.id)
			// Skip subagent sessions: pi marks forked sessions with parentSessionPath
			// so delegated Agent runs don't clutter the user's session list.
			if (s.parentSessionPath) continue
			sessions.push(toAcpSessionInfo(s))
		}
		// Sort newest-first by updatedAt so Zed's picker surfaces recent threads
		// at the top without client-side sorting.
		sessions.sort((a, b) => (b.updatedAt ?? "").localeCompare(a.updatedAt ?? ""))
		// Explicit `nextCursor: null` signals end-of-pagination per the v1 spec
		// so clients don't infer it from an omitted field.
		return { sessions, nextCursor: null }
	}

	async authenticate(params: AuthenticateRequest): Promise<AuthenticateResponse> {
		// Agent Auth ("kimchi-agent") follows the configured region; the pinned
		// "kimchi-agent-<regionId>" companions authenticate against that region
		// regardless of config. Terminal Auth ("kimchi-terminal") is resolved
		// out-of-band: the client launches `kimchi login` as a separate process,
		// so this method is never called for it.
		const region = authMethodRegion(params.methodId)
		if (region === undefined) {
			throw RequestError.invalidParams(undefined, `unknown auth method: ${params.methodId}`)
		}

		// Run the browser OAuth flow: starts a local callback server, opens the
		// user's browser to the Kimchi web app, and awaits the resulting token.
		// The success page copy names no client: this flow may be launched by any
		// ACP client, so it stays neutral instead of the terminal CLI wording.
		let token: string
		try {
			;({ token } = await authenticateViaBrowser({
				webAppUrl: endpointsForRegion(region).webAppUrl,
				successMessage: ACP_SUCCESS_MESSAGE,
			}))
		} catch (error) {
			const detail = error instanceof Error ? error.message : String(error)
			throw RequestError.internalError(undefined, `Browser authentication failed: ${detail}`)
		}
		if (!token) {
			throw RequestError.internalError(undefined, "Browser authentication did not return a token")
		}

		// Persist the key so new sessions pick it up via the login extension's
		// session_start handler (which reads loadConfig().apiKey), with its region.
		writeApiKey(token, undefined, { region })
		// Fresh login invalidates earlier 401 marks — auth_status flips back now.
		clearCredentialStale(KIMCHI_PROVIDER_ID)

		// Eagerly refresh the model cache so the subsequent newSession() call
		// finds available models without another round-trip.
		await updateModelsConfig(join(this.agentDir, "models.json"), token)

		// Write Pi's credential store too, and refresh every OPEN session's
		// ModelRuntime: hasConfiguredAuth reads a snapshot captured at session
		// creation (model-runtime.js), so without this an already-open session
		// keeps rejecting with -32000 until the process is respawned. A failing
		// refresh must not fail the login — the credential is persisted and the
		// next action re-reads it.
		await syncPiAuth(join(this.agentDir, "auth.json"), join(this.agentDir, "models.json"), token)
		await Promise.all(
			[...this.sessions.values()].map((record) =>
				record.session.modelRuntime.refresh({ allowNetwork: false }).catch(() => {}),
			),
		)

		return {}
	}

	async unstable_logout(_params: LogoutRequest): Promise<LogoutResponse> {
		// Clear the persisted API key from config (loadConfig().apiKey), so
		// new sessions no longer pick it up via the login extension.
		clearApiKey()

		// clearPiAuth over AuthStorage.logout(): it removes kimchi-dev/*
		// sub-provider entries, not just the exact kimchi-dev id.
		await clearPiAuth(join(this.agentDir, "auth.json"))

		return {}
	}

	async newSession(params: NewSessionRequest): Promise<NewSessionResponse> {
		const session = await this.sessionFactory(params)
		try {
			const initialMode = this.getInitialPermissionMode(session)
			assertSessionHasModel(session)
			// Credential gate (work item #367): a keyless machine must reject
			// here, not only at first prompt — this is the earliest reactive
			// login trigger clients consume.
			assertSessionModelHasAuth(session)

			const sessionId = session.sessionId
			// A fresh ACP session has neither a process entry nor a session log, so
			// multi-model would otherwise resolve to the global default (true) and
			// report "multi-model" no matter which model the session actually
			// resolved to. Anchor the flag to that resolved model instead, the same
			// way setSessionModel does for an explicit client change.
			setMultiModelEnabled(sessionId, isMultiModelOrchestrator(session))
			const uiContext = this.createUiContext(session)
			registerPermissionFlagController(session, initialMode, (params) => this.send(params))
			// Build the record early so the ACP prompter can allocate ACP
			// toolCallIds that match the ids later emitted by tool_execution_start.
			// The unsubscribe placeholder is replaced after bindAcpExtensions so no
			// extension events are dropped before this.sessions is populated.
			const record: SessionRecord = {
				session,
				unsubscribe: () => {},
				cwd: session.sessionManager.getCwd(),
				nextBlockId: 0,
				contentIndexToBlockId: new Map(),
				streamedText: new Map(),
				nextToolCallId: 0,
				toolCallIdMap: new Map(),
				skillCommands: new Map(),
			}
			registerAcpPrompter(
				sessionId,
				createAcpPermissionPrompter(this.conn, sessionId, uiContext, (piToolCallId, toolName) =>
					this.getOrAllocateAcpToolCallId(record, piToolCallId, toolName),
				),
			)
			await this.bindAcpExtensions(session, uiContext)

			// Populate skill commands only after binding: extensions contribute
			// cwd-local skill roots to the loader during resources_discover, so
			// the palette and /skill: parsing see every skill exactly once.
			this.populateSkillCommands(session, record)
			this.skillWatcher.addSession(record)

			record.unsubscribe = session.subscribe((event) => this.onSessionEvent(sessionId, event))
			this.sessions.set(sessionId, record)

			this.startPlanTracker(record, sessionId)

			this.scheduleAvailableCommandsUpdate(sessionId)
			this.scheduleProjectTrustUpdate(sessionId)

			const configOptions = buildConfigOptions(session, initialMode.mode)
			// Seed the tracker with what the client is about to receive, so the
			// first message_start only re-publishes when the router's pick has
			// actually changed the label.
			record.lastModelOptionName = autoOptionName(configOptions)
			return {
				sessionId,
				configOptions,
				models: buildSessionModelState(configOptions),
			}
		} catch (err) {
			unregisterAcpPrompter(session.sessionId)
			unregisterSessionPermissionFlagController(session.sessionId)
			clearPermissionModeEnv(session.sessionId)
			session.dispose()
			throw err
		}
	}

	private createUiContext(session: AgentSession): ExtensionUIContext {
		// Build the ExtensionUIContext that pi's runner routes `ctx.ui.*` calls
		// through. Bound to a single session for its lifetime — the connection,
		// capabilities, and `send` callback are all session-scoped state.
		return createAcpUIContext(this.conn, session.sessionId, this.clientCapabilities, (params) => this.send(params))
	}

	private async bindAcpExtensions(session: AgentSession, uiContext: ExtensionUIContext): Promise<void> {
		await session.bindExtensions({
			uiContext,
			// Mode is "rpc" so extensions can branch on `ctx.mode === "rpc"` to detect
			// this transport (added in pi-coding-agent 0.78.1). `ctx.hasUI` is derived
			// from the uiContext by the runner, so extensions that only check the
			// legacy boolean keep working too.
			mode: "rpc",
			onError: (err) => {
				process.stderr.write(`acp ext error [${err.extensionPath}] ${err.event}: ${err.error}\n`)
			},
		})

		// Activate the Skill tool if the claude-code-skills extension registered it.
		// This gives ACP sessions the same model-driven skill loading that TUI has
		// by default (skills === true).
		if (session.getToolDefinition("Skill")) {
			const active = new Set(session.getActiveToolNames())
			if (!active.has("Skill")) {
				session.setActiveToolsByName([...active, "Skill"])
			}
		}
	}

	private populateSkillCommands(session: AgentSession, record: SessionRecord): void {
		record.skillCommands = discoverSkillCommandsMap(session)
	}

	/** Start forwarding this session's Todo store writes to the ACP client. */
	private startPlanTracker(record: SessionRecord, sessionId: string): void {
		const tracker = new AcpPlanTracker({
			sessionId,
			send: (params) => this.send(params),
		})
		tracker.start()
		record.planTracker = tracker
		// Startup hooks and restored sessions can populate Todos before subscription.
		tracker.emitRestoredSnapshot()
	}

	async unstable_setSessionModel(params: SetSessionModelRequest): Promise<SetSessionModelResponse> {
		const record = this.sessions.get(params.sessionId)
		if (!record) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${params.sessionId}`)
		}
		await this.doSetModel(record, params.modelId)
		return {}
	}

	async setSessionConfigOption(params: SetSessionConfigOptionRequest): Promise<SetSessionConfigOptionResponse> {
		const record = this.sessions.get(params.sessionId)
		if (!record) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${params.sessionId}`)
		}
		switch (params.configId) {
			case "permissions-mode": {
				this.doSetPermissionMode(record, params.value ? `${params.value}` : "")
				break
			}
			case "model": {
				await this.doSetModel(record, params.value ? `${params.value}` : "")
				break
			}
			default:
				throw RequestError.invalidParams(undefined, `unknown config option ${params.configId}`)
		}
		return {
			configOptions: buildConfigOptions(record.session, this.getInitialPermissionMode(record.session).mode),
		}
	}

	private doSetPermissionMode(record: SessionRecord, mode: string): PermissionMode {
		const permissionMode = mode as PermissionMode
		if (!PERMISSION_MODES.includes(permissionMode)) {
			throw RequestError.invalidParams(undefined, `invalid mode ${permissionMode}`)
		}
		const sessionId = record.session.sessionId
		const { sessionManager } = record.session
		const state: PermissionModeState = { mode: permissionMode, initiatedBy: "user", source: "runtime" }
		persistPermissionModeIfChanged(sessionManager, (...args) => sessionManager.appendCustomEntry(...args), state)
		setPermissionMode(sessionId, state)
		return permissionMode
	}

	private async doSetModel(record: SessionRecord, value: string): Promise<string> {
		if (record.turn) {
			throw RequestError.invalidRequest(undefined, "a prompt is already in progress for this session")
		}
		if (!value) {
			throw RequestError.invalidParams(undefined, "modelId is required")
		}
		const { session } = record
		const sessionId = session.sessionId
		const modelRegistry = getSessionModelRegistry(session)
		if (value === "multi-model") {
			const { model: orchestrator, modelRef: orchRef } = getOrchestratorModel(session.sessionId, modelRegistry)
			if (!orchestrator) {
				// Orchestrator unresolvable: unknown ref → invalidParams; no
				// credentials → authRequired (-32000 → client login UI).
				// ModelRegistry.hasConfiguredAuth(model) delegates to
				// ModelRuntime.hasConfiguredAuth(providerId) (model-registry.js).
				const parsed = splitModelRef(orchRef)
				if (parsed && !session.modelRuntime.hasConfiguredAuth(parsed.provider)) {
					throw RequestError.authRequired(
						undefined,
						`multi-model orchestrator (${orchRef}) is not available: auth required. ${AUTH_REQUIRED_HINT}`,
					)
				}
				throw RequestError.invalidParams(undefined, `multi-model orchestrator (${orchRef}) is not available`)
			}
			const previousMultiModelEnabled = getMultiModelEnabled(session.sessionManager)
			setMultiModelEnabled(sessionId, true)
			try {
				// An explicit client request to change the model, so save it as the default.
				await session.setModel(orchestrator, { persist: true })
			} catch {
				setMultiModelEnabled(sessionId, previousMultiModelEnabled)
				// Pi's setModel only throws "if no auth is configured for the model"
				throw RequestError.authRequired(undefined, `orchestrator model ${orchRef} is not available: auth required`)
			}
			return value
		}

		const parsed = splitModelRef(value)
		if (!parsed) {
			throw RequestError.invalidParams(
				undefined,
				`invalid model format: "${value}". expected "provider/modelId" or "multi-model".`,
			)
		}
		const target = findModelByRef(modelRegistry, value)
		if (!target) {
			throw RequestError.invalidParams(
				undefined,
				`model not found: "${value}". available models: multi-model, ${availableModelRefs(modelRegistry).join(", ")}`,
			)
		}

		const previousMultiModelEnabled = getMultiModelEnabled(session.sessionManager)
		setMultiModelEnabled(sessionId, false)
		try {
			// An explicit client request to change the model, so save it as the default.
			await session.setModel(target, { persist: true })
		} catch {
			setMultiModelEnabled(sessionId, previousMultiModelEnabled)
			// Pi's setModel only throws "if no auth is configured for the model"
			throw RequestError.authRequired(undefined, `model ${refFromModel(target)} is not available: auth required`)
		}
		return value
	}

	async loadSession(params: LoadSessionRequest): Promise<LoadSessionResponse> {
		const sessionId = params.sessionId
		const existing = this.sessions.get(sessionId)
		if (existing) {
			// Mid-turn attach is opt-in; clients passing the flag declared the
			// previous connection dead, so attach and replay instead of rejecting.
			// Everyone else keeps the strict guard.
			if (existing.turn && params._meta?.[ACP_REATTACH_MID_TURN_META_KEY] !== true) {
				throw RequestError.invalidRequest(undefined, `session ${sessionId} has a turn in progress; cancel it first`)
			}
			this.replayTranscript(existing.session)
			this.scheduleAvailableCommandsUpdate(sessionId)
			this.scheduleProjectTrustUpdate(sessionId)

			const configOptions = buildConfigOptions(existing.session, this.getInitialPermissionMode(existing.session).mode)
			return {
				configOptions,
				models: buildSessionModelState(configOptions),
			}
		}
		const loading = this.loadingSessions.get(sessionId)
		if (loading) return loading

		const loadingPromise = this.loadSessionFresh(params)
		this.loadingSessions.set(sessionId, loadingPromise)
		try {
			return await loadingPromise
		} finally {
			if (this.loadingSessions.get(sessionId) === loadingPromise) {
				this.loadingSessions.delete(sessionId)
			}
		}
	}

	private async loadSessionFresh(params: LoadSessionRequest): Promise<LoadSessionResponse> {
		// Atomic ownership transfer mirrors newSession but covers the full
		// register → replay → respond path: a throw at any point after the
		// loader hands back a live session must unwind registration AND dispose,
		// otherwise the session sits in `sessions` while loadSession rejects —
		// Zed thinks load failed but the agent thinks the id is live, and the
		// next loadSession for the same id wrongly returns invalidRequest.
		const session = await this.sessionLoader(params)
		const initialMode = this.getInitialPermissionMode(session)
		const sessionId = session.sessionId
		try {
			// Defensive: pi reads the sessionId from the JSONL header, not the
			// filename, so a corrupted / hand-edited session whose header id
			// disagrees with the requested id would land under the wrong key in
			// `sessions`. Subsequent session/prompt for params.sessionId would then
			// fail with "unknown sessionId" while the file is still held open.
			// Reject up front and dispose so we don't quietly diverge.
			if (sessionId !== params.sessionId) {
				session.dispose()
				throw RequestError.invalidParams(
					undefined,
					`session header id ${sessionId} does not match requested sessionId ${params.sessionId}`,
				)
			}
			assertSessionHasModel(session)

			const uiContext = this.createUiContext(session)
			registerPermissionFlagController(session, initialMode, (params) => this.send(params))
			// Build the record early so the ACP prompter can allocate ACP
			// toolCallIds that match the ids later emitted by tool_execution_start.
			// The unsubscribe placeholder is replaced after bindAcpExtensions so no
			// extension events are dropped before this.sessions is populated.
			const record: SessionRecord = {
				session,
				unsubscribe: () => {},
				// The session header cwd was validated against params.cwd above, so
				// the session manager's cwd is the session's true cwd.
				cwd: session.sessionManager.getCwd(),
				nextBlockId: 0,
				contentIndexToBlockId: new Map(),
				streamedText: new Map(),
				nextToolCallId: 0,
				toolCallIdMap: new Map(),
				skillCommands: new Map(),
			}
			registerAcpPrompter(
				sessionId,
				createAcpPermissionPrompter(this.conn, sessionId, uiContext, (piToolCallId, toolName) =>
					this.getOrAllocateAcpToolCallId(record, piToolCallId, toolName),
				),
			)
			await this.bindAcpExtensions(session, uiContext)

			// Same post-binding skill population as newSession (see there).
			this.populateSkillCommands(session, record)
			this.skillWatcher.addSession(record)

			record.unsubscribe = session.subscribe((event) => this.onSessionEvent(sessionId, event))
			this.sessions.set(sessionId, record)

			this.startPlanTracker(record, sessionId)

			// Seed the block counter from the persisted branch so replay emits the
			// same messageIds the live turn would have — and so any new block the
			// user creates after the load gets a fresh, non-colliding id.
			this.seedBlockCounterFromBranch(session, record)

			// Replay BEFORE the response resolves so client sees a coherent transcript
			// when the loadSession promise settles. No turn context is created, so a
			// concurrent session/cancel during replay is a no-op — a turn must not
			// be considered active during replay.
			this.replayTranscript(session)
			this.scheduleAvailableCommandsUpdate(sessionId)
			this.scheduleProjectTrustUpdate(sessionId)

			const configOptions = buildConfigOptions(session, initialMode.mode)
			// Same seeding as newSession (see there) — a resumed Auto session
			// hydrates its pick before this point, so the label is already final.
			record.lastModelOptionName = autoOptionName(configOptions)
			return {
				configOptions,
				models: buildSessionModelState(configOptions),
			}
		} catch (err) {
			unregisterAcpPrompter(sessionId)
			unregisterSessionPermissionFlagController(sessionId)
			clearPermissionModeEnv(sessionId)
			const existing = this.sessions.get(sessionId)
			if (existing) {
				this.sessions.delete(sessionId)
				existing.planTracker?.stop()
				existing.unsubscribe()
			}
			session.dispose()
			throw err
		}
	}

	async unstable_closeSession(params: CloseSessionRequest): Promise<CloseSessionResponse> {
		await this.closeSessionRecord(params.sessionId)
		return {}
	}

	async prompt(params: PromptRequest): Promise<PromptResponse> {
		const entry = this.sessions.get(params.sessionId)
		if (!entry) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${params.sessionId}`)
		}
		if (entry.turn) {
			throw RequestError.invalidRequest(undefined, "a prompt is already in progress for this session")
		}
		const supportsImages = modelSupportsImages(entry.session.model)
		// Warn about unsupported block types (audio, embeddedContext) once per
		// type. Dropped images do NOT join this dedupe — they additionally surface
		// to the client as a per-turn agent_message_chunk warning below, so every
		// dropping turn is visible, not just the first one per connection.
		for (const b of params.prompt) {
			if (b.type !== "text" && b.type !== "image" && !this.warnedBlockTypes.has(b.type)) {
				this.warnedBlockTypes.add(b.type)
				process.stderr.write(`acp prompt: dropping ${b.type} block (unsupported block type)\n`)
			}
		}
		let text = params.prompt
			.map((b: ContentBlock) => (b.type === "text" ? b.text : ""))
			.join("")
			.trim()

		// If the prompt starts with `/skill:<name>` and matches a skill advertised
		// for this session, rewrite the turn to inject the skill content.
		const skillRewrite = await tryParseSkillCommand(text, entry.skillCommands)
		if (skillRewrite) {
			text = buildSkillCommandPrompt(skillRewrite)
		}

		// Extract image blocks from the prompt only if model supports vision.
		const images: ImageContent[] = supportsImages ? extractImages(params.prompt) : []
		// Image blocks a text-only model cannot take: the turn is refused, not
		// sent text-only — sending it would spend a model turn answering a prompt
		// missing its attached context, and the TUI vision gate never silently
		// submits text-only either. The client is informed exactly once per turn
		// as ordinary assistant text via the standard agent_message_chunk schema
		// (ACP has no dedicated warning channel), with its own km.-prefixed message
		// id plus a trailing blank line so clients that concatenate chunks keep it
		// visually separate.
		const droppedImages = supportsImages ? 0 : params.prompt.filter((b) => b.type === "image").length
		if (droppedImages > 0) {
			const noun = droppedImages === 1 ? "image" : "images"
			const modelId = entry.session.model?.id ?? "The current model"
			process.stderr.write(
				`acp prompt: refusing prompt with ${droppedImages} ${noun} (active model has no vision input)\n`,
			)
			this.send({
				sessionId: params.sessionId,
				update: {
					sessionUpdate: "agent_message_chunk",
					messageId: `km.${randomUUID()}`,
					content: {
						type: "text",
						text: `${modelId} does not accept image input — switch to a model with image support or remove the ${noun} and resend.\n\n`,
					},
				},
			})
			// Nothing reaches the session — the turn is refused without a model call.
			return { stopReason: "refusal" }
		}
		if (!text && images.length === 0) {
			return { stopReason: "end_turn" }
		}
		let turnResolve!: (r: PromptResponse) => void
		let turnReject!: (e: unknown) => void
		const result = new Promise<PromptResponse>((resolve, reject) => {
			turnResolve = resolve
			turnReject = reject
		})
		entry.turn = {
			cancelled: false,
			hiddenToolCallIds: new Set(),
			announcedToolCallIds: new Set(),
			lastStreamedContent: new Map(),
			preWriteContents: new Map(),
			pendingFileChanges: new Map(),
			usage: emptyTurnUsage(),
			resolve: turnResolve,
			reject: turnReject,
		}
		// Kick off session.prompt but don't await inside the async function body —
		// shutdown() needs to be able to reject `result` and have the caller's await
		// on prompt() settle immediately, which can't happen while this body is
		// paused on `await session.prompt()`. Instead, attach handlers that drive
		// finalizeTurn/failTurn and return `result` directly; settling `result`
		// propagates to the caller regardless of whether session.prompt ever resolves.
		entry.session.prompt(text, { source: "rpc", images }).then(
			() => {
				// session.prompt() is the source of truth for "turn is done". We
				// deliberately do NOT finalize on agent_end: pi-mono's _runAgentPrompt
				// (agent-session.js) chains multiple agent.prompt / agent.continue
				// calls — each emits its own agent_start + agent_end — when retries,
				// queued follow-up messages, or compaction are pending. If we finalized
				// on the first agent_end, end_turn would be sent mid-stream and the
				// client's subsequent prompt would hit pi-mono's
				// "Agent is already processing" throw because session.prompt is still
				// running the chained continues. session.prompt() resolves only after
				// ALL chained calls complete.
				if (!entry.turn) return
				// Resolved with terminal "error" (retries exhausted): do not report
				// end_turn — the client would show a silent empty reply.
				if (entry.turn.lastAssistantError && !entry.turn.cancelled) {
					const terminal = entry.turn.lastAssistantError
					// Turn-time 401 = first proof this key is dead. Blame the
					// provider, not a key: the failing call may use config apiKey
					// or auth.json OAuth.
					if (isAuthRejectedMessage(terminal.errorMessage)) {
						markCredentialStale(undefined, entry.session.model?.provider ?? KIMCHI_PROVIDER_ID)
					}
					this.failTurn(entry, toTurnError(terminal))
				} else {
					this.finalizeTurn(entry, entry.turn.cancelled ? "cancelled" : "end_turn")
				}
			},
			(err) => {
				// If cancel() arrived mid-turn, session.prompt() may reject with an abort
				// error instead of resolving and letting agent_end drive finalization. The
				// spec still says the client-initiated cancel should surface as
				// stopReason: "cancelled", not a JSON-RPC error — so swallow the abort
				// and resolve with the expected stop reason. Any other error propagates.
				// shutdown() may have already failed the turn; failTurn is a no-op in that case.
				if (!entry.turn) return
				if (entry.turn.cancelled) {
					this.finalizeTurn(entry, "cancelled")
				} else {
					this.failTurn(entry, this.toAuthRequiredIfUnauthenticated(entry.session, err))
				}
			},
		)
		return result
	}

	async cancel(params: CancelNotification): Promise<void> {
		const entry = this.sessions.get(params.sessionId)
		if (!entry) return
		if (entry.turn) entry.turn.cancelled = true
		// Drain the steer/follow-up queue BEFORE awaiting the abort. pi-mono
		// chains queued steering messages into the running prompt —
		// session.prompt() resolves only after all chained calls — so awaiting
		// abort() first lets every still-queued steer self-deliver into history
		// with a full reply while we wait for idle. clearQueue() is synchronous,
		// so running it first drops undelivered steers before the chain can
		// drain them. Mirrors the TUI's Escape → clearAllQueues() behaviour.
		const droppedQueue = this.drainQueue(entry)
		notifyDroppedQueue(this.conn, params.sessionId, droppedQueue, "cancelled")
		await entry.session.abort()
	}

	async extMethod(method: string, params: Record<string, unknown>): Promise<Record<string, unknown>> {
		switch (method) {
			case AVAILABLE_EXT_METHODS.probe_mcp_server: {
				const result = await handleProbeMcpServer(this.mcpProbe, params)
				return result as Record<keyof ProbeResult, unknown>
			}
			case AVAILABLE_EXT_METHODS.auth_status:
				// Read the shared credential store per call so authenticate(),
				// unstable_logout(), and logins from other Kimchi surfaces are
				// reflected without a reconnect.
				return handleAuthStatus({
					authPath: join(this.agentDir, "auth.json"),
					modelsPath: join(this.agentDir, "models.json"),
				})
			case AVAILABLE_EXT_METHODS.set_onboarding_flag:
				// Write the shared config per call through the harness's
				// read-modify-write helper so sibling onboarding keys set by other
				// Kimchi surfaces survive.
				return handleSetOnboardingFlag({}, params)
			case AVAILABLE_EXT_METHODS.set_session_title:
				return handleSetSessionTitle((sessionId) => this.sessions.get(sessionId)?.session, params)
			case AVAILABLE_EXT_METHODS.steering:
				return handleSteering((sessionId) => {
					const entry = this.sessions.get(sessionId)
					if (!entry) return undefined
					// A cancelled turn stays defined until the prompt settles, but
					// cancel() has already drained its queue — a steer landing in this
					// window must not re-queue text that would leak into the next prompt.
					const turnActive = entry.turn !== undefined && !entry.turn.cancelled
					return { session: entry.session, turnActive }
				}, params)
			case AVAILABLE_EXT_METHODS.import_discover:
				// Sessionless, read-only source-app discovery for the import screen
				// (ADR-0043/ADR-0044): nothing is written to disk and no session is
				// touched. ImportDiscoverResult is a type alias, so it is directly
				// assignable to the string-indexed record the extMethod contract
				// wants — no cast, no spread.
				return importDiscover()
			case AVAILABLE_EXT_METHODS.import_apply:
				// Sessionless write half of the import (ADR-0043/ADR-0044): copies
				// selected skills into Kimchi's own skills dir, merges selected MCP
				// servers conservatively, and satisfies the migration marker. No
				// session is touched. The copied skills land in a watched root, so
				// the file watcher re-advertises palettes on its own.
				return { ...handleImportApply({ agentDir: this.agentDir }, params) }
			case AVAILABLE_EXT_METHODS.set_project_trust:
				// Session-scoped trust survey answer (LLM-3628): persists the
				// decision, opens the kimchi project-scope gate, and (on grant)
				// live-refreshes skills. See handleSetProjectTrust.
				return this.handleSetProjectTrust(params)
			case AVAILABLE_EXT_METHODS.get_path_trust:
				// Sessionless read (LLM-3628): resolved trust state for an
				// arbitrary path, incl. ancestor inheritance and the canonicalized
				// deciding entry. See handleGetPathTrust.
				return this.handleGetPathTrust(params)
			case AVAILABLE_EXT_METHODS.set_path_trust:
				// Sessionless write (LLM-3628): persist a trust/deny decision for
				// any path (root and home included — deliberate power-user
				// capability), then live-refresh affected sessions. See
				// handleSetPathTrust.
				return this.handleSetPathTrust(params)
			default:
				throw RequestError.methodNotFound(method)
		}
	}

	async shutdown(cause: "signal" | "disconnect" = "disconnect"): Promise<void> {
		if (this.shutdownPromise) return this.shutdownPromise
		this.shutdownPromise = this.doShutdown(cause)
		return this.shutdownPromise
	}

	private async doShutdown(_cause: "signal" | "disconnect"): Promise<void> {
		this.commandsRefresher.cancel()
		this.skillWatcher.close()
		// Drain any in-flight turn promises before tearing down the session.
		// On the signal path we process.exit immediately so this is mostly
		// cosmetic, but runAcpMode's finally also calls shutdown when conn.closed
		// resolves — in that window a pending PromptResponse would otherwise hang
		// until process exit. Reject symmetrically so the caller's await settles.
		for (const entry of this.sessions.values()) {
			if (entry.turn) this.failTurn(entry, new Error("acp agent shutting down"))
			unregisterAcpPrompter(entry.session.sessionId)
			unregisterSessionPermissionFlagController(entry.session.sessionId)
			clearPermissionModeEnv(entry.session.sessionId)
			const droppedQueue = this.drainQueue(entry)
			notifyDroppedQueue(this.conn, entry.session.sessionId, droppedQueue, "shutdown")
			await this.disposeSessionRecord(entry)
		}
		this.sessions.clear()
		resetAcpClientInfo()
	}

	private async closeSessionRecord(sessionId: string): Promise<void> {
		const entry = this.sessions.get(sessionId)
		if (!entry) return
		this.sessions.delete(sessionId)
		const droppedQueue = this.drainQueue(entry)
		notifyDroppedQueue(this.conn, sessionId, droppedQueue, "shutdown")
		unregisterAcpPrompter(sessionId)
		unregisterSessionPermissionFlagController(sessionId)
		clearPermissionModeEnv(sessionId)
		entry.unsubscribe()
		if (entry.turn) {
			entry.turn.cancelled = true
			try {
				await entry.session.abort()
			} catch {
				// Closing is best-effort cleanup; still resolve the pending prompt
				// as cancelled and release the session resources below.
			}
			this.finalizeTurn(entry, "cancelled")
		}
		await this.disposeSessionRecord(entry, { alreadyUnsubscribed: true })
	}

	/**
	 * Read-and-drain via clearQueue()'s return value. The previousQueue reset
	 * MUST precede clearQueue(): pi-mono dispatches queue_update synchronously
	 * (AgentSession._emit is a plain listener loop, and clearQueue/
	 * message_start-splice emit inline — verified in the bundled source), so
	 * the post-drain empty snapshot arrives before this method returns and
	 * diffs against `undefined` → zero consumed. Any pre-drain snapshot this
	 * drains reports is gone; there is no async buffer in which a stale
	 * queue_update could resurrect dropped messages.
	 */
	private drainQueue(entry: SessionRecord): {
		steering: string[]
		followUp: string[]
	} {
		entry.previousQueue = undefined
		return entry.session.clearQueue()
	}

	private async disposeSessionRecord(entry: SessionRecord, opts: DisposeSessionRecordOpts = {}): Promise<void> {
		entry.planTracker?.stop()
		if (!opts.alreadyUnsubscribed) entry.unsubscribe()
		// Emit session_shutdown to extensions and await all handlers before
		// calling dispose(). dispose() is synchronous and returns void, so async
		// extension handlers (e.g. telemetry drain, shutdown marker) would be
		// fire-and-forgotten if we relied on dispose() alone.
		await entry.session.extensionRunner?.emit({ type: "session_shutdown", reason: "quit" })
		entry.session.dispose()
		this.skillWatcher?.removeSession(entry)
	}

	private onSessionEvent(sessionId: string, event: AgentSessionEvent): void {
		const entry = this.sessions.get(sessionId)
		if (!entry) return
		const turn = entry.turn
		// Stall/retry/compaction events have no schema session-update type —
		// forward them as a kimchi.dev activity notification so the client can
		// pin a running turn's pause to its cause. No-op for transcript/tool
		// events, which carry their own schema updates.
		emitAgentActivityUpdate(this.conn, sessionId, event)
		switch (event.type) {
			case "queue_update": {
				if (!entry.previousQueue) {
					entry.previousQueue = { steering: [], followUp: [] }
				}
				const steering = reconcileQueue(entry.previousQueue.steering, event.steering)
				const followUp = reconcileQueue(entry.previousQueue.followUp, event.followUp)
				entry.previousQueue = {
					steering: steering.previousQueue,
					followUp: followUp.previousQueue,
				}
				for (const update of [...steering.sessionUpdates, ...followUp.sessionUpdates]) {
					this.send({ sessionId, update })
				}
				return
			}
			case "agent_start": {
				// New turn → contentIndex restarts from 0 and any in-flight tool
				// id mappings from the previous turn are stale (the calls either
				// ended or were orphaned). Wipe both maps so fresh allocations
				// don't reuse old ids.
				entry.contentIndexToBlockId.clear()
				entry.streamedText.clear()
				entry.toolCallIdMap.clear()
				return
			}
			case "message_start": {
				// New assistant message → contentIndex restarts from 0. Wipe the
				// per-message maps so a fresh block at index 0 gets a fresh id
				// (and no streamed prefix) instead of inheriting the previous
				// message's assignment.
				entry.contentIndexToBlockId.clear()
				entry.streamedText.clear()
				// A resolved pick may already be known here (e.g. restored from the
				// last session), so push the resolved label once per change so clients
				// showing the selected model reflect what the auto model chose.
				this.publishModelOptionIfChanged(sessionId, entry)
				return
			}
			case "message_update": {
				if (!turn) return
				const ame = event.assistantMessageEvent
				if ((ame.type === "text_delta" || ame.type === "thinking_delta") && ame.delta) {
					let messageId = entry.contentIndexToBlockId.get(ame.contentIndex)
					if (messageId === undefined) {
						messageId = `km.${entry.nextBlockId++}`
						entry.contentIndexToBlockId.set(ame.contentIndex, messageId)
					}
					this.send({
						sessionId,
						update: {
							sessionUpdate: ame.type === "text_delta" ? "agent_message_chunk" : "agent_thought_chunk",
							content: { type: "text", text: ame.delta },
							messageId,
						},
					})
					// Track streamed text length only — thinking is not restored at
					// message_end and must not be re-emitted from that path.
					if (ame.type === "text_delta") {
						const streamed = entry.streamedText.get(ame.contentIndex) ?? ""
						entry.streamedText.set(ame.contentIndex, streamed + ame.delta)
					}
				}

				// Tool call argument generation started — emit pending tool_call so
				// the client can show progress while the model streams the arguments.
				if (ame.type === "toolcall_start") {
					const block = ame.partial?.content?.[ame.contentIndex]
					if (block?.type === "toolCall" && block.id && block.name) {
						if (isHiddenToolCall(block.name, block.arguments)) {
							turn.hiddenToolCallIds.add(block.id)
							return
						}
						const update: SessionUpdate = buildToolCall({
							toolName: block.name,
							toolCallId: this.getOrAllocateAcpToolCallId(entry, block.id, block.name),
							piToolCallId: block.id,
							rawInput: block.arguments,
							// Arguments are still streaming: the call hasn't been approved or started
							// executing yet, so ACP status is `pending`, not `in_progress`.
							status: "pending",
						})
						this.send({ sessionId, update })
						turn.announcedToolCallIds.add(block.id)
					}
					return
				}

				// Progress streaming — emit the incremental content delta (just
				// the new characters) so the client can show a live preview without
				// re-sending the full arguments on every delta.
				if (ame.type === "toolcall_delta") {
					const block = ame.partial?.content?.[ame.contentIndex]
					if (
						block?.type === "toolCall" &&
						block.id &&
						turn.announcedToolCallIds.has(block.id) &&
						!turn.hiddenToolCallIds.has(block.id)
					) {
						const content = extractStreamContent(block.arguments)
						if (content) {
							const prev = turn.lastStreamedContent.get(block.id) ?? ""
							const delta = content.slice(prev.length)
							if (delta.length > 0) {
								turn.lastStreamedContent.set(block.id, content)
								const update: SessionUpdate = buildToolCallUpdate({
									toolCallId: this.getOrAllocateAcpToolCallId(entry, block.id, block.name),
									piToolCallId: block.id,
									rawOutput: { delta },
									_meta: { generatedChars: content.length },
									// Arguments are still streaming: the call hasn't been approved or started
									// executing yet, so ACP status is `pending`, not `in_progress`.
									status: "pending",
								})
								this.send({ sessionId, update })
							}
						}
					}
					return
				}

				// Argument generation finished — the pending tool_call sent at
				// toolcall_start carried partial (usually empty) arguments. Push the
				// complete rawInput now, before approval and tool_execution_start,
				// so clients can show the target (e.g. the path of an edit) during
				// the whole approval window instead of only once execution begins.
				if (ame.type === "toolcall_end") {
					const toolCall = ame.toolCall
					if (!toolCall?.id || !toolCall.name) return
					if (isHiddenToolCall(toolCall.name, toolCall.arguments)) {
						// Arguments revealed the call as hidden only at stream end (the
						// start event's partial arguments couldn't see it yet) — retire
						// the pending card that went out early. retireToolCall only
						// deletes keyed state (no id allocation, no emission), so this
						// is also safe for calls that were hidden at toolcall_start
						// and never announced.
						turn.hiddenToolCallIds.add(toolCall.id)
						this.retireToolCall(entry, turn, toolCall.id)
						return
					}
					if (!turn.announcedToolCallIds.has(toolCall.id) || turn.hiddenToolCallIds.has(toolCall.id)) {
						return
					}
					const { title, kind, locations } = describeToolCall(toolCall.name, toolCall.arguments)
					const update: SessionUpdate = buildToolCallUpdate({
						toolCallId: this.getOrAllocateAcpToolCallId(entry, toolCall.id, toolCall.name),
						piToolCallId: toolCall.id,
						title,
						kind,
						locations,
						rawInput: toolCall.arguments,
						// Arguments are complete but the call hasn't been approved or
						// started executing yet, so ACP status stays `pending`.
						status: "pending",
					})
					this.send({ sessionId, update })
				}

				return
			}
			case "message_end": {
				if (!turn) return
				const msg = event.message
				if (msg.role !== "assistant") return
				// The pick is learned from this message (responseModel), after
				// message_start — push the resolved label here too. Idempotent: the
				// lastModelOptionName seed makes this a no-op unless the label changed.
				this.publishModelOptionIfChanged(sessionId, entry)
				// Terminal-error tracking for the finalize path: only the LAST
				// assistant message's stopReason decides the turn outcome.
				// StopReason (pi-ai): error → record; aborted → leave (finalization
				// reads entry.turn.cancelled instead); anything else (stop, length,
				// toolUse, deferred) → a completed message, clear. A failed attempt
				// pi auto-retries is superseded by the retry's message_end, which
				// lands here and clears the flag.
				if (msg.stopReason === "error") {
					turn.lastAssistantError = { stopReason: "error", errorMessage: msg.errorMessage }
				} else if (msg.stopReason !== "aborted") {
					turn.lastAssistantError = undefined
				}
				// Emit whatever text a block carries that streaming never sent —
				// an extension can zero text_delta while streaming and restore the
				// text only in message_end's returned message (Ferment V2 does
				// this for any message that isn't an unaccepted completion
				// candidate), and a provider can emit a text block with no
				// incremental deltas at all. In the normal fully-streamed case
				// sent === block.text.length for every block, so nothing extra
				// goes out here. Emitted before usage accounting so ordering
				// relative to emitUsageUpdate is unchanged.
				if (Array.isArray(msg.content)) {
					msg.content.forEach((block, index) => {
						if (block.type !== "text") return
						const streamed = entry.streamedText.get(index) ?? ""
						if (block.text === streamed || (streamed && !block.text.startsWith(streamed))) return
						let messageId = entry.contentIndexToBlockId.get(index)
						if (messageId === undefined) {
							messageId = `km.${entry.nextBlockId++}`
							entry.contentIndexToBlockId.set(index, messageId)
						}
						this.send({
							sessionId,
							update: {
								sessionUpdate: "agent_message_chunk",
								content: { type: "text", text: block.text.slice(streamed.length) },
								messageId,
							},
						})
						entry.streamedText.set(index, block.text)
					})
				}
				const usage = msg.usage
				if (usage) {
					updateTurnUsage(turn, usage)
					// Live context-window refresh: a message_end carrying usage means
					// the session's estimate just moved. Emit here (subject to
					// emitUsageUpdate's undefined/null skip) so clients track the
					// context window across chained steps, not just at turn end.
					this.emitUsageUpdate(entry.session, turn.usage)
				}
				return
			}
			case "tool_execution_start": {
				// Symmetry with the other turn-lifecycle branches: if the turn was
				// already finalized (e.g., shutdown cleared it), don't emit stray
				// tool_call notifications the client would have to reconcile against
				// a turn it already considers over.
				if (!turn) return
				if (isHiddenToolCall(event.toolName, event.args)) {
					turn.hiddenToolCallIds.add(event.toolCallId)
					// A hidden call may already have an allocated ACP id if the permission
					// prompter ran before we knew it was hidden — retire its state.
					this.retireToolCall(entry, turn, event.toolCallId)
					return
				}
				// Capture the diff data now — tool_execution_end carries no args.
				// For `write` the pre-existing content must be read before the tool
				// runs; afterwards the file already holds the new content.
				const fileChanges = collectFileChanges(event.toolName, event.args, entry.cwd, turn, event.toolCallId)
				if (fileChanges.length > 0) {
					turn.pendingFileChanges.set(event.toolCallId, fileChanges)
				}
				const acpToolCallId = this.getOrAllocateAcpToolCallId(entry, event.toolCallId, event.toolName)
				if (turn.announcedToolCallIds.has(event.toolCallId)) {
					// Pending tool_call was already sent via toolcall_start → emit update
					const { title, kind, locations } = describeToolCall(event.toolName, event.args)
					const update: SessionUpdate = buildToolCallUpdate({
						toolCallId: acpToolCallId,
						piToolCallId: event.toolCallId,
						title,
						kind,
						locations,
						rawInput: event.args,
						status: "in_progress",
					})
					this.send({ sessionId, update })
				} else {
					const update: SessionUpdate = buildToolCall({
						toolCallId: acpToolCallId,
						piToolCallId: event.toolCallId,
						toolName: event.toolName,
						rawInput: event.args,
						status: "in_progress",
					})
					// No pending notification was sent (back-compat) → emit tool_call as before
					this.send({ sessionId, update })
				}
				return
			}
			case "tool_execution_update": {
				if (!turn) return
				if (turn.hiddenToolCallIds.has(event.toolCallId) || isHiddenToolCall(event.toolName, event.args)) {
					turn.hiddenToolCallIds.add(event.toolCallId)
					// A hidden call may already have an allocated ACP id if the permission
					// prompter ran before we knew it was hidden — retire its state.
					this.retireToolCall(entry, turn, event.toolCallId)
					return
				}
				const acpToolCallId = this.resolveAcpToolCallId(entry, event.toolCallId)
				const partial = toolResultContent(event.partialResult)
				if (partial.length === 0) return
				const update: SessionUpdate = buildToolCallUpdate({
					toolCallId: acpToolCallId,
					piToolCallId: event.toolCallId,
					content: partial,
					status: "in_progress",
				})
				this.send({ sessionId, update })
				return
			}
			case "tool_execution_end": {
				if (!turn) return
				if (turn.hiddenToolCallIds.has(event.toolCallId)) {
					this.retireToolCall(entry, turn, event.toolCallId, { removeFromHidden: true })
					return
				}
				// Consume the per-call capture so a later turn reusing the id (or a
				// retried call) can't leak stale diff data across tool calls.
				const pending = turn.pendingFileChanges.get(event.toolCallId) ?? []
				turn.pendingFileChanges.delete(event.toolCallId)
				const preWrite = turn.preWriteContents.get(event.toolCallId)
				turn.preWriteContents.delete(event.toolCallId)
				// Diffs are additional content blocks, appended after the existing
				// text/image content. Failed mutations emit no diff: the client
				// would otherwise render a change that never landed.
				const diffs = event.isError ? [] : pending.map((p) => fileChangeToDiffContent(resolveFileChange(p, preWrite)))
				const acpToolCallId = this.resolveAcpToolCallId(entry, event.toolCallId)
				const update: SessionUpdate = buildToolCallUpdate({
					toolCallId: acpToolCallId,
					piToolCallId: event.toolCallId,
					status: event.isError ? "failed" : "completed",
					content: [...toolResultContent(event.result), ...diffs],
					rawOutput: event.result,
				})
				this.send({ sessionId, update })
				// Upstream ids can repeat after compaction or even within a turn. Retire
				// all state keyed on this upstream id so a future call reusing it starts
				// with a fresh ACP id and clean streaming/announcement state.
				this.retireToolCall(entry, turn, event.toolCallId, { removeFromHidden: true })
				return
			}
			case "session_info_changed": {
				const name = event.name
				if (!name) return
				this.send({
					sessionId,
					update: {
						sessionUpdate: "session_info_update",
						title: name,
					},
				})
				return
			}
			default:
				return
		}
	}

	// Replay: walk the persisted transcript on the leaf path and emit
	// session/update notifications per content block — text, thinking, tool
	// calls. Tool results are paired with their originating toolCall by id so
	// the historical tool render shape (tool_call + terminal tool_call_update)
	// matches what live turns produce. Compaction / branch_summary /
	// model_change / custom entries emit nothing — using getBranch() (raw
	// entries) instead of buildSessionContext() avoids surfacing compaction
	// summaries as synthetic user messages.
	//
	// Notifications go straight from this method to conn.sessionUpdate; we do
	// NOT replay through the AgentSession event emitter, so extensions like
	// telemetryExtension don't double-count historical turns.
	private replayTranscript(session: AgentSession): void {
		const sessionId = session.sessionId
		const entries = session.sessionManager.getBranch()
		const toolResults = collectToolResults(entries)

		for (const entry of entries) {
			if (!entry || typeof entry !== "object" || entry.type !== "message") continue
			const msg = entry.message
			if (msg.role === "user") {
				const text = userMessageText(msg.content)
				if (!text) continue
				this.send({
					sessionId,
					update: {
						sessionUpdate: "user_message_chunk",
						content: { type: "text", text },
					},
				})
			} else if (msg.role === "assistant") {
				this.replayAssistantBlocks(sessionId, msg.content, toolResults, this.sessions.get(sessionId))
			}
			// toolResult: handled inline alongside its originating toolCall above.
		}
	}

	/**
	 * Walk the persisted branch and count how many ACP content chunks the
	 * replay would emit (text segments + dimmed text parts + non-redacted
	 * thinking blocks). Sets `record.nextBlockId` so that:
	 *   - replayTranscript emits the same messageIds a live turn would have
	 *     for the historical blocks, and
	 *   - any new block the user creates after the load gets a fresh, non-
	 *     colliding id.
	 *
	 * Mirrors replayAssistantBlocks' emission logic exactly — coalescing
	 * contiguous text blocks into one chunk, and gating thinking emission on
	 * the hideThinkingBlock setting. If these drift, messageIds replayed
	 * after a load won't line up with what the client saw during the live
	 * turn.
	 */
	private seedBlockCounterFromBranch(session: AgentSession, record: SessionRecord): void {
		const entries = session.sessionManager.getBranch()

		let count = 0
		for (const entry of entries) {
			if (entry?.type !== "message" || entry.message.role !== "assistant") continue

			let inTextSegment = false
			const countTextSegment = () => {
				if (!inTextSegment) {
					count++
					inTextSegment = true
				}
			}

			const content = entry.message.content
			for (const block of content) {
				if (block.type === "text") {
					if (!block.text) continue
					countTextSegment()
					for (const part of replayTextParts(block.text)) {
						if (part.kind === "thinking") count++
					}
				} else if (block.type === "thinking") {
					inTextSegment = false
					if (block.redacted || !block.thinking) continue
					count++
				} else {
					// toolCall / unknown: replay flushes the text buffer before
					// emitting the structural block, which terminates any open
					// text segment.
					inTextSegment = false
				}
			}
		}
		record.nextBlockId = count + 1
	}

	private replayAssistantBlocks(
		sessionId: string,
		content: AssistantMessage["content"],
		toolResults: Map<string, ReplayToolResult>,
		record: SessionRecord | undefined,
	): void {
		if (!Array.isArray(content)) return
		// Allocates a fresh session-unique messageId for every emitted chunk
		// and leaves it off the wire if the SessionRecord isn't loaded (e.g.
		// the unit-test harness wiring a partial replay path).
		const nextMessageId = () => {
			if (!record) return undefined
			return `km.${record.nextBlockId++}`
		}
		// Buffer contiguous text blocks so a single assistant message renders as
		// one agent_message_chunk per natural text segment — emit the full
		// message as a single chunk, no per-token chunking. When a thinking or
		// toolCall block interrupts the run, flush the buffered text first so
		// ordering relative to those structural blocks is preserved.
		let textBuffer = ""
		const flushText = () => {
			if (textBuffer.length === 0) return
			const messageId = nextMessageId()
			this.send({
				sessionId,
				update: {
					sessionUpdate: "agent_message_chunk",
					content: { type: "text", text: textBuffer },
					...(messageId !== undefined ? { messageId } : {}),
				},
			})
			textBuffer = ""
		}
		for (const block of content) {
			if (!block || typeof block !== "object") continue
			const b = block
			if (b.type === "text") {
				const text = (b as { text?: unknown }).text
				if (typeof text !== "string" || text.length === 0) continue
				for (const part of replayTextParts(text)) {
					if (part.kind === "text") {
						textBuffer += part.text
					} else if (part.kind === "thinking") {
						flushText()
						const messageId = nextMessageId()
						this.send({
							sessionId,
							update: {
								sessionUpdate: "agent_thought_chunk",
								content: { type: "text", text: part.text },
								...(messageId !== undefined ? { messageId } : {}),
							},
						})
					}
				}
			} else if (b.type === "thinking") {
				flushText()
				const thinking = (b as { thinking?: unknown; redacted?: unknown }).thinking
				const redacted = (b as { redacted?: unknown }).redacted === true
				// Redacted thinking has no plaintext to surface — the encrypted
				// payload only matters for multi-turn provider continuity.
				if (redacted || typeof thinking !== "string" || thinking.length === 0) continue
				const messageId = nextMessageId()
				this.send({
					sessionId,
					update: {
						sessionUpdate: "agent_thought_chunk",
						content: { type: "text", text: stripAnsi(thinking) },
						...(messageId !== undefined ? { messageId } : {}),
					},
				})
			} else if (b.type === "toolCall") {
				flushText()
				const tc = b
				const upstreamId = typeof tc.id === "string" ? tc.id : undefined
				const name = typeof tc.name === "string" ? tc.name : undefined
				if (!upstreamId || !name) continue
				const args = (tc.arguments ?? {}) as Record<string, unknown>
				if (isHiddenToolCall(name, args)) continue
				const acpToolCallId = record ? this.getOrAllocateAcpToolCallId(record, upstreamId, name) : upstreamId
				const result = toolResults.get(upstreamId)
				// No persisted result → the call never finished (interrupted mid
				// turn). "failed" is the closest terminal status; leaving the call
				// in_progress would hang the client's spinner forever on replay.
				const status: "completed" | "failed" = result ? (result.isError ? "failed" : "completed") : "failed"
				this.send({
					sessionId,
					update: buildToolCall({
						toolName: name,
						toolCallId: acpToolCallId,
						piToolCallId: tc.id,
						status,
						rawInput: args,
					}),
				})
				this.send({
					sessionId,
					update: buildToolCallUpdate({
						toolCallId: acpToolCallId,
						piToolCallId: tc.id,
						status,
						content: result ? toolResultContent(result) : [],
						rawOutput: result,
					}),
				})
				// The branch may contain multiple toolCalls with the same upstream id
				// (e.g., across a compaction boundary). Drop the mapping after replaying
				// each call so the next one with the same upstream id gets a fresh id.
				record?.toolCallIdMap.delete(upstreamId)
			}
		}
		// Trailing text after the last structural block (or a text-only message)
		// still needs to land — flushText is a no-op when the buffer is empty.
		flushText()
	}

	/**
	 * Re-publish the session's config options when the model option's name has
	 * changed since the last push — which happens when the Auto router resolves
	 * a concrete model and the label becomes `Auto (<id>)`.
	 *
	 * No-op for concrete and unresolved selections, so a session that never uses
	 * Auto sends nothing extra — which relies on session creation/load seeding
	 * `lastModelOptionName` with the label the client already received.
	 */
	private publishModelOptionIfChanged(sessionId: string, entry: SessionRecord): void {
		const configOptions = buildConfigOptions(entry.session, this.getInitialPermissionMode(entry.session).mode)
		const autoName = autoOptionName(configOptions)
		if (!autoName || autoName === entry.lastModelOptionName) return
		entry.lastModelOptionName = autoName
		this.send({ sessionId, update: { sessionUpdate: "config_option_update", configOptions } })
	}

	private send(params: SessionNotification): void {
		// Fire-and-forget is safe here because the ACP SDK chains every outbound
		// message onto a shared writeQueue Promise (see @agentclientprotocol/sdk
		// acp.js#sendMessage), so two consecutive sessionUpdate() calls are
		// written to the stream in the order we invoked them even though we
		// don't await. Do NOT "fix" this into `await this.conn.sessionUpdate(...)`
		// in onSessionEvent — the subscriber is called synchronously from the
		// AgentSession event emitter, and awaiting inside it would back-pressure
		// every subsequent event through the event loop, which pi-mono's
		// _processAgentEvent does not expect.
		this.conn.sessionUpdate(params).catch((err: unknown) => {
			process.stderr.write(`acp sessionUpdate failed: ${String(err)}\n`)
		})
	}

	/**
	 * Return the existing ACP toolCallId for an upstream id, allocating a fresh
	 * session-unique id if none exists. Permission prompts fire before
	 * `tool_execution_start`, so this ensures the permission request and the
	 * subsequent tool_call notification share the same id.
	 */
	private getOrAllocateAcpToolCallId(record: SessionRecord, piToolCallId: string, toolName: string): string {
		let acpId = record.toolCallIdMap.get(piToolCallId)
		if (acpId === undefined) {
			acpId = buildToolCallId(toolName, record.nextToolCallId++)
			record.toolCallIdMap.set(piToolCallId, acpId)
		}
		return acpId
	}

	/**
	 * Look up the ACP toolCallId for an in-flight upstream call. Falls back to
	 * the upstream id if no mapping exists (defensive: should only happen for
	 * events that arrived before their start, which pi-mono does not emit).
	 */
	private resolveAcpToolCallId(record: SessionRecord, piToolCallId: string): string {
		return record.toolCallIdMap.get(piToolCallId) ?? piToolCallId
	}

	/**
	 * Retire all per-call state keyed on an upstream toolCallId.
	 *
	 * Upstream ids are provider-supplied and can repeat within a turn (e.g. after
	 * compaction). Leaving stale entries in `announcedToolCallIds` or
	 * `lastStreamedContent` causes corrupted deltas or updates for ids the client
	 * never saw when the id is reused.
	 */
	private retireToolCall(
		record: SessionRecord,
		turn: TurnContext,
		piToolCallId: string,
		opts: RetireToolCallOpts = {},
	): void {
		record.toolCallIdMap.delete(piToolCallId)
		turn.announcedToolCallIds.delete(piToolCallId)
		turn.lastStreamedContent.delete(piToolCallId)
		if (opts.removeFromHidden) {
			turn.hiddenToolCallIds.delete(piToolCallId)
		}
	}

	/**
	 * Broadcast the command palette AFTER the pending session/new or
	 * session/load response, not while the handler is still building it. The
	 * SDK writes the response only once the handler's returned promise
	 * resolves, so sending inside the handler puts the notification on the
	 * wire BEFORE the client learns the session id — and clients drop
	 * session/update notifications for sessions they haven't registered yet
	 * (https://github.com/zed-industries/zed/issues/53161). A setImmediate
	 * macrotask outlasts the SDK's response-writing microtask chain, and the
	 * outbound writeQueue then keeps notification after response (see `send`),
	 * so the update lands strictly after the response.
	 *
	 * This is the ecosystem-wide pattern: the reference claude-agent-acp
	 * adapter defers with setTimeout(0) under a "Needs to happen after we
	 * return the session" comment (with the same dead-session guard)
	 * (https://github.com/agentclientprotocol/claude-agent-acp/blob/main/src/acp-agent.ts),
	 * and prime-agent (https://github.com/PrimeIntellect-ai/prime-agent/pull/1308),
	 * pi-acp, and hermes-agent all schedule the same way.
	 */
	private scheduleAvailableCommandsUpdate(sessionId: string): void {
		setImmediate(() => {
			// The session may have been torn down between the response and
			// the deferred send (e.g. instant disconnect); don't broadcast a
			// palette for a dead session.
			const record = this.sessions.get(sessionId)
			if (!record) return
			this.send({
				sessionId,
				update: {
					sessionUpdate: "available_commands_update",
					availableCommands: composeAvailableCommands(record.skillCommands),
				},
			})
		})
	}

	/**
	 * Push the session's project-trust state to the client after the
	 * session/new (or loadSession) response — same setImmediate-after-response
	 * pattern and for the same reason as scheduleAvailableCommandsUpdate: a
	 * client drops notifications for sessions it hasn't registered yet.
	 *
	 * Delivered as a `_kimchi.dev/project_trust_update` extNotification (the
	 * SDK's SessionUpdate union cannot carry a custom kind); unaware clients
	 * ignore unknown ext notifications per JSON-RPC rules, so this is purely
	 * additive.
	 */
	private scheduleProjectTrustUpdate(sessionId: string): void {
		setImmediate(() => {
			const record = this.sessions.get(sessionId)
			if (!record) return
			notifyProjectTrustUpdate(this.conn, buildProjectTrustUpdate(sessionId, record.cwd))
		})
	}

	/**
	 * `_kimchi.dev/set_project_trust` — record the client's trust-survey answer
	 * for the session's project (LLM-3628).
	 *
	 * - "trust" / "deny_persist" persist via pi's ProjectTrustStore (canonical
	 *   keying is the store's job — the /var vs /private/var trap lives there).
	 * - "trust_parent" mirrors the TUI's "Trust parent folder" option exactly:
	 *   it persists { [parent]: true, [cwd]: null } (one level up — the same
	 *   single-level semantics pi's getProjectTrustOptions offers) and the
	 *   clearing write keeps the parent's grant the nearest entry for the cwd.
	 *   Sessions under that parent are refreshed and notified too.
	 * - "trust_session" opens the gate for this connection only — the mirror
	 *   of "deny": skills load live, but nothing is stored and the next
	 *   session asks again.
	 * - "deny" keeps the decision in-memory for this connection only.
	 * - The kimchi project-scope gate is updated immediately, and the skill
	 *   palette + system-prompt skill list refresh live on BOTH grant and
	 *   revoke (no session restart): the refresher sweep re-runs
	 *   resources_discover per session, and the per-loader skill-list block
	 *   cache is invalidated so the next prompt rebuild advertises (or
	 *   drops) the project skills.
	 * - "deny" does NOT override an existing persisted grant for the cwd: it
	 *   is meaningful only for a previously-undecided project, keeping this
	 *   connection untrusted while the stored decision (if any) keeps
	 *   governing new sessions. To override a stored grant, the client must
	 *   send "deny_persist".
	 * - Other gated categories (project config, .pi settings) keep applying on
	 *   the next session; the returned `blocked` list tells the client what.
	 */
	private async handleSetProjectTrust(params: Record<string, unknown>): Promise<Record<string, unknown>> {
		const sessionId = params.sessionId
		if (typeof sessionId !== "string" || sessionId.length === 0) {
			throw RequestError.invalidParams(undefined, "sessionId must be a non-empty string")
		}
		const record = this.sessions.get(sessionId)
		if (!record) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${sessionId}`)
		}
		const decision = parseProjectTrustDecision(params.decision)
		const trusted = decision === "trust" || decision === "trust_session" || decision === "trust_parent"
		const cwd = record.cwd

		// The directory whose stored decision governs the requesting session —
		// the cwd for every decision except trust_parent, which grants the
		// parent. Also the subtree of live sessions that must be notified and
		// refreshed: trust is per-directory, not per-session, and the gate
		// lookup walks ancestors, so a parent grant covers sibling sessions
		// under it too.
		let affectedRoot = cwd
		if (decision === "trust_parent") {
			const parent = parentTrustPath(cwd)
			if (parent === undefined) {
				throw RequestError.invalidParams(undefined, "session cwd is at the filesystem root; no parent to trust")
			}
			// Same update shape pi's "Trust parent folder" option writes
			// (getProjectTrustOptions): grant the parent, clear any decision
			// pinned on the cwd so the parent's is the nearest entry.
			new ProjectTrustStore(this.agentDir).setMany([
				{ path: parent, decision: true },
				{ path: cwd, decision: null },
			])
			setProjectScopeTrusted(parent, true)
			affectedRoot = parent
		} else if (decision === "trust") {
			new ProjectTrustStore(this.agentDir).set(cwd, true)
			setProjectScopeTrusted(cwd, true)
		} else if (decision === "deny_persist") {
			new ProjectTrustStore(this.agentDir).set(cwd, false)
			setProjectScopeTrusted(cwd, false)
		} else {
			// "trust_session" / "deny": in-memory only, nothing persisted. Scope
			// caveat: the gate pin is keyed by cwd in the process-wide map
			// (src/project-scope-trust.ts), not by session — so a second session
			// on the SAME cwd shares the decision, and a new session at that cwd
			// re-pins fail-closed at start (createSessionSettings), stomping a
			// prior trust_session grant. Session-granular pins are a known v1
			// limitation; only different-cwd sessions are isolated.
			setProjectScopeTrusted(cwd, trusted)
		}

		// Session start pins a fail-closed decision on the session cwd when the
		// project is undecided — and the ancestor-walking lookup would find that
		// pin BEFORE the decision just recorded on affectedRoot, shadowing it
		// (the in-memory analogue of why pi's "Trust parent folder" clears the
		// cwd's store entry with `decision: null`). The sweep below re-mirrors
		// every live session's pin from the store so the walk resolves through
		// the new decision. Session-scoped decisions (trust_session/deny) live
		// only in this in-memory map — the store has no entry for them — so the
		// requester's own cwd is overridden with the in-memory decision instead
		// of a store lookup. Sessions AT affectedRoot are included: without
		// them a session pinned untrusted at the parent would keep shadowing a
		// trust_parent grant.
		this.refreshTrustAffectedSessions(
			new ProjectTrustStore(this.agentDir),
			affectedRoot,
			trusted,
			decision === "trust_session" || decision === "deny" ? { cwd, trusted } : undefined,
		)

		const update = buildProjectTrustUpdate(sessionId, cwd)
		return { trusted: update.trusted, blocked: [...update.blocked] }
	}

	/**
	 * `_kimchi.dev/get_path_trust` — sessionless resolved trust state for an
	 * arbitrary path (LLM-3628). Runs the store's nearest-wins ancestor walk,
	 * so an inherited ancestor grant reads as trusted with the ancestor as
	 * `decisionSource`; undecided paths report decided:false (fail-closed).
	 * Clients should prefer this over reading trust.json by hand — the store's
	 * canonicalized keys make hand-editing fragile (trailing slashes and
	 * /var-vs-/private/var paths silently never match).
	 */
	private handleGetPathTrust(params: Record<string, unknown>): Record<string, unknown> {
		const path = requireAbsolutePath(params.path)
		return pathTrustResponse(buildPathTrustInfo(new ProjectTrustStore(this.agentDir), path))
	}

	/**
	 * `_kimchi.dev/set_path_trust` — sessionless write for an arbitrary path
	 * (LLM-3628). Persists trust/deny through ProjectTrustStore (which
	 * canonicalizes the key — the supported write path for this file), then
	 * live-refreshes every session under the path: gate update, fail-closed
	 * pin clearing beneath on grant, watcher root re-derivation, refresher
	 * sweep, and a project_trust_update push per affected session. Any path is
	 * accepted, home and filesystem root included — a deliberate power-user
	 * capability; callers own the blast radius.
	 *
	 * Known v1 limitation: no "remove" — a written entry can be flipped but
	 * not forgotten (hand-editing trust.json is the only escape, and fragile).
	 */
	private handleSetPathTrust(params: Record<string, unknown>): Record<string, unknown> {
		const path = requireAbsolutePath(params.path)
		const decision = parsePathTrustDecision(params.decision)
		const trusted = decision === "trust"

		const store = new ProjectTrustStore(this.agentDir)
		store.set(path, trusted)
		setProjectScopeTrusted(path, trusted)

		// Re-resolve every live session under the written path FROM THE STORE.
		// A session pinned at start (from the store state then) can shadow the
		// new entry: its own pin is nearer in the ancestor walk than the path
		// just written, so a later revoke at the root would be invisible to it
		// — and a blind clear would equally break a deeper stored grant. Setting
		// each pin to the store's current nearest-wins resolution for that
		// session's cwd (or clearing it when undecided, so the walk falls
		// through to the written entry) mirrors store semantics exactly.
		this.refreshTrustAffectedSessions(store, path, trusted)

		return pathTrustResponse(buildPathTrustInfo(store, path))
	}

	/**
	 * Shared tail of every trust write (`set_project_trust`, `set_path_trust`):
	 * re-mirror the in-memory gate pins of every live session under `root`
	 * (inclusive) from `store`'s nearest-wins resolution, then notify and
	 * refresh those sessions.
	 *
	 * Pin mirroring is store-backed, not clear-on-grant: session start pins a
	 * fail-closed decision on the session cwd when the project is undecided,
	 * and that pin is NEARER in the ancestor walk than any decision later
	 * recorded on an ancestor — it would shadow a grant at or above the root
	 * (the in-memory analogue of why pi's "Trust parent folder" clears the
	 * cwd's store entry with `decision: null`). A blind clear on grant is
	 * equally wrong: a deeper stored grant must keep winning over a new
	 * ancestor revoke (the set_path_trust e2e caught exactly that stale-pin
	 * bug). Setting each pin to `store.getEntry(session.cwd)?.decision` — or
	 * clearing it when null, so the walk falls through to the new entry —
	 * makes the pins exactly mirror store inheritance. Sessions AT `root`
	 * itself are included.
	 *
	 * `inMemoryOverride` covers session-scoped decisions (trust_session/deny):
	 * they exist only in this in-memory map, the store has no entry for them,
	 * so the session whose cwd matches is pinned to the in-memory decision
	 * instead of a store lookup.
	 *
	 * `commandsRefresher.request()` is load-bearing: a trust decision is not a
	 * filesystem event, so the watcher cannot fire on its own, and the
	 * palette must never advertise skills the gate will now refuse to load.
	 * The sweep's reloadSkillCommandsMap invalidates each session's cached
	 * system-prompt block after its loader reload, so the next prompt rebuild
	 * matches the new gate state. Notifications are pushed per affected
	 * session (grant AND revoke alike) — every connected client showing trust
	 * state needs the fresh push, not just the requester.
	 */
	private refreshTrustAffectedSessions(
		store: ProjectTrustStore,
		root: string,
		grant: boolean,
		inMemoryOverride?: { cwd: string; trusted: boolean },
	): void {
		for (const other of this.sessions.values()) {
			if (!isPathWithin(other.cwd, root)) continue
			if (inMemoryOverride && other.cwd === inMemoryOverride.cwd) {
				setProjectScopeTrusted(other.cwd, inMemoryOverride.trusted)
				continue
			}
			const entry = store.getEntry(other.cwd)
			if (entry === null) clearProjectScopeTrust(other.cwd)
			else setProjectScopeTrusted(other.cwd, entry.decision)
		}
		for (const [id, other] of this.sessions) {
			if (!isPathWithin(other.cwd, root)) continue
			notifyProjectTrustUpdate(this.conn, buildProjectTrustUpdate(id, other.cwd))
		}
		if (grant) {
			// The watcher's root set must be re-derived on grant: while
			// untrusted, the project skills dir was never added to the watch set,
			// so without refresh() post-grant edits to project skills would never
			// re-advertise palettes. (Roots only grow; revoke keeps watching —
			// see skill-watcher's roots-never-removed note.)
			this.skillWatcher.refresh()
		}
		this.commandsRefresher.request()
	}

	private emitUsageUpdate(session: AgentSession, lifetime: TurnUsage): void {
		const ctx = session.getContextUsage()
		// Per the issue doc: skip when getContextUsage() returns undefined or
		// tokens is null (e.g. right after compaction). ACP requires both `used`
		// and `size`, so there is no null-safe emission.
		if (!ctx || ctx.tokens === null) return
		// Piggyback the turn's cumulative lifetime token totals on the
		// notification via _meta — usage_update's used/size only describe the
		// context window, so long-running remote clients would otherwise see no
		// token consumption until the PromptResponse resolves. Cumulative (not
		// per-update) totals keep client-side delta computation idempotent across
		// session/load replays.
		const usageMeta =
			lifetime.messages > 0
				? {
						input: lifetime.input,
						output: lifetime.output,
						cacheRead: lifetime.cacheRead,
						cacheWrite: lifetime.cacheWrite,
					}
				: undefined
		this.send({
			sessionId: session.sessionId,
			...(usageMeta ? { _meta: { [ACP_LIFETIME_USAGE_META_KEY]: usageMeta } } : {}),
			update: {
				sessionUpdate: "usage_update",
				used: ctx.tokens,
				size: ctx.contextWindow,
			},
		})
	}

	private finalizeTurn(entry: SessionRecord, stopReason: PromptResponse["stopReason"]): void {
		const turn = entry.turn
		if (!turn) return
		entry.turn = undefined
		try {
			this.emitUsageUpdate(entry.session, turn.usage)
		} finally {
			const response: PromptResponse = { stopReason }
			// usage is v1/experimental-only on PromptResponse (v2 drops it in favor
			// of usage_update session events) and is omitted when the turn produced
			// no usage data (e.g. cancelled before the first assistant message).
			// totalTokens is emitted because the pinned ACP SDK's experimental Usage
			// type marks it required, even though the ticket's v1 field table drops it.
			if (turn.usage.messages > 0) {
				const u = turn.usage
				response.usage = {
					inputTokens: u.input,
					outputTokens: u.output,
					cachedReadTokens: u.cacheRead,
					cachedWriteTokens: u.cacheWrite,
					...(u.sawReasoning ? { thoughtTokens: u.reasoning } : {}),
					totalTokens: u.total,
				}
			}
			turn.resolve(response)
		}
	}

	/**
	 * Convert pi's plain "No API key" prompt rejection into ACP authRequired
	 * (-32000) so clients route to their login UI instead of an opaque generic
	 * error (-32603). Detection consults the registry's credential state rather
	 * than the error message — messages are copy, not contract — so failures on
	 * models whose provider HAS configured auth (network errors, rate limits,
	 * provider outages) propagate unchanged.
	 */
	private toAuthRequiredIfUnauthenticated(session: AgentSession, err: unknown): unknown {
		if (err instanceof RequestError) return err
		const model = session.model
		if (!model) return err
		if (getSessionModelRegistry(session).hasConfiguredAuth(model)) return err
		return modelAuthRequiredError(model)
	}

	private failTurn(entry: SessionRecord, err: unknown): void {
		const turn = entry.turn
		if (!turn) return
		entry.turn = undefined
		turn.reject(err)
	}
}

export function buildPermissionsConfigOption(currentMode: PermissionMode): SessionConfigOption {
	return {
		id: "permissions-mode",
		name: "Permissions Mode",
		type: "select",
		category: "mode",
		description:
			"Control tool execution permissions: default (prompt for writes), plan (read-only), auto (classifier-gated), yolo (no restrictions)",
		currentValue: currentMode,
		options: PERMISSION_MODES_WITH_META.map(({ mode, label, description }) => ({
			name: label,
			value: mode,
			description,
		})),
	}
}

function isMultiModelOrchestrator(session: AgentSessionModelConfig): boolean {
	if (!session.model) return false
	const { model: orchestrator } = getOrchestratorModel(session.sessionId, getSessionModelRegistry(session))
	return !!orchestrator && refFromModel(session.model) === refFromModel(orchestrator)
}

function getSessionModelRegistry(
	session: Pick<AgentSession, "modelRuntime"> & { modelRegistry?: ModelRegistry },
): ModelRegistry {
	return session.modelRegistry ?? new ModelRegistry(session.modelRuntime)
}

function autoModelOption(model: Model<Api>, sessionId: string): SessionConfigSelectOption {
	// The backend may ship the description inside the display name; ACP has a
	// dedicated description field, so the pair is split apart here.
	const { name: baseName, description: nameDescription } = splitModelDisplayName(model.name ?? model.id)
	const description = nameDescription ?? AUTO_MODEL_DESCRIPTION
	const state = getAutoRoutingState(sessionId)
	if (state.status === "resolved" && isRoutedModel(model, sessionId)) {
		return {
			value: refFromModel(model),
			name: `${baseName} (${state.model.id})`,
			description,
		}
	}
	return { value: refFromModel(model), name: baseName, description }
}

export function buildModelConfigOption(session: AgentSessionModelConfig): SessionConfigOption {
	const multiModelEnabled = getMultiModelEnabled(session.sessionManager)
	const modelRegistry = getSessionModelRegistry(session)
	const {
		model: orchestrator,
		modelRef: orchRef,
		modelId: orchId,
	} = getOrchestratorModel(session.sessionId, modelRegistry)
	const orchName = orchestrator?.name ?? orchId ?? orchRef
	// `description` is the optional secondary line ACP clients render beneath an
	// option's name. Only the two routing entries carry one — concrete models are
	// self-describing — and a client that ignores the field still shows the name.
	const options = [
		{
			value: "multi-model",
			name: `Multi-model (${orchName})`,
			description: "Routes each task to the best model, with an orchestrator and workers.",
		},
		...modelRegistry
			.getAvailable()
			.map((m) =>
				isAutoRoutedModel(m) ? autoModelOption(m, session.sessionId) : { value: refFromModel(m), name: m.name },
			)
			.sort((a, b) => a.value.localeCompare(b.value)),
	]
	// biome-ignore lint/style/noNonNullAssertion: we assert model availability before session is created/loaded via assertSessionHasModel.
	const currentValue = multiModelEnabled ? "multi-model" : refFromModel(session.model!)
	return {
		id: "model",
		name: "Model",
		type: "select",
		category: "model",
		description: "Select the active AI model: single-model or multi-model (orchestrator + workers).",
		currentValue,
		options,
	}
}

function autoOptionName(configOptions: SessionConfigOption[]): string | undefined {
	const modelOption = configOptions.find((opt) => opt.id === "model")
	if (modelOption?.type !== "select") return undefined
	const autoNames = (modelOption.options as SessionConfigSelectOption[])
		.filter((opt) => opt.value.startsWith(`${AUTO_MODEL_PROVIDER}/auto`))
		.map((opt) => opt.name)
		.sort()
	return autoNames.length > 0 ? autoNames.join(" · ") : undefined
}

function buildConfigOptions(session: AgentSession, defaultMode: PermissionMode): SessionConfigOption[] {
	const mode = getPermissionMode(session.sessionId)?.mode ?? defaultMode
	return [buildPermissionsConfigOption(mode), buildModelConfigOption(session)]
}

export function buildSessionModelState(configOptions: SessionConfigOption[]): SessionModelState | null {
	// biome-ignore lint/style/noNonNullAssertion: model config option is static, it is always available
	const configOption = configOptions.find((opt) => opt.id === "model")!
	const options = (configOption as SessionConfigOption & { type: "select" }).options as SessionConfigSelectOption[]
	return {
		currentModelId: configOption.currentValue as string,
		availableModels: options.map((m) => ({
			modelId: m.value,
			name: m.name,
			// Carry the option's secondary line through, so clients reading
			// `models` see the same labelling as those reading `configOptions`.
			...(m.description ? { description: m.description } : {}),
		})),
	}
}

export function assertSessionHasModel(session: Pick<AgentSession, "model">): void {
	if (!session.model) {
		throw RequestError.authRequired(
			undefined,
			"No model available for ACP session. Configure an API key or models.json first.",
		)
	}
}

function toTurnError(terminal: { stopReason: "error"; errorMessage?: string }): Error {
	const detail = terminal.errorMessage ?? "the provider returned an error"
	if (isAuthRejectedMessage(terminal.errorMessage)) {
		return RequestError.authRequired(
			{ kind: "auth" },
			`${detail}: auth required. Call session/authenticate to log in again, then retry.`,
		)
	}
	// Structured reason data so clients branch on fields, not message text.
	// JSON-RPC transports carry the data payload untouched; clients that ignore
	// it lose nothing (message keeps the raw provider text).
	// CAVEAT for clients discovering this wire shape: classification is
	// heuristic — classifyLLMGatewayError matches known English provider
	// phrasings, so a novel/garbled provider error yields no `data` at all
	// (bare -32603 with the raw text). A present `kind` is contract; an ABSENT
	// one means "unknown", never "no error of that kind". Clients must keep a
	// message-text fallback path for that case.
	const classification = classifyLLMGatewayError(detail)
	const retryAtMs = classification?.reason === "rate_limit" ? parseRateLimitRetryAt(detail) : undefined
	// Keys appear only when they carry a value, so the wire shape of `data`
	// stays predictable per kind (clients see no key, never `undefined`/`null`).
	const data = classification
		? {
				kind: classification.reason,
				...(classification.httpStatusCode !== undefined ? { httpStatusCode: classification.httpStatusCode } : {}),
				...(typeof retryAtMs === "number" && !Number.isNaN(retryAtMs) ? { retryAtMs } : {}),
			}
		: undefined
	return RequestError.internalError(data, detail)
}

function modelAuthRequiredError(model: Model<Api>): RequestError {
	// Pi's placeholder on keyless machines reads as "unknown/unknown" — omit it.
	const ref = refFromModel(model)
	const detail =
		ref === "unknown/unknown" ? "no credentials configured for the selected model" : `model ${ref} is not available`
	return RequestError.authRequired(undefined, `${detail}: auth required. ${AUTH_REQUIRED_HINT}`)
}

export function assertSessionModelHasAuth(
	session: Pick<AgentSession, "model" | "modelRuntime"> & { modelRegistry?: ModelRegistry },
): void {
	const model = session.model
	if (!model) return
	if (getSessionModelRegistry(session).hasConfiguredAuth(model)) return
	throw modelAuthRequiredError(model)
}

export function initializeHeadlessTheme(settingsManager: Pick<SettingsManager, "getTheme">): void {
	initTheme(settingsManager.getTheme(), false)
}

function registerPermissionFlagController(
	session: AgentSession,
	initialMode: PermissionModeState,
	send: (params: SessionNotification) => void,
): void {
	const permissionFlagController = createSessionPermissionFlagController({
		mode: initialMode,
	})
	// Register with permissions extension so tool gating uses session-scoped mode
	registerSessionPermissionFlagController(session.sessionId, permissionFlagController)
	permissionFlagController.subscribe(({ mode }) => {
		if (mode === undefined) return
		send({
			sessionId: session.sessionId,
			update: {
				sessionUpdate: "config_option_update",
				configOptions: buildConfigOptions(session, initialMode.mode),
			},
		})
	})
}

export function toAcpSessionInfo(info: PiSessionInfo): AcpSessionInfo {
	// Use truthiness rather than `??` so an empty `name` (migration artifact or
	// hand-edited session-info entry) still falls through to firstMessage —
	// `??` only short-circuits on null/undefined and would otherwise leave the
	// title as the empty string and end up null below.
	const fallback = info.firstMessage ? truncate(info.firstMessage, TITLE_MAX) : ""
	const title = info.name && info.name.length > 0 ? info.name : fallback
	return {
		sessionId: info.id,
		cwd: info.cwd,
		title: title.length > 0 ? title : null,
		updatedAt: info.modified.toISOString(),
	}
}

function resolveSessionPathById(sessionDir: string, sessionId: string): string | null {
	let entries: string[]
	try {
		entries = readdirSync(sessionDir)
	} catch (err) {
		if ((err as NodeJS.ErrnoException).code === "ENOENT") return null
		throw err
	}
	const suffix = `_${sessionId}.jsonl`
	const bare = `${sessionId}.jsonl`
	const match = entries.find((f) => f === bare || f.endsWith(suffix))
	return match ? join(sessionDir, match) : null
}

function parseSessionHeader(raw: string): Pick<SessionHeader, "id" | "cwd"> | null {
	for (const line of raw.split("\n")) {
		const trimmed = line.trim()
		if (!trimmed) continue
		let entry: unknown
		try {
			entry = JSON.parse(trimmed)
		} catch {
			continue
		}
		if (!entry || typeof entry !== "object" || (entry as { type?: unknown }).type !== "session") continue
		const header = entry as { id?: unknown; cwd?: unknown }
		if (typeof header.id !== "string" || typeof header.cwd !== "string") return null
		return { id: header.id, cwd: header.cwd }
	}
	return null
}

function readSessionHeaderPeek(sessionPath: string): { raw: string; complete: boolean } {
	const fd = openSync(sessionPath, "r")
	try {
		const buffer = Buffer.allocUnsafe(SESSION_HEADER_PEEK_BYTES)
		const bytesRead = readSync(fd, buffer, 0, buffer.length, 0)
		return {
			raw: buffer.toString("utf-8", 0, bytesRead),
			complete: bytesRead < SESSION_HEADER_PEEK_BYTES,
		}
	} finally {
		closeSync(fd)
	}
}

function readSessionHeader(sessionPath: string): Pick<SessionHeader, "id" | "cwd"> | null {
	const peek = readSessionHeaderPeek(sessionPath)
	const parseablePeek = peek.complete ? peek.raw : peek.raw.slice(0, Math.max(0, peek.raw.lastIndexOf("\n") + 1))
	const header = parseSessionHeader(parseablePeek)
	if (header || peek.complete) return header
	return parseSessionHeader(readFileSync(sessionPath, "utf-8"))
}

function defaultSessionLister(options: RunAcpOptions): AcpSessionLister {
	return async (params: ListSessionsRequest) => {
		// Build the set of roots to enumerate: cwd (when present) plus any
		// non-empty additionalDirectories. Dedupe to avoid double-listing when
		// a client sends cwd as one of the additional roots.
		const roots: string[] = []
		if (params.cwd) roots.push(params.cwd)
		for (const dir of params.additionalDirectories ?? []) {
			if (!roots.includes(dir)) roots.push(dir)
		}
		if (roots.length === 0) {
			// listAll has no agentDir slot in pi today, so a non-default agentDir
			// won't be honored for the unscoped path. Acceptable v1 limitation:
			// Zed's thread-import always supplies a cwd.
			return SessionManager.listAll()
		}
		const lists = await Promise.all(
			roots.map((root) => SessionManager.list(root, join(options.agentDir, "sessions", encodeCwdDir(root)))),
		)
		return lists.flat()
	}
}

async function createSessionSettings(
	cwd: string,
	options: RunAcpOptions,
	params: { _meta?: unknown; mcpServers?: ReadonlyArray<McpServer> },
) {
	// Construct untrusted first: pi's SettingsManager.create defaults
	// projectTrusted to TRUE, which would let an untrusted repo's
	// .pi/settings.json influence HTTP behavior (e.g. disable the idle
	// timeout) — and the defaultProjectTrust read below must be global-scope
	// only so a project cannot grant itself trust. Trust is then resolved the
	// way pi's own no-UI path does and applied in-memory.
	const settingsManager = SettingsManager.create(cwd, options.agentDir, { projectTrusted: false })
	const projectTrusted = resolveHeadlessProjectTrust(cwd, options.agentDir, settingsManager.getDefaultProjectTrust())
	settingsManager.setProjectTrusted(projectTrusted)
	// Sync the same decision onto the kimchi project-scope gate so this
	// session's reads of project-local .kimchi/ and .claude/ resources
	// (config, permissions, hooks, skills) honor it. Keyed by cwd so concurrent
	// ACP sessions in one process stay isolated.
	setProjectScopeTrusted(cwd, projectTrusted)
	initializeHeadlessTheme(settingsManager)
	// Getter form: re-read on every request so mid-session settings edits
	// apply live. The override slot is process-global — with several ACP
	// sessions in one process, the last-configured session's value governs
	// all of them (see setStreamIdleTimeoutOverride).
	configureHttpIdleTimeout(() => settingsManager.getHttpIdleTimeoutMs())
	const callerServers = convertAcpMcpServers(params.mcpServers ?? [])
	const mcpExtension = options.mcpExtensionFactory?.({ cwd, callerServers })
	// Annotated explicitly: the appendSystemPromptOverride closure references
	// `resourceLoader` in its own initializer, which TS otherwise flags as
	// circular (7022).
	const resourceLoader: DefaultResourceLoader = new DefaultResourceLoader({
		cwd,
		agentDir: options.agentDir,
		settingsManager,
		extensionFactories: [...options.extensionFactories, ...(mcpExtension ? [mcpExtension] : [])],
		appendSystemPromptOverride: () => {
			// Per-loader cached so a mid-session project-trust grant can
			// invalidate it (see invalidateSkillListBlock); built lazily on
			// first access, errors fall back to an empty block — it is
			// non-essential.
			let block = cachedSkillListBlock(resourceLoader)
			if (block === undefined) {
				try {
					block = buildSkillListBlock(resourceLoader)
				} catch {
					// If the loader isn't ready (e.g. during reload before skills
					// are populated), return empty rather than crashing session
					// startup.
					block = ""
				}
				setCachedSkillListBlock(resourceLoader, block)
			}
			// CLI flag content first, then _meta["kimchi.dev"].appendSystemPrompt,
			// then the skill list block (matches upstream override behaviour).
			const base = resolveAcpAppendSystemPrompt(params, options) ?? []
			return [...base, ...(block ? [block] : [])]
		},
	})
	await resourceLoader.reload()
	return { settingsManager, resourceLoader }
}

export function defaultSessionLoader(options: RunAcpOptions): AcpSessionLoader {
	return async (params: LoadSessionRequest): Promise<AgentSession> => {
		const cwd = params.cwd
		// Mirror defaultSessionLister: encode cwd inline because pi doesn't
		// re-export getDefaultSessionDir from its package index. Threading
		// agentDir explicitly is load-bearing — pi reads PI_CODING_AGENT_DIR,
		// not KIMCHI_CODING_AGENT_DIR, so default lookups would miss kimchi
		// sessions stored under the kimchi agent dir.
		const sessionDir = join(options.agentDir, "sessions", encodeCwdDir(cwd))
		// pi writes session files as `<isoTimestamp>_<sessionId>.jsonl` (see
		// SessionManager.setSessionFile auto-generation). Looking up by bare
		// `<sessionId>.jsonl` would miss every real session — match the
		// timestamp-prefixed form (and accept the bare form too as a forward-
		// compat hedge if pi ever drops the prefix). Scan the cwd-scoped dir
		// directly rather than calling SessionManager.list, which would parse
		// every JSONL header just to find one file.
		let sessionPath: string | null
		try {
			sessionPath = resolveSessionPathById(sessionDir, params.sessionId)
		} catch (err) {
			// EACCES / EMFILE / etc. — surface the underlying readdir error so
			// Zed can show something more useful than "session not found", but
			// still as invalidParams so it doesn't trip Zed's "server shut down
			// unexpectedly" error path.
			const msg = err instanceof Error ? err.message : String(err)
			throw RequestError.invalidParams(undefined, `failed to read session directory: ${msg}`)
		}
		if (!sessionPath) {
			// Pi intentionally delays writing a new session until its first
			// assistant response. If the ACP process restarts before that, Zed
			// reloads a valid id with no file. Recreate the empty manager with the
			// same id; it remains lazy, so abandoned empty threads leave no files.
			let sessionManager: SessionManager
			try {
				sessionManager = SessionManager.create(cwd, sessionDir, { id: params.sessionId })
			} catch (err) {
				const msg = err instanceof Error ? err.message : String(err)
				throw RequestError.invalidParams(undefined, `invalid sessionId: ${msg}`)
			}
			const { settingsManager, resourceLoader } = await createSessionSettings(cwd, options, params)
			const { session } = await createAgentSession({
				cwd,
				agentDir: options.agentDir,
				settingsManager,
				resourceLoader,
				sessionManager,
			})
			return session
		}
		let header: Pick<SessionHeader, "id" | "cwd"> | null
		try {
			header = readSessionHeader(sessionPath)
		} catch (err) {
			// Same invalidParams treatment as SessionManager.open below: the file
			// existed at resolve time but could not be read now (permissions,
			// post-readdir delete, etc.).
			const msg = err instanceof Error ? err.message : String(err)
			throw RequestError.invalidParams(undefined, `failed to read session header: ${msg}`)
		}
		if (!header) {
			throw RequestError.invalidParams(undefined, `session ${params.sessionId} has no valid session header`)
		}
		if (header.id !== params.sessionId) {
			throw RequestError.invalidParams(
				undefined,
				`session header id ${header.id} does not match requested sessionId ${params.sessionId}`,
			)
		}
		// Reject cwd mismatch before opening SessionManager. pi has no
		// close/dispose hook on SessionManager itself; peeking the header avoids
		// constructing a manager for a session this request is not allowed to
		// load.
		if (header.cwd !== cwd) {
			throw RequestError.invalidParams(undefined, `session cwd ${header.cwd} does not match requested cwd ${cwd}`)
		}
		let sessionManager: SessionManager
		try {
			// Open WITHOUT cwdOverride so the on-disk header cwd is preserved —
			// pi's open is `cwd = cwdOverride ?? header.cwd ?? process.cwd()`
			// (no comparison), so passing params.cwd upfront would silently
			// re-root a session created elsewhere. We compare below instead.
			sessionManager = SessionManager.open(sessionPath, sessionDir)
		} catch (err) {
			// loadEntriesFromFile silently skips malformed lines, but I/O
			// errors (permissions, post-readdir delete) and migration
			// failures still propagate. Surface as invalidParams with a
			// one-line message instead of crashing the connection (which
			// triggers Zed's "server shut down unexpectedly" toast).
			const msg = err instanceof Error ? err.message : String(err)
			throw RequestError.invalidParams(undefined, `failed to open session: ${msg}`)
		}
		const { settingsManager, resourceLoader } = await createSessionSettings(cwd, options, params)
		const { session } = await createAgentSession({
			cwd,
			agentDir: options.agentDir,
			settingsManager,
			resourceLoader,
			sessionManager,
		})
		return session
	}
}

export function defaultSessionFactory(options: RunAcpOptions): AcpSessionFactory {
	return async (params: NewSessionRequest): Promise<AgentSession> => {
		const cwd = params.cwd ?? process.cwd()
		const { settingsManager, resourceLoader } = await createSessionSettings(cwd, options, params)
		const { session } = await createAgentSession({
			cwd,
			agentDir: options.agentDir,
			settingsManager,
			resourceLoader,
		})
		return session
	}
}

export function stripAnsi(text: string): string {
	return text.replace(ANSI_PATTERN, "")
}

function replayTextParts(text: string): ReplayTextPart[] {
	const parts: ReplayTextPart[] = []
	let lastIndex = 0
	for (const match of text.matchAll(ANSI_THINKING_PATTERN)) {
		const index = match.index ?? 0
		const before = stripAnsi(text.slice(lastIndex, index))
		if (before.length > 0) parts.push({ kind: "text", text: before })
		const thinking = stripAnsi(match[1] ?? "")
		if (thinking.length > 0) parts.push({ kind: "thinking", text: thinking })
		lastIndex = index + match[0].length
	}
	const after = stripAnsi(text.slice(lastIndex))
	if (after.length > 0) parts.push({ kind: "text", text: after })
	return parts
}

function extractStreamContent(args: unknown): string | undefined {
	const a = (args ?? {}) as Record<string, unknown>
	return asString(a.content) ?? asString(a.newText) ?? asString(a.command)
}

export function fileChangeToDiffContent(change: FileChange): ToolCallContent {
	switch (change.operation) {
		case "add":
			return { type: "diff", path: change.path, newText: change.newText ?? "", oldText: null }
		case "modify":
			return { type: "diff", path: change.path, newText: change.newText ?? "", oldText: change.oldText ?? null }
		case "delete":
			// The SDK's v1 Diff type marks newText required, but the protocol
			// treats it as absent for deletions (oldText is the "None for new
			// files" mirror). Cast keeps the wire shape per the v1 mapping.
			return { type: "diff", path: change.path, oldText: change.oldText ?? null } as ToolCallContent
	}
}

function resolveToolPath(input: string, cwd: string): string {
	let p = input.replace(UNICODE_SPACES, " ")
	if (p.startsWith("@")) p = p.slice(1)
	if (p === "~") {
		p = homedir()
	} else if (p.startsWith("~/") || (process.platform === "win32" && p.startsWith("~\\"))) {
		p = join(homedir(), p.slice(2))
	}
	if (/^file:\/\//.test(p)) p = fileURLToPath(p)
	return isAbsolute(p) ? resolve(p) : resolve(cwd, p)
}

function readPreWriteContent(toolPath: string, cwd: string): string | null {
	try {
		return readFileSync(resolveToolPath(toolPath, cwd), "utf-8")
	} catch (err) {
		if ((err as NodeJS.ErrnoException).code !== "ENOENT") {
			process.stderr.write(`acp per-turn-diff: pre-write read failed for ${toolPath}: ${String(err)}\n`)
		}
		return null
	}
}

function collectFileChanges(
	toolName: string,
	args: unknown,
	cwd: string,
	turn: { preWriteContents: Map<string, string | null> },
	toolCallId: string,
): PendingFileChange[] {
	const a = (args ?? {}) as Record<string, unknown>
	const path = typeof a.path === "string" ? a.path : undefined
	if (toolName === "edit") {
		if (!path) return []
		// pi's edit tool accepts the multi-edit shape {path, edits: [...]} and
		// normalizes a legacy single-edit shape {path, oldText, newText}
		// internally. Mirror that normalization so legacy-shape calls still
		// emit a diff instead of silently producing none.
		const editsInput: unknown[] = Array.isArray(a.edits)
			? a.edits
			: typeof a.oldText === "string" && typeof a.newText === "string"
				? [{ oldText: a.oldText, newText: a.newText }]
				: []
		const changes: FileChange[] = []
		for (const e of editsInput) {
			if (!e || typeof e !== "object") continue
			const edit = e as { oldText?: unknown; newText?: unknown }
			if (typeof edit.oldText !== "string" || typeof edit.newText !== "string") continue
			changes.push({ operation: "modify", path, oldText: edit.oldText, newText: edit.newText })
		}
		return changes
	}
	if (toolName === "write") {
		if (!path || typeof a.content !== "string") return []
		// Capture the pre-existing content now (before the tool overwrites it).
		// The entry is stored with its operation undecided; tool_execution_end
		// resolves add-vs-modify from preWriteContents via resolveFileChange,
		// keeping that map the single source of truth for the write oldText.
		turn.preWriteContents.set(toolCallId, readPreWriteContent(path, cwd))
		return [{ operation: "write", path, newText: a.content }]
	}
	return []
}

function resolveFileChange(pending: PendingFileChange, preWrite: string | null | undefined): FileChange {
	if (pending.operation !== "write") return pending
	return preWrite === null || preWrite === undefined
		? { operation: "add", path: pending.path, newText: pending.newText }
		: { operation: "modify", path: pending.path, oldText: preWrite, newText: pending.newText }
}

export function userMessageText(content: unknown): string {
	if (typeof content === "string") return content
	if (!Array.isArray(content)) return ""
	const parts: string[] = []
	for (const block of content) {
		if (block && typeof block === "object" && (block as { type?: unknown }).type === "text") {
			const text = (block as { text?: unknown }).text
			if (typeof text === "string") parts.push(text)
		}
	}
	return parts.join("")
}

type ReplayToolResult = {
	content?: unknown
	isError: boolean
	// Pass-through `details` so the replay's tool_call_update rawOutput carries
	// the same shape as the live path's event.result (AgentToolResult includes
	// details). Clients keying UI off rawOutput.details would otherwise see a
	// thinner payload on replay.
	details?: unknown
	toolName?: string
}

function collectToolResults(entries: unknown[]): Map<string, ReplayToolResult> {
	const out = new Map<string, ReplayToolResult>()
	for (const entry of entries) {
		if (!entry || typeof entry !== "object") continue
		const e = entry as { type?: unknown; message?: unknown }
		if (e.type !== "message") continue
		const m = e.message as
			| {
					role?: unknown
					toolCallId?: unknown
					toolName?: unknown
					content?: unknown
					details?: unknown
					isError?: unknown
			  }
			| undefined
		if (m?.role !== "toolResult" || typeof m.toolCallId !== "string") continue
		out.set(m.toolCallId, {
			content: m.content,
			isError: m.isError === true,
			details: m.details,
			toolName: typeof m.toolName === "string" ? m.toolName : undefined,
		})
	}
	return out
}

function toolResultContent(result: unknown): ToolCallContent[] {
	// Tool results carry pi-ai content blocks, typed as (TextContent |
	// ImageContent)[] on pi-ai's ToolResultMessage. Forward both, so a tool that
	// emits an image (e.g. web_fetch, or an MCP image tool whose block survives
	// transformMcpContent) doesn't surface to the client as a completed call with
	// empty content.
	//
	// resource / resource_link / audio blocks never reach here: the MCP bridge
	// (transformMcpContent) already flattens them to text, because pi-ai tool
	// results only model text and image. Forwarding them as native ACP resource
	// blocks would require widening pi-ai's tool-result content type upstream.
	const r = result as { content?: unknown } | null | undefined
	const content = r?.content
	if (!Array.isArray(content)) return []
	const out: ToolCallContent[] = []
	for (const block of content) {
		if (!block || typeof block !== "object") continue
		const b = block as { type?: string; text?: string; data?: string; mimeType?: string }
		if (b.type === "text" && typeof b.text === "string") {
			out.push({ type: "content", content: { type: "text", text: b.text } })
		} else if (b.type === "image" && typeof b.data === "string" && typeof b.mimeType === "string") {
			out.push({ type: "content", content: { type: "image", data: b.data, mimeType: b.mimeType } })
		}
	}
	return out
}

export async function runAcpMode(options: RunAcpOptions): Promise<void> {
	// stdout is reserved for JSON-RPC frames; redirect stray console output to
	// stderr so a lone `console.log` anywhere in pi-mono/extensions can't corrupt
	// the protocol stream.
	console.log = console.error
	console.info = console.error
	console.warn = console.error
	console.debug = console.error

	const writable = Writable.toWeb(process.stdout) as WritableStream<Uint8Array>
	const readable = Readable.toWeb(process.stdin) as ReadableStream<Uint8Array>
	const stream = ndJsonStream(writable, readable)

	let agentInstance: KimchiAcpAgent | undefined
	const conn = new AgentSideConnection((c) => {
		agentInstance = new KimchiAcpAgent(c, options)
		return agentInstance
	}, stream)

	const signals: NodeJS.Signals[] = process.platform === "win32" ? ["SIGTERM"] : ["SIGTERM", "SIGHUP", "SIGINT"]
	let shuttingDown = false
	const onSignal = (sig: NodeJS.Signals) => {
		if (shuttingDown) return
		shuttingDown = true
		const code = sig === "SIGHUP" ? 129 : sig === "SIGINT" ? 130 : 143
		agentInstance
			?.shutdown("signal")
			.catch(() => {})
			.finally(() => process.exit(code))
	}
	for (const s of signals) process.on(s, onSignal)

	try {
		await conn.closed
	} finally {
		for (const s of signals) process.off(s, onSignal)
		await agentInstance?.shutdown()
	}
}

kimchi_acp_methods.text:
private readonly commandsRefresher = createCommandsRefresher({
		sessions: () => this.sessions,
		broadcast: (sessionId) => this.scheduleAvailableCommandsUpdate(sessionId),
	})

private getInitialPermissionMode(session: AgentSession): PermissionModeState {
		const cwd = session.sessionManager.getCwd()
		const { loaded } = loadConfig({ cwd })
		return resolveInitialPermissionMode(
			session.sessionManager,
			this.permissionsEnvFlag,
			resolveCliPermissionMode(),
			loaded,
		)
	}

constructor(
		private readonly conn: AgentSideConnection,
		options: RunAcpOptions,
	) {
		this.sessionFactory = options.sessionFactory ?? defaultSessionFactory(options)
		this.agentDir = options.agentDir
		this.sessionLister = options.sessionLister ?? defaultSessionLister(options)
		this.sessionLoader = options.sessionLoader ?? defaultSessionLoader(options)
		this.mcpProbe = options.mcpProbe
		this.skillWatcher = createSkillWatcher({
			agentDir: options.agentDir,
			getExtraSkillPaths: () => [...new Set(loadKimchiConfig().skillPaths ?? [])],
			requestRefresh: () => this.commandsRefresher.request(),
		})
	}

async initialize(request: InitializeRequest): Promise<InitializeResponse> {
		setAcpClientInfo(request.clientInfo ?? { name: "unknown", version: "0.0.0" })

		this.clientCapabilities = request.clientCapabilities

		const modelRuntime = await ModelRuntime.create({
			authPath: join(this.agentDir, "auth.json"),
			modelsPath: join(this.agentDir, "models.json"),
		})
		const modelRegistry = new ModelRegistry(modelRuntime)
		const supportsImages = modelRegistry.getAvailable().some((m) => modelSupportsImages(m))

		// ACP Registry compliance: advertise at least one auth method. Agent Auth
		// (browser-based OAuth via local callback server) is always declared.
		// Terminal Auth (interactive `kimchi login`) is declared only when the
		// client advertises the terminal capability, per the auth-methods RFD:
		// "An Agent may advertise a terminal authentication method only when the
		// Client advertised the corresponding capability."
		const authMethods: AuthMethod[] = [
			{
				id: KIMCHI_AGENT_AUTH_METHOD_ID,
				name: "Kimchi Login",
				description: "Authenticate via browser to Kimchi",
			},
			// Region-pinned companions for clients that can pick a region.
			...selectableRegions().map(regionAuthMethod),
		]
		if (request.clientCapabilities?.auth?.terminal === true) {
			authMethods.push({
				id: "kimchi-terminal",
				name: "Log in from terminal",
				description: "Run Kimchi's interactive login flow",
				type: "terminal",
				args: ["login"],
			})
		}

		return {
			protocolVersion: PROTOCOL_VERSION,
			agentInfo: {
				name: "kimchi",
				version: getVersion(),
			},
			agentCapabilities: {
				loadSession: true,
				// Advertise logout support so clients know they can call
				// `unstable_logout` to clear stored credentials.
				auth: { logout: {} },
				// `list: {}` advertises support for session/list per spec
				// (SessionListCapabilities is `{ _meta? }` — empty object means
				// "supported"). loadSession remains the top-level flag because
				// the spec hasn't unified it under sessionCapabilities yet.
				sessionCapabilities: { list: {}, close: {} },
				promptCapabilities: { image: supportsImages, audio: false, embeddedContext: false },
				mcpCapabilities: { http: true, sse: false },
				// Extended capabilities
				_meta: {
					[CAPABILITIES_KEY]: {
						...ADVERTISED_CAPABILITIES,
						...(this.mcpProbe ? {} : { probe_mcp_server: false }),
					},
				},
			},
			authMethods,
		}
	}

async listSessions(params: ListSessionsRequest): Promise<ListSessionsResponse> {
		// Cursor pagination is out of scope for v1: pi reads only JSONL headers,
		// so even four-digit session counts comfortably meet the 500ms NFR
		// (revisit only if real installs hit slowness). `additionalDirectories`
		// (@experimental) is honored when non-empty by the default lister.
		const piSessions = await this.sessionLister(params)
		// Dedupe by session id: the default lister merges results from multiple
		// roots (cwd + additionalDirectories), and the same session can surface
		// twice when a client passes its cwd as one of the additional roots.
		// Keep first occurrence so cwd-listed entries win.
		const seen = new Set<string>()
		const sessions: ReturnType<typeof toAcpSessionInfo>[] = []
		for (const s of piSessions) {
			if (seen.has(s.id)) continue
			seen.add(s.id)
			// Skip subagent sessions: pi marks forked sessions with parentSessionPath
			// so delegated Agent runs don't clutter the user's session list.
			if (s.parentSessionPath) continue
			sessions.push(toAcpSessionInfo(s))
		}
		// Sort newest-first by updatedAt so Zed's picker surfaces recent threads
		// at the top without client-side sorting.
		sessions.sort((a, b) => (b.updatedAt ?? "").localeCompare(a.updatedAt ?? ""))
		// Explicit `nextCursor: null` signals end-of-pagination per the v1 spec
		// so clients don't infer it from an omitted field.
		return { sessions, nextCursor: null }
	}

async authenticate(params: AuthenticateRequest): Promise<AuthenticateResponse> {
		// Agent Auth ("kimchi-agent") follows the configured region; the pinned
		// "kimchi-agent-<regionId>" companions authenticate against that region
		// regardless of config. Terminal Auth ("kimchi-terminal") is resolved
		// out-of-band: the client launches `kimchi login` as a separate process,
		// so this method is never called for it.
		const region = authMethodRegion(params.methodId)
		if (region === undefined) {
			throw RequestError.invalidParams(undefined, `unknown auth method: ${params.methodId}`)
		}

		// Run the browser OAuth flow: starts a local callback server, opens the
		// user's browser to the Kimchi web app, and awaits the resulting token.
		// The success page copy names no client: this flow may be launched by any
		// ACP client, so it stays neutral instead of the terminal CLI wording.
		let token: string
		try {
			;({ token } = await authenticateViaBrowser({
				webAppUrl: endpointsForRegion(region).webAppUrl,
				successMessage: ACP_SUCCESS_MESSAGE,
			}))
		} catch (error) {
			const detail = error instanceof Error ? error.message : String(error)
			throw RequestError.internalError(undefined, `Browser authentication failed: ${detail}`)
		}
		if (!token) {
			throw RequestError.internalError(undefined, "Browser authentication did not return a token")
		}

		// Persist the key so new sessions pick it up via the login extension's
		// session_start handler (which reads loadConfig().apiKey), with its region.
		writeApiKey(token, undefined, { region })
		// Fresh login invalidates earlier 401 marks — auth_status flips back now.
		clearCredentialStale(KIMCHI_PROVIDER_ID)

		// Eagerly refresh the model cache so the subsequent newSession() call
		// finds available models without another round-trip.
		await updateModelsConfig(join(this.agentDir, "models.json"), token)

		// Write Pi's credential store too, and refresh every OPEN session's
		// ModelRuntime: hasConfiguredAuth reads a snapshot captured at session
		// creation (model-runtime.js), so without this an already-open session
		// keeps rejecting with -32000 until the process is respawned. A failing
		// refresh must not fail the login — the credential is persisted and the
		// next action re-reads it.
		await syncPiAuth(join(this.agentDir, "auth.json"), join(this.agentDir, "models.json"), token)
		await Promise.all(
			[...this.sessions.values()].map((record) =>
				record.session.modelRuntime.refresh({ allowNetwork: false }).catch(() => {}),
			),
		)

		return {}
	}

async unstable_logout(_params: LogoutRequest): Promise<LogoutResponse> {
		// Clear the persisted API key from config (loadConfig().apiKey), so
		// new sessions no longer pick it up via the login extension.
		clearApiKey()

		// clearPiAuth over AuthStorage.logout(): it removes kimchi-dev/*
		// sub-provider entries, not just the exact kimchi-dev id.
		await clearPiAuth(join(this.agentDir, "auth.json"))

		return {}
	}

async newSession(params: NewSessionRequest): Promise<NewSessionResponse> {
		const session = await this.sessionFactory(params)
		try {
			const initialMode = this.getInitialPermissionMode(session)
			assertSessionHasModel(session)
			// Credential gate (work item #367): a keyless machine must reject
			// here, not only at first prompt — this is the earliest reactive
			// login trigger clients consume.
			assertSessionModelHasAuth(session)

			const sessionId = session.sessionId
			// A fresh ACP session has neither a process entry nor a session log, so
			// multi-model would otherwise resolve to the global default (true) and
			// report "multi-model" no matter which model the session actually
			// resolved to. Anchor the flag to that resolved model instead, the same
			// way setSessionModel does for an explicit client change.
			setMultiModelEnabled(sessionId, isMultiModelOrchestrator(session))
			const uiContext = this.createUiContext(session)
			registerPermissionFlagController(session, initialMode, (params) => this.send(params))
			// Build the record early so the ACP prompter can allocate ACP
			// toolCallIds that match the ids later emitted by tool_execution_start.
			// The unsubscribe placeholder is replaced after bindAcpExtensions so no
			// extension events are dropped before this.sessions is populated.
			const record: SessionRecord = {
				session,
				unsubscribe: () => {},
				cwd: session.sessionManager.getCwd(),
				nextBlockId: 0,
				contentIndexToBlockId: new Map(),
				streamedText: new Map(),
				nextToolCallId: 0,
				toolCallIdMap: new Map(),
				skillCommands: new Map(),
			}
			registerAcpPrompter(
				sessionId,
				createAcpPermissionPrompter(this.conn, sessionId, uiContext, (piToolCallId, toolName) =>
					this.getOrAllocateAcpToolCallId(record, piToolCallId, toolName),
				),
			)
			await this.bindAcpExtensions(session, uiContext)

			// Populate skill commands only after binding: extensions contribute
			// cwd-local skill roots to the loader during resources_discover, so
			// the palette and /skill: parsing see every skill exactly once.
			this.populateSkillCommands(session, record)
			this.skillWatcher.addSession(record)

			record.unsubscribe = session.subscribe((event) => this.onSessionEvent(sessionId, event))
			this.sessions.set(sessionId, record)

			this.startPlanTracker(record, sessionId)

			this.scheduleAvailableCommandsUpdate(sessionId)
			this.scheduleProjectTrustUpdate(sessionId)

			const configOptions = buildConfigOptions(session, initialMode.mode)
			// Seed the tracker with what the client is about to receive, so the
			// first message_start only re-publishes when the router's pick has
			// actually changed the label.
			record.lastModelOptionName = autoOptionName(configOptions)
			return {
				sessionId,
				configOptions,
				models: buildSessionModelState(configOptions),
			}
		} catch (err) {
			unregisterAcpPrompter(session.sessionId)
			unregisterSessionPermissionFlagController(session.sessionId)
			clearPermissionModeEnv(session.sessionId)
			session.dispose()
			throw err
		}
	}

private createUiContext(session: AgentSession): ExtensionUIContext {
		// Build the ExtensionUIContext that pi's runner routes `ctx.ui.*` calls
		// through. Bound to a single session for its lifetime — the connection,
		// capabilities, and `send` callback are all session-scoped state.
		return createAcpUIContext(this.conn, session.sessionId, this.clientCapabilities, (params) => this.send(params))
	}

private async bindAcpExtensions(session: AgentSession, uiContext: ExtensionUIContext): Promise<void> {
		await session.bindExtensions({
			uiContext,
			// Mode is "rpc" so extensions can branch on `ctx.mode === "rpc"` to detect
			// this transport (added in pi-coding-agent 0.78.1). `ctx.hasUI` is derived
			// from the uiContext by the runner, so extensions that only check the
			// legacy boolean keep working too.
			mode: "rpc",
			onError: (err) => {
				process.stderr.write(`acp ext error [${err.extensionPath}] ${err.event}: ${err.error}\n`)
			},
		})

		// Activate the Skill tool if the claude-code-skills extension registered it.
		// This gives ACP sessions the same model-driven skill loading that TUI has
		// by default (skills === true).
		if (session.getToolDefinition("Skill")) {
			const active = new Set(session.getActiveToolNames())
			if (!active.has("Skill")) {
				session.setActiveToolsByName([...active, "Skill"])
			}
		}
	}

private populateSkillCommands(session: AgentSession, record: SessionRecord): void {
		record.skillCommands = discoverSkillCommandsMap(session)
	}

private startPlanTracker(record: SessionRecord, sessionId: string): void {
		const tracker = new AcpPlanTracker({
			sessionId,
			send: (params) => this.send(params),
		})
		tracker.start()
		record.planTracker = tracker
		// Startup hooks and restored sessions can populate Todos before subscription.
		tracker.emitRestoredSnapshot()
	}

async unstable_setSessionModel(params: SetSessionModelRequest): Promise<SetSessionModelResponse> {
		const record = this.sessions.get(params.sessionId)
		if (!record) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${params.sessionId}`)
		}
		await this.doSetModel(record, params.modelId)
		return {}
	}

async setSessionConfigOption(params: SetSessionConfigOptionRequest): Promise<SetSessionConfigOptionResponse> {
		const record = this.sessions.get(params.sessionId)
		if (!record) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${params.sessionId}`)
		}
		switch (params.configId) {
			case "permissions-mode": {
				this.doSetPermissionMode(record, params.value ? `${params.value}` : "")
				break
			}
			case "model": {
				await this.doSetModel(record, params.value ? `${params.value}` : "")
				break
			}
			default:
				throw RequestError.invalidParams(undefined, `unknown config option ${params.configId}`)
		}
		return {
			configOptions: buildConfigOptions(record.session, this.getInitialPermissionMode(record.session).mode),
		}
	}

private doSetPermissionMode(record: SessionRecord, mode: string): PermissionMode {
		const permissionMode = mode as PermissionMode
		if (!PERMISSION_MODES.includes(permissionMode)) {
			throw RequestError.invalidParams(undefined, `invalid mode ${permissionMode}`)
		}
		const sessionId = record.session.sessionId
		const { sessionManager } = record.session
		const state: PermissionModeState = { mode: permissionMode, initiatedBy: "user", source: "runtime" }
		persistPermissionModeIfChanged(sessionManager, (...args) => sessionManager.appendCustomEntry(...args), state)
		setPermissionMode(sessionId, state)
		return permissionMode
	}

private async doSetModel(record: SessionRecord, value: string): Promise<string> {
		if (record.turn) {
			throw RequestError.invalidRequest(undefined, "a prompt is already in progress for this session")
		}
		if (!value) {
			throw RequestError.invalidParams(undefined, "modelId is required")
		}
		const { session } = record
		const sessionId = session.sessionId
		const modelRegistry = getSessionModelRegistry(session)
		if (value === "multi-model") {
			const { model: orchestrator, modelRef: orchRef } = getOrchestratorModel(session.sessionId, modelRegistry)
			if (!orchestrator) {
				// Orchestrator unresolvable: unknown ref → invalidParams; no
				// credentials → authRequired (-32000 → client login UI).
				// ModelRegistry.hasConfiguredAuth(model) delegates to
				// ModelRuntime.hasConfiguredAuth(providerId) (model-registry.js).
				const parsed = splitModelRef(orchRef)
				if (parsed && !session.modelRuntime.hasConfiguredAuth(parsed.provider)) {
					throw RequestError.authRequired(
						undefined,
						`multi-model orchestrator (${orchRef}) is not available: auth required. ${AUTH_REQUIRED_HINT}`,
					)
				}
				throw RequestError.invalidParams(undefined, `multi-model orchestrator (${orchRef}) is not available`)
			}
			const previousMultiModelEnabled = getMultiModelEnabled(session.sessionManager)
			setMultiModelEnabled(sessionId, true)
			try {
				// An explicit client request to change the model, so save it as the default.
				await session.setModel(orchestrator, { persist: true })
			} catch {
				setMultiModelEnabled(sessionId, previousMultiModelEnabled)
				// Pi's setModel only throws "if no auth is configured for the model"
				throw RequestError.authRequired(undefined, `orchestrator model ${orchRef} is not available: auth required`)
			}
			return value
		}

		const parsed = splitModelRef(value)
		if (!parsed) {
			throw RequestError.invalidParams(
				undefined,
				`invalid model format: "${value}". expected "provider/modelId" or "multi-model".`,
			)
		}
		const target = findModelByRef(modelRegistry, value)
		if (!target) {
			throw RequestError.invalidParams(
				undefined,
				`model not found: "${value}". available models: multi-model, ${availableModelRefs(modelRegistry).join(", ")}`,
			)
		}

		const previousMultiModelEnabled = getMultiModelEnabled(session.sessionManager)
		setMultiModelEnabled(sessionId, false)
		try {
			// An explicit client request to change the model, so save it as the default.
			await session.setModel(target, { persist: true })
		} catch {
			setMultiModelEnabled(sessionId, previousMultiModelEnabled)
			// Pi's setModel only throws "if no auth is configured for the model"
			throw RequestError.authRequired(undefined, `model ${refFromModel(target)} is not available: auth required`)
		}
		return value
	}

async loadSession(params: LoadSessionRequest): Promise<LoadSessionResponse> {
		const sessionId = params.sessionId
		const existing = this.sessions.get(sessionId)
		if (existing) {
			// Mid-turn attach is opt-in; clients passing the flag declared the
			// previous connection dead, so attach and replay instead of rejecting.
			// Everyone else keeps the strict guard.
			if (existing.turn && params._meta?.[ACP_REATTACH_MID_TURN_META_KEY] !== true) {
				throw RequestError.invalidRequest(undefined, `session ${sessionId} has a turn in progress; cancel it first`)
			}
			this.replayTranscript(existing.session)
			this.scheduleAvailableCommandsUpdate(sessionId)
			this.scheduleProjectTrustUpdate(sessionId)

			const configOptions = buildConfigOptions(existing.session, this.getInitialPermissionMode(existing.session).mode)
			return {
				configOptions,
				models: buildSessionModelState(configOptions),
			}
		}
		const loading = this.loadingSessions.get(sessionId)
		if (loading) return loading

		const loadingPromise = this.loadSessionFresh(params)
		this.loadingSessions.set(sessionId, loadingPromise)
		try {
			return await loadingPromise
		} finally {
			if (this.loadingSessions.get(sessionId) === loadingPromise) {
				this.loadingSessions.delete(sessionId)
			}
		}
	}

private async loadSessionFresh(params: LoadSessionRequest): Promise<LoadSessionResponse> {
		// Atomic ownership transfer mirrors newSession but covers the full
		// register → replay → respond path: a throw at any point after the
		// loader hands back a live session must unwind registration AND dispose,
		// otherwise the session sits in `sessions` while loadSession rejects —
		// Zed thinks load failed but the agent thinks the id is live, and the
		// next loadSession for the same id wrongly returns invalidRequest.
		const session = await this.sessionLoader(params)
		const initialMode = this.getInitialPermissionMode(session)
		const sessionId = session.sessionId
		try {
			// Defensive: pi reads the sessionId from the JSONL header, not the
			// filename, so a corrupted / hand-edited session whose header id
			// disagrees with the requested id would land under the wrong key in
			// `sessions`. Subsequent session/prompt for params.sessionId would then
			// fail with "unknown sessionId" while the file is still held open.
			// Reject up front and dispose so we don't quietly diverge.
			if (sessionId !== params.sessionId) {
				session.dispose()
				throw RequestError.invalidParams(
					undefined,
					`session header id ${sessionId} does not match requested sessionId ${params.sessionId}`,
				)
			}
			assertSessionHasModel(session)

			const uiContext = this.createUiContext(session)
			registerPermissionFlagController(session, initialMode, (params) => this.send(params))
			// Build the record early so the ACP prompter can allocate ACP
			// toolCallIds that match the ids later emitted by tool_execution_start.
			// The unsubscribe placeholder is replaced after bindAcpExtensions so no
			// extension events are dropped before this.sessions is populated.
			const record: SessionRecord = {
				session,
				unsubscribe: () => {},
				// The session header cwd was validated against params.cwd above, so
				// the session manager's cwd is the session's true cwd.
				cwd: session.sessionManager.getCwd(),
				nextBlockId: 0,
				contentIndexToBlockId: new Map(),
				streamedText: new Map(),
				nextToolCallId: 0,
				toolCallIdMap: new Map(),
				skillCommands: new Map(),
			}
			registerAcpPrompter(
				sessionId,
				createAcpPermissionPrompter(this.conn, sessionId, uiContext, (piToolCallId, toolName) =>
					this.getOrAllocateAcpToolCallId(record, piToolCallId, toolName),
				),
			)
			await this.bindAcpExtensions(session, uiContext)

			// Same post-binding skill population as newSession (see there).
			this.populateSkillCommands(session, record)
			this.skillWatcher.addSession(record)

			record.unsubscribe = session.subscribe((event) => this.onSessionEvent(sessionId, event))
			this.sessions.set(sessionId, record)

			this.startPlanTracker(record, sessionId)

			// Seed the block counter from the persisted branch so replay emits the
			// same messageIds the live turn would have — and so any new block the
			// user creates after the load gets a fresh, non-colliding id.
			this.seedBlockCounterFromBranch(session, record)

			// Replay BEFORE the response resolves so client sees a coherent transcript
			// when the loadSession promise settles. No turn context is created, so a
			// concurrent session/cancel during replay is a no-op — a turn must not
			// be considered active during replay.
			this.replayTranscript(session)
			this.scheduleAvailableCommandsUpdate(sessionId)
			this.scheduleProjectTrustUpdate(sessionId)

			const configOptions = buildConfigOptions(session, initialMode.mode)
			// Same seeding as newSession (see there) — a resumed Auto session
			// hydrates its pick before this point, so the label is already final.
			record.lastModelOptionName = autoOptionName(configOptions)
			return {
				configOptions,
				models: buildSessionModelState(configOptions),
			}
		} catch (err) {
			unregisterAcpPrompter(sessionId)
			unregisterSessionPermissionFlagController(sessionId)
			clearPermissionModeEnv(sessionId)
			const existing = this.sessions.get(sessionId)
			if (existing) {
				this.sessions.delete(sessionId)
				existing.planTracker?.stop()
				existing.unsubscribe()
			}
			session.dispose()
			throw err
		}
	}

async unstable_closeSession(params: CloseSessionRequest): Promise<CloseSessionResponse> {
		await this.closeSessionRecord(params.sessionId)
		return {}
	}

async prompt(params: PromptRequest): Promise<PromptResponse> {
		const entry = this.sessions.get(params.sessionId)
		if (!entry) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${params.sessionId}`)
		}
		if (entry.turn) {
			throw RequestError.invalidRequest(undefined, "a prompt is already in progress for this session")
		}
		const supportsImages = modelSupportsImages(entry.session.model)
		// Warn about unsupported block types (audio, embeddedContext) once per
		// type. Dropped images do NOT join this dedupe — they additionally surface
		// to the client as a per-turn agent_message_chunk warning below, so every
		// dropping turn is visible, not just the first one per connection.
		for (const b of params.prompt) {
			if (b.type !== "text" && b.type !== "image" && !this.warnedBlockTypes.has(b.type)) {
				this.warnedBlockTypes.add(b.type)
				process.stderr.write(`acp prompt: dropping ${b.type} block (unsupported block type)\n`)
			}
		}
		let text = params.prompt
			.map((b: ContentBlock) => (b.type === "text" ? b.text : ""))
			.join("")
			.trim()

		// If the prompt starts with `/skill:<name>` and matches a skill advertised
		// for this session, rewrite the turn to inject the skill content.
		const skillRewrite = await tryParseSkillCommand(text, entry.skillCommands)
		if (skillRewrite) {
			text = buildSkillCommandPrompt(skillRewrite)
		}

		// Extract image blocks from the prompt only if model supports vision.
		const images: ImageContent[] = supportsImages ? extractImages(params.prompt) : []
		// Image blocks a text-only model cannot take: the turn is refused, not
		// sent text-only — sending it would spend a model turn answering a prompt
		// missing its attached context, and the TUI vision gate never silently
		// submits text-only either. The client is informed exactly once per turn
		// as ordinary assistant text via the standard agent_message_chunk schema
		// (ACP has no dedicated warning channel), with its own km.-prefixed message
		// id plus a trailing blank line so clients that concatenate chunks keep it
		// visually separate.
		const droppedImages = supportsImages ? 0 : params.prompt.filter((b) => b.type === "image").length
		if (droppedImages > 0) {
			const noun = droppedImages === 1 ? "image" : "images"
			const modelId = entry.session.model?.id ?? "The current model"
			process.stderr.write(
				`acp prompt: refusing prompt with ${droppedImages} ${noun} (active model has no vision input)\n`,
			)
			this.send({
				sessionId: params.sessionId,
				update: {
					sessionUpdate: "agent_message_chunk",
					messageId: `km.${randomUUID()}`,
					content: {
						type: "text",
						text: `${modelId} does not accept image input — switch to a model with image support or remove the ${noun} and resend.\n\n`,
					},
				},
			})
			// Nothing reaches the session — the turn is refused without a model call.
			return { stopReason: "refusal" }
		}
		if (!text && images.length === 0) {
			return { stopReason: "end_turn" }
		}
		let turnResolve!: (r: PromptResponse) => void
		let turnReject!: (e: unknown) => void
		const result = new Promise<PromptResponse>((resolve, reject) => {
			turnResolve = resolve
			turnReject = reject
		})
		entry.turn = {
			cancelled: false,
			hiddenToolCallIds: new Set(),
			announcedToolCallIds: new Set(),
			lastStreamedContent: new Map(),
			preWriteContents: new Map(),
			pendingFileChanges: new Map(),
			usage: emptyTurnUsage(),
			resolve: turnResolve,
			reject: turnReject,
		}
		// Kick off session.prompt but don't await inside the async function body —
		// shutdown() needs to be able to reject `result` and have the caller's await
		// on prompt() settle immediately, which can't happen while this body is
		// paused on `await session.prompt()`. Instead, attach handlers that drive
		// finalizeTurn/failTurn and return `result` directly; settling `result`
		// propagates to the caller regardless of whether session.prompt ever resolves.
		entry.session.prompt(text, { source: "rpc", images }).then(
			() => {
				// session.prompt() is the source of truth for "turn is done". We
				// deliberately do NOT finalize on agent_end: pi-mono's _runAgentPrompt
				// (agent-session.js) chains multiple agent.prompt / agent.continue
				// calls — each emits its own agent_start + agent_end — when retries,
				// queued follow-up messages, or compaction are pending. If we finalized
				// on the first agent_end, end_turn would be sent mid-stream and the
				// client's subsequent prompt would hit pi-mono's
				// "Agent is already processing" throw because session.prompt is still
				// running the chained continues. session.prompt() resolves only after
				// ALL chained calls complete.
				if (!entry.turn) return
				// Resolved with terminal "error" (retries exhausted): do not report
				// end_turn — the client would show a silent empty reply.
				if (entry.turn.lastAssistantError && !entry.turn.cancelled) {
					const terminal = entry.turn.lastAssistantError
					// Turn-time 401 = first proof this key is dead. Blame the
					// provider, not a key: the failing call may use config apiKey
					// or auth.json OAuth.
					if (isAuthRejectedMessage(terminal.errorMessage)) {
						markCredentialStale(undefined, entry.session.model?.provider ?? KIMCHI_PROVIDER_ID)
					}
					this.failTurn(entry, toTurnError(terminal))
				} else {
					this.finalizeTurn(entry, entry.turn.cancelled ? "cancelled" : "end_turn")
				}
			},
			(err) => {
				// If cancel() arrived mid-turn, session.prompt() may reject with an abort
				// error instead of resolving and letting agent_end drive finalization. The
				// spec still says the client-initiated cancel should surface as
				// stopReason: "cancelled", not a JSON-RPC error — so swallow the abort
				// and resolve with the expected stop reason. Any other error propagates.
				// shutdown() may have already failed the turn; failTurn is a no-op in that case.
				if (!entry.turn) return
				if (entry.turn.cancelled) {
					this.finalizeTurn(entry, "cancelled")
				} else {
					this.failTurn(entry, this.toAuthRequiredIfUnauthenticated(entry.session, err))
				}
			},
		)
		return result
	}

async cancel(params: CancelNotification): Promise<void> {
		const entry = this.sessions.get(params.sessionId)
		if (!entry) return
		if (entry.turn) entry.turn.cancelled = true
		// Drain the steer/follow-up queue BEFORE awaiting the abort. pi-mono
		// chains queued steering messages into the running prompt —
		// session.prompt() resolves only after all chained calls — so awaiting
		// abort() first lets every still-queued steer self-deliver into history
		// with a full reply while we wait for idle. clearQueue() is synchronous,
		// so running it first drops undelivered steers before the chain can
		// drain them. Mirrors the TUI's Escape → clearAllQueues() behaviour.
		const droppedQueue = this.drainQueue(entry)
		notifyDroppedQueue(this.conn, params.sessionId, droppedQueue, "cancelled")
		await entry.session.abort()
	}

async extMethod(method: string, params: Record<string, unknown>): Promise<Record<string, unknown>> {
		switch (method) {
			case AVAILABLE_EXT_METHODS.probe_mcp_server: {
				const result = await handleProbeMcpServer(this.mcpProbe, params)
				return result as Record<keyof ProbeResult, unknown>
			}
			case AVAILABLE_EXT_METHODS.auth_status:
				// Read the shared credential store per call so authenticate(),
				// unstable_logout(), and logins from other Kimchi surfaces are
				// reflected without a reconnect.
				return handleAuthStatus({
					authPath: join(this.agentDir, "auth.json"),
					modelsPath: join(this.agentDir, "models.json"),
				})
			case AVAILABLE_EXT_METHODS.set_onboarding_flag:
				// Write the shared config per call through the harness's
				// read-modify-write helper so sibling onboarding keys set by other
				// Kimchi surfaces survive.
				return handleSetOnboardingFlag({}, params)
			case AVAILABLE_EXT_METHODS.set_session_title:
				return handleSetSessionTitle((sessionId) => this.sessions.get(sessionId)?.session, params)
			case AVAILABLE_EXT_METHODS.steering:
				return handleSteering((sessionId) => {
					const entry = this.sessions.get(sessionId)
					if (!entry) return undefined
					// A cancelled turn stays defined until the prompt settles, but
					// cancel() has already drained its queue — a steer landing in this
					// window must not re-queue text that would leak into the next prompt.
					const turnActive = entry.turn !== undefined && !entry.turn.cancelled
					return { session: entry.session, turnActive }
				}, params)
			case AVAILABLE_EXT_METHODS.import_discover:
				// Sessionless, read-only source-app discovery for the import screen
				// (ADR-0043/ADR-0044): nothing is written to disk and no session is
				// touched. ImportDiscoverResult is a type alias, so it is directly
				// assignable to the string-indexed record the extMethod contract
				// wants — no cast, no spread.
				return importDiscover()
			case AVAILABLE_EXT_METHODS.import_apply:
				// Sessionless write half of the import (ADR-0043/ADR-0044): copies
				// selected skills into Kimchi's own skills dir, merges selected MCP
				// servers conservatively, and satisfies the migration marker. No
				// session is touched. The copied skills land in a watched root, so
				// the file watcher re-advertises palettes on its own.
				return { ...handleImportApply({ agentDir: this.agentDir }, params) }
			case AVAILABLE_EXT_METHODS.set_project_trust:
				// Session-scoped trust survey answer (LLM-3628): persists the
				// decision, opens the kimchi project-scope gate, and (on grant)
				// live-refreshes skills. See handleSetProjectTrust.
				return this.handleSetProjectTrust(params)
			case AVAILABLE_EXT_METHODS.get_path_trust:
				// Sessionless read (LLM-3628): resolved trust state for an
				// arbitrary path, incl. ancestor inheritance and the canonicalized
				// deciding entry. See handleGetPathTrust.
				return this.handleGetPathTrust(params)
			case AVAILABLE_EXT_METHODS.set_path_trust:
				// Sessionless write (LLM-3628): persist a trust/deny decision for
				// any path (root and home included — deliberate power-user
				// capability), then live-refresh affected sessions. See
				// handleSetPathTrust.
				return this.handleSetPathTrust(params)
			default:
				throw RequestError.methodNotFound(method)
		}
	}

async shutdown(cause: "signal" | "disconnect" = "disconnect"): Promise<void> {
		if (this.shutdownPromise) return this.shutdownPromise
		this.shutdownPromise = this.doShutdown(cause)
		return this.shutdownPromise
	}

private async doShutdown(_cause: "signal" | "disconnect"): Promise<void> {
		this.commandsRefresher.cancel()
		this.skillWatcher.close()
		// Drain any in-flight turn promises before tearing down the session.
		// On the signal path we process.exit immediately so this is mostly
		// cosmetic, but runAcpMode's finally also calls shutdown when conn.closed
		// resolves — in that window a pending PromptResponse would otherwise hang
		// until process exit. Reject symmetrically so the caller's await settles.
		for (const entry of this.sessions.values()) {
			if (entry.turn) this.failTurn(entry, new Error("acp agent shutting down"))
			unregisterAcpPrompter(entry.session.sessionId)
			unregisterSessionPermissionFlagController(entry.session.sessionId)
			clearPermissionModeEnv(entry.session.sessionId)
			const droppedQueue = this.drainQueue(entry)
			notifyDroppedQueue(this.conn, entry.session.sessionId, droppedQueue, "shutdown")
			await this.disposeSessionRecord(entry)
		}
		this.sessions.clear()
		resetAcpClientInfo()
	}

private async closeSessionRecord(sessionId: string): Promise<void> {
		const entry = this.sessions.get(sessionId)
		if (!entry) return
		this.sessions.delete(sessionId)
		const droppedQueue = this.drainQueue(entry)
		notifyDroppedQueue(this.conn, sessionId, droppedQueue, "shutdown")
		unregisterAcpPrompter(sessionId)
		unregisterSessionPermissionFlagController(sessionId)
		clearPermissionModeEnv(sessionId)
		entry.unsubscribe()
		if (entry.turn) {
			entry.turn.cancelled = true
			try {
				await entry.session.abort()
			} catch {
				// Closing is best-effort cleanup; still resolve the pending prompt
				// as cancelled and release the session resources below.
			}
			this.finalizeTurn(entry, "cancelled")
		}
		await this.disposeSessionRecord(entry, { alreadyUnsubscribed: true })
	}

private drainQueue(entry: SessionRecord): {
		steering: string[]
		followUp: string[]
	} {
		entry.previousQueue = undefined
		return entry.session.clearQueue()
	}

private async disposeSessionRecord(entry: SessionRecord, opts: DisposeSessionRecordOpts = {}): Promise<void> {
		entry.planTracker?.stop()
		if (!opts.alreadyUnsubscribed) entry.unsubscribe()
		// Emit session_shutdown to extensions and await all handlers before
		// calling dispose(). dispose() is synchronous and returns void, so async
		// extension handlers (e.g. telemetry drain, shutdown marker) would be
		// fire-and-forgotten if we relied on dispose() alone.
		await entry.session.extensionRunner?.emit({ type: "session_shutdown", reason: "quit" })
		entry.session.dispose()
		this.skillWatcher?.removeSession(entry)
	}

private onSessionEvent(sessionId: string, event: AgentSessionEvent): void {
		const entry = this.sessions.get(sessionId)
		if (!entry) return
		const turn = entry.turn
		// Stall/retry/compaction events have no schema session-update type —
		// forward them as a kimchi.dev activity notification so the client can
		// pin a running turn's pause to its cause. No-op for transcript/tool
		// events, which carry their own schema updates.
		emitAgentActivityUpdate(this.conn, sessionId, event)
		switch (event.type) {
			case "queue_update": {
				if (!entry.previousQueue) {
					entry.previousQueue = { steering: [], followUp: [] }
				}
				const steering = reconcileQueue(entry.previousQueue.steering, event.steering)
				const followUp = reconcileQueue(entry.previousQueue.followUp, event.followUp)
				entry.previousQueue = {
					steering: steering.previousQueue,
					followUp: followUp.previousQueue,
				}
				for (const update of [...steering.sessionUpdates, ...followUp.sessionUpdates]) {
					this.send({ sessionId, update })
				}
				return
			}
			case "agent_start": {
				// New turn → contentIndex restarts from 0 and any in-flight tool
				// id mappings from the previous turn are stale (the calls either
				// ended or were orphaned). Wipe both maps so fresh allocations
				// don't reuse old ids.
				entry.contentIndexToBlockId.clear()
				entry.streamedText.clear()
				entry.toolCallIdMap.clear()
				return
			}
			case "message_start": {
				// New assistant message → contentIndex restarts from 0. Wipe the
				// per-message maps so a fresh block at index 0 gets a fresh id
				// (and no streamed prefix) instead of inheriting the previous
				// message's assignment.
				entry.contentIndexToBlockId.clear()
				entry.streamedText.clear()
				// A resolved pick may already be known here (e.g. restored from the
				// last session), so push the resolved label once per change so clients
				// showing the selected model reflect what the auto model chose.
				this.publishModelOptionIfChanged(sessionId, entry)
				return
			}
			case "message_update": {
				if (!turn) return
				const ame = event.assistantMessageEvent
				if ((ame.type === "text_delta" || ame.type === "thinking_delta") && ame.delta) {
					let messageId = entry.contentIndexToBlockId.get(ame.contentIndex)
					if (messageId === undefined) {
						messageId = `km.${entry.nextBlockId++}`
						entry.contentIndexToBlockId.set(ame.contentIndex, messageId)
					}
					this.send({
						sessionId,
						update: {
							sessionUpdate: ame.type === "text_delta" ? "agent_message_chunk" : "agent_thought_chunk",
							content: { type: "text", text: ame.delta },
							messageId,
						},
					})
					// Track streamed text length only — thinking is not restored at
					// message_end and must not be re-emitted from that path.
					if (ame.type === "text_delta") {
						const streamed = entry.streamedText.get(ame.contentIndex) ?? ""
						entry.streamedText.set(ame.contentIndex, streamed + ame.delta)
					}
				}

				// Tool call argument generation started — emit pending tool_call so
				// the client can show progress while the model streams the arguments.
				if (ame.type === "toolcall_start") {
					const block = ame.partial?.content?.[ame.contentIndex]
					if (block?.type === "toolCall" && block.id && block.name) {
						if (isHiddenToolCall(block.name, block.arguments)) {
							turn.hiddenToolCallIds.add(block.id)
							return
						}
						const update: SessionUpdate = buildToolCall({
							toolName: block.name,
							toolCallId: this.getOrAllocateAcpToolCallId(entry, block.id, block.name),
							piToolCallId: block.id,
							rawInput: block.arguments,
							// Arguments are still streaming: the call hasn't been approved or started
							// executing yet, so ACP status is `pending`, not `in_progress`.
							status: "pending",
						})
						this.send({ sessionId, update })
						turn.announcedToolCallIds.add(block.id)
					}
					return
				}

				// Progress streaming — emit the incremental content delta (just
				// the new characters) so the client can show a live preview without
				// re-sending the full arguments on every delta.
				if (ame.type === "toolcall_delta") {
					const block = ame.partial?.content?.[ame.contentIndex]
					if (
						block?.type === "toolCall" &&
						block.id &&
						turn.announcedToolCallIds.has(block.id) &&
						!turn.hiddenToolCallIds.has(block.id)
					) {
						const content = extractStreamContent(block.arguments)
						if (content) {
							const prev = turn.lastStreamedContent.get(block.id) ?? ""
							const delta = content.slice(prev.length)
							if (delta.length > 0) {
								turn.lastStreamedContent.set(block.id, content)
								const update: SessionUpdate = buildToolCallUpdate({
									toolCallId: this.getOrAllocateAcpToolCallId(entry, block.id, block.name),
									piToolCallId: block.id,
									rawOutput: { delta },
									_meta: { generatedChars: content.length },
									// Arguments are still streaming: the call hasn't been approved or started
									// executing yet, so ACP status is `pending`, not `in_progress`.
									status: "pending",
								})
								this.send({ sessionId, update })
							}
						}
					}
					return
				}

				// Argument generation finished — the pending tool_call sent at
				// toolcall_start carried partial (usually empty) arguments. Push the
				// complete rawInput now, before approval and tool_execution_start,
				// so clients can show the target (e.g. the path of an edit) during
				// the whole approval window instead of only once execution begins.
				if (ame.type === "toolcall_end") {
					const toolCall = ame.toolCall
					if (!toolCall?.id || !toolCall.name) return
					if (isHiddenToolCall(toolCall.name, toolCall.arguments)) {
						// Arguments revealed the call as hidden only at stream end (the
						// start event's partial arguments couldn't see it yet) — retire
						// the pending card that went out early. retireToolCall only
						// deletes keyed state (no id allocation, no emission), so this
						// is also safe for calls that were hidden at toolcall_start
						// and never announced.
						turn.hiddenToolCallIds.add(toolCall.id)
						this.retireToolCall(entry, turn, toolCall.id)
						return
					}
					if (!turn.announcedToolCallIds.has(toolCall.id) || turn.hiddenToolCallIds.has(toolCall.id)) {
						return
					}
					const { title, kind, locations } = describeToolCall(toolCall.name, toolCall.arguments)
					const update: SessionUpdate = buildToolCallUpdate({
						toolCallId: this.getOrAllocateAcpToolCallId(entry, toolCall.id, toolCall.name),
						piToolCallId: toolCall.id,
						title,
						kind,
						locations,
						rawInput: toolCall.arguments,
						// Arguments are complete but the call hasn't been approved or
						// started executing yet, so ACP status stays `pending`.
						status: "pending",
					})
					this.send({ sessionId, update })
				}

				return
			}
			case "message_end": {
				if (!turn) return
				const msg = event.message
				if (msg.role !== "assistant") return
				// The pick is learned from this message (responseModel), after
				// message_start — push the resolved label here too. Idempotent: the
				// lastModelOptionName seed makes this a no-op unless the label changed.
				this.publishModelOptionIfChanged(sessionId, entry)
				// Terminal-error tracking for the finalize path: only the LAST
				// assistant message's stopReason decides the turn outcome.
				// StopReason (pi-ai): error → record; aborted → leave (finalization
				// reads entry.turn.cancelled instead); anything else (stop, length,
				// toolUse, deferred) → a completed message, clear. A failed attempt
				// pi auto-retries is superseded by the retry's message_end, which
				// lands here and clears the flag.
				if (msg.stopReason === "error") {
					turn.lastAssistantError = { stopReason: "error", errorMessage: msg.errorMessage }
				} else if (msg.stopReason !== "aborted") {
					turn.lastAssistantError = undefined
				}
				// Emit whatever text a block carries that streaming never sent —
				// an extension can zero text_delta while streaming and restore the
				// text only in message_end's returned message (Ferment V2 does
				// this for any message that isn't an unaccepted completion
				// candidate), and a provider can emit a text block with no
				// incremental deltas at all. In the normal fully-streamed case
				// sent === block.text.length for every block, so nothing extra
				// goes out here. Emitted before usage accounting so ordering
				// relative to emitUsageUpdate is unchanged.
				if (Array.isArray(msg.content)) {
					msg.content.forEach((block, index) => {
						if (block.type !== "text") return
						const streamed = entry.streamedText.get(index) ?? ""
						if (block.text === streamed || (streamed && !block.text.startsWith(streamed))) return
						let messageId = entry.contentIndexToBlockId.get(index)
						if (messageId === undefined) {
							messageId = `km.${entry.nextBlockId++}`
							entry.contentIndexToBlockId.set(index, messageId)
						}
						this.send({
							sessionId,
							update: {
								sessionUpdate: "agent_message_chunk",
								content: { type: "text", text: block.text.slice(streamed.length) },
								messageId,
							},
						})
						entry.streamedText.set(index, block.text)
					})
				}
				const usage = msg.usage
				if (usage) {
					updateTurnUsage(turn, usage)
					// Live context-window refresh: a message_end carrying usage means
					// the session's estimate just moved. Emit here (subject to
					// emitUsageUpdate's undefined/null skip) so clients track the
					// context window across chained steps, not just at turn end.
					this.emitUsageUpdate(entry.session, turn.usage)
				}
				return
			}
			case "tool_execution_start": {
				// Symmetry with the other turn-lifecycle branches: if the turn was
				// already finalized (e.g., shutdown cleared it), don't emit stray
				// tool_call notifications the client would have to reconcile against
				// a turn it already considers over.
				if (!turn) return
				if (isHiddenToolCall(event.toolName, event.args)) {
					turn.hiddenToolCallIds.add(event.toolCallId)
					// A hidden call may already have an allocated ACP id if the permission
					// prompter ran before we knew it was hidden — retire its state.
					this.retireToolCall(entry, turn, event.toolCallId)
					return
				}
				// Capture the diff data now — tool_execution_end carries no args.
				// For `write` the pre-existing content must be read before the tool
				// runs; afterwards the file already holds the new content.
				const fileChanges = collectFileChanges(event.toolName, event.args, entry.cwd, turn, event.toolCallId)
				if (fileChanges.length > 0) {
					turn.pendingFileChanges.set(event.toolCallId, fileChanges)
				}
				const acpToolCallId = this.getOrAllocateAcpToolCallId(entry, event.toolCallId, event.toolName)
				if (turn.announcedToolCallIds.has(event.toolCallId)) {
					// Pending tool_call was already sent via toolcall_start → emit update
					const { title, kind, locations } = describeToolCall(event.toolName, event.args)
					const update: SessionUpdate = buildToolCallUpdate({
						toolCallId: acpToolCallId,
						piToolCallId: event.toolCallId,
						title,
						kind,
						locations,
						rawInput: event.args,
						status: "in_progress",
					})
					this.send({ sessionId, update })
				} else {
					const update: SessionUpdate = buildToolCall({
						toolCallId: acpToolCallId,
						piToolCallId: event.toolCallId,
						toolName: event.toolName,
						rawInput: event.args,
						status: "in_progress",
					})
					// No pending notification was sent (back-compat) → emit tool_call as before
					this.send({ sessionId, update })
				}
				return
			}
			case "tool_execution_update": {
				if (!turn) return
				if (turn.hiddenToolCallIds.has(event.toolCallId) || isHiddenToolCall(event.toolName, event.args)) {
					turn.hiddenToolCallIds.add(event.toolCallId)
					// A hidden call may already have an allocated ACP id if the permission
					// prompter ran before we knew it was hidden — retire its state.
					this.retireToolCall(entry, turn, event.toolCallId)
					return
				}
				const acpToolCallId = this.resolveAcpToolCallId(entry, event.toolCallId)
				const partial = toolResultContent(event.partialResult)
				if (partial.length === 0) return
				const update: SessionUpdate = buildToolCallUpdate({
					toolCallId: acpToolCallId,
					piToolCallId: event.toolCallId,
					content: partial,
					status: "in_progress",
				})
				this.send({ sessionId, update })
				return
			}
			case "tool_execution_end": {
				if (!turn) return
				if (turn.hiddenToolCallIds.has(event.toolCallId)) {
					this.retireToolCall(entry, turn, event.toolCallId, { removeFromHidden: true })
					return
				}
				// Consume the per-call capture so a later turn reusing the id (or a
				// retried call) can't leak stale diff data across tool calls.
				const pending = turn.pendingFileChanges.get(event.toolCallId) ?? []
				turn.pendingFileChanges.delete(event.toolCallId)
				const preWrite = turn.preWriteContents.get(event.toolCallId)
				turn.preWriteContents.delete(event.toolCallId)
				// Diffs are additional content blocks, appended after the existing
				// text/image content. Failed mutations emit no diff: the client
				// would otherwise render a change that never landed.
				const diffs = event.isError ? [] : pending.map((p) => fileChangeToDiffContent(resolveFileChange(p, preWrite)))
				const acpToolCallId = this.resolveAcpToolCallId(entry, event.toolCallId)
				const update: SessionUpdate = buildToolCallUpdate({
					toolCallId: acpToolCallId,
					piToolCallId: event.toolCallId,
					status: event.isError ? "failed" : "completed",
					content: [...toolResultContent(event.result), ...diffs],
					rawOutput: event.result,
				})
				this.send({ sessionId, update })
				// Upstream ids can repeat after compaction or even within a turn. Retire
				// all state keyed on this upstream id so a future call reusing it starts
				// with a fresh ACP id and clean streaming/announcement state.
				this.retireToolCall(entry, turn, event.toolCallId, { removeFromHidden: true })
				return
			}
			case "session_info_changed": {
				const name = event.name
				if (!name) return
				this.send({
					sessionId,
					update: {
						sessionUpdate: "session_info_update",
						title: name,
					},
				})
				return
			}
			default:
				return
		}
	}

private replayTranscript(session: AgentSession): void {
		const sessionId = session.sessionId
		const entries = session.sessionManager.getBranch()
		const toolResults = collectToolResults(entries)

		for (const entry of entries) {
			if (!entry || typeof entry !== "object" || entry.type !== "message") continue
			const msg = entry.message
			if (msg.role === "user") {
				const text = userMessageText(msg.content)
				if (!text) continue
				this.send({
					sessionId,
					update: {
						sessionUpdate: "user_message_chunk",
						content: { type: "text", text },
					},
				})
			} else if (msg.role === "assistant") {
				this.replayAssistantBlocks(sessionId, msg.content, toolResults, this.sessions.get(sessionId))
			}
			// toolResult: handled inline alongside its originating toolCall above.
		}
	}

private seedBlockCounterFromBranch(session: AgentSession, record: SessionRecord): void {
		const entries = session.sessionManager.getBranch()

		let count = 0
		for (const entry of entries) {
			if (entry?.type !== "message" || entry.message.role !== "assistant") continue

			let inTextSegment = false
			const countTextSegment = () => {
				if (!inTextSegment) {
					count++
					inTextSegment = true
				}
			}

			const content = entry.message.content
			for (const block of content) {
				if (block.type === "text") {
					if (!block.text) continue
					countTextSegment()
					for (const part of replayTextParts(block.text)) {
						if (part.kind === "thinking") count++
					}
				} else if (block.type === "thinking") {
					inTextSegment = false
					if (block.redacted || !block.thinking) continue
					count++
				} else {
					// toolCall / unknown: replay flushes the text buffer before
					// emitting the structural block, which terminates any open
					// text segment.
					inTextSegment = false
				}
			}
		}
		record.nextBlockId = count + 1
	}

private replayAssistantBlocks(
		sessionId: string,
		content: AssistantMessage["content"],
		toolResults: Map<string, ReplayToolResult>,
		record: SessionRecord | undefined,
	): void {
		if (!Array.isArray(content)) return
		// Allocates a fresh session-unique messageId for every emitted chunk
		// and leaves it off the wire if the SessionRecord isn't loaded (e.g.
		// the unit-test harness wiring a partial replay path).
		const nextMessageId = () => {
			if (!record) return undefined
			return `km.${record.nextBlockId++}`
		}
		// Buffer contiguous text blocks so a single assistant message renders as
		// one agent_message_chunk per natural text segment — emit the full
		// message as a single chunk, no per-token chunking. When a thinking or
		// toolCall block interrupts the run, flush the buffered text first so
		// ordering relative to those structural blocks is preserved.
		let textBuffer = ""
		const flushText = () => {
			if (textBuffer.length === 0) return
			const messageId = nextMessageId()
			this.send({
				sessionId,
				update: {
					sessionUpdate: "agent_message_chunk",
					content: { type: "text", text: textBuffer },
					...(messageId !== undefined ? { messageId } : {}),
				},
			})
			textBuffer = ""
		}
		for (const block of content) {
			if (!block || typeof block !== "object") continue
			const b = block
			if (b.type === "text") {
				const text = (b as { text?: unknown }).text
				if (typeof text !== "string" || text.length === 0) continue
				for (const part of replayTextParts(text)) {
					if (part.kind === "text") {
						textBuffer += part.text
					} else if (part.kind === "thinking") {
						flushText()
						const messageId = nextMessageId()
						this.send({
							sessionId,
							update: {
								sessionUpdate: "agent_thought_chunk",
								content: { type: "text", text: part.text },
								...(messageId !== undefined ? { messageId } : {}),
							},
						})
					}
				}
			} else if (b.type === "thinking") {
				flushText()
				const thinking = (b as { thinking?: unknown; redacted?: unknown }).thinking
				const redacted = (b as { redacted?: unknown }).redacted === true
				// Redacted thinking has no plaintext to surface — the encrypted
				// payload only matters for multi-turn provider continuity.
				if (redacted || typeof thinking !== "string" || thinking.length === 0) continue
				const messageId = nextMessageId()
				this.send({
					sessionId,
					update: {
						sessionUpdate: "agent_thought_chunk",
						content: { type: "text", text: stripAnsi(thinking) },
						...(messageId !== undefined ? { messageId } : {}),
					},
				})
			} else if (b.type === "toolCall") {
				flushText()
				const tc = b
				const upstreamId = typeof tc.id === "string" ? tc.id : undefined
				const name = typeof tc.name === "string" ? tc.name : undefined
				if (!upstreamId || !name) continue
				const args = (tc.arguments ?? {}) as Record<string, unknown>
				if (isHiddenToolCall(name, args)) continue
				const acpToolCallId = record ? this.getOrAllocateAcpToolCallId(record, upstreamId, name) : upstreamId
				const result = toolResults.get(upstreamId)
				// No persisted result → the call never finished (interrupted mid
				// turn). "failed" is the closest terminal status; leaving the call
				// in_progress would hang the client's spinner forever on replay.
				const status: "completed" | "failed" = result ? (result.isError ? "failed" : "completed") : "failed"
				this.send({
					sessionId,
					update: buildToolCall({
						toolName: name,
						toolCallId: acpToolCallId,
						piToolCallId: tc.id,
						status,
						rawInput: args,
					}),
				})
				this.send({
					sessionId,
					update: buildToolCallUpdate({
						toolCallId: acpToolCallId,
						piToolCallId: tc.id,
						status,
						content: result ? toolResultContent(result) : [],
						rawOutput: result,
					}),
				})
				// The branch may contain multiple toolCalls with the same upstream id
				// (e.g., across a compaction boundary). Drop the mapping after replaying
				// each call so the next one with the same upstream id gets a fresh id.
				record?.toolCallIdMap.delete(upstreamId)
			}
		}
		// Trailing text after the last structural block (or a text-only message)
		// still needs to land — flushText is a no-op when the buffer is empty.
		flushText()
	}

private publishModelOptionIfChanged(sessionId: string, entry: SessionRecord): void {
		const configOptions = buildConfigOptions(entry.session, this.getInitialPermissionMode(entry.session).mode)
		const autoName = autoOptionName(configOptions)
		if (!autoName || autoName === entry.lastModelOptionName) return
		entry.lastModelOptionName = autoName
		this.send({ sessionId, update: { sessionUpdate: "config_option_update", configOptions } })
	}

private send(params: SessionNotification): void {
		// Fire-and-forget is safe here because the ACP SDK chains every outbound
		// message onto a shared writeQueue Promise (see @agentclientprotocol/sdk
		// acp.js#sendMessage), so two consecutive sessionUpdate() calls are
		// written to the stream in the order we invoked them even though we
		// don't await. Do NOT "fix" this into `await this.conn.sessionUpdate(...)`
		// in onSessionEvent — the subscriber is called synchronously from the
		// AgentSession event emitter, and awaiting inside it would back-pressure
		// every subsequent event through the event loop, which pi-mono's
		// _processAgentEvent does not expect.
		this.conn.sessionUpdate(params).catch((err: unknown) => {
			process.stderr.write(`acp sessionUpdate failed: ${String(err)}\n`)
		})
	}

private getOrAllocateAcpToolCallId(record: SessionRecord, piToolCallId: string, toolName: string): string {
		let acpId = record.toolCallIdMap.get(piToolCallId)
		if (acpId === undefined) {
			acpId = buildToolCallId(toolName, record.nextToolCallId++)
			record.toolCallIdMap.set(piToolCallId, acpId)
		}
		return acpId
	}

private resolveAcpToolCallId(record: SessionRecord, piToolCallId: string): string {
		return record.toolCallIdMap.get(piToolCallId) ?? piToolCallId
	}

private retireToolCall(
		record: SessionRecord,
		turn: TurnContext,
		piToolCallId: string,
		opts: RetireToolCallOpts = {},
	): void {
		record.toolCallIdMap.delete(piToolCallId)
		turn.announcedToolCallIds.delete(piToolCallId)
		turn.lastStreamedContent.delete(piToolCallId)
		if (opts.removeFromHidden) {
			turn.hiddenToolCallIds.delete(piToolCallId)
		}
	}

private scheduleAvailableCommandsUpdate(sessionId: string): void {
		setImmediate(() => {
			// The session may have been torn down between the response and
			// the deferred send (e.g. instant disconnect); don't broadcast a
			// palette for a dead session.
			const record = this.sessions.get(sessionId)
			if (!record) return
			this.send({
				sessionId,
				update: {
					sessionUpdate: "available_commands_update",
					availableCommands: composeAvailableCommands(record.skillCommands),
				},
			})
		})
	}

private scheduleProjectTrustUpdate(sessionId: string): void {
		setImmediate(() => {
			const record = this.sessions.get(sessionId)
			if (!record) return
			notifyProjectTrustUpdate(this.conn, buildProjectTrustUpdate(sessionId, record.cwd))
		})
	}

private async handleSetProjectTrust(params: Record<string, unknown>): Promise<Record<string, unknown>> {
		const sessionId = params.sessionId
		if (typeof sessionId !== "string" || sessionId.length === 0) {
			throw RequestError.invalidParams(undefined, "sessionId must be a non-empty string")
		}
		const record = this.sessions.get(sessionId)
		if (!record) {
			throw RequestError.invalidParams(undefined, `unknown sessionId ${sessionId}`)
		}
		const decision = parseProjectTrustDecision(params.decision)
		const trusted = decision === "trust" || decision === "trust_session" || decision === "trust_parent"
		const cwd = record.cwd

		// The directory whose stored decision governs the requesting session —
		// the cwd for every decision except trust_parent, which grants the
		// parent. Also the subtree of live sessions that must be notified and
		// refreshed: trust is per-directory, not per-session, and the gate
		// lookup walks ancestors, so a parent grant covers sibling sessions
		// under it too.
		let affectedRoot = cwd
		if (decision === "trust_parent") {
			const parent = parentTrustPath(cwd)
			if (parent === undefined) {
				throw RequestError.invalidParams(undefined, "session cwd is at the filesystem root; no parent to trust")
			}
			// Same update shape pi's "Trust parent folder" option writes
			// (getProjectTrustOptions): grant the parent, clear any decision
			// pinned on the cwd so the parent's is the nearest entry.
			new ProjectTrustStore(this.agentDir).setMany([
				{ path: parent, decision: true },
				{ path: cwd, decision: null },
			])
			setProjectScopeTrusted(parent, true)
			affectedRoot = parent
		} else if (decision === "trust") {
			new ProjectTrustStore(this.agentDir).set(cwd, true)
			setProjectScopeTrusted(cwd, true)
		} else if (decision === "deny_persist") {
			new ProjectTrustStore(this.agentDir).set(cwd, false)
			setProjectScopeTrusted(cwd, false)
		} else {
			// "trust_session" / "deny": in-memory only, nothing persisted. Scope
			// caveat: the gate pin is keyed by cwd in the process-wide map
			// (src/project-scope-trust.ts), not by session — so a second session
			// on the SAME cwd shares the decision, and a new session at that cwd
			// re-pins fail-closed at start (createSessionSettings), stomping a
			// prior trust_session grant. Session-granular pins are a known v1
			// limitation; only different-cwd sessions are isolated.
			setProjectScopeTrusted(cwd, trusted)
		}

		// Session start pins a fail-closed decision on the session cwd when the
		// project is undecided — and the ancestor-walking lookup would find that
		// pin BEFORE the decision just recorded on affectedRoot, shadowing it
		// (the in-memory analogue of why pi's "Trust parent folder" clears the
		// cwd's store entry with `decision: null`). The sweep below re-mirrors
		// every live session's pin from the store so the walk resolves through
		// the new decision. Session-scoped decisions (trust_session/deny) live
		// only in this in-memory map — the store has no entry for them — so the
		// requester's own cwd is overridden with the in-memory decision instead
		// of a store lookup. Sessions AT affectedRoot are included: without
		// them a session pinned untrusted at the parent would keep shadowing a
		// trust_parent grant.
		this.refreshTrustAffectedSessions(
			new ProjectTrustStore(this.agentDir),
			affectedRoot,
			trusted,
			decision === "trust_session" || decision === "deny" ? { cwd, trusted } : undefined,
		)

		const update = buildProjectTrustUpdate(sessionId, cwd)
		return { trusted: update.trusted, blocked: [...update.blocked] }
	}

private handleGetPathTrust(params: Record<string, unknown>): Record<string, unknown> {
		const path = requireAbsolutePath(params.path)
		return pathTrustResponse(buildPathTrustInfo(new ProjectTrustStore(this.agentDir), path))
	}

private handleSetPathTrust(params: Record<string, unknown>): Record<string, unknown> {
		const path = requireAbsolutePath(params.path)
		const decision = parsePathTrustDecision(params.decision)
		const trusted = decision === "trust"

		const store = new ProjectTrustStore(this.agentDir)
		store.set(path, trusted)
		setProjectScopeTrusted(path, trusted)

		// Re-resolve every live session under the written path FROM THE STORE.
		// A session pinned at start (from the store state then) can shadow the
		// new entry: its own pin is nearer in the ancestor walk than the path
		// just written, so a later revoke at the root would be invisible to it
		// — and a blind clear would equally break a deeper stored grant. Setting
		// each pin to the store's current nearest-wins resolution for that
		// session's cwd (or clearing it when undecided, so the walk falls
		// through to the written entry) mirrors store semantics exactly.
		this.refreshTrustAffectedSessions(store, path, trusted)

		return pathTrustResponse(buildPathTrustInfo(store, path))
	}

private refreshTrustAffectedSessions(
		store: ProjectTrustStore,
		root: string,
		grant: boolean,
		inMemoryOverride?: { cwd: string; trusted: boolean },
	): void {
		for (const other of this.sessions.values()) {
			if (!isPathWithin(other.cwd, root)) continue
			if (inMemoryOverride && other.cwd === inMemoryOverride.cwd) {
				setProjectScopeTrusted(other.cwd, inMemoryOverride.trusted)
				continue
			}
			const entry = store.getEntry(other.cwd)
			if (entry === null) clearProjectScopeTrust(other.cwd)
			else setProjectScopeTrusted(other.cwd, entry.decision)
		}
		for (const [id, other] of this.sessions) {
			if (!isPathWithin(other.cwd, root)) continue
			notifyProjectTrustUpdate(this.conn, buildProjectTrustUpdate(id, other.cwd))
		}
		if (grant) {
			// The watcher's root set must be re-derived on grant: while
			// untrusted, the project skills dir was never added to the watch set,
			// so without refresh() post-grant edits to project skills would never
			// re-advertise palettes. (Roots only grow; revoke keeps watching —
			// see skill-watcher's roots-never-removed note.)
			this.skillWatcher.refresh()
		}
		this.commandsRefresher.request()
	}

private emitUsageUpdate(session: AgentSession, lifetime: TurnUsage): void {
		const ctx = session.getContextUsage()
		// Per the issue doc: skip when getContextUsage() returns undefined or
		// tokens is null (e.g. right after compaction). ACP requires both `used`
		// and `size`, so there is no null-safe emission.
		if (!ctx || ctx.tokens === null) return
		// Piggyback the turn's cumulative lifetime token totals on the
		// notification via _meta — usage_update's used/size only describe the
		// context window, so long-running remote clients would otherwise see no
		// token consumption until the PromptResponse resolves. Cumulative (not
		// per-update) totals keep client-side delta computation idempotent across
		// session/load replays.
		const usageMeta =
			lifetime.messages > 0
				? {
						input: lifetime.input,
						output: lifetime.output,
						cacheRead: lifetime.cacheRead,
						cacheWrite: lifetime.cacheWrite,
					}
				: undefined
		this.send({
			sessionId: session.sessionId,
			...(usageMeta ? { _meta: { [ACP_LIFETIME_USAGE_META_KEY]: usageMeta } } : {}),
			update: {
				sessionUpdate: "usage_update",
				used: ctx.tokens,
				size: ctx.contextWindow,
			},
		})
	}

private finalizeTurn(entry: SessionRecord, stopReason: PromptResponse["stopReason"]): void {
		const turn = entry.turn
		if (!turn) return
		entry.turn = undefined
		try {
			this.emitUsageUpdate(entry.session, turn.usage)
		} finally {
			const response: PromptResponse = { stopReason }
			// usage is v1/experimental-only on PromptResponse (v2 drops it in favor
			// of usage_update session events) and is omitted when the turn produced
			// no usage data (e.g. cancelled before the first assistant message).
			// totalTokens is emitted because the pinned ACP SDK's experimental Usage
			// type marks it required, even though the ticket's v1 field table drops it.
			if (turn.usage.messages > 0) {
				const u = turn.usage
				response.usage = {
					inputTokens: u.input,
					outputTokens: u.output,
					cachedReadTokens: u.cacheRead,
					cachedWriteTokens: u.cacheWrite,
					...(u.sawReasoning ? { thoughtTokens: u.reasoning } : {}),
					totalTokens: u.total,
				}
			}
			turn.resolve(response)
		}
	}

private toAuthRequiredIfUnauthenticated(session: AgentSession, err: unknown): unknown {
		if (err instanceof RequestError) return err
		const model = session.model
		if (!model) return err
		if (getSessionModelRegistry(session).hasConfiguredAuth(model)) return err
		return modelAuthRequiredError(model)
	}

private failTurn(entry: SessionRecord, err: unknown): void {
		const turn = entry.turn
		if (!turn) return
		entry.turn = undefined
		turn.reject(err)
	}

