function removeCastAiOtelVar(env: Record<string, unknown>, endpointKey: string, headerKey: string): void {
	const endpoint = env[endpointKey]
	if (typeof endpoint !== "string" || !ALL_TELEMETRY_URLS.has(endpoint)) return
	env[endpointKey] = undefined
	const headers = env[headerKey]
	if (typeof headers === "string" && headers.startsWith("Authorization=Bearer ")) {
		env[headerKey] = undefined
	}
}

export function injectClaudeCodeEnv(
	env: Record<string, unknown>,
	baseUrl: string,
	apiKey: string,
	options?: { telemetryEnabled?: boolean },
): void {
	const pairs = claudeCodeEnv(apiKey, baseUrl, options)
	for (const [k, v] of Object.entries(pairs)) {
		env[k] = v
	}
	if (!options?.telemetryEnabled) {
		removeCastAiOtelVar(env, "OTEL_EXPORTER_OTLP_LOGS_ENDPOINT", "OTEL_EXPORTER_OTLP_LOGS_HEADERS")
		removeCastAiOtelVar(env, "OTEL_EXPORTER_OTLP_METRICS_ENDPOINT", "OTEL_EXPORTER_OTLP_METRICS_HEADERS")
	}
}

interface EnvDiff {
	kind: "add" | "remove" | "change"
	key: string
	old?: string
	new?: string
}

function envDiff(before: Record<string, unknown>, after: Record<string, unknown>): EnvDiff[] {
	const diffs: ReturnType<typeof envDiff> = []
	const allKeys = new Set([...Object.keys(before), ...Object.keys(after)])
	for (const key of allKeys) {
		const a = String(before[key] ?? "")
		const b = String(after[key] ?? "")
		if (a === b) continue

		if (before[key] === undefined || !(key in before)) {
			diffs.push({ kind: "add", key, new: b })
		} else if (after[key] === undefined || !(key in after)) {
			diffs.push({ kind: "remove", key, old: a })
		} else {
			diffs.push({ kind: "change", key, old: a, new: b })
		}
	}
	return diffs
}

function formatDiff(diffs: EnvDiff[]): string {
	if (diffs.length === 0) return "No changes."

	const lines: string[] = []
	for (const d of diffs) {
		if (d.kind === "add") lines.push(`  + ${d.key}: ${d.new}`)
		else if (d.kind === "remove") lines.push(`  - ${d.key}: ${d.old}`)
		else lines.push(`  ~ ${d.key}: ${d.old} → ${d.new}`)
	}
	return lines.join("\n")
}

async function writeClaudeCode(
	scope: ConfigScope,
	apiKey: string,
	_models: readonly ModelMetadata[],
	options?: { telemetryEnabled?: boolean },
): Promise<void> {
	if (!findBinary("claude")) {
		throw new Error(
			"Claude Code is not installed or not on PATH. " +
				"Install it first: https://docs.anthropic.com/en/docs/claude-code/setup",
		)
	}

	if (!apiKey) {
		throw new Error("API key not configured")
	}

	const path = resolveScopePath(scope, CLAUDE_CONFIG_PATH)
	mkdirSync(dirname(path), { recursive: true })

	const existing = readJson(path)
	const envBlock =
		existing.env && typeof existing.env === "object" && !Array.isArray(existing.env)
			? structuredClone
				? (structuredClone(existing.env) as Record<string, unknown>)
				: (JSON.parse(JSON.stringify(existing.env)) as Record<string, unknown>)
			: {}

	const before = structuredClone
		? structuredClone(envBlock)
		: (JSON.parse(JSON.stringify(envBlock)) as Record<string, unknown>)
	injectClaudeCodeEnv(envBlock, resolveEndpoints().anthropicBaseUrl, apiKey, options)
	const diffs = envDiff(before, envBlock)

	if (diffs.length > 0 && process.stdin?.isTTY) {
		log.message(`Claude Code environment variable changes (${path}):`)
		log.message(formatDiff(diffs))

		const answer = await confirm({
			message: "Apply these changes to Claude Code environment variables?",
			initialValue: true,
			backable: false,
		})

		if (answer.kind === "cancel") {
			throw new Error("User cancelled the settings update.")
		}
		if (answer.kind === "next" && !answer.value) {
			throw new Error("User declined the settings update.")
		}
	}

	existing.env = envBlock
	writeJson(path, existing)

	// Post-write validation: re-read and verify the written file
	const verified = readJson(path)
	if (!verified.env || typeof verified.env !== "object" || Array.isArray(verified.env)) {
		throw new Error(`Claude Code config validation failed at ${path}: env must be an object`)
	}
	const verifiedEnv = verified.env as Record<string, unknown>
	if (typeof verifiedEnv.ANTHROPIC_AUTH_TOKEN !== "string" || verifiedEnv.ANTHROPIC_AUTH_TOKEN.length === 0) {
		throw new Error(`Claude Code config validation failed at ${path}: ANTHROPIC_AUTH_TOKEN must be a non-empty string`)
	}
	if (typeof verifiedEnv.ANTHROPIC_BASE_URL !== "string" || verifiedEnv.ANTHROPIC_BASE_URL.length === 0) {
		throw new Error(`Claude Code config validation failed at ${path}: ANTHROPIC_BASE_URL must be a non-empty string`)
	}
	if (verifiedEnv.ANTHROPIC_API_KEY !== "") {
		throw new Error(
			`Claude Code config validation failed at ${path}: ANTHROPIC_API_KEY must be an empty string so Claude Code uses ANTHROPIC_AUTH_TOKEN`,
		)
	}
}

