export function createSessionPermissionFlagController(initialFlags: {
	mode: PermissionModeState
}): SessionPermissionFlagController {
	let mode = initialFlags.mode
	const listeners = new Set<(changes: SessionPermissionFlagChanges) => void>()

	return {
		getMode: () => mode,
		setMode: (newMode, skipNotify) => {
			mode = newMode
			if (!skipNotify) {
				for (const _l of listeners) _l({ mode })
			}
		},
		subscribe: (listener) => {
			listeners.add(listener)
			return () => listeners.delete(listener)
		},
	}
}

export function getPermissionModeEnvKey(sessionId: string): string {
	return `${PERMISSIONS_ENV_KEY}_${sessionId}`
}

function setPermissionModeEnv(sessionId: string, mode: PermissionMode): void {
	process.env[getPermissionModeEnvKey(sessionId)] = mode
}

export function clearPermissionModeEnv(sessionId: string): void {
	Reflect.deleteProperty(process.env, getPermissionModeEnvKey(sessionId))
}

export function setPermissionMode(sessionId: string, mode: PermissionModeState, skipNotify?: boolean): void {
	const sessionController = getSessionPermissionFlagController(sessionId)
	if (sessionController) {
		sessionController.setMode(mode, skipNotify)
	} else {
		const controller = createSessionPermissionFlagController({ mode })
		registerSessionPermissionFlagController(sessionId, controller)
	}
	setPermissionModeEnv(sessionId, mode.mode)
}

export function getPermissionMode(sessionId: string): PermissionModeState | undefined {
	const sessionController = getSessionPermissionFlagController(sessionId)
	if (sessionController) {
		return sessionController.getMode()
	}
	const envKey = getPermissionModeEnvKey(sessionId)
	const mode = parseModeString(process.env[envKey])
	if (mode) {
		// Runtime because this env is keyed by session id which is a runtime setting
		const state: PermissionModeState = { mode, initiatedBy: "user", source: "runtime" }
		setPermissionMode(sessionId, state)
		return state
	}
	return undefined
}

export function getPersistedPermissionMode(
	sessionManager: Pick<SessionManager, "getEntries">,
	filterBy?: (state: PermissionModeState) => boolean,
): PermissionModeState | undefined {
	const entries = sessionManager.getEntries()
	for (let i = entries.length - 1; i >= 0; i--) {
		const item = entries[i]
		if (item.type !== "custom" || item.customType !== PERMISSION_MODE_SESSION_ENTRY_TYPE) continue
		const data = (item as CustomEntry<PermissionModeState>).data
		if (!data || (filterBy && !filterBy(data))) continue
		return data
	}
	return undefined
}

export function persistPermissionModeIfChanged(
	sessionManager: Pick<SessionManager, "getEntries">,
	appendEntry: (customType: string, data: PermissionModeState) => void,
	mode: PermissionModeState,
): boolean {
	const lastLogged = getPersistedPermissionMode(sessionManager)
	if (lastLogged?.mode === mode.mode && lastLogged.initiatedBy === mode.initiatedBy) return false
	appendEntry(PERMISSION_MODE_SESSION_ENTRY_TYPE, mode)
	return true
}

export function resolveInitialPermissionMode(
	sessionManager: Pick<SessionManager, "getSessionId" | "getEntries">,
	permissionsEnvFlag: string | undefined,
	cliFlag: PermissionMode | undefined,
	config: LoadedConfig,
): PermissionModeState {
	const sessionId = sessionManager.getSessionId()
	const runtimeMode = getPermissionMode(sessionId)

	// Subagents inherit the parent session's current mode via the parent's
	// per-session env key. Treat that inherited value as runtime state so it
	// outranks the subagent's own session log.
	const parentSessionId = process.env[PARENT_SESSION_ID_ENV_KEY]
	const inheritedMode = parentSessionId
		? parseModeString(process.env[getPermissionModeEnvKey(parentSessionId)])
		: undefined
	const effectiveRuntime =
		runtimeMode ?? (inheritedMode ? { mode: inheritedMode, source: "runtime", initiatedBy: "user" } : undefined)

	const persistedMode = getPersistedPermissionMode(sessionManager, (state) => state.initiatedBy === "user")
	return {
		...resolveMode({
			runtime: effectiveRuntime,
			flag: cliFlag,
			env: permissionsEnvFlag,
			persisted: persistedMode,
			config: config.config.defaultMode,
		}),
		initiatedBy: "user",
	}
}

kimchi_extensions/permissions/mode.ts.text:
export interface ModeResolution {
	mode: PermissionMode
	source: PermissionModeSource
}

export interface ModeResolutionInput {
	/** Active runtime controller value (highest precedence). */
	runtime?: PermissionModeState
	/** CLI flag value (--plan/--yolo/--auto/--dangerously-skip-permissions). */
	flag?: PermissionMode
	/** KIMCHI_PERMISSIONS env var. */
	env?: string
	/** Last persisted permission_mode session-log entry. */
	persisted?: PermissionModeState
	/** defaultMode from merged permissions.json. */
	config: PermissionMode
}

export function parseModeString(s: string | undefined): PermissionMode | undefined {
	if (!s) return undefined
	const lower = s.toLowerCase()
	if (PERMISSION_MODES.includes(lower as PermissionMode)) return lower as PermissionMode
	return undefined
}

export function resolveMode(input: ModeResolutionInput): PermissionModeState {
	if (input.runtime) return input.runtime
	if (input.flag) return { mode: input.flag, source: "flag", initiatedBy: "user" }
	const envMode = parseModeString(input.env)
	if (envMode) return { mode: envMode, source: "env", initiatedBy: "user" }
	if (input.persisted) return input.persisted
	return { mode: input.config, source: "config", initiatedBy: "user" }
}

mcp_probe_methods.text:
async probeTools(name: string, definition: ServerEntry, options: McpProbeOptions = {}): Promise<ProbeResult> {
		options.signal?.throwIfAborted()
		installKeyringRequireBridge()
		installProbeToolMetadataCapture()
		const capturedTools = new Map<string, ProbeTool>()
		// URL-only servers can advertise OAuth during connection. Reserve time
		// for that discovery without assuming every remote server needs a login.
		const timeoutMs = definition.url ? 60_000 : 15_000
		const timeoutMessage = `Probe timed out after ${timeoutMs / 1000} seconds`
		const deadline = new AbortController()
		let timer: ReturnType<typeof setTimeout> | undefined = setTimeout(
			() => deadline.abort(new Error(timeoutMessage)),
			timeoutMs,
		)
		// Interactive OAuth can legitimately outlast the probe deadline (the user
		// must find the browser and consent), so the auth phase suspends/resumes it.
		const suspendDeadline = (): void => {
			if (timer !== undefined) {
				clearTimeout(timer)
				timer = undefined
			}
		}
		const resumeDeadline = (): void => {
			// The post-auth phase intentionally re-arms a full fresh `timeoutMs`
			// budget, so total wall time can reach
			// timeoutMs + INTERACTIVE_AUTH_TIMEOUT_MS + timeoutMs.
			if (timer === undefined && !deadline.signal.aborted) {
				timer = setTimeout(() => deadline.abort(new Error(timeoutMessage)), timeoutMs)
			}
		}
		const signal = options.signal ? AbortSignal.any([options.signal, deadline.signal]) : deadline.signal
		try {
			return await probeToolCapture.run(capturedTools, () =>
				this.probeToolsWithMetadata(name, definition, { ...options, signal }, capturedTools, {
					suspendDeadline,
					resumeDeadline,
				}),
			)
		} catch (error) {
			if (deadline.signal.aborted && !options.signal?.aborted) {
				return { tools: [], needsAuth: false, error: timeoutMessage }
			}
			throw error
		} finally {
			suspendDeadline()
		}
	}

private async probeToolsWithMetadata(
		name: string,
		definition: ServerEntry,
		options: McpProbeOptions & { signal: AbortSignal },
		capturedTools: Map<string, ProbeTool>,
		deadline: DeadlineControl,
	): Promise<ProbeResult> {
		const cwd = options.cwd ?? process.cwd()
		if (definition.url) {
			const { warnings } = migrateLegacyOAuthCredentials({ mcpServers: { [name]: definition } }, { cwd })
			for (const warning of warnings) console.warn(warning)
		}
		const probeName = resolveProbeName(name, definition)
		const throwaway = probeName !== name
		const serverUrl = definition.url
		const hasHeaders = Boolean(definition.headers && Object.keys(definition.headers).length > 0)
		// Exact mirror of the adapter's supportsOAuth gate and its return ordering
		// (pi-mcp-adapter/mcp-auth-flow.ts): URL servers only (stdio cannot run
		// the browser flow), an explicit `auth: false` or `oauth: false` disables
		// it, an explicit `auth: "oauth"` wins BEFORE the custom-headers check —
		// headers only veto the implicit oauth auto-detection, never a declared
		// one — and auto-detection requires `auth` to be unset with no headers.
		const supportsOAuthLike =
			serverUrl !== undefined &&
			definition.auth !== false &&
			definition.oauth !== false &&
			(definition.auth === "oauth" || (definition.auth === undefined && !hasHeaders))
		// Deliberately NARROWER than supportsOAuthLike: auto-detect servers
		// (auth unset, no oauth block) must NOT be badged needs-auth up front.
		// Used ONLY for the needs-auth reporting branch; the connect consent
		// window uses the upstream-mirrored supportsOAuthLike instead.
		const declaresOAuth =
			serverUrl !== undefined &&
			definition.auth !== false &&
			definition.oauth !== false &&
			(definition.auth === "oauth" || (definition.auth === undefined && !hasHeaders && Boolean(definition.oauth)))
		const hasCredentials = serverUrl !== undefined && hasOAuthCredentials(name, serverUrl)
		// Scoped to this interactive mcp-auth invocation: aborting it rejects the
		// fake UI hooks, which unwinds upstream's manual-paste race (and closes the
		// localhost callback listener) instead of abandoning the flow.
		const authAbort = new AbortController()
		const host = createProbeHost(cwd, options.signal, authAbort)
		const config = {
			mcpServers: {
				[probeName]: { ...definition, directTools: false, lifecycle: "lazy" as const },
			},
			settings: {
				toolPrefix: "none" as const,
				directTools: false,
				scriptMode: false,
				// Upstream only starts OAuth after a needs-auth connection result
				// and its supportsOAuth check; public and bearer servers skip it.
				autoAuth: options.authenticate === true,
				sampling: false,
				elicitation: false,
			},
		}
		const { signal } = options
		let onAbort: () => void = () => {}
		const aborted = new Promise<never>((_resolve, reject) => {
			onAbort = () => reject(signal.reason)
			signal.addEventListener("abort", onAbort, { once: true })
		})
		try {
			signal.throwIfAborted()
			createMcpAdapter({ config })(host.api)
			await Promise.race([emitHandlers(host, "session_start"), aborted])
			signal.throwIfAborted()
			// For servers that 401 at connect, upstream's attemptAutoAuth opens the
			// consent browser INSIDE this first connect. That must not run under the
			// 60s probe deadline (a slow consent would surface as "Probe timed out
			// after 60 seconds" with needsAuth: false), so suspend it and race the
			// connect against the interactive consent budget instead.
			const connectAuthWindow =
				options.authenticate === true && supportsOAuthLike ? createInteractiveAuthWindow(authAbort) : null
			if (connectAuthWindow) deadline.suspendDeadline()
			let connected: GatewayResult
			try {
				connected = await Promise.race(
					connectAuthWindow
						? [executeGateway(host, { connect: probeName }), connectAuthWindow.deadline, aborted]
						: [executeGateway(host, { connect: probeName }), aborted],
				)
			} catch (error) {
				if (connectAuthWindow && error === connectAuthWindow.timeoutError) {
					// The auth signal is already aborted, so upstream's flow has unwound;
					// report the expiry as a needs-auth result.
					return { tools: [], needsAuth: true, error: connectAuthWindow.timeoutError.message }
				}
				throw error
			} finally {
				if (connectAuthWindow) {
					connectAuthWindow.cancel()
					deadline.resumeDeadline()
				}
			}
			signal.throwIfAborted()
			const details = resultDetails(connected)
			if (details.error === "auth_required") {
				return {
					tools: [],
					needsAuth: true,
					error: options.authenticate ? String(details.message ?? resultMessage(connected)) : null,
				}
			}
			if (details.error) {
				return { tools: [], needsAuth: false, error: String(details.message ?? resultMessage(connected)) }
			}

			// Anonymous tools/list (e.g. Google's hosted MCP endpoints) means a successful
			// connect doesn't imply auth: declared-OAuth servers without credentials must
			// report needs-auth, driving the TUI's /mcp-auth flow when authenticate=true.
			if (declaresOAuth && serverUrl && !hasCredentials) {
				// Never drive OAuth under a throwaway name — the finally-block logout
				// would discard the just-consented credentials.
				if (options.authenticate !== true || throwaway) {
					return { tools: [...capturedTools.values()], needsAuth: true, error: null }
				}
				// The first connect may already have auto-authenticated (401-at-connect
				// servers store tokens inside attemptAutoAuth); re-inspect so a successful
				// autoAuth doesn't redundantly re-run mcp-auth. Credentials are keyed by
				// server name; the throwaway guard above keeps durable credentials safe.
				if (!hasOAuthCredentials(probeName, serverUrl)) {
					deadline.suspendDeadline()
					const authWindow = createInteractiveAuthWindow(authAbort)
					let authFailureMessage: string | null = null
					const mcpAuthCommand = host.commands.get("mcp-auth")
					try {
						if (!mcpAuthCommand) {
							throw new Error("pi-mcp-adapter did not register its mcp-auth command")
						}
						await Promise.race([
							mcpAuthCommand.handler(probeName, host.context as Parameters<Command["handler"]>[1]),
							authWindow.deadline,
							aborted,
						])
					} catch (authError) {
						signal.throwIfAborted()
						// Failures are re-detected via credential inspection below, but must not
						// stay silent: surface the reason on the result for diagnosis.
						authFailureMessage = authError instanceof Error ? authError.message : String(authError)
						console.warn(`MCP probe: interactive OAuth for "${probeName}" failed: ${authFailureMessage}`)
					} finally {
						authWindow.cancel()
						deadline.resumeDeadline()
					}
					signal.throwIfAborted()
					if (!hasOAuthCredentials(probeName, serverUrl)) {
						// Upstream's mcp-auth handler resolves without a result on {ok:false}
						// (denied consent or a failed token exchange): thrown errors carry the
						// real reason, resolved denials reach here without one and get this
						// generic message — surfacing is best-effort by design.
						if (authFailureMessage === null) {
							authFailureMessage = "Interactive OAuth did not complete (consent denied or cancelled)"
						}
						// The anonymous connect already listed the tools; a denied consent
						// must not make the catalog disappear.
						return { tools: [...capturedTools.values()], needsAuth: true, error: authFailureMessage }
					}
					const reconnected = await Promise.race([executeGateway(host, { connect: probeName }), aborted])
					signal.throwIfAborted()
					const reconnectDetails = resultDetails(reconnected)
					if (reconnectDetails.error === "auth_required") {
						// A denied/failed interactive attempt can still land here (e.g. tokens
						// stored but rejected on reconnect); don't discard its reason.
						return { tools: [...capturedTools.values()], needsAuth: true, error: authFailureMessage ?? null }
					}
					if (reconnectDetails.error) {
						return {
							tools: [],
							needsAuth: false,
							error: String(reconnectDetails.message ?? resultMessage(reconnected)),
						}
					}
				}
			}

			// The gateway catalog is filtered, renames tools, and adds resource tools.
			// Discovery must expose the server's original tools/list catalog so users
			// can select tools that their current model-facing configuration excludes.
			return { tools: [...capturedTools.values()], needsAuth: false, error: null }
		} finally {
			signal.removeEventListener("abort", onAbort)
			if (throwaway) {
				const commandContext = host.context as Parameters<Command["handler"]>[1]
				await host.commands
					.get("mcp")
					?.handler(`logout ${probeName}`, commandContext)
					.catch(() => {})
			}
			await emitHandlers(host, "session_shutdown").catch(() => {})
		}
	}

mcp_probe_process_helpers.text:
function executeProcess(
	command: string,
	args: string[],
	options: { cwd?: string; env?: NodeJS.ProcessEnv; signal?: AbortSignal } = {},
): Promise<{ code: number; stdout: string; stderr: string }> {
	return new Promise((resolve) => {
		const child = spawn(command, args, {
			cwd: options.cwd,
			env: options.env,
			stdio: ["ignore", "pipe", "pipe"],
		})
		let stdout = ""
		let stderr = ""
		const abort = () => child.kill()
		options.signal?.addEventListener("abort", abort, { once: true })
		child.stdout?.setEncoding("utf8").on("data", (chunk: string) => {
			stdout += chunk
		})
		child.stderr?.setEncoding("utf8").on("data", (chunk: string) => {
			stderr += chunk
		})
		child.once("error", (error) => {
			options.signal?.removeEventListener("abort", abort)
			resolve({ code: 1, stdout, stderr: stderr || error.message })
		})
		child.once("close", (code) => {
			options.signal?.removeEventListener("abort", abort)
			resolve({ code: code ?? 1, stdout, stderr })
		})
	})
}

function createProbeHost(cwd: string, signal: AbortSignal | undefined, authAbort?: AbortController): ProbeHost {
	const handlers = new Map<string, Handler[]>()
	const commands = new Map<string, Command>()
	const tools = new Map<string, ToolDefinition>()
	const activeTools = new Set<string>()
	const eventHandlers = new Map<string, Array<(data: unknown) => void>>()

	// The fake UI hooks must stay pending while the OAuth flow is active, but
	// reject once the probe or the interactive auth window aborts — otherwise an
	// abandoned flow would leave upstream's localhost callback listener bound.
	const uiSignals = [signal, authAbort?.signal].filter((s): s is AbortSignal => Boolean(s))
	const ui = {
		select: () => neverSettle(uiSignals),
		confirm: () => neverSettle(uiSignals),
		input: () => neverSettle(uiSignals),
		notify: () => {},
		onTerminalInput: () => () => {},
		setStatus: () => {},
		setWorkingMessage: () => {},
		setWorkingVisible: () => {},
		setWorkingIndicator: () => {},
		setHiddenThinkingLabel: () => {},
		setWidget: () => {},
		setFooter: () => {},
		setHeader: () => {},
		setTitle: () => {},
	}
	const context = { cwd, hasUI: true, mode: "tui", signal, ui } as unknown as ExtensionContext

	const api = {
		on(event: string, handler: Handler) {
			const current = handlers.get(event) ?? []
			current.push(handler)
			handlers.set(event, current)
		},
		registerCommand(name: string, command: Command) {
			commands.set(name, command)
		},
		registerFlag() {},
		getFlag() {
			return undefined
		},
		registerTool(tool: ToolDefinition) {
			tools.set(tool.name, tool)
			activeTools.add(tool.name)
		},
		unregisterTool(name: string) {
			activeTools.delete(name)
			return tools.delete(name)
		},
		getActiveTools() {
			return [...activeTools]
		},
		getAllTools() {
			return [...tools.values()]
		},
		setActiveTools(names: string[]) {
			activeTools.clear()
			for (const name of names) activeTools.add(name)
		},
		events: {
			on(channel: string, handler: (data: unknown) => void) {
				const current = eventHandlers.get(channel) ?? []
				current.push(handler)
				eventHandlers.set(channel, current)
				return () => {
					const index = current.indexOf(handler)
					if (index >= 0) current.splice(index, 1)
				}
			},
			emit(channel: string, data: unknown) {
				for (const handler of eventHandlers.get(channel) ?? []) handler(data)
			},
		},
		exec: executeProcess,
		sendMessage() {},
		sendUserMessage() {},
		appendEntry() {},
		registerShortcut() {},
		registerMessageRenderer() {},
		registerMarkdownTransformer() {},
		registerEntryRenderer() {},
	} as unknown as ExtensionAPI

	return { api, context, commands, handlers, tools }
}

agent_manager_methods.text:
setMaxConcurrent(n: number) {
		this.maxConcurrent = Math.max(1, n)
		this.drainQueue()
	}

getMaxConcurrent(): number {
		return this.maxConcurrent
	}

spawn(pi: ExtensionAPI, ctx: ExtensionContext, type: SubagentType, prompt: string, options: SpawnOptions): string {
		const effectiveOptions = applyLinkedWorkerLimits(options)
		// Steer prompts assume sandbox context — never default to a local run.
		if (effectiveOptions.continuation && !effectiveOptions.remote) {
			throw new Error("SpawnOptions.continuation requires remote: true")
		}
		const id = randomUUID().slice(0, 17)
		const abortController = new AbortController()
		const record: AgentRecord = {
			id,
			type,
			description: effectiveOptions.description,
			visibility: effectiveOptions.visibility ?? "user",
			status: effectiveOptions.isBackground ? "queued" : "running",
			modelId: (effectiveOptions.model as { id?: string } | undefined)?.id,
			toolUses: 0,
			startedAt: Date.now(),
			abortController,
			sessionFile: effectiveOptions.sessionFile,
			taskRef: effectiveOptions.taskRef,
			currentAttemptId: 0,
			maxTurns: effectiveOptions.maxTurns,
			resumeAttempts: [],
			lifetimeUsage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
			compactionCount: 0,
			remote: effectiveOptions.remote,
			gitWorkflow: effectiveOptions.gitWorkflow,
		}
		this.agents.set(id, record)

		const args: SpawnArgs = {
			pi,
			ctx,
			type,
			prompt: withAgentReportProtocol(prompt, effectiveOptions.taskRef),
			options: effectiveOptions,
		}

		if (
			effectiveOptions.isBackground &&
			!effectiveOptions.bypassQueue &&
			this.runningBackground >= this.maxConcurrent
		) {
			this.queue.push({ id, args })
			return id
		}

		try {
			this.startAgent(id, record, args)
		} catch (err) {
			this.agents.delete(id)
			throw err
		}
		return id
	}

private startAgent(id: string, record: AgentRecord, { pi, ctx, type, prompt, options }: SpawnArgs) {
		record.status = "running"
		record.startedAt = Date.now()
		record.isBackground = options.isBackground ?? false
		if (record.isBackground) this.runningBackground++
		this.onStart?.(record, ctx)

		let detachParentSignal: (() => void) | undefined
		if (options.signal) {
			const onParentAbort = () => this.abort(id)
			options.signal.addEventListener("abort", onParentAbort, { once: true })
			detachParentSignal = () => options.signal?.removeEventListener("abort", onParentAbort)
		}
		record.detachFromParent = () => {
			detachParentSignal?.()
			detachParentSignal = undefined
		}
		const detach = () => {
			record.detachFromParent?.()
			record.detachFromParent = undefined
		}

		const runPromise = record.remote
			? this._runRemote(record, prompt, options, ctx)
			: runAgent(ctx, type, prompt, {
					pi,
					model: options.model,
					maxTurns: options.maxTurns,
					tokenBudget: options.tokenBudget,
					inactivityTimeout: options.inactivityTimeout,
					maxDuration: options.maxDuration,
					workerReport: record.taskRef
						? {
								isAccepted: () => record.agentReport?.attempt_id === record.currentAttemptId,
								submit: (report) => {
									const accepted = this.submitReport(id, report) != null
									return {
										accepted,
										message: accepted
											? "Agent report recorded. Worker run complete."
											: "Agent report rejected because this worker is no longer active.",
									}
								},
							}
						: undefined,
					hardTurnLimit: record.taskRef?.kind === "ferment_step",
					isolated: options.isolated,
					inheritContext: options.inheritContext,
					thinkingLevel: options.thinkingLevel,
					sessionFile: options.sessionFile,
					sessionDir: options.sessionDir,
					signal: record.abortController?.signal,
					onToolActivity: (activity) => {
						// Count only terminal statuses — a "pending" notification is
						// not a completed tool use.
						if (activity.status === "completed" || activity.status === "failed") record.toolUses++
						options.onToolActivity?.(activity)
					},
					onTurnEnd: (turnCount) => {
						record.lastTurnCount = turnCount
						options.onTurnEnd?.(turnCount)
					},
					onTextDelta: options.onTextDelta,
					onAssistantUsage: (usage) => {
						addUsage(record.lifetimeUsage, usage)
						options.onAssistantUsage?.(usage)
					},
					onCompaction: (info) => {
						record.compactionCount++
						this.onCompact?.(record, info)
						options.onCompaction?.(info)
					},
					onRuntimeCleanupRegistered: (cleanup) => {
						this.runtimeCleanups.set(record, cleanup)
					},
					onSessionCreated: (session) => {
						record.session = session
						if (record.pendingSteers?.length) {
							for (const msg of record.pendingSteers) {
								session.steer(msg).catch(() => {})
							}
							record.pendingSteers = undefined
						}
						options.onSessionCreated?.(session)
					},
					onSystemPrompt: (prompt) => {
						record.systemPrompt = prompt
					},
				})
		// Remote runs (fresh and resumed) share one completion wiring; the
		// local chain below is the original code, deliberately untouched.
		const promise = record.remote
			? this.wireRemoteCompletion(record, runPromise, { detach, maxTurns: options.maxTurns })
			: runPromise
					.then(({ responseText, session, aborted, abortReason, steered, turnsUsed, maxTurns, planPath }) => {
						if (record.status !== "stopped") {
							record.status = aborted ? "aborted" : steered ? "steered" : "completed"
						}
						record.abortReason = abortReason
						const finalText = planPath ? `${responseText}\n\nPlan saved to: ${planPath}` : responseText
						record.result = finalText
						record.session = session
						record.lastTurnCount = turnsUsed
						// Preserve the effective, normalized turn cap returned by the runner.
						record.maxTurns = maxTurns ?? options.maxTurns
						record.completedAt ??= Date.now()
						record.latestOutcome = buildAgentOutcome(record)

						if (record.isBackground) {
							this.runningBackground--
							this.onComplete?.(record)
							this.drainQueue()
						}
						return finalText
					})
					.catch((err) => {
						if (record.status !== "stopped") {
							record.status = "error"
							record.error = err instanceof Error ? err.message : String(err)
						}
						record.completedAt ??= Date.now()
						record.latestOutcome = buildAgentOutcome(record)

						if (record.isBackground) {
							this.runningBackground--
							this.onComplete?.(record)
							this.drainQueue()
						}
						return ""
					})
					.finally(() => {
						detach()
						this.cleanupRecordRuntime(record)
						record.promise = undefined
					})

		record.promise = promise
	}

private _prepareRemoteAdapter(record: AgentRecord, prompt: string, options: SpawnOptions): RemoteAgentSession {
		const remoteSession = new RemoteAgentSession()
		record.session = remoteSession as unknown as AgentSession
		// Fire onSessionCreated so the activity tracker (in index.ts) can
		// subscribe to session events — specifically activity_reset which
		// fires on WS reattach to clear stale tools from the progress line.
		options.onSessionCreated?.(remoteSession as unknown as AgentSession)
		// Seed the transcript with the user prompt so ConversationViewer shows it
		// immediately, before any assistant text arrives.
		remoteSession.setUserPrompt(prompt)
		return remoteSession
	}

private _remoteCallbacks(record: AgentRecord, remoteSession: RemoteAgentSession, options: SpawnOptions) {
		return {
			onTextDelta: (delta: string, fullText: string) => {
				remoteSession.appendAssistantText(fullText)
				options.onTextDelta?.(delta, fullText)
			},
			onToolActivity: (activity: ToolActivity) => {
				if (activity.status === "in_progress") {
					remoteSession.recordToolCallStart(activity.toolName, activity.toolCallId, activity.rawInput)
				} else {
					remoteSession.recordToolCallEndFromActivity(activity)
					record.toolUses++
				}
				options.onToolActivity?.(activity)
			},
			onTurnEnd: (turnCount: number) => {
				record.lastTurnCount = turnCount
				remoteSession.incrementTurnCount()
				options.onTurnEnd?.(turnCount)
			},
			onAssistantUsage: (usage: LifetimeUsage) => {
				remoteSession.addUsage(usage)
				addUsage(record.lifetimeUsage, usage)
				options.onAssistantUsage?.(usage)
			},
			onContextUsage: (used: number, size: number) => remoteSession.setContextUsage(used, size),
			onRawNotification: (params: SessionNotification) => {
				options.onRawNotification?.(params)
			},
		}
	}

private _remoteCompletedResult(
		record: AgentRecord,
		remoteSession: RemoteAgentSession,
		result: Awaited<ReturnType<typeof runRemoteAgent>>,
	): RemoteRunResult {
		record.remoteSession = result.remoteSession
		if (result.recoveryNote) {
			record.recoveryNote = result.recoveryNote
		}

		// A failed recovery means the run's outcome is unknown — the run must
		// not read as completed (the post-completion dropdown would offer
		// Review/Sync on a result nobody has). Throw so the manager's catch
		// path marks the record "error" and the failure UX takes over.
		if (result.stopReason === "recovery_failed") {
			throw new Error(
				"the remote run finished during a network disconnect and its result could not be recovered — outcome unknown",
			)
		}
		// Whitelist successful stop reasons: "end_turn" (normal completion) and
		// "recovered" (result replayed after a disconnect). ACP can also resolve
		// a prompt with "refusal", "max_tokens", or "max_turn_requests" — those
		// are failures, not completions. "cancelled" maps to aborted below.
		if (result.stopReason !== "end_turn" && result.stopReason !== "recovered" && result.stopReason !== "cancelled") {
			throw new Error(`remote agent stopped unexpectedly (stopReason: ${result.stopReason})`)
		}

		return {
			responseText: result.responseText,
			session: remoteSession as unknown as AgentSession,
			aborted: result.stopReason === "cancelled",
			abortReason: undefined,
			steered: false,
			turnsUsed: remoteSession.turnCount,
			maxTurns: undefined,
		}
	}

private async _runRemoteContinuation(
		record: AgentRecord,
		prompt: string,
		options: SpawnOptions,
		_ctx: ExtensionContext,
	): Promise<RemoteRunResult> {
		const apiKey = loadConfig().apiKey
		if (!apiKey) throw new Error("No API key configured. Run `kimchi login`.")
		const continuation = options.continuation
		if (!continuation) throw new Error("_runRemoteContinuation requires options.continuation")

		const remoteSession = this._prepareRemoteAdapter(record, prompt, options)
		const result = await continueRemoteAgent({
			apiKey,
			endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
			signal: record.abortController?.signal,
			remoteSession: continuation.remoteSession,
			acpSessionId: continuation.acpSessionId,
			prompt,
			outputFile: record.outputFile,
			onReady: async (acpClient, meta) => {
				remoteSession.bindClient(acpClient, meta)
				record.acpSessionId = continuation.acpSessionId
				record.remoteSession ??= meta
				options.onRemoteReady?.({ meta, acpSessionId: continuation.acpSessionId })
			},
			onReconnecting: (reconnecting) => {
				remoteSession.setReconnecting(reconnecting)
				if (isActiveStatus(record.status)) {
					record.status = reconnecting ? "reconnecting" : "running"
				}
			},
			callbacks: this._remoteCallbacks(record, remoteSession, options),
		})
		return this._remoteCompletedResult(record, remoteSession, result)
	}

private async _runRemote(
		record: AgentRecord,
		prompt: string,
		options: SpawnOptions,
		ctx: ExtensionContext,
	): Promise<RemoteRunResult> {
		// Steer continuation of a kept-alive PR session hands off here — the
		// remote dispatch is the single entry point for fresh runs and steers.
		if (options.continuation) return this._runRemoteContinuation(record, prompt, options, ctx)

		const apiKey = loadConfig().apiKey
		if (!apiKey) throw new Error("No API key configured. Run `kimchi login`.")

		const workspaces = await listWorkspaces(apiKey, {
			endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
			signal: record.abortController?.signal,
		})
		// Match a workspace whose name matches the current repo dir (same convention
		// as /teleport, which names workspaces by basename(cwd)). If no match is
		// found, mint a new one rather than reusing an unrelated workspace.
		const dirName = basename(ctx.cwd) || "kimchi"
		const byName = workspaces.find((w) => w.name.toLowerCase() === dirName.toLowerCase())
		const workspaceId = byName?.id ?? randomUUID()
		// Workspace spec (kimchi_workspace.yaml) rides the upsert PUT only
		// when minting — a name-matched workspace keeps its existing spec
		// (spec fields are create-time-only server-side).
		const workspaceSpec = byName ? undefined : resolveWorkspaceSpec(loadWorkspaceFile(ctx.cwd))

		// Resolve git clone plan from the local repo so the sandbox gets a
		// shallow clone of the repo (like /teleport --fast) instead of an empty dir.
		// If cwd isn't a git repo or has no origin, this is a no-op.
		let gitDetails: { repo: string; branch?: string; targetDirectory: string; noHistory?: boolean } | undefined
		let gitCredential: { host: string; token: string } | undefined
		try {
			const clonePlan = await resolveClonePlan(ctx.cwd, undefined, { signal: record.abortController?.signal })
			gitDetails = {
				repo: clonePlan.httpsUrl,
				// PR-intent runs override the branch: the worker forks the clone's
				// default branch into the PR branch (created when missing).
				branch: record.gitWorkflow?.branch ?? clonePlan.branch,
				targetDirectory: repoBasename(clonePlan.url),
				noHistory: true,
			}
			// Resolve git credential separately — a failure here (bad URL, prompt
			// rejection) must not wipe the clone plan. The clone proceeds without
			// creds; private repos fail, public repos still work.
			try {
				gitCredential = await resolveGitCredential(ctx, clonePlan)
			} catch (err) {
				gitCredential = undefined
				console.warn(`[agent-manager] git credential resolution failed: ${err instanceof Error ? err.message : err}`)
			}
		} catch {
			// Not a git repo or no origin — proceed without git details.
			gitDetails = undefined
			gitCredential = undefined
		}

		const remoteSession = this._prepareRemoteAdapter(record, prompt, options)

		let baselineCaptureAttempted = false
		const result = await runRemoteAgent(workspaceId, prompt, {
			apiKey,
			endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
			signal: record.abortController?.signal,
			// PR-intent runs keep the remote session after completion — the
			// review/steer loop attaches to it (deleted at terminal actions).
			keepAlive: record.gitWorkflow !== undefined,
			gitDetails,
			gitCredential,
			localPath: ctx.cwd,
			workspaceName: dirName,
			outputFile: record.outputFile,
			tags: { [SESSION_TAG_PARENT_SESSION_ID]: ctx.sessionManager.getSessionId() },
			...(workspaceSpec ? { spec: workspaceSpec } : {}),
			onReady: async (acpClient, meta) => {
				remoteSession.bindClient(acpClient, meta)
				// Capture the ACP session id for resume-after-restart persistence
				// (session/load attaches by id, never by name).
				const acpSessionId = acpClient.sessionId ?? undefined
				if (acpSessionId) {
					record.acpSessionId = acpSessionId
					record.remoteSession ??= meta
				}
				// Baseline capture (PR-first runs): HEAD at provisioning + the
				// user's pre-existing dirty files. The runner awaits this before
				// prompt() so the persisted running-state entry carries it. The
				// attempted flag guards re-runs on reattach: a FAILED first capture
				// must degrade to the plain completion menu, not re-capture a
				// post-commit HEAD as baseSha (silently poisoning the diff range).
				if (record.gitWorkflow && !record.gitWorkflow.baseSha && !baselineCaptureAttempted) {
					baselineCaptureAttempted = true
					// Bounded per ssh round trip (two commands: rev-parse + status);
					// the run otherwise looks idle for up to ~90s on a cold sandbox —
					// name what it's doing instead of staring at "analyzing".
					ctx.ui.notify?.(
						"Capturing the pre-run git baseline over SSH (one-time snapshot used for the review diff)…",
						"info",
					)
					// One retry for the ssh layer: the proxy enumerates the control
					// API with its own deadline and transient stalls answer as exit
					// status 255. Everything else fails once, honestly.
					for (let attempt = 0; ; attempt++) {
						try {
							const connection = await resolveSandboxGitConnection(meta, apiKey, {
								endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
							})
							const baseline = await captureBaseline(connection, {
								signal: record.abortController?.signal,
								timeoutMs: 45_000,
							})
							record.gitWorkflow.baseSha = baseline.baseSha
							record.gitWorkflow.dirtyFiles = baseline.dirtyFiles
							break
						} catch (err) {
							const isSshLayer = err instanceof SandboxGitError && err.exitCode === 255
							if (isSshLayer && attempt === 0) continue
							// Was console.warn — invisible. This degrades the PR review at
							// completion (no deterministic range), so tell the user now.
							const message = `Pre-run snapshot failed: ${err instanceof Error ? err.message : err}. This is a one-time HEAD snapshot taken before the agent commits — diff review at completion will recover via merge-base instead.`
							ctx.ui.notify?.(message, "warning")
							console.warn(`[agent-manager] baseline capture failed: ${err instanceof Error ? err.message : err}`)
							break
						}
					}
				}
				if (acpSessionId) {
					options.onRemoteReady?.({ meta, acpSessionId })
				}
			},
			onReconnecting: (reconnecting) => {
				remoteSession.setReconnecting(reconnecting)
				// Never resurrect a record the user already stopped or aborted.
				if (isActiveStatus(record.status)) {
					record.status = reconnecting ? "reconnecting" : "running"
				}
			},
			callbacks: this._remoteCallbacks(record, remoteSession, options),
		})

		return this._remoteCompletedResult(record, remoteSession, result)
	}

private drainQueue() {
		while (this.queue.length > 0 && this.runningBackground < this.maxConcurrent) {
			// biome-ignore lint/style/noNonNullAssertion: shift() is guaranteed non-undefined inside while(length > 0) loop
			const next = this.queue.shift()!
			const record = this.agents.get(next.id)
			if (record?.status !== "queued") continue
			// Snapshot the slot count so we can detect (and undo) startAgent's
			// background-slot increment when it throws synchronously. Without this,
			// a synchronous throw in startAgent leaks runningBackground forever.
			const beforeRunningBackground = this.runningBackground
			try {
				this.startAgent(next.id, record, next.args)
			} catch (err) {
				if (this.runningBackground > beforeRunningBackground) {
					this.runningBackground--
				}
				record.status = "error"
				record.error = err instanceof Error ? err.message : String(err)
				record.completedAt = Date.now()
				this.onComplete?.(record)
			}
		}
	}

async spawnAndWait(
		pi: ExtensionAPI,
		ctx: ExtensionContext,
		type: SubagentType,
		prompt: string,
		options: Omit<SpawnOptions, "isBackground">,
	): Promise<AgentRecord> {
		const id = this.spawn(pi, ctx, type, prompt, { ...options, isBackground: false })
		// biome-ignore lint/style/noNonNullAssertion: spawn() just inserted this id into the agents map
		const record = this.agents.get(id)!
		await record.promise
		return record
	}

async resume(
		id: string,
		prompt: string | undefined,
		options: {
			signal?: AbortSignal
			maxTurns?: number
			tokenBudget?: number
			inactivityTimeout?: number
			maxDuration?: number
			purpose?: "continuation" | "finalize_report"
		} = {},
	): Promise<AgentRecord | undefined> {
		const record = this.agents.get(id)
		if (!record?.session) return undefined
		const purpose = options.purpose ?? "continuation"
		if (this.getResumeBlockReason(id, purpose)) return record
		const tierBudget = record.taskRef ? FERMENT_WORKER_BUDGETS[record.taskRef.budget_tier ?? "standard"] : undefined
		const attemptLimits =
			purpose === "finalize_report"
				? REPORT_FINALIZATION_LIMITS
				: tierBudget
					? {
							...options,
							maxTurns: Math.min(options.maxTurns ?? tierBudget.maxTurns, tierBudget.maxTurns),
							maxDuration: Math.min(options.maxDuration ?? tierBudget.maxDuration, tierBudget.maxDuration),
							tokenBudget: Math.min(options.tokenBudget ?? tierBudget.tokenBudget, tierBudget.tokenBudget),
						}
					: options
		const remainingTokenBudget = record.taskRef
			? Math.max(0, cumulativeTokenBudget(record.taskRef) - record.lifetimeUsage.output)
			: undefined
		const attemptTokenBudget =
			remainingTokenBudget == null
				? attemptLimits.tokenBudget
				: Math.min(attemptLimits.tokenBudget ?? remainingTokenBudget, remainingTokenBudget)

		record.status = "running"
		record.completedAt = undefined
		record.result = undefined
		record.error = undefined
		record.abortReason = undefined
		record.maxTurns = attemptLimits.maxTurns
		record.lastTurnCount = 0
		record.currentAttemptId++
		record.agentReport = undefined
		const attemptStartedAt = Date.now()
		const attempt: AgentResumeAttempt = {
			attempt_id: record.currentAttemptId,
			purpose,
			startedAt: attemptStartedAt,
			maxTurns: attemptLimits.maxTurns,
			tokenBudget: attemptTokenBudget,
		}
		record.resumeAttempts ??= []
		record.resumeAttempts.push(attempt)
		const abortController = new AbortController()
		record.abortController = abortController
		const onCallerAbort = () => abortController.abort()
		if (options.signal?.aborted) abortController.abort()
		else options.signal?.addEventListener("abort", onCallerAbort, { once: true })

		const attemptPrompt =
			purpose === "finalize_report" && record.taskRef
				? reportFinalizationPrompt(record.taskRef)
				: withAgentReportProtocol(prompt ?? "", record.taskRef)
		const resumePromise = resumeAgent(record.session, attemptPrompt, {
			onToolActivity: (activity) => {
				if (activity.status === "completed" || activity.status === "failed") record.toolUses++
			},
			onTurnEnd: (turnCount) => {
				record.lastTurnCount = turnCount
			},
			onAssistantUsage: (usage) => {
				addUsage(record.lifetimeUsage, usage)
			},
			onCompaction: (info) => {
				record.compactionCount++
				this.onCompact?.(record, info)
			},
			signal: abortController.signal,
			maxTurns: attemptLimits.maxTurns,
			tokenBudget: attemptTokenBudget,
			minTokenBudget: purpose === "finalize_report" ? MIN_FINALIZE_TOKEN_BUDGET : undefined,
			inactivityTimeout: options.inactivityTimeout,
			maxDuration: attemptLimits.maxDuration,
			hardTurnLimit: record.taskRef?.kind === "ferment_step",
			shouldTerminateAfterTool: (toolName) =>
				toolName === "submit_agent_report" && record.agentReport?.attempt_id === record.currentAttemptId,
			onRuntimeCleanupRegistered: (cleanup) => {
				this.runtimeCleanups.set(record, cleanup)
			},
		})
		this.activeResumePromises.set(record, resumePromise)

		try {
			const result = await resumePromise
			if ((record.status as AgentRecord["status"]) !== "stopped") {
				record.status = result.aborted ? "aborted" : result.steered ? "steered" : "completed"
			}
			record.abortReason = result.abortReason
			record.result = result.responseText
			record.lastTurnCount = result.turnsUsed
			record.maxTurns = result.maxTurns ?? attemptLimits.maxTurns
			record.completedAt = Date.now()
		} catch (err) {
			if ((record.status as AgentRecord["status"]) !== "stopped") {
				record.status = "error"
				record.error = err instanceof Error ? err.message : String(err)
			}
			record.completedAt = Date.now()
		} finally {
			options.signal?.removeEventListener("abort", onCallerAbort)
			this.activeResumePromises.delete(record)
			this.cleanupRecordRuntime(record)
		}
		attempt.completedAt = record.completedAt
		attempt.outcome = classifyAgentOutcome(record)
		attempt.reason = record.status === "error" ? "error" : record.abortReason
		record.latestOutcome = buildAgentOutcome(record)

		return record
	}

getResumeBlockReason(id: string, purpose: "continuation" | "finalize_report"): string | undefined {
		const record = this.agents.get(id)
		if (!record?.session) return `Agent "${id}" has no active session to resume.`
		if (purpose === "finalize_report" && record.taskRef?.kind !== "ferment_step") {
			return `Agent "${id}" is not a Ferment-linked worker and cannot finalize a worker report.`
		}
		if (record.agentReport?.attempt_id === record.currentAttemptId && record.agentReport.status === "completed") {
			return `Agent "${id}" already has an accepted completed report for its current attempt.`
		}
		const attemptsForPurpose = record.resumeAttempts?.filter((attempt) => attempt.purpose === purpose).length ?? 0
		const attemptLimit =
			purpose === "finalize_report" ? DEFAULT_MAX_REPORT_FINALIZERS : DEFAULT_MAX_CONTINUATION_RESUMES
		if (record.taskRef?.kind === "ferment_step" && attemptsForPurpose >= attemptLimit) {
			return `Agent "${id}" has already used the Ferment worker ${purpose} resume limit (${attemptLimit}). Spawn a new linked worker for remaining work.`
		}
		if (record.taskRef && record.lifetimeUsage.output >= cumulativeTokenBudget(record.taskRef)) {
			return `Agent "${id}" exhausted the cumulative ${record.taskRef.budget_tier ?? "standard"} Ferment worker output budget (${cumulativeTokenBudget(record.taskRef)} tokens).`
		}
		if (record.taskRef) {
			const remaining = cumulativeTokenBudget(record.taskRef) - record.lifetimeUsage.output
			const minBudget = purpose === "finalize_report" ? MIN_FINALIZE_TOKEN_BUDGET : MIN_TOKEN_BUDGET
			if (remaining < minBudget) {
				return purpose === "finalize_report"
					? `Agent "${id}" has only ${remaining} output tokens remaining, below the minimum report-finalization budget (${minBudget} tokens). The session retains its work but cannot produce a structured report. Inspect the raw output and either spawn a replacement worker or stop and report the step as incomplete.`
					: `Agent "${id}" has only ${remaining} output tokens remaining, below the minimum enforceable resume budget (${minBudget} tokens). Spawn a new linked worker for remaining work.`
			}
		}
		return undefined
	}

submitReport(agentId: string, report: WorkerReportSubmission): AgentRecord | undefined {
		const record = this.agents.get(agentId)
		if (!record || record.visibility === "system" || record.taskRef?.kind !== "ferment_step") return undefined
		record.agentReport = {
			...report,
			attempt_id: record.currentAttemptId,
			submitted_at: Date.now(),
		}
		record.latestOutcome = buildAgentOutcome(record)
		return record
	}

getRecord(id: string): AgentRecord | undefined {
		return this.agents.get(id)
	}

listAgents(): AgentRecord[] {
		return [...this.agents.values()].sort((a, b) => b.startedAt - a.startedAt)
	}

completeTransient(id: string): void {
		const record = this.agents.get(id)
		if (!record) return
		record.status = "completed"
		record.completedAt = Date.now()
		// Schedule removal after a short delay — long enough for the widget to
		// render one final "✓ done" frame, but not so long it lingers in listAgents().
		setTimeout(() => this.agents.delete(id), 2000)
	}

abort(id: string): boolean {
		const record = this.agents.get(id)
		if (!record) return false

		if (record.status === "queued") {
			this.queue = this.queue.filter((q) => q.id !== id)
			record.status = "stopped"
			record.completedAt = Date.now()
			return true
		}

		// "reconnecting" is live remote work (a transport reattach in flight) —
		// it must be killable too, or a wedged reconnect can never be stopped
		// (Escape / Ctrl+X both route through here).
		if (record.status !== "running" && record.status !== "reconnecting") return false
		record.abortController?.abort()
		record.status = "stopped"
		record.completedAt = Date.now()
		return true
	}

private cleanupRecordRuntime(record: AgentRecord): void {
		if (record.outputCleanup) {
			try {
				record.outputCleanup()
			} catch {
				/* ignore */
			}
			record.outputCleanup = undefined
		}
		const runtimeCleanup = this.runtimeCleanups.get(record)
		if (runtimeCleanup) {
			try {
				runtimeCleanup()
			} catch {
				/* ignore */
			}
			this.runtimeCleanups.delete(record)
		}
	}

private removeRecord(id: string, record: AgentRecord): void {
		this.cleanupRecordRuntime(record)
		record.session?.dispose?.()
		record.session = undefined
		this.agents.delete(id)
	}

private cleanup() {
		const cutoff = Date.now() - 10 * 60_000
		for (const [id, record] of this.agents) {
			if (isActiveStatus(record.status)) continue
			if ((record.completedAt ?? 0) >= cutoff) continue
			this.removeRecord(id, record)
		}
	}

clearCompleted(): void {
		for (const [id, record] of this.agents) {
			if (isActiveStatus(record.status)) continue
			this.removeRecord(id, record)
		}
	}

hasRunning(): boolean {
		return [...this.agents.values()].some((r) => isActiveStatus(r.status))
	}

getRunningCount(): number {
		let count = 0
		for (const r of this.agents.values()) {
			if (isActiveStatus(r.status)) count++
		}
		return count
	}

private wireRemoteCompletion(
		record: AgentRecord,
		runPromise: Promise<{
			responseText: string
			session?: AgentSession
			aborted?: boolean
			abortReason?: AgentAbortReason
			steered?: boolean
			turnsUsed?: number
			maxTurns?: number
			planPath?: string
		}>,
		options: { detach?: () => void; maxTurns?: number },
	): Promise<string> {
		return runPromise
			.then(({ responseText, session, aborted, abortReason, steered, turnsUsed, maxTurns, planPath }) => {
				if (record.status !== "stopped") {
					record.status = aborted ? "aborted" : steered ? "steered" : "completed"
				}
				record.abortReason = abortReason
				const finalText = planPath ? `${responseText}\n\nPlan saved to: ${planPath}` : responseText
				record.result = finalText
				record.session = session
				record.lastTurnCount = turnsUsed
				// Preserve the effective, normalized turn cap returned by the runner.
				record.maxTurns = maxTurns ?? options.maxTurns
				record.completedAt ??= Date.now()
				record.latestOutcome = buildAgentOutcome(record)

				if (record.isBackground) {
					this.runningBackground--
					this.onComplete?.(record)
					this.drainQueue()
				}
				return finalText
			})
			.catch((err) => {
				if (record.status !== "stopped") {
					record.status = "error"
					record.error = err instanceof Error ? err.message : String(err)
				}
				record.completedAt ??= Date.now()
				record.latestOutcome = buildAgentOutcome(record)

				if (record.isBackground) {
					this.runningBackground--
					this.onComplete?.(record)
					this.drainQueue()
				}
				return ""
			})
			.finally(() => {
				options.detach?.()
				this.cleanupRecordRuntime(record)
				record.promise = undefined
			})
	}

async resumeRemoteRecord(
		state: RemoteRunState,
		ctx: ExtensionContext,
		options?: { callbacks?: AcpSessionCallbacks },
	): Promise<"resumed" | "already-watched"> {
		const apiKey = loadConfig().apiKey
		if (!apiKey) throw new Error("No API key configured. Run `kimchi login`.")

		// Guard against double-attach: a live WS on the session means another
		// kimchi process (typically the one that dispatched the run, or an
		// earlier resume of it) is still watching it. Best-effort: only a
		// POSITIVE sighting skips — a failed poll falls through to the attach,
		// whose recovery machinery handles the real session state.
		if (
			await isRemoteSessionConnected(state.remoteSession, apiKey, {
				endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
			})
		) {
			return "already-watched"
		}

		const abortController = new AbortController()
		const record: AgentRecord = {
			id: state.id,
			type: "Remote-Runner",
			description: state.description,
			visibility: "user",
			status: "running",
			toolUses: 0,
			startedAt: state.startedAt,
			abortController,
			currentAttemptId: 0,
			resumeAttempts: [],
			lifetimeUsage: { input: 0, output: 0, cacheRead: 0, cacheWrite: 0 },
			compactionCount: 0,
			remote: true,
			remoteSession: state.remoteSession,
			acpSessionId: state.acpSessionId,
			remoteOrigin: state.remoteOrigin,
			fermentId: state.fermentId,
			gitWorkflow: state.gitWorkflow,
			outputFile: state.outputFile,
			spawnCtx: ctx,
			isBackground: true,
			triggersRemoteCompletion: true,
		}
		this.agents.set(record.id, record)
		this.runningBackground++

		// The session adapter restores steer_subagent / get_subagent_result and
		// the activity stream mid-run — same as a normal background remote run.
		const adapter = new RemoteAgentSession()
		record.session = adapter as unknown as AgentSession

		const promise = attachRemoteAgent({
			apiKey,
			endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
			signal: abortController.signal,
			remoteSession: state.remoteSession,
			acpSessionId: state.acpSessionId,
			outputFile: state.outputFile,
			// A resumed PR-intent run keeps the session for the steer loop.
			keepAlive: state.gitWorkflow !== undefined,
			onReconnecting: (reconnecting) => {
				// Mirror the attach state onto the record (same as the in-run
				// reconnecting flow).
				if (isActiveStatus(record.status)) {
					record.status = reconnecting ? "reconnecting" : "running"
				}
			},
			onReady: (acpClient, meta) => {
				adapter.bindClient(acpClient, meta)
			},
			callbacks: {
				onTextDelta: (delta, fullText) => {
					adapter.appendAssistantText(fullText)
					options?.callbacks?.onTextDelta?.(delta, fullText)
				},
				onToolActivity: (activity) => {
					if (activity.status === "in_progress") {
						adapter.recordToolCallStart(activity.toolName, activity.toolCallId, activity.rawInput)
					} else {
						adapter.recordToolCallEndFromActivity(activity)
						record.toolUses++
					}
					options?.callbacks?.onToolActivity?.(activity)
				},
				onTurnEnd: (turnCount) => {
					record.lastTurnCount = turnCount
					adapter.incrementTurnCount()
					options?.callbacks?.onTurnEnd?.(turnCount)
				},
				onAssistantUsage: (usage) => {
					adapter.addUsage(usage)
					addUsage(record.lifetimeUsage, usage)
					options?.callbacks?.onAssistantUsage?.(usage)
				},
				onContextUsage: (used, size) => adapter.setContextUsage(used, size),
			},
		}).then((result) => {
			record.recoveryNote = result.recoveryNote
			record.remoteSession = result.remoteSession
			// Same contract as _runRemote's stopReason whitelist: a failed
			// recovery means the run's outcome is unknown — the record must not
			// read as completed (the post-completion dropdown would offer
			// Review/Sync on a result nobody has).
			if (result.stopReason === "recovery_failed") {
				throw new Error(
					"the remote run finished while kimchi was closed and its result could not be recovered — outcome unknown",
				)
			}
			return {
				responseText: result.responseText,
				session: adapter as unknown as AgentSession,
				turnsUsed: adapter.turnCount,
			}
		})
		record.promise = this.wireRemoteCompletion(record, promise, {})
		return "resumed"
	}

abortAll(options?: { skipRemote?: boolean }): number {
		let count = 0
		for (const queued of this.queue) {
			const record = this.agents.get(queued.id)
			if (record) {
				record.status = "stopped"
				record.completedAt = Date.now()
				count++
			}
		}
		this.queue = []
		for (const record of this.agents.values()) {
			// A spared remote run keeps running on the worker — its promise dies
			// with the process, and the persisted state lets a resumed session
			// reattach (remote-run-persistence.ts).
			if (options?.skipRemote && record.remote) continue
			if (isActiveStatus(record.status)) {
				record.abortController?.abort()
				record.status = "stopped"
				record.completedAt = Date.now()
				count++
			}
		}
		return count
	}

async waitForAll(options?: { skipRemote?: boolean }): Promise<void> {
		while (true) {
			this.drainQueue()
			const pending = [...this.agents.values()].flatMap((r) => {
				// Remote runs spared by shutdown never settle — their promises die
				// with the process while the runs continue on the worker.
				if (options?.skipRemote && r.remote && isActiveStatus(r.status)) return []
				return [r.promise, this.activeResumePromises.get(r)].filter(Boolean)
			})
			if (pending.length === 0) break
			await Promise.allSettled(pending)
		}
	}

dispose() {
		clearInterval(this.cleanupInterval)
		this.queue = []
		for (const record of this.agents.values()) {
			this.cleanupRecordRuntime(record)
			record.session?.dispose()
		}
		this.agents.clear()
	}

agent_shutdown_hooks.text:
pi.on("session_shutdown", async () => {
		unsubCtrlB?.()
		unsubCtrlB = undefined
		unsubKill?.()
		unsubKill = undefined
		currentUi = undefined
		// Remote runs survive the process — they are owned by the worker and
		// resumable via kimchi --session (remote-run-persistence.ts).
		manager.abortAll({ skipRemote: true })
		budgetRetryCandidates.clear()
		if (batchFinalizeTimer) {
			clearTimeout(batchFinalizeTimer)
			batchFinalizeTimer = undefined
		}
		nudgeScheduler.beginShutdown()
		await waitForSubagentShutdown(manager)
		widget.dispose()
		manager.dispose()
	})

agent_tool_registrations.text:
pi.registerTool(
		defineTool({
			name: "Agent",
			label: "Agent",
			description: `Launch an agent to run a complex multi-step task autonomously.

${typeListText}

${AGENT_TOOL_GUIDELINES}`,
			parameters: Type.Object({
				prompt: Type.String({
					description: "The task for the agent to perform.",
				}),
				description: Type.String({
					description: "A short (3-5 word) description of the task (shown in UI).",
				}),
				subagent_type: Type.String({
					description:
						"Agent type (see list above); custom agents come from .kimchi/agents/*.md (project) or the global agents dir.",
				}),
				model: Type.Optional(
					Type.String({
						description: AGENT_MODEL_PARAMETER_DESCRIPTION,
					}),
				),
				thinking: Type.Optional(
					Type.String({
						description:
							"Thinking effort: off, minimal, low, medium, high, xhigh, max. Overrides agent profile defaults.",
					}),
				),
				max_turns: Type.Optional(
					Type.Number({
						description:
							"Requested maximum agentic turns before stopping. Agent profiles with fixed maxTurns keep their profile value.",
						minimum: 1,
					}),
				),
				token_budget: Type.Optional(
					Type.Integer({
						description:
							"Maximum cumulative output tokens this agent is allowed to generate. Input tokens are not counted.",
						minimum: 1,
					}),
				),
				max_duration: Type.Optional(
					Type.Integer({
						description: "Maximum wall-clock duration in seconds. The agent is aborted when this limit is exceeded.",
						minimum: 1,
					}),
				),
				run_in_background: Type.Optional(
					Type.Boolean({
						description:
							"Default: true in interactive sessions (false in headless runs). Run the agent in the background and return its ID immediately; you will be notified on completion. Set to false only when the next step in your workflow cannot proceed without the agent's result.",
					}),
				),
				isolated: Type.Optional(
					Type.Boolean({
						description: "If true, agent gets no extension/MCP tools - only built-in tools.",
					}),
				),
				inherit_context: Type.Optional(
					Type.Boolean({
						description: "If true, fork parent conversation into the agent. Default: false (fresh context).",
					}),
				),
				task_ref: Type.Optional(
					Type.Object({
						kind: Type.Literal("ferment_step"),
						ferment_id: Type.String(),
						phase_id: Type.String(),
						step_id: Type.String(),
						budget_tier: Type.Optional(
							Type.Union([Type.Literal("narrow"), Type.Literal("standard"), Type.Literal("complex")]),
						),
					}),
				),
			}),

			renderCall(args, theme, context) {
				// Defense-in-depth: `visibility` is not in this tool's public schema (see execute()),
				// but if an LLM hallucinates the arg we'd rather hide the tool call than render it.
				if ((args as Record<string, unknown>).visibility === "system") return new Text("", 0, 0)
				if (!context.argsComplete && !args.subagent_type) return new Text("", 0, 0)
				const displayName = getDisplayName(args.subagent_type || AGENT_GENERAL_PURPOSE)
				const desc = (args.description as string) ?? ""
				return new Text(
					`▸ ${theme.fg("toolTitle", theme.bold(displayName))}${desc ? `  ${theme.fg("muted", desc)}` : ""}`,
					0,
					0,
				)
			},

			renderResult(result, { expanded: piExpanded, isPartial }, theme, context) {
				// Wire kimchi's global ctrl+o cycle: register on first render, then read the
				// per-tool flag back. Falls back to pi's renderer flag if available.
				if (context?.toolCallId) registerToolCall(context.toolCallId)
				const expanded = piExpanded || (context?.toolCallId ? isToolExpanded(context.toolCallId) : false)

				const details = result.details as AgentDetails | undefined
				if (details?.visibility === "system") return new Text("", 0, 0)
				if (!details) {
					const text = result.content[0]?.type === "text" ? result.content[0].text : ""
					return new Text(text, 0, 0)
				}

				const stats = (d: AgentDetails) => {
					const parts: string[] = []
					if (d.modelName) parts.push(d.modelName)
					if (d.tags) parts.push(...d.tags)
					if (d.turnCount != null && d.turnCount > 0) {
						parts.push(formatTurns(d.turnCount, d.maxTurns))
					}
					if (d.toolUses > 0) parts.push(`${d.toolUses} tool use${d.toolUses === 1 ? "" : "s"}`)
					if (d.tokens) parts.push(d.tokens)
					return parts.map((p) => theme.fg("dim", p)).join(` ${theme.fg("dim", "·")} `)
				}

				if (isPartial || details.status === "running") {
					const frame = SPINNER[details.spinnerFrame ?? 0]
					const s = stats(details)
					let line = theme.fg("accent", frame) + (s ? ` ${s}` : "")
					line += `\n${theme.fg("dim", `  ⎿  ${details.activity ?? "thinking..."}`)}  ${theme.fg("muted", "(ctrl+b to run in background)")}`
					return new Text(line, 0, 0)
				}

				if (details.status === "background") {
					return new Text(theme.fg("dim", `  ⎿  Background agent running (ID: ${details.agentId})`), 0, 0)
				}

				if (details.status === "completed" || details.status === "steered") {
					const duration = formatMs(details.durationMs)
					const isSteered = details.status === "steered"
					const icon = isSteered ? theme.fg("warning", "✓") : theme.fg("success", "✓")
					const s = stats(details)
					let line = icon + (s ? ` ${s}` : "")
					line += ` ${theme.fg("dim", "·")} ${theme.fg("dim", duration)}`

					if (expanded) {
						const resultText = result.content[0]?.type === "text" ? result.content[0].text : ""
						if (resultText) {
							const lines = resultText.split("\n").slice(0, 50)
							for (const l of lines) {
								line += `\n${theme.fg("dim", `  ${l}`)}`
							}
							if (resultText.split("\n").length > 50) {
								line += `\n${theme.fg("muted", "  ... (use get_subagent_result with verbose for full output)")}`
							}
						}
					} else {
						const doneText = isSteered ? "Wrapped up (turn limit)" : "Done"
						line += `\n${theme.fg("dim", `  ⎿  ${doneText}`)}`
					}
					return new Text(line, 0, 0)
				}

				if (details.status === "stopped") {
					const s = stats(details)
					let line = theme.fg("dim", "■") + (s ? ` ${s}` : "")
					line += `\n${theme.fg("dim", "  ⎿  Stopped")}`
					return new Text(line, 0, 0)
				}

				const s = stats(details)
				let line = theme.fg("error", "✗") + (s ? ` ${s}` : "")

				if (details.status === "error") {
					line += `\n${theme.fg("error", `  ⎿  Error: ${details.error ?? "unknown"}`)}`
				} else {
					line += `\n${theme.fg("warning", `  ⎿  ${getAbortLabel(details.abortReason)}`)}`
				}

				return new Text(line, 0, 0)
			},

			execute: async (toolCallId, params, signal, onUpdate, ctx) => {
				widget.setUICtx(ctx.ui as UICtx)

				reloadCustomAgents()

				const rawType = params.subagent_type as SubagentType
				const resolved = resolveType(rawType)
				const subagentType = resolved ?? AGENT_GENERAL_PURPOSE
				const fellBack = resolved === undefined

				const displayName = getDisplayName(subagentType)

				const customConfig = getAgentConfig(subagentType)

				// Background-by-default only applies with a UI loop that can consume
				// completion notifications; headless/one-shot runs keep foreground so
				// spawned work cannot outlive the process.
				const resolvedConfig = resolveAgentInvocationConfig(
					customConfig,
					params as Parameters<typeof resolveAgentInvocationConfig>[1],
					ctx.hasUI,
				)

				let model = ctx.model
				if (resolvedConfig.modelInput) {
					const resolvedModel = resolveModel(resolvedConfig.modelInput, ctx.modelRegistry as ModelRegistry)
					if (typeof resolvedModel === "string") {
						if (resolvedConfig.modelFromParams) return textResult(resolvedModel)
					} else {
						model = resolvedModel as typeof ctx.model
					}
				}

				// When multi-model is enabled and the caller did NOT specify a model,
				// resolve the default model from the role config based on the agent
				// type. This ensures Builder calls use the configured builder model,
				// not the orchestrator's own model.
				if (getMultiModelEnabled(ctx.sessionManager) && !resolvedConfig.modelFromParams) {
					const roleModelRef = resolveRoleModelRef(subagentType)
					if (roleModelRef) {
						const resolved = resolveModel(roleModelRef, ctx.modelRegistry as ModelRegistry)
						if (typeof resolved !== "string") {
							// resolveModel returns `unknown | string` — the cast is required because
							// ModelRegistry.find() returns unknown. Same pattern as line 1243.
							model = resolved as typeof ctx.model
						}
					}
				}

				// Multi-model guard: when multi-model mode is active and the caller supplied
				// an explicit model, the resolved model must belong to the configured
				// multi-model role pool. This runs before budget-retry and task_ref checks
				// so invalid models are rejected immediately.
				if (getMultiModelEnabled(ctx.sessionManager) && resolvedConfig.modelFromParams) {
					const fullRef = `${(model as { provider?: string }).provider}/${(model as { id?: string }).id}`
					const allowed = new Set(getAllowedMultiModelRefs())
					if (!allowed.has(fullRef)) {
						const allowedList = Array.from(allowed)
							.map((ref) => `  - ${ref}`)
							.join("\n")
						return textResult(
							`Model "${fullRef}" is not allowed in multi-model mode.\n\nAllowed models:\n${allowedList}\n\nOmit the model parameter to use the current session model, or specify one of the allowed models.`,
						)
					}
				}

				const explicitTokenBudget =
					(params as { token_budget?: number; tokenBudget?: number }).token_budget ??
					(params as { token_budget?: number; tokenBudget?: number }).tokenBudget
				const activeBudgetRetryBlock = budgetRetryBlock
				if (
					activeBudgetRetryBlock &&
					shouldBlockBudgetRetry(activeBudgetRetryBlock, {
						tokenBudget: resolvedConfig.tokenBudget,
						subagentType,
						description: params.description as string,
						prompt: params.prompt as string,
					})
				) {
					return textResult(
						`Agent retry blocked: the previous Agent call for "${activeBudgetRetryBlock.description}" already aborted because the user-supplied token_budget (${formatTokens(activeBudgetRetryBlock.budget)}) was too small. Do not raise the budget or retry the Agent tool unless the user explicitly asks.`,
					)
				}

				const thinking = resolvedConfig.thinking
				const inheritContext = resolvedConfig.inheritContext
				const isolated = resolvedConfig.isolated
				const taskRef = readAgentTaskRef(params)
				if (taskRef && (params.max_turns == null || params.max_duration == null || params.token_budget == null)) {
					return textResult(
						"Ferment-linked Agent calls require explicit max_turns, max_duration, and token_budget from the shared worker budget policy.",
					)
				}
				if (taskRef && isolated) {
					return textResult(
						"Agent task_ref cannot be used with isolated: true. Ferment-linked workers must have extension tools enabled so they can call submit_agent_report.",
					)
				}
				// The `visibility` field is intentionally NOT exposed in this tool's public schema -
				// LLMs and personas cannot create hidden agents. Internal kimchi callers (e.g. permission
				// classifiers, future MCP adapters) spawn hidden agents directly via `AgentManager.spawn(..., { visibility: "system" })`,
				// which bypasses the tool layer entirely. Hardcoding "user" here ensures any defiant
				// LLM that hallucinates a `visibility` arg gets ignored at the source.
				const visibility: AgentVisibility = "user"
				const runInBackground = resolvedConfig.runInBackground

				// Image forwarding: when session has images and subagent model supports vision,
				// extract image paths from read tool calls and prepend them to the prompt.
				const modelInput = (model as { input?: string[] } | undefined)?.input
				const imagePaths = sessionHasImages() && modelInput?.includes("image") ? extractImagePathsFromSession(ctx) : []
				const effectivePrompt =
					imagePaths.length > 0
						? `Context images from parent session: ${imagePaths.join(", ")}. Read them if needed for your task.\n\n${params.prompt as string}`
						: (params.prompt as string)

				const parentModelId = ctx.model?.id
				const effectiveModelId = (model as { id?: string } | undefined)?.id
				const agentModelName =
					effectiveModelId && effectiveModelId !== parentModelId
						? ((model as { name?: string; id?: string } | undefined)?.name ?? effectiveModelId)
								.replace(/^Claude\s+/i, "")
								.toLowerCase()
						: undefined
				const agentTags: string[] = []
				if (thinking) agentTags.push(`thinking: ${thinking}`)
				if (resolvedConfig.tokenBudget != null) agentTags.push(`budget: ${formatTokens(resolvedConfig.tokenBudget)}`)
				if (isolated) agentTags.push("isolated")
				const effectiveMaxTurns = normalizeMaxTurns(resolvedConfig.maxTurns ?? getDefaultMaxTurns())
				const detailBase = {
					displayName,
					description: params.description as string,
					subagentType,
					visibility,
					modelName: agentModelName,
					tags: agentTags.length > 0 ? agentTags : undefined,
				}

				if (runInBackground) {
					const { state: bgState, callbacks: bgCallbacks } = createActivityTracker(effectiveMaxTurns)
					let childSessionFile: string | undefined
					const parentSessionDir = ctx.sessionManager.getSessionDir()
					try {
						childSessionFile = prepareAgentSessionFile(
							parentSessionDir,
							ctx.sessionManager.getSessionFile(),
							ctx.cwd,
							subagentType,
						)?.sessionFile
					} catch (err) {
						const detail = err instanceof Error ? err.message : String(err)
						return textResult(`Failed to pre-write Agent session file under ${parentSessionDir}: ${detail}`)
					}

					let id: string
					const origBgOnSession = bgCallbacks.onSessionCreated
					bgCallbacks.onSessionCreated = (session: unknown) => {
						origBgOnSession(session)
						const rec = manager.getRecord(id)
						if (rec?.outputFile) {
							rec.outputCleanup = streamToOutputFile(
								session as Parameters<typeof streamToOutputFile>[0],
								rec.outputFile,
								id,
								ctx.cwd,
							)
						}
					}

					try {
						id = manager.spawn(pi, ctx, subagentType, effectivePrompt, {
							description: params.description as string,
							visibility,
							model: model as Parameters<typeof manager.spawn>[4]["model"],
							maxTurns: effectiveMaxTurns,
							tokenBudget: resolvedConfig.tokenBudget,
							taskRef,
							maxDuration: resolvedConfig.maxDuration,
							isolated,
							inheritContext,
							thinkingLevel: thinking,
							isBackground: true,
							sessionFile: childSessionFile,
							sessionDir: parentSessionDir,
							...bgCallbacks,
						})
					} catch (err) {
						return textResult(err instanceof Error ? err.message : String(err))
					}

					const joinMode = resolveJoinMode(getDefaultJoinMode(), true)
					const record = manager.getRecord(id)
					if (record && joinMode) {
						record.joinMode = joinMode
						record.toolCallId = toolCallId
						record.outputFile = createOutputFilePath(ctx.cwd, id, ctx.sessionManager.getSessionId(), parentSessionDir)
						writeInitialEntry(record.outputFile, id, params.prompt as string, ctx.cwd)
					}
					if (explicitTokenBudget != null) {
						budgetRetryCandidates.set(id, {
							budget: explicitTokenBudget,
							subagentType,
							description: params.description as string,
							prompt: params.prompt as string,
						})
					}

					if (joinMode != null && joinMode !== "async") {
						currentBatchAgents.push({ id, joinMode })
						if (batchFinalizeTimer) clearTimeout(batchFinalizeTimer)
						batchFinalizeTimer = setTimeout(finalizeBatch, 100)
					}

					agentActivity.set(id, bgState)
					widget.ensureTimer()
					widget.update()

					pi.events.emit("subagents:created", {
						id,
						type: subagentType,
						description: params.description,
						isBackground: true,
						visibility,
					})

					const isQueued = record?.status === "queued"
					return textResult(
						`Agent ${isQueued ? "queued" : "started"} in background.\nAgent ID: ${id}\nType: ${displayName}\nDescription: ${params.description}\n${record?.outputFile ? `Output file: ${record.outputFile}\n` : ""}${isQueued ? `Position: queued (max ${manager.getMaxConcurrent()} concurrent)\n` : ""}\nYou will be notified when this agent completes — the completion notification will contain the results.\nDo NOT call get_subagent_result with wait: true just to wait for it — that blocks your run and queues user input. Continue with other independent work, or stop your turn and return control to the user.\nUse steer_subagent to send it messages. Do not duplicate this agent's work.`,
						{ ...detailBase, toolUses: 0, tokens: "", durationMs: 0, status: "background" as const, agentId: id },
					)
				}

				// Foreground (synchronous) execution
				let spinnerFrame = 0
				const startedAt = Date.now()
				let fgId: string | undefined
				let fgDetached = false

				const streamUpdate = () => {
					if (fgDetached) return
					const details: AgentDetails = {
						...detailBase,
						toolUses: fgState.toolUses,
						tokens: formatLifetimeTokens(fgState),
						turnCount: fgState.turnCount,
						maxTurns: fgState.maxTurns,
						durationMs: Date.now() - startedAt,
						status: "running",
						activity: describeActivity(fgState.activeTools, fgState.responseText),
						spinnerFrame: spinnerFrame % SPINNER.length,
					}
					onUpdate?.({
						content: [{ type: "text", text: `${fgState.toolUses} tool uses...` }],
						details: details as unknown,
					})
				}

				const { state: fgState, callbacks: fgCallbacks } = createActivityTracker(effectiveMaxTurns, streamUpdate)

				const origOnSession = fgCallbacks.onSessionCreated
				fgCallbacks.onSessionCreated = (session: unknown) => {
					origOnSession(session)
					for (const a of manager.listAgents()) {
						if (a.session === session) {
							fgId = a.id
							agentActivity.set(a.id, fgState)
							widget.ensureTimer()
							const rec = manager.getRecord(a.id)
							if (rec?.outputFile) {
								rec.outputCleanup = streamToOutputFile(
									session as Parameters<typeof streamToOutputFile>[0],
									rec.outputFile,
									a.id,
									ctx.cwd,
								)
							}
							break
						}
					}
				}

				const spinnerInterval = setInterval(() => {
					spinnerFrame++
					streamUpdate()
				}, 80)

				streamUpdate()

				let childSessionFile: string | undefined
				let fgOutputFile: string | undefined
				const parentSessionDir = ctx.sessionManager.getSessionDir()
				try {
					childSessionFile = prepareAgentSessionFile(
						parentSessionDir,
						ctx.sessionManager.getSessionFile(),
						ctx.cwd,
						subagentType,
					)?.sessionFile
					fgOutputFile = createOutputFilePath(
						ctx.cwd,
						"placeholder",
						ctx.sessionManager.getSessionId(),
						parentSessionDir,
					)
				} catch (err) {
					clearInterval(spinnerInterval)
					const detail = err instanceof Error ? err.message : String(err)
					return textResult(`Failed to pre-write Agent session file under ${parentSessionDir}: ${detail}`)
				}

				let detachResolve: (() => void) | undefined
				const detachPromise = new Promise<"detached">((resolve) => {
					detachResolve = () => resolve("detached")
				})

				let spawnedId: string
				try {
					spawnedId = manager.spawn(pi, ctx, subagentType, effectivePrompt, {
						description: params.description as string,
						visibility,
						model: model as Parameters<typeof manager.spawn>[4]["model"],
						maxTurns: effectiveMaxTurns,
						tokenBudget: resolvedConfig.tokenBudget,
						taskRef,
						maxDuration: resolvedConfig.maxDuration,
						isolated,
						inheritContext,
						thinkingLevel: thinking,
						isBackground: false,
						sessionFile: childSessionFile,
						sessionDir: parentSessionDir,
						signal,
						...fgCallbacks,
					})
				} catch (err) {
					clearInterval(spinnerInterval)
					return textResult(err instanceof Error ? err.message : String(err))
				}

				// biome-ignore lint/style/noNonNullAssertion: spawn() just inserted this id into the agents map
				const record = manager.getRecord(spawnedId)!
				fgId = spawnedId
				record.detachResolver = detachResolve
				if (fgOutputFile) {
					record.outputFile = fgOutputFile.replace("placeholder", spawnedId)
					record.toolCallId = toolCallId
					writeInitialEntry(record.outputFile, spawnedId, params.prompt as string, ctx.cwd)
				}

				// biome-ignore lint/style/noNonNullAssertion: promise is always set after spawn() calls startAgent()
				const raceResult = await Promise.race([record.promise!.then(() => "completed" as const), detachPromise])

				if (raceResult === "detached") {
					fgDetached = true
					clearInterval(spinnerInterval)

					const outputFile = createOutputFilePath(
						ctx.cwd,
						spawnedId,
						ctx.sessionManager.getSessionId(),
						parentSessionDir,
					)
					record.outputFile = outputFile
					writeInitialEntry(outputFile, spawnedId, params.prompt as string, ctx.cwd)
					if (record.session) {
						// Tear down the foreground streaming subscription before
						// re-subscribing against the same session for background output.
						record.outputCleanup?.()
						record.outputCleanup = streamToOutputFile(
							record.session as Parameters<typeof streamToOutputFile>[0],
							outputFile,
							spawnedId,
							ctx.cwd,
						)
					}

					const joinMode = resolveJoinMode(getDefaultJoinMode(), true)
					if (record && joinMode) {
						record.joinMode = joinMode
					}
					if (explicitTokenBudget != null) {
						budgetRetryCandidates.set(spawnedId, {
							budget: explicitTokenBudget,
							subagentType,
							description: params.description as string,
							prompt: params.prompt as string,
						})
					}
					if (joinMode != null && joinMode !== "async") {
						currentBatchAgents.push({ id: spawnedId, joinMode })
						if (batchFinalizeTimer) clearTimeout(batchFinalizeTimer)
						batchFinalizeTimer = setTimeout(finalizeBatch, 100)
					}

					widget.ensureTimer()
					widget.update()

					pi.events.emit("subagents:backgrounded", {
						id: spawnedId,
						type: subagentType,
						description: params.description,
						visibility,
					})

					return textResult(
						`Agent sent to background by the user (Ctrl+B).\nAgent ID: ${spawnedId}\nType: ${displayName}\nDescription: ${params.description}\n${outputFile ? `Output file: ${outputFile}\n` : ""}\nThe agent continues running in the background. You will be notified when it completes.\nDo NOT call get_subagent_result now — that would block and defeat the purpose of backgrounding. Continue with other independent work, or stop your turn and return control to the user. The completion notification will contain the results.`,
						{
							...detailBase,
							toolUses: fgState.toolUses,
							tokens: formatLifetimeTokens(fgState),
							durationMs: Date.now() - startedAt,
							status: "background" as const,
							agentId: spawnedId,
						},
					)
				}

				// Normal completion path
				record.detachResolver = undefined
				clearInterval(spinnerInterval)

				if (fgId) {
					agentActivity.delete(fgId)
					widget.markFinished(fgId)
				}

				const fallbackNote = fellBack
					? `Note: Unknown agent type "${rawType}" - using ${AGENT_GENERAL_PURPOSE}.\n\n`
					: ""

				// Ferment step worker killed by its OWN budget (turns/duration) on a
				// first attempt: auto-resume once so the worker finishes instead of the
				// orchestrator patching the remaining work on the main thread — the
				// exact residue workers exist to keep out. Measured run 019ff5cc: 8/17
				// Builders aborted at the hard cap with no report and every one was
				// finished by main-thread edits. First abort only (resumeAttempts
				// empty); a second exhaustion returns to the planner as before.
				const autoResumeCandidate = shouldAutoResumeFermentWorker(record)
				let autoResumedFromReason: AgentAbortReason | undefined
				if (autoResumeCandidate) {
					// Capture the pre-resume state — manager.resume mutates record in
					// place (clears abortReason on success), so reading it after the call
					// loses the reason the note exists to report.
					const beforeAbortReason = record.abortReason
					try {
						await manager.resume(record.id, FERMENT_WORKER_AUTO_RESUME_PROMPT, {})
						autoResumedFromReason = beforeAbortReason
					} catch {
						// Fall back to the normal aborted-agent summary/instruction below
						// instead of surfacing an unhandled tool error.
					}
					// The summary note/instruction below reads record.status/abortReason,
					// so it describes the post-resume state automatically.
				}

				// Built AFTER the auto-resume block so they reflect the post-resume
				// state (resume mutates record/fgState: status, abortReason, counters).
				const tokenText = formatLifetimeTokens(fgState)
				const details = buildDetails(detailBase, record, fgState, { tokens: tokenText })

				if (record.status === "error") {
					return textResult(`${fallbackNote}Agent failed: ${record.error}`, details)
				}
				blockBudgetRetryIfNeeded(
					record,
					explicitTokenBudget != null
						? {
								budget: explicitTokenBudget,
								subagentType,
								description: params.description as string,
								prompt: params.prompt as string,
							}
						: undefined,
				)

				const durationMs = (record.completedAt ?? Date.now()) - record.startedAt
				const statsParts = [`${record.toolUses} tool uses`]
				if (tokenText) statsParts.push(tokenText)
				const outcome = record.status === "aborted" ? "aborted" : record.status === "stopped" ? "stopped" : "completed"
				record.latestOutcome ??= buildAgentOutcome(record)
				// Persist a subagents:record entry for foreground agents so exports
				// can enrich them with full transcripts the same way background
				// agents are handled.
				appendSubagentRecord(record)

				const timeTaken = formatMs(durationMs)
				const autoResumeNote = buildAutoResumeNote(autoResumedFromReason)
				const note = getStatusNote(record.status, record.abortReason)
				const instruction = getStatusInstruction(
					record.status,
					getMultiModelEnabled(ctx.sessionManager),
					record.abortReason,
				)
				const outcomeBlock = formatAgentOutcomeBlock(record.latestOutcome)
				return textResult(
					`${fallbackNote}Agent ${outcome} in ${timeTaken} (${statsParts.join(", ")})${note}.${instruction}${autoResumeNote}\n\n${record.result?.trim() || "No output."}${outcomeBlock}`,
					details,
				)
			},
		}),
	)

pi.registerTool(
		defineTool({
			name: "get_subagent_result",
			label: "Get Agent Result",
			description:
				"Check status and retrieve results from a background agent. Use the agent ID returned by Agent with run_in_background.",
			parameters: Type.Object({
				agent_id: Type.String({
					description: "The agent ID to check.",
				}),
				wait: Type.Optional(
					Type.Boolean({
						description:
							"If true, block until the agent completes (capped at 60s). Do NOT use right after backgrounding an agent — you will be notified when it completes, and blocking queues user input. Only for true dependencies. Default: false.",
					}),
				),
				verbose: Type.Optional(
					Type.Boolean({
						description: "If true, include the agent's full conversation (messages + tool calls). Default: false.",
					}),
				),
			}),

			renderResult(result, { expanded: piExpanded }, theme, context) {
				if (context?.toolCallId) registerToolCall(context.toolCallId)
				const expanded = piExpanded || (context?.toolCallId ? isToolExpanded(context.toolCallId) : false)

				const details = result.details as GetSubagentResultDetails | undefined
				// Defense-in-depth: hide get_subagent_result output for system agents in the TUI
				// (consistency with the Agent tool's renderCall/renderResult short-circuits).
				if (details?.visibility === "system") return new Text("", 0, 0)
				if (!details) {
					const text = result.content[0]?.type === "text" ? result.content[0].text : ""
					return new Text(text, 0, 0)
				}

				const statsLine = (d: GetSubagentResultDetails) => {
					const parts: string[] = [d.status]
					if (d.toolUses > 0) parts.push(`${d.toolUses} tool use${d.toolUses === 1 ? "" : "s"}`)
					if (d.tokens) parts.push(d.tokens)
					if (d.contextPercent != null) parts.push(`${Math.round(d.contextPercent)}% ctx`)
					if (d.compactionCount && d.compactionCount > 0) {
						parts.push(`${d.compactionCount} compaction${d.compactionCount === 1 ? "" : "s"}`)
					}
					return parts.map((p) => theme.fg("dim", p)).join(` ${theme.fg("dim", "·")} `)
				}

				const icon = getSubagentResultIcon(details.status, theme)

				const headerName = theme.fg("toolTitle", theme.bold("Get Agent Result"))
				const headerDesc = details.description ? `  ${theme.fg("muted", details.description)}` : ""
				const durationTail =
					details.durationMs != null ? ` ${theme.fg("dim", "·")} ${theme.fg("dim", formatMs(details.durationMs))}` : ""

				let line = `${icon} ${headerName}${headerDesc}${durationTail}`
				const stats = statsLine(details)
				if (stats) line += `\n${theme.fg("dim", "  ⎿  ")}${stats}`

				const bodyText = details.bodyText ?? ""
				if (expanded && bodyText) {
					const lines = bodyText.split("\n")
					const maxLines = 50
					const visible = lines.slice(0, maxLines)
					for (const l of visible) {
						line += `\n${theme.fg("dim", `  ${l}`)}`
					}
					if (lines.length > maxLines) {
						line += `\n${theme.fg("muted", `  ... (${lines.length - maxLines} more lines - use verbose: true for full output)`)}`
					}
				} else if (!expanded) {
					const summary = summaryForStatus(details.status, details.error, details.abortReason)
					line += `\n${theme.fg("dim", `  ⎿  ${summary}`)}`
				}

				return new Text(line, 0, 0)
			},

			execute: async (_toolCallId, params, signal, _onUpdate, _ctx) => {
				const record = manager.getRecord(params.agent_id as string)
				if (!record) {
					return textResult(`Agent not found: "${params.agent_id}". It may have been cleaned up.`)
				}

				let waitOutcome: AgentWaitOutcome | undefined
				if (params.wait && record.status === "running" && record.promise) {
					// Bounded, interruptible join: honor the tool's abort signal and
					// the wait cap instead of blocking the caller's run indefinitely.
					// On timeout/abort the result stays unconsumed and the completion
					// nudge stays armed, so the notification still delivers the result.
					waitOutcome = await waitForAgentCompletion(record.promise, signal)
					if (waitOutcome === "completed") {
						record.resultConsumed = true
						cancelNudge(params.agent_id as string)
					}
				}

				const displayName = getDisplayName(record.type)
				const duration = formatDuration(record.startedAt, record.completedAt)
				const tokens = formatLifetimeTokens(record)
				const contextPercent = getSessionContextPercent(record.session)
				const statsParts = [`Tool uses: ${record.toolUses}`]
				if (tokens) statsParts.push(tokens)
				if (contextPercent !== null) statsParts.push(`Context: ${Math.round(contextPercent)}%`)
				if (record.compactionCount) statsParts.push(`Compactions: ${record.compactionCount}`)
				statsParts.push(`Duration: ${duration}`)

				let output =
					`Agent: ${record.id}\n` +
					`Type: ${displayName} | Status: ${record.status} | ${statsParts.join(" | ")}\n` +
					`Description: ${record.description}\n\n`

				let bodyForDisplay: string
				if (record.status === "queued") {
					bodyForDisplay = `Agent is queued behind the background-agent concurrency cap (max ${manager.getMaxConcurrent()} concurrent) and has not started. Do not wait on it — you will be notified when it completes. If its output is a hard dependency, check back with wait: true once it reports running.`
					output += bodyForDisplay
				} else if (record.status === "running") {
					if (waitOutcome === "timed_out") {
						bodyForDisplay = `Waited ${GET_SUBAGENT_RESULT_WAIT_CAP_MS / 1000}s (cap) and the agent is still running. The result was NOT consumed — you will be notified when it completes. If this agent's output is a hard dependency (e.g. joining a ferment worker), call get_subagent_result with wait: true again to re-join; otherwise end your turn and continue when the notification arrives.`
					} else if (waitOutcome === "aborted") {
						bodyForDisplay =
							"Wait cancelled before the agent completed. The result was NOT consumed — you will be notified when it completes. Re-call with wait: true to re-join, or continue other work and wait for the notification."
					} else {
						bodyForDisplay =
							"Agent is still running. Do not poll or wait for it — end your turn; you will be notified when it completes and the notification will contain the results."
					}
					output += bodyForDisplay
				} else if (record.status === "error") {
					bodyForDisplay = `Error: ${record.error}`
					output += bodyForDisplay
				} else {
					bodyForDisplay = record.result?.trim() || "No output."
					output += bodyForDisplay
				}
				record.latestOutcome ??= buildAgentOutcome(record)
				if (record.latestOutcome && record.status !== "running" && record.status !== "queued") {
					const outcomeBlock = formatAgentOutcomeBlock(record.latestOutcome)
					output += outcomeBlock
					bodyForDisplay += outcomeBlock
				}

				if (record.status !== "running" && record.status !== "queued") {
					record.resultConsumed = true
					cancelNudge(params.agent_id as string)
				}

				if (params.verbose && record.session) {
					const conversation = getAgentConversation(record.session)
					if (conversation) {
						const verboseTail = `\n\n--- Agent Conversation ---\n${conversation}`
						output += verboseTail
						bodyForDisplay += verboseTail
					}
				}

				const completedAt = record.completedAt ?? Date.now()
				const durationMs = record.startedAt != null ? completedAt - record.startedAt : undefined
				const details: GetSubagentResultDetails = {
					agentId: record.id,
					displayName,
					description: record.description,
					status: record.status,
					visibility: record.visibility,
					abortReason: record.abortReason,
					toolUses: record.toolUses,
					tokens,
					contextPercent,
					compactionCount: record.compactionCount,
					durationMs,
					error: record.error,
					bodyText: formatAgentBodyForDisplay(bodyForDisplay),
					agentOutcome: record.latestOutcome,
				}

				return textResult(output, details)
			},
		}),
	)

pi.registerTool(
		defineTool({
			name: "steer_subagent",
			label: "Steer Agent",
			description:
				"Send a steering message to a running agent; it is injected into the agent's conversation after the current tool completes.",
			parameters: Type.Object({
				agent_id: Type.String({
					description: "The running agent's ID.",
				}),
				message: Type.String({
					description: "Steering message (appears as a user message in the agent's conversation).",
				}),
			}),
			execute: async (_toolCallId, params, _signal, _onUpdate, _ctx) => {
				const record = manager.getRecord(params.agent_id as string)
				if (!record) {
					return textResult(`Agent not found: "${params.agent_id}". It may have been cleaned up.`)
				}
				if (record.status !== "running") {
					return textResult(
						`Agent "${params.agent_id}" is not running (status: ${record.status}). Cannot steer a non-running agent.`,
					)
				}
				if (!record.session) {
					if (!record.pendingSteers) record.pendingSteers = []
					record.pendingSteers.push(params.message as string)
					pi.events.emit("subagents:steered", { id: record.id, message: params.message })
					return textResult(
						`Steering message queued for agent ${record.id}. It will be delivered once the session initializes.`,
					)
				}

				try {
					await steerAgent(record.session, params.message as string)
					pi.events.emit("subagents:steered", { id: record.id, message: params.message })
					const tokens = formatLifetimeTokens(record)
					const contextPercent = getSessionContextPercent(record.session)
					const stateParts: string[] = []
					if (tokens) stateParts.push(tokens)
					stateParts.push(`${record.toolUses} tool ${record.toolUses === 1 ? "use" : "uses"}`)
					if (contextPercent !== null) stateParts.push(`context ${Math.round(contextPercent)}% full`)
					if (record.compactionCount)
						stateParts.push(`${record.compactionCount} compaction${record.compactionCount === 1 ? "" : "s"}`)
					return textResult(
						`Steering message sent to agent ${record.id}. The agent will process it after its current tool execution.\n` +
							`Current state: ${stateParts.join(" · ")}`,
					)
				} catch (err) {
					return textResult(`Failed to steer agent: ${err instanceof Error ? err.message : String(err)}`)
				}
			},
		}),
	)

agent_spawn_calls.text:
runAgent(ctx, type, prompt, {
					pi,
					model: options.model,
					maxTurns: options.maxTurns,
					tokenBudget: options.tokenBudget,
					inactivityTimeout: options.inactivityTimeout,
					maxDuration: options.maxDuration,
					workerReport: record.taskRef
						? {
								isAccepted: () => record.agentReport?.attempt_id === record.currentAttemptId,
								submit: (report) => {
									const accepted = this.submitReport(id, report) != null
									return {
										accepted,
										message: accepted
											? "Agent report recorded. Worker run complete."
											: "Agent report rejected because this worker is no longer active.",
									}
								},
							}
						: undefined,
					hardTurnLimit: record.taskRef?.kind === "ferment_step",
					isolated: options.isolated,
					inheritContext: options.inheritContext,
					thinkingLevel: options.thinkingLevel,
					sessionFile: options.sessionFile,
					sessionDir: options.sessionDir,
					signal: record.abortController?.signal,
					onToolActivity: (activity) => {
						// Count only terminal statuses — a "pending" notification is
						// not a completed tool use.
						if (activity.status === "completed" || activity.status === "failed") record.toolUses++
						options.onToolActivity?.(activity)
					},
					onTurnEnd: (turnCount) => {
						record.lastTurnCount = turnCount
						options.onTurnEnd?.(turnCount)
					},
					onTextDelta: options.onTextDelta,
					onAssistantUsage: (usage) => {
						addUsage(record.lifetimeUsage, usage)
						options.onAssistantUsage?.(usage)
					},
					onCompaction: (info) => {
						record.compactionCount++
						this.onCompact?.(record, info)
						options.onCompaction?.(info)
					},
					onRuntimeCleanupRegistered: (cleanup) => {
						this.runtimeCleanups.set(record, cleanup)
					},
					onSessionCreated: (session) => {
						record.session = session
						if (record.pendingSteers?.length) {
							for (const msg of record.pendingSteers) {
								session.steer(msg).catch(() => {})
							}
							record.pendingSteers = undefined
						}
						options.onSessionCreated?.(session)
					},
					onSystemPrompt: (prompt) => {
						record.systemPrompt = prompt
					},
				})

runRemoteAgent(workspaceId, prompt, {
			apiKey,
			endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
			signal: record.abortController?.signal,
			// PR-intent runs keep the remote session after completion — the
			// review/steer loop attaches to it (deleted at terminal actions).
			keepAlive: record.gitWorkflow !== undefined,
			gitDetails,
			gitCredential,
			localPath: ctx.cwd,
			workspaceName: dirName,
			outputFile: record.outputFile,
			tags: { [SESSION_TAG_PARENT_SESSION_ID]: ctx.sessionManager.getSessionId() },
			...(workspaceSpec ? { spec: workspaceSpec } : {}),
			onReady: async (acpClient, meta) => {
				remoteSession.bindClient(acpClient, meta)
				// Capture the ACP session id for resume-after-restart persistence
				// (session/load attaches by id, never by name).
				const acpSessionId = acpClient.sessionId ?? undefined
				if (acpSessionId) {
					record.acpSessionId = acpSessionId
					record.remoteSession ??= meta
				}
				// Baseline capture (PR-first runs): HEAD at provisioning + the
				// user's pre-existing dirty files. The runner awaits this before
				// prompt() so the persisted running-state entry carries it. The
				// attempted flag guards re-runs on reattach: a FAILED first capture
				// must degrade to the plain completion menu, not re-capture a
				// post-commit HEAD as baseSha (silently poisoning the diff range).
				if (record.gitWorkflow && !record.gitWorkflow.baseSha && !baselineCaptureAttempted) {
					baselineCaptureAttempted = true
					// Bounded per ssh round trip (two commands: rev-parse + status);
					// the run otherwise looks idle for up to ~90s on a cold sandbox —
					// name what it's doing instead of staring at "analyzing".
					ctx.ui.notify?.(
						"Capturing the pre-run git baseline over SSH (one-time snapshot used for the review diff)…",
						"info",
					)
					// One retry for the ssh layer: the proxy enumerates the control
					// API with its own deadline and transient stalls answer as exit
					// status 255. Everything else fails once, honestly.
					for (let attempt = 0; ; attempt++) {
						try {
							const connection = await resolveSandboxGitConnection(meta, apiKey, {
								endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
							})
							const baseline = await captureBaseline(connection, {
								signal: record.abortController?.signal,
								timeoutMs: 45_000,
							})
							record.gitWorkflow.baseSha = baseline.baseSha
							record.gitWorkflow.dirtyFiles = baseline.dirtyFiles
							break
						} catch (err) {
							const isSshLayer = err instanceof SandboxGitError && err.exitCode === 255
							if (isSshLayer && attempt === 0) continue
							// Was console.warn — invisible. This degrades the PR review at
							// completion (no deterministic range), so tell the user now.
							const message = `Pre-run snapshot failed: ${err instanceof Error ? err.message : err}. This is a one-time HEAD snapshot taken before the agent commits — diff review at completion will recover via merge-base instead.`
							ctx.ui.notify?.(message, "warning")
							console.warn(`[agent-manager] baseline capture failed: ${err instanceof Error ? err.message : err}`)
							break
						}
					}
				}
				if (acpSessionId) {
					options.onRemoteReady?.({ meta, acpSessionId })
				}
			},
			onReconnecting: (reconnecting) => {
				remoteSession.setReconnecting(reconnecting)
				// Never resurrect a record the user already stopped or aborted.
				if (isActiveStatus(record.status)) {
					record.status = reconnecting ? "reconnecting" : "running"
				}
			},
			callbacks: this._remoteCallbacks(record, remoteSession, options),
		})

resumeAgent(record.session, attemptPrompt, {
			onToolActivity: (activity) => {
				if (activity.status === "completed" || activity.status === "failed") record.toolUses++
			},
			onTurnEnd: (turnCount) => {
				record.lastTurnCount = turnCount
			},
			onAssistantUsage: (usage) => {
				addUsage(record.lifetimeUsage, usage)
			},
			onCompaction: (info) => {
				record.compactionCount++
				this.onCompact?.(record, info)
			},
			signal: abortController.signal,
			maxTurns: attemptLimits.maxTurns,
			tokenBudget: attemptTokenBudget,
			minTokenBudget: purpose === "finalize_report" ? MIN_FINALIZE_TOKEN_BUDGET : undefined,
			inactivityTimeout: options.inactivityTimeout,
			maxDuration: attemptLimits.maxDuration,
			hardTurnLimit: record.taskRef?.kind === "ferment_step",
			shouldTerminateAfterTool: (toolName) =>
				toolName === "submit_agent_report" && record.agentReport?.attempt_id === record.currentAttemptId,
			onRuntimeCleanupRegistered: (cleanup) => {
				this.runtimeCleanups.set(record, cleanup)
			},
		})

attachRemoteAgent({
			apiKey,
			endpoint: process.env.KIMCHI_REMOTE_ENDPOINT,
			signal: abortController.signal,
			remoteSession: state.remoteSession,
			acpSessionId: state.acpSessionId,
			outputFile: state.outputFile,
			// A resumed PR-intent run keeps the session for the steer loop.
			keepAlive: state.gitWorkflow !== undefined,
			onReconnecting: (reconnecting) => {
				// Mirror the attach state onto the record (same as the in-run
				// reconnecting flow).
				if (isActiveStatus(record.status)) {
					record.status = reconnecting ? "reconnecting" : "running"
				}
			},
			onReady: (acpClient, meta) => {
				adapter.bindClient(acpClient, meta)
			},
			callbacks: {
				onTextDelta: (delta, fullText) => {
					adapter.appendAssistantText(fullText)
					options?.callbacks?.onTextDelta?.(delta, fullText)
				},
				onToolActivity: (activity) => {
					if (activity.status === "in_progress") {
						adapter.recordToolCallStart(activity.toolName, activity.toolCallId, activity.rawInput)
					} else {
						adapter.recordToolCallEndFromActivity(activity)
						record.toolUses++
					}
					options?.callbacks?.onToolActivity?.(activity)
				},
				onTurnEnd: (turnCount) => {
					record.lastTurnCount = turnCount
					adapter.incrementTurnCount()
					options?.callbacks?.onTurnEnd?.(turnCount)
				},
				onAssistantUsage: (usage) => {
					adapter.addUsage(usage)
					addUsage(record.lifetimeUsage, usage)
					options?.callbacks?.onAssistantUsage?.(usage)
				},
				onContextUsage: (used, size) => adapter.setContextUsage(used, size),
			},
		})

