cases.text:
case "prompt": {
                // Start prompt handling immediately, but emit the authoritative response only after
                // prompt preflight succeeds. Queued and immediately handled prompts also count as success.
                let preflightSucceeded = false;
                void session
                    .prompt(command.message, {
                    images: command.images,
                    streamingBehavior: command.streamingBehavior,
                    source: "rpc",
                    preflightResult: (didSucceed) => {
                        if (didSucceed) {
                            preflightSucceeded = true;
                            output(success(id, "prompt"));
                        }
                    },
                })
                    .catch((e) => {
                    if (!preflightSucceeded) {
                        output(error(id, "prompt", e.message));
                    }
                });
                return undefined;
            }

case "steer": {
                await session.steer(command.message, command.images);
                return success(id, "steer");
            }

case "follow_up": {
                await session.followUp(command.message, command.images);
                return success(id, "follow_up");
            }

case "abort": {
                await session.abort();
                return success(id, "abort");
            }

case "clear_queue": {
                return success(id, "clear_queue", session.clearQueue());
            }

case "new_session": {
                const options = command.parentSession ? { parentSession: command.parentSession } : undefined;
                const result = await runtimeHost.newSession(options);
                if (!result.cancelled) {
                    await rebindSession();
                }
                return success(id, "new_session", result);
            }

case "get_state": {
                const state = {
                    model: session.model,
                    thinkingLevel: session.thinkingLevel,
                    isStreaming: session.isStreaming,
                    isCompacting: session.isCompacting,
                    steeringMode: session.steeringMode,
                    followUpMode: session.followUpMode,
                    sessionFile: session.sessionFile,
                    sessionId: session.sessionId,
                    sessionName: session.sessionName,
                    autoCompactionEnabled: session.autoCompactionEnabled,
                    messageCount: session.messages.length,
                    pendingMessageCount: session.pendingMessageCount,
                };
                return success(id, "get_state", state);
            }

case "set_model": {
                const models = session.modelRuntime.getAvailableSnapshot();
                const model = models.find((m) => m.provider === command.provider && m.id === command.modelId);
                if (!model) {
                    return error(id, "set_model", `Model not found: ${command.provider}/${command.modelId}`);
                }
                await session.setModel(model);
                return success(id, "set_model", model);
            }

case "cycle_model": {
                const result = await session.cycleModel();
                if (!result) {
                    return success(id, "cycle_model", null);
                }
                return success(id, "cycle_model", result);
            }

case "get_available_models": {
                const models = session.modelRuntime.getAvailableSnapshot();
                return success(id, "get_available_models", { models });
            }

case "set_thinking_level": {
                session.setThinkingLevel(command.level);
                return success(id, "set_thinking_level");
            }

case "cycle_thinking_level": {
                const level = session.cycleThinkingLevel();
                if (!level) {
                    return success(id, "cycle_thinking_level", null);
                }
                return success(id, "cycle_thinking_level", { level });
            }

case "get_available_thinking_levels": {
                const levels = session.getAvailableThinkingLevels();
                return success(id, "get_available_thinking_levels", { levels });
            }

case "set_steering_mode": {
                session.setSteeringMode(command.mode);
                return success(id, "set_steering_mode");
            }

case "set_follow_up_mode": {
                session.setFollowUpMode(command.mode);
                return success(id, "set_follow_up_mode");
            }

case "compact": {
                const result = await session.compact(command.customInstructions);
                return success(id, "compact", result);
            }

case "set_auto_compaction": {
                session.setAutoCompactionEnabled(command.enabled);
                return success(id, "set_auto_compaction");
            }

case "set_auto_retry": {
                session.setAutoRetryEnabled(command.enabled);
                return success(id, "set_auto_retry");
            }

case "abort_retry": {
                session.abortRetry();
                return success(id, "abort_retry");
            }

case "bash": {
                const eventResult = await session.extensionRunner.emitUserBash({
                    type: "user_bash",
                    command: command.command,
                    excludeFromContext: command.excludeFromContext ?? false,
                    cwd: session.sessionManager.getCwd(),
                });
                if (eventResult?.result) {
                    session.recordBashResult(command.command, eventResult.result, {
                        excludeFromContext: command.excludeFromContext,
                    });
                    return success(id, "bash", eventResult.result);
                }
                const result = await session.executeBash(command.command, undefined, {
                    excludeFromContext: command.excludeFromContext,
                    id,
                    operations: eventResult?.operations,
                });
                return success(id, "bash", result);
            }

case "abort_bash": {
                session.abortBash();
                return success(id, "abort_bash");
            }

case "get_session_stats": {
                const stats = session.getSessionStats();
                return success(id, "get_session_stats", stats);
            }

case "export_html": {
                const path = await session.exportToHtml(command.outputPath);
                return success(id, "export_html", { path });
            }

case "switch_session": {
                const result = await runtimeHost.switchSession(command.sessionPath);
                if (!result.cancelled) {
                    await rebindSession();
                }
                return success(id, "switch_session", result);
            }

case "fork": {
                const result = await runtimeHost.fork(command.entryId);
                if (!result.cancelled) {
                    await rebindSession();
                }
                return success(id, "fork", { text: result.selectedText, cancelled: result.cancelled });
            }

case "clone": {
                const leafId = session.sessionManager.getLeafId();
                if (!leafId) {
                    return error(id, "clone", "Cannot clone session: no current entry selected");
                }
                const result = await runtimeHost.fork(leafId, { position: "at" });
                if (!result.cancelled) {
                    await rebindSession();
                }
                return success(id, "clone", { cancelled: result.cancelled });
            }

case "get_fork_messages": {
                const messages = session.getUserMessagesForForking();
                return success(id, "get_fork_messages", { messages });
            }

case "get_entries": {
                const sessionManager = session.sessionManager;
                let entries = sessionManager.getEntries();
                if (command.since !== undefined) {
                    const sinceIndex = entries.findIndex((e) => e.id === command.since);
                    if (sinceIndex === -1) {
                        return error(id, "get_entries", `Entry not found: ${command.since}`);
                    }
                    entries = entries.slice(sinceIndex + 1);
                }
                return success(id, "get_entries", { entries, leafId: sessionManager.getLeafId() });
            }

case "get_tree": {
                const sessionManager = session.sessionManager;
                return success(id, "get_tree", { tree: sessionManager.getTree(), leafId: sessionManager.getLeafId() });
            }

case "get_last_assistant_text": {
                const text = session.getLastAssistantText();
                return success(id, "get_last_assistant_text", { text });
            }

case "set_session_name": {
                const name = command.name.trim();
                if (!name) {
                    return error(id, "set_session_name", "Session name cannot be empty");
                }
                session.setSessionName(name);
                return success(id, "set_session_name");
            }

case "get_messages": {
                return success(id, "get_messages", { messages: session.messages });
            }

case "get_commands": {
                const commands = [];
                for (const command of session.extensionRunner.getRegisteredCommands()) {
                    commands.push({
                        name: command.invocationName,
                        description: command.description,
                        source: "extension",
                        sourceInfo: command.sourceInfo,
                    });
                }
                for (const template of session.promptTemplates) {
                    commands.push({
                        name: template.name,
                        description: template.description,
                        source: "prompt",
                        sourceInfo: template.sourceInfo,
                    });
                }
                for (const skill of session.resourceLoader.getSkills().skills) {
                    commands.push({
                        name: `skill:${skill.name}`,
                        description: skill.description,
                        source: "skill",
                        sourceInfo: skill.sourceInfo,
                    });
                }
                return success(id, "get_commands", { commands });
            }

default: {
                const unknownCommand = command;
                return error(id, unknownCommand.type, `Unknown command: ${unknownCommand.type}`);
            }

case AVAILABLE_EXT_METHODS.probe_mcp_server: {
				const result = await handleProbeMcpServer(this.mcpProbe, params)
				return result as Record<keyof ProbeResult, unknown>
			}

case AVAILABLE_EXT_METHODS.auth_status:
				// Read the shared credential store per call so authenticate(),
				// unstable_logout(), and logins from other Kimchi surfaces are
				// reflected without a reconnect.
				return handleAuthStatus({
					authPath: join(this.agentDir, "auth.json"),
					modelsPath: join(this.agentDir, "models.json"),
				})

case AVAILABLE_EXT_METHODS.set_onboarding_flag:
				// Write the shared config per call through the harness's
				// read-modify-write helper so sibling onboarding keys set by other
				// Kimchi surfaces survive.
				return handleSetOnboardingFlag({}, params)

case AVAILABLE_EXT_METHODS.steering:
				return handleSteering((sessionId) => {
					const entry = this.sessions.get(sessionId)
					if (!entry) return undefined
					// A cancelled turn stays defined until the prompt settles, but
					// cancel() has already drained its queue — a steer landing in this
					// window must not re-queue text that would leak into the next prompt.
					const turnActive = entry.turn !== undefined && !entry.turn.cancelled
					return { session: entry.session, turnActive }
				}, params)

case AVAILABLE_EXT_METHODS.import_discover:
				// Sessionless, read-only source-app discovery for the import screen
				// (ADR-0043/ADR-0044): nothing is written to disk and no session is
				// touched. ImportDiscoverResult is a type alias, so it is directly
				// assignable to the string-indexed record the extMethod contract
				// wants — no cast, no spread.
				return importDiscover()

case AVAILABLE_EXT_METHODS.import_apply:
				// Sessionless write half of the import (ADR-0043/ADR-0044): copies
				// selected skills into Kimchi's own skills dir, merges selected MCP
				// servers conservatively, and satisfies the migration marker. No
				// session is touched. The copied skills land in a watched root, so
				// the file watcher re-advertises palettes on its own.
				return { ...handleImportApply({ agentDir: this.agentDir }, params) }

case AVAILABLE_EXT_METHODS.set_project_trust:
				// Session-scoped trust survey answer (LLM-3628): persists the
				// decision, opens the kimchi project-scope gate, and (on grant)
				// live-refreshes skills. See handleSetProjectTrust.
				return this.handleSetProjectTrust(params)

case AVAILABLE_EXT_METHODS.get_path_trust:
				// Sessionless read (LLM-3628): resolved trust state for an
				// arbitrary path, incl. ancestor inheritance and the canonicalized
				// deciding entry. See handleGetPathTrust.
				return this.handleGetPathTrust(params)

case AVAILABLE_EXT_METHODS.set_path_trust:
				// Sessionless write (LLM-3628): persist a trust/deny decision for
				// any path (root and home included — deliberate power-user
				// capability), then live-refresh affected sessions. See
				// handleSetPathTrust.
				return this.handleSetPathTrust(params)

pi_sdk_agent_session_declarations.text:
export interface CreateAgentSessionOptions {
    /** Working directory for project-local discovery. Default: process.cwd() */
    cwd?: string;
    /** Global config directory. Default: ~/.pi/agent */
    agentDir?: string;
    /** Canonical model/auth runtime. Defaults to a runtime using agentDir/auth.json and models.json. */
    modelRuntime?: ModelRuntime;
    /** Model to use. Default: from settings, else first available */
    model?: Model<any>;
    /** Thinking level. Default: from settings, else 'medium' (clamped to model capabilities) */
    thinkingLevel?: ThinkingLevel;
    /** Models available for cycling (Ctrl+P in interactive mode) */
    scopedModels?: Array<{
        model: Model<any>;
        thinkingLevel?: ThinkingLevel;
    }>;
    /**
     * Optional default tool suppression mode when no explicit allowlist is provided.
     *
     * - "all": start with no tools enabled
     * - "builtin": disable the default built-in tools (read, bash, edit, write)
     *   but keep extension/custom tools enabled
     */
    noTools?: "all" | "builtin";
    /**
     * Optional allowlist of tool names.
     *
     * When omitted, pi uses the `defaultTools` setting for the initial built-in
     * selection when configured. Otherwise it enables the default built-in tools
     * (read, bash, edit, write). Extension/custom tools remain enabled unless
     * `noTools` changes that default. When provided, only the listed tool names are
     * enabled.
     */
    tools?: string[];
    /** Optional denylist of tool names to disable. Applies after `tools` when both are provided. */
    excludeTools?: string[];
    /** Custom tools to register (in addition to built-in tools). */
    customTools?: ToolDefinition[];
    /** Resource loader. When omitted, DefaultResourceLoader is used. */
    resourceLoader?: ResourceLoader;
    /** Session manager. Default: SessionManager.create(cwd) */
    sessionManager?: SessionManager;
    /** Settings manager. Default: SettingsManager.create(cwd, agentDir) */
    settingsManager?: SettingsManager;
    /** Session start event metadata for extension runtime startup. */
    sessionStartEvent?: SessionStartEvent;
}

pi_cli_parse_args_declarations.text:
export function parseArgs(args) {
    const result = {
        messages: [],
        fileArgs: [],
        unknownFlags: new Map(),
        diagnostics: [],
    };
    for (let i = 0; i < args.length; i++) {
        const arg = args[i];
        if (arg === "--") {
            for (const positionalArg of args.slice(i + 1)) {
                if (positionalArg.startsWith("@")) {
                    result.fileArgs.push(positionalArg.slice(1));
                }
                else {
                    result.messages.push(positionalArg);
                }
            }
            break;
        }
        else if (arg === "--help" || arg === "-h") {
            result.help = true;
        }
        else if (arg === "--version" || arg === "-v") {
            result.version = true;
        }
        else if (arg === "--mode" && i + 1 < args.length) {
            const mode = args[++i];
            if (mode === "text" || mode === "json" || mode === "rpc") {
                result.mode = mode;
            }
        }
        else if (arg === "--continue" || arg === "-c") {
            result.continue = true;
        }
        else if (arg === "--resume" || arg === "-r") {
            result.resume = true;
        }
        else if (arg === "--provider" && i + 1 < args.length) {
            result.provider = args[++i];
        }
        else if (arg === "--model" && i + 1 < args.length) {
            result.model = args[++i];
        }
        else if (arg === "--api-key" && i + 1 < args.length) {
            result.apiKey = args[++i];
        }
        else if (arg === "--system-prompt" && i + 1 < args.length) {
            result.systemPrompt = args[++i];
        }
        else if (arg === "--append-system-prompt" && i + 1 < args.length) {
            result.appendSystemPrompt = result.appendSystemPrompt ?? [];
            result.appendSystemPrompt.push(args[++i]);
        }
        else if (arg === "--name" || arg === "-n") {
            if (i + 1 < args.length) {
                result.name = args[++i];
            }
            else {
                result.diagnostics.push({ type: "error", message: "--name requires a value" });
            }
        }
        else if (arg === "--no-session") {
            result.noSession = true;
        }
        else if (arg === "--session" && i + 1 < args.length) {
            result.session = args[++i];
        }
        else if (arg === "--session-id" && i + 1 < args.length) {
            result.sessionId = args[++i];
        }
        else if (arg === "--fork" && i + 1 < args.length) {
            result.fork = args[++i];
        }
        else if (arg === "--session-dir" && i + 1 < args.length) {
            result.sessionDir = args[++i];
        }
        else if (arg === "--models" && i + 1 < args.length) {
            result.models = args[++i].split(",").map((s) => s.trim());
        }
        else if (arg === "--no-tools" || arg === "-nt") {
            result.noTools = true;
        }
        else if (arg === "--no-builtin-tools" || arg === "-nbt") {
            result.noBuiltinTools = true;
        }
        else if ((arg === "--tools" || arg === "-t") && i + 1 < args.length) {
            result.tools = args[++i]
                .split(",")
                .map((s) => s.trim())
                .filter((name) => name.length > 0);
        }
        else if ((arg === "--exclude-tools" || arg === "-xt") && i + 1 < args.length) {
            result.excludeTools = args[++i]
                .split(",")
                .map((s) => s.trim())
                .filter((name) => name.length > 0);
        }
        else if (arg === "--thinking" && i + 1 < args.length) {
            const level = args[++i];
            if (isValidThinkingLevel(level)) {
                result.thinking = level;
            }
            else {
                result.diagnostics.push({
                    type: "warning",
                    message: `Invalid thinking level "${level}". Valid values: ${VALID_THINKING_LEVELS.join(", ")}`,
                });
            }
        }
        else if (arg === "--print" || arg === "-p") {
            result.print = true;
            const next = args[i + 1];
            if (next !== undefined && !next.startsWith("@") && (!next.startsWith("-") || next.startsWith("---"))) {
                result.messages.push(next);
                i++;
            }
        }
        else if (arg === "--export" && i + 1 < args.length) {
            result.export = args[++i];
        }
        else if ((arg === "--extension" || arg === "-e") && i + 1 < args.length) {
            result.extensions = result.extensions ?? [];
            result.extensions.push(args[++i]);
        }
        else if (arg === "--no-extensions" || arg === "-ne") {
            result.noExtensions = true;
        }
        else if (arg === "--skill" && i + 1 < args.length) {
            result.skills = result.skills ?? [];
            result.skills.push(args[++i]);
        }
        else if (arg === "--prompt-template" && i + 1 < args.length) {
            result.promptTemplates = result.promptTemplates ?? [];
            result.promptTemplates.push(args[++i]);
        }
        else if (arg === "--theme" && i + 1 < args.length) {
            result.themes = result.themes ?? [];
            result.themes.push(args[++i]);
        }
        else if (arg === "--use-theme") {
            const themeName = args[i + 1];
            if (themeName === undefined || themeName.startsWith("-")) {
                result.diagnostics.push({ type: "error", message: "--use-theme requires a theme name" });
            }
            else {
                result.useTheme = themeName;
                i++;
            }
        }
        else if (arg === "--no-skills" || arg === "-ns") {
            result.noSkills = true;
        }
        else if (arg === "--no-prompt-templates" || arg === "-np") {
            result.noPromptTemplates = true;
        }
        else if (arg === "--no-themes") {
            result.noThemes = true;
        }
        else if (arg === "--no-context-files" || arg === "-nc") {
            result.noContextFiles = true;
        }
        else if (arg === "--list-models") {
            // Check if next arg is a search pattern (not a flag or file arg)
            if (i + 1 < args.length && !args[i + 1].startsWith("-") && !args[i + 1].startsWith("@")) {
                result.listModels = args[++i];
            }
            else {
                result.listModels = true;
            }
        }
        else if (arg === "--tui-mode") {
            const mode = args[i + 1];
            if (mode === "regular" || mode === "fullscreen") {
                result.tuiMode = mode;
                i++;
            }
            else if (mode === undefined || mode.startsWith("-")) {
                result.diagnostics.push({ type: "error", message: "--tui-mode requires regular or fullscreen" });
            }
            else {
                i++;
                result.diagnostics.push({
                    type: "error",
                    message: `Invalid TUI mode "${mode}". Valid values: regular, fullscreen`,
                });
            }
        }
        else if (arg === "--verbose") {
            result.verbose = true;
        }
        else if (arg === "--approve" || arg === "-a") {
            result.projectTrustOverride = true;
        }
        else if (arg === "--no-approve" || arg === "-na") {
            result.projectTrustOverride = false;
        }
        else if (arg === "--offline") {
            result.offline = true;
        }
        else if (arg.startsWith("@")) {
            result.fileArgs.push(arg.slice(1)); // Remove @ prefix
        }
        else if (arg.startsWith("--")) {
            const eqIndex = arg.indexOf("=");
            if (eqIndex !== -1) {
                result.unknownFlags.set(arg.slice(2, eqIndex), arg.slice(eqIndex + 1));
            }
            else {
                const flagName = arg.slice(2);
                const next = args[i + 1];
                if (next !== undefined && !next.startsWith("-") && !next.startsWith("@")) {
                    result.unknownFlags.set(flagName, next);
                    i++;
                }
                else {
                    result.unknownFlags.set(flagName, true);
                }
            }
        }
        else if (arg.startsWith("-") && !arg.startsWith("--")) {
            result.diagnostics.push({ type: "error", message: `Unknown option: ${arg}` });
        }
        else if (!arg.startsWith("-")) {
            result.messages.push(arg);
        }
    }
    return result;
}

pi_cli_main_declaration.text:
export async function main(args, options) {
    resetTimings();
    const extensionFactories = [...builtInExtensions, ...(options?.extensionFactories ?? [])];
    const offlineMode = args.includes("--offline") || isTruthyEnvFlag(process.env.PI_OFFLINE);
    if (offlineMode) {
        process.env.PI_OFFLINE = "1";
        process.env.PI_SKIP_VERSION_CHECK = "1";
    }
    if (await runAuthCommand(args)) {
        return;
    }
    if (process.platform === "win32") {
        cleanupWindowsSelfUpdateQuarantine(getPackageDir());
    }
    cleanupManagedInstall();
    const cwd = process.cwd();
    const agentDir = getAgentDir();
    const bootstrapSettingsManager = SettingsManager.create(cwd, agentDir, { projectTrusted: false });
    applyHttpProxySettings(bootstrapSettingsManager.getGlobalSettings().httpProxy);
    configureHttpDispatcher();
    if (await handlePackageCommand(args, { extensionFactories })) {
        const exitCode = process.exitCode ?? 0;
        if (process.platform === "win32" && exitCode === 0 && args[0] === "update") {
            // We normally prefer process.exit(0) for package commands so bad extensions cannot keep
            // one-shot commands alive. On Windows, Node can assert after fetch() if process.exit(0)
            // runs during teardown; let successful `pi update` drain naturally instead.
            // https://github.com/nodejs/node/issues/56645
            return;
        }
        process.exit(exitCode);
        return;
    }
    if (await handleConfigCommand(args, { extensionFactories })) {
        return;
    }
    const parsed = parseArgs(args);
    if (parsed.diagnostics.length > 0) {
        for (const d of parsed.diagnostics) {
            const color = d.type === "error" ? chalk.red : chalk.yellow;
            console.error(color(`${d.type === "error" ? "Error" : "Warning"}: ${d.message}`));
        }
        if (parsed.diagnostics.some((d) => d.type === "error")) {
            process.exit(1);
        }
    }
    time("parseArgs");
    if (parsed.version) {
        console.log(VERSION);
        process.exit(0);
    }
    if (parsed.export) {
        let result;
        try {
            const outputPath = parsed.messages.length > 0 ? parsed.messages[0] : undefined;
            result = await exportFromFile(parsed.export, outputPath);
        }
        catch (error) {
            const message = error instanceof Error ? error.message : "Failed to export session";
            console.error(chalk.red(`Error: ${message}`));
            process.exit(1);
        }
        console.log(`Exported to: ${result}`);
        process.exit(0);
    }
    let appMode = resolveAppMode(parsed, process.stdin.isTTY, process.stdout.isTTY);
    const shouldTakeOverStdout = appMode !== "interactive" && !isPlainRuntimeMetadataCommand(parsed);
    if (shouldTakeOverStdout) {
        takeOverStdout();
    }
    if (parsed.mode === "rpc" && parsed.fileArgs.length > 0) {
        console.error(chalk.red("Error: @file arguments are not supported in RPC mode"));
        process.exit(1);
    }
    validateForkFlags(parsed);
    validateSessionIdFlags(parsed);
    // Run migrations (pass cwd for project-local migrations)
    const { migratedAuthProviders: migratedProviders, deprecationWarnings } = runMigrations(cwd);
    time("runMigrations");
    const startupSettingsManager = SettingsManager.create(cwd, agentDir);
    const startupSettingsDiagnostics = collectSettingsDiagnostics(startupSettingsManager);
    // Experimental first-time setup: theme choice and analytics opt-in.
    // Runs before any runtime services are created so the chosen settings apply everywhere.
    if (appMode === "interactive" && !parsed.help && parsed.listModels === undefined && shouldRunFirstTimeSetup()) {
        await showFirstTimeSetup(startupSettingsManager);
        time("firstTimeSetup");
    }
    if (appMode === "interactive" && parsed.useTheme !== undefined) {
        startupSettingsManager.applyOverrides({ theme: parsed.useTheme });
    }
    // Decide the final runtime cwd before creating cwd-bound runtime services.
    // --session and --resume may select a session from another project, so project-local
    // settings, resources, provider registrations, and models must be resolved only after
    // the target session cwd is known. The startup-cwd settings manager is used only for
    // sessionDir lookup during session selection.
    const envSessionDir = process.env[ENV_SESSION_DIR];
    const sessionDir = (parsed.sessionDir ? normalizePath(parsed.sessionDir) : undefined) ??
        (envSessionDir ? expandTildePath(envSessionDir) : undefined) ??
        startupSettingsManager.getSessionDir();
    let sessionManager = await createSessionManager(parsed, cwd, sessionDir, startupSettingsManager);
    const missingSessionCwdIssue = getMissingSessionCwdIssue(sessionManager, cwd);
    if (missingSessionCwdIssue) {
        if (appMode === "interactive") {
            const selectedCwd = await promptForMissingSessionCwd(missingSessionCwdIssue, startupSettingsManager);
            if (!selectedCwd) {
                process.exit(0);
            }
            sessionManager = SessionManager.open(missingSessionCwdIssue.sessionFile, sessionDir, selectedCwd);
        }
        else {
            console.error(chalk.red(new MissingSessionCwdError(missingSessionCwdIssue).message));
            process.exit(1);
        }
    }
    if (parsed.name !== undefined) {
        const name = normalizeSessionName(parsed.name);
        if (name === undefined) {
            console.error(chalk.red("Error: --name requires a non-empty value"));
            process.exit(1);
        }
        sessionManager.appendSessionInfo(name);
    }
    time("createSessionManager");
    const trustStore = new ProjectTrustStore(agentDir);
    const sessionCwd = sessionManager.getCwd();
    const autoTrustOnReloadCwd = parsed.projectTrustOverride === undefined && !hasTrustRequiringProjectResources(sessionCwd)
        ? sessionCwd
        : undefined;
    const trustPromptMode = parsed.help || parsed.listModels !== undefined ? "print" : appMode;
    const projectTrustByCwd = new Map();
    const resolvedExtensionPaths = resolveCliPaths(cwd, parsed.extensions);
    const resolvedSkillPaths = resolveCliPaths(cwd, parsed.skills);
    const resolvedPromptTemplatePaths = resolveCliPaths(cwd, parsed.promptTemplates);
    const resolvedThemePaths = resolveCliPaths(cwd, parsed.themes);
    const createRuntime = async ({ cwd, agentDir, sessionManager, sessionStartEvent, projectTrustContext, }) => {
        const isInitialRuntime = sessionStartEvent === undefined;
        const projectTrustDiagnostics = [];
        const cachedProjectTrust = projectTrustByCwd.get(cwd);
        const hasTrustRequiringResources = hasTrustRequiringProjectResources(cwd);
        const shouldResolveProjectTrust = parsed.projectTrustOverride === undefined && cachedProjectTrust === undefined && hasTrustRequiringResources;
        const projectTrusted = shouldResolveProjectTrust
            ? false
            : (cachedProjectTrust ??
                parsed.projectTrustOverride ??
                (!hasTrustRequiringResources || trustStore.get(cwd) === true));
        const runtimeSettingsManager = SettingsManager.create(cwd, agentDir, { projectTrusted });
        const services = await createAgentSessionServices({
            cwd,
            agentDir,
            settingsManager: runtimeSettingsManager,
            modelRuntimeSignal: AbortSignal.timeout(15_000),
            extensionFlagValues: parsed.unknownFlags,
            resourceLoaderReloadOptions: shouldResolveProjectTrust
                ? {
                    resolveProjectTrust: async ({ extensionsResult }) => {
                        const trusted = await resolveProjectTrusted({
                            cwd,
                            trustStore,
                            trustOverride: parsed.projectTrustOverride,
                            defaultProjectTrust: startupSettingsManager.getDefaultProjectTrust(),
                            extensionsResult,
                            projectTrustContext: projectTrustContext ??
                                createProjectTrustContext({
                                    cwd,
                                    mode: isInitialRuntime ? trustPromptMode : appMode,
                                    settingsManager: startupSettingsManager,
                                    hasUI: isInitialRuntime && trustPromptMode === "interactive",
                                }),
                            onExtensionError: (message) => projectTrustDiagnostics.push({ type: "warning", message }),
                        });
                        projectTrustByCwd.set(cwd, trusted);
                        return trusted;
                    },
                }
                : undefined,
            resourceLoaderOptions: {
                additionalExtensionPaths: resolvedExtensionPaths,
                additionalSkillPaths: resolvedSkillPaths,
                additionalPromptTemplatePaths: resolvedPromptTemplatePaths,
                additionalThemePaths: resolvedThemePaths,
                noExtensions: parsed.noExtensions,
                noSkills: parsed.noSkills,
                noPromptTemplates: parsed.noPromptTemplates,
                noThemes: parsed.noThemes,
                noContextFiles: parsed.noContextFiles,
                systemPrompt: parsed.systemPrompt,
                appendSystemPrompt: parsed.appendSystemPrompt,
                extensionFactories,
            },
        });
        const { settingsManager, modelRuntime, resourceLoader } = services;
        const diagnostics = [
            ...projectTrustDiagnostics,
            ...services.diagnostics,
            ...collectSettingsDiagnostics(settingsManager),
            ...resourceLoader.getExtensions().errors.map(({ path, error }) => ({
                type: "error",
                message: `Failed to load extension "${path}": ${error}`,
            })),
        ];
        const modelPatterns = parsed.models ?? settingsManager.getEnabledModels();
        const scopedModels = modelPatterns && modelPatterns.length > 0
            ? await resolveModelScope(modelPatterns, modelRuntime, { signal: AbortSignal.timeout(15_000) })
            : [];
        const { options: sessionOptions, cliThinkingFromModel, diagnostics: sessionOptionDiagnostics, } = buildSessionOptions(parsed, scopedModels, sessionManager.buildSessionContext().messages.length > 0, modelRuntime, settingsManager);
        diagnostics.push(...sessionOptionDiagnostics);
        if (parsed.apiKey) {
            if (!sessionOptions.model) {
                diagnostics.push({
                    type: "error",
                    message: "--api-key requires a model to be specified via --model, --provider/--model, or --models",
                });
            }
            else {
                await modelRuntime.setRuntimeApiKey(sessionOptions.model.provider, parsed.apiKey);
            }
        }
        const created = await createAgentSessionFromServices({
            services,
            sessionManager,
            sessionStartEvent,
            model: sessionOptions.model,
            thinkingLevel: sessionOptions.thinkingLevel,
            scopedModels: sessionOptions.scopedModels,
            tools: sessionOptions.tools,
            excludeTools: sessionOptions.excludeTools,
            noTools: sessionOptions.noTools,
            customTools: sessionOptions.customTools,
        });
        const cliThinkingOverride = parsed.thinking !== undefined || cliThinkingFromModel;
        if (created.session.model && cliThinkingOverride) {
            created.session.setThinkingLevel(created.session.thinkingLevel);
        }
        return {
            ...created,
            services,
            diagnostics,
        };
    };
    time("createRuntime");
    const runtime = await createAgentSessionRuntime(createRuntime, {
        cwd: sessionManager.getCwd(),
        agentDir,
        sessionManager,
    });
    time("createAgentSessionRuntime");
    const { services, session, modelFallbackMessage } = runtime;
    const { settingsManager, modelRuntime, resourceLoader } = services;
    setCapabilityOverrides(settingsManager.getTerminalCapabilityOverrides());
    applyHttpProxySettings(settingsManager.getGlobalSettings().httpProxy);
    configureHttpDispatcher(settingsManager.getHttpIdleTimeoutMs());
    if (parsed.help) {
        reportDiagnostics(startupSettingsDiagnostics);
        const extensionFlags = resourceLoader
            .getExtensions()
            .extensions.flatMap((extension) => Array.from(extension.flags.values()));
        printHelp(extensionFlags);
        process.exit(0);
    }
    if (parsed.listModels !== undefined) {
        reportDiagnostics(startupSettingsDiagnostics);
        const searchPattern = typeof parsed.listModels === "string" ? parsed.listModels : undefined;
        await listModels(modelRuntime, searchPattern, AbortSignal.timeout(15_000));
        process.exit(0);
    }
    // Read piped stdin content (if any) - skip for RPC mode which uses stdin for JSON-RPC
    let stdinContent;
    if (appMode !== "rpc") {
        stdinContent = await readPipedStdin();
        if (stdinContent !== undefined && appMode === "interactive") {
            appMode = "print";
        }
    }
    time("readPipedStdin");
    const { initialMessage, initialImages } = await prepareInitialMessage(parsed, settingsManager.getImageAutoResize(), stdinContent);
    time("prepareInitialMessage");
    // pi reads user-authored themes, so it opts into full validation before any theme loads.
    setThemeJsonValidator(validateThemeJson);
    initTheme(settingsManager.getTheme(), appMode === "interactive");
    time("initTheme");
    // Show deprecation warnings in interactive mode
    if (appMode === "interactive" && deprecationWarnings.length > 0) {
        await showDeprecationWarnings(deprecationWarnings);
    }
    time("resolveModelScope");
    const startupDiagnostics = deduplicateDiagnostics([...startupSettingsDiagnostics, ...runtime.diagnostics]);
    const hasRuntimeErrors = runtime.diagnostics.some((diagnostic) => diagnostic.type === "error");
    if (appMode !== "interactive" || hasRuntimeErrors) {
        reportDiagnostics(startupDiagnostics);
    }
    if (hasRuntimeErrors) {
        if (runtime.diagnostics.some((diagnostic) => diagnostic.message.includes("Failed to load extension"))) {
            console.error(chalk.yellow(EXTENSION_LOAD_FAILURE_HINT));
        }
        process.exit(1);
    }
    time("createAgentSession");
    if (appMode !== "interactive" && !session.model) {
        console.error(chalk.red(formatNoModelsAvailableMessage()));
        process.exit(1);
    }
    const startupBenchmark = isTruthyEnvFlag(process.env.PI_STARTUP_BENCHMARK);
    if (startupBenchmark && appMode !== "interactive") {
        console.error(chalk.red("Error: PI_STARTUP_BENCHMARK only supports interactive mode"));
        process.exit(1);
    }
    // RPC refreshes catalogs here in the background; interactive mode starts its refresh after TUI initialization.
    if (!offlineMode && appMode === "rpc") {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 15_000);
        void modelRuntime
            .refresh({ signal: controller.signal })
            .catch(() => { })
            .finally(() => clearTimeout(timeout));
    }
    if (appMode === "rpc") {
        printTimings();
        await runRpcMode(runtime);
    }
    else if (appMode === "interactive") {
        const interactiveMode = new InteractiveMode(runtime, {
            migratedProviders,
            startupDiagnostics,
            modelFallbackMessage,
            autoTrustOnReloadCwd,
            initialMessage,
            initialImages,
            initialMessages: parsed.messages,
            verbose: parsed.verbose,
            tuiMode: parsed.tuiMode,
            initialThemeSetting: parsed.useTheme,
        });
        if (startupBenchmark) {
            await interactiveMode.init();
            time("interactiveMode.init");
            // Give the TUI's stdin handler a brief chance to consume terminal query replies
            // (Kitty keyboard protocol, device attributes, cell size) before restoring the terminal.
            await new Promise((resolve) => setTimeout(resolve, 150));
            interactiveMode.stop();
            stopThemeWatcher();
            printTimings();
            if (process.stdout.writableLength > 0) {
                await new Promise((resolve) => process.stdout.once("drain", resolve));
            }
            if (process.stderr.writableLength > 0) {
                await new Promise((resolve) => process.stderr.once("drain", resolve));
            }
            return;
        }
        printTimings();
        await interactiveMode.run();
    }
    else {
        printTimings();
        const exitCode = await runPrintMode(runtime, {
            mode: toPrintOutputMode(appMode),
            messages: parsed.messages,
            initialMessage,
            initialImages,
        });
        stopThemeWatcher();
        restoreStdout();
        if (exitCode !== 0) {
            process.exitCode = exitCode;
        }
        return;
    }
}

