export function populateCliArgs(args: string[]): void {
	cachedCliArgs = parseCliArgs(args)
}

export function parseCliArgs(args: string[]): SessionCliArgs {
	const { values, positionals } = parseArgs({
		args,
		options: PARSE_ARGS_OPTIONS,
		strict: false,
		allowPositionals: true,
	})
	const options: SessionCliArgs["options"] = {}
	for (const key of CACHEABLE_OPTION_NAMES) {
		let value = values[key]
		if (value === undefined) continue
		// node:util parseArgs with strict:false returns the raw string for
		// `--flag=value` even when the flag is declared boolean. For boolean
		// flags, accept only the explicit =true/=false forms — anything else
		// (e.g. --memory=1) would store a string into a boolean-typed option,
		// making `=== true` and truthiness checks disagree.
		if (CLI_OPTIONS[key]?.type === "boolean" && typeof value === "string") {
			if (value !== "true" && value !== "false") {
				throw new Error(`--${key} expects a boolean (=true or =false); got --${key}=${JSON.stringify(value)}`)
			}
			value = value === "true"
		}
		;(options as Record<string, unknown>)[key] = value
	}
	return { options, positionals }
}

export function getParsedCliArgs(): SessionCliArgs {
	if (!cachedCliArgs) {
		cachedCliArgs = parseCliArgs(process.argv.slice(2))
	}
	return cachedCliArgs
}

export function normalizeResumeIdArgs(args: string[]): string[] {
	const normalized: string[] = []
	for (let i = 0; i < args.length; i += 1) {
		const arg = args[i]
		if (arg.startsWith("--resume=") && arg.length > "--resume=".length) {
			normalized.push("--session", arg.slice("--resume=".length))
		} else if (arg.startsWith("-r") && arg.length > 2) {
			normalized.push("--session", arg.slice(2))
		} else if ((arg === "-r" || arg === "--resume") && i + 1 < args.length && isSessionSelector(args[i + 1])) {
			normalized.push("--session", args[i + 1])
			i += 1
		} else {
			normalized.push(arg)
		}
	}
	return normalized
}

function isSessionSelector(value: string): boolean {
	return /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(value) || isPathLike(value)
}

function isPathLike(value: string): boolean {
	return value.startsWith("/") || value.startsWith("./") || value.startsWith("../") || value.startsWith("~/")
}

export function isCliAtFileArg(arg: string, index: number, args: string[]): boolean {
	if (!arg.startsWith("@") || arg === "@") return false
	// Use Pi's parser as the source of truth instead of mirroring every value-taking flag.
	return parsePiArgs(args.slice(0, index + 1)).fileArgs.length > parsePiArgs(args.slice(0, index)).fileArgs.length
}

export function isHelpOrVersionArgs(args: string[]): boolean {
	return args.some((a) => a === "--help" || a === "-h" || a === "--version" || a === "-v")
}

export function isProtocolCliMode(mode: string | undefined): boolean {
	return mode !== undefined && PROTOCOL_MODES.has(mode as CliMode)
}

export function isProtocolOrPrintMode(args: string[]): boolean {
	const parsed = parsePiArgs(args)
	const mode = parsed.mode ?? getCliModeArg(args)
	return isProtocolCliMode(mode) || parsed.print === true
}

export function isTerminalUiMode(args: string[], io: { stdinIsTTY: boolean; stdoutIsTTY: boolean }): boolean {
	return io.stdinIsTTY && io.stdoutIsTTY && !isProtocolOrPrintMode(args)
}

export function isExperimentalFeaturesArg(args: string[]): boolean {
	return args.includes("--enable-experimental-features")
}

export function hasFermentOneshotArg(args: readonly string[]): boolean {
	return args.some((a) => a === "--ferment-oneshot" || a === "--ferment-oneshot=true" || a === "ferment-oneshot=true")
}

export function stripExperimentalFeaturesArg(args: string[]): string[] {
	return args.filter((a) => a !== "--enable-experimental-features")
}

acp_session_factory_declarations.text:
export interface RunAcpOptions {
	extensionFactories: InlineExtension[]
	agentDir: string
	/** Add the session-scoped MCP adapter after caller servers are known. */
	mcpExtensionFactory?: (options: KimchiMcpAdapterExtensionOptions) => ExtensionFactory
	/**
	 * Content of the `--append-system-prompt` CLI flag, forwarded verbatim to
	 * every session's DefaultResourceLoader. When a client also sends
	 * `_meta["kimchi.dev"].appendSystemPrompt`, meta content is appended after this.
	 */
	appendSystemPrompt?: string[]
	/** Override for tests. Defaults to the pi-coding-agent-backed factory. */
	sessionFactory?: AcpSessionFactory
	/** Override for tests. Defaults to {@link defaultSessionLister}. */
	sessionLister?: AcpSessionLister
	/** Override for tests. Defaults to {@link defaultSessionLoader}. */
	sessionLoader?: AcpSessionLoader
	/**
	 * Isolated MCP probe used by `_kimchi.dev/probe_mcp_server`. Injected so
	 * tests can stub it; production uses the upstream-adapter-backed probe.
	 */
	mcpProbe?: McpProbe
}

async function createSessionSettings(
	cwd: string,
	options: RunAcpOptions,
	params: { _meta?: unknown; mcpServers?: ReadonlyArray<McpServer> },
) {
	// Construct untrusted first: pi's SettingsManager.create defaults
	// projectTrusted to TRUE, which would let an untrusted repo's
	// .pi/settings.json influence HTTP behavior (e.g. disable the idle
	// timeout) — and the defaultProjectTrust read below must be global-scope
	// only so a project cannot grant itself trust. Trust is then resolved the
	// way pi's own no-UI path does and applied in-memory.
	const settingsManager = SettingsManager.create(cwd, options.agentDir, { projectTrusted: false })
	const projectTrusted = resolveHeadlessProjectTrust(cwd, options.agentDir, settingsManager.getDefaultProjectTrust())
	settingsManager.setProjectTrusted(projectTrusted)
	// Sync the same decision onto the kimchi project-scope gate so this
	// session's reads of project-local .kimchi/ and .claude/ resources
	// (config, permissions, hooks, skills) honor it. Keyed by cwd so concurrent
	// ACP sessions in one process stay isolated.
	setProjectScopeTrusted(cwd, projectTrusted)
	initializeHeadlessTheme(settingsManager)
	// Getter form: re-read on every request so mid-session settings edits
	// apply live. The override slot is process-global — with several ACP
	// sessions in one process, the last-configured session's value governs
	// all of them (see setStreamIdleTimeoutOverride).
	configureHttpIdleTimeout(() => settingsManager.getHttpIdleTimeoutMs())
	const callerServers = convertAcpMcpServers(params.mcpServers ?? [])
	const mcpExtension = options.mcpExtensionFactory?.({ cwd, callerServers })
	// Annotated explicitly: the appendSystemPromptOverride closure references
	// `resourceLoader` in its own initializer, which TS otherwise flags as
	// circular (7022).
	const resourceLoader: DefaultResourceLoader = new DefaultResourceLoader({
		cwd,
		agentDir: options.agentDir,
		settingsManager,
		extensionFactories: [...options.extensionFactories, ...(mcpExtension ? [mcpExtension] : [])],
		appendSystemPromptOverride: () => {
			// Per-loader cached so a mid-session project-trust grant can
			// invalidate it (see invalidateSkillListBlock); built lazily on
			// first access, errors fall back to an empty block — it is
			// non-essential.
			let block = cachedSkillListBlock(resourceLoader)
			if (block === undefined) {
				try {
					block = buildSkillListBlock(resourceLoader)
				} catch {
					// If the loader isn't ready (e.g. during reload before skills
					// are populated), return empty rather than crashing session
					// startup.
					block = ""
				}
				setCachedSkillListBlock(resourceLoader, block)
			}
			// CLI flag content first, then _meta["kimchi.dev"].appendSystemPrompt,
			// then the skill list block (matches upstream override behaviour).
			const base = resolveAcpAppendSystemPrompt(params, options) ?? []
			return [...base, ...(block ? [block] : [])]
		},
	})
	await resourceLoader.reload()
	return { settingsManager, resourceLoader }
}

export function defaultSessionFactory(options: RunAcpOptions): AcpSessionFactory {
	return async (params: NewSessionRequest): Promise<AgentSession> => {
		const cwd = params.cwd ?? process.cwd()
		const { settingsManager, resourceLoader } = await createSessionSettings(cwd, options, params)
		const { session } = await createAgentSession({
			cwd,
			agentDir: options.agentDir,
			settingsManager,
			resourceLoader,
		})
		return session
	}
}

permission_functions.text:
function canPrompt(ctx: ExtensionContext): boolean {
	if (isAgentWorker()) return false

	const acpPrompter = getAcpPrompter(ctx.sessionManager.getSessionId())
	if (ctx.mode === "rpc" && acpPrompter) return true

	if (ctx.hasUI) return true
	return false
}

function resolvePrompter(ctx: ExtensionContext): ToolPermissionPrompter | undefined {
	if (isAgentWorker()) return undefined

	const acpPrompter = getAcpPrompter(ctx.sessionManager.getSessionId())
	if (ctx.mode === "rpc" && acpPrompter) return acpPrompter

	if (ctx.hasUI) return terminalPrompter(ctx)
	return undefined
}

async function handleConfirm(
	event: ToolCallEvent,
	opts: ConfirmOptions,
): Promise<{ block: true; reason: string } | "aborted" | undefined> {
	const abort = new AbortController()
	const unlinkAbort = linkAbortSignal(opts.ctx.signal, abort)
	opts.activeAborts.add(abort)
	try {
		const prompter = resolvePrompter(opts.ctx)
		if (!prompter) {
			emitToolDecision(opts.pi, event, opts.permissionMode, "reject", "no_ui")
			return { block: true, reason: "No UI to confirm permission" }
		}

		opts.pi.events.emit("notification", {
			notification_type: "permission_prompt",
			tool_name: event.toolName,
			tool_use_id: event.toolCallId,
		})

		return await withBlocked(opts.pi.events, `Permission: ${event.toolName}`, async () => {
			opts.pi.events.emit(PERMISSION_EVENTS.BEFORE_PROMPT, {
				toolCallId: event.toolCallId,
				toolName: event.toolName,
				compound: false,
				riskScore: opts.riskScore,
				classifierReason: opts.subtitle,
			})

			const input = event.input
			const outcome = await prompter.request({
				toolCallId: event.toolCallId ?? `${event.toolName}-permission`,
				toolName: event.toolName,
				input,
				subtitle: opts.subtitle,
				riskScore: opts.riskScore,
				choices: buildPermissionChoices(event.toolName, input),
				signal: abort.signal,
			})

			opts.pi.events.emit(PERMISSION_EVENTS.AFTER_DECISION, {
				toolCallId: event.toolCallId,
				toolName: event.toolName,
				decision: approvalOutcomeToDecision(outcome),
				ruleAdded:
					outcome.kind === "allow-remember" || outcome.kind === "allow-remember-wildcard"
						? { toolName: event.toolName, behavior: "allow" as const, source: "session" as RuleSource }
						: undefined,
			})
			emitOutcomeDecision(opts.pi, event, opts.permissionMode, outcome.kind)

			return applyApprovalOutcome(outcome, opts.session)
		})
	} finally {
		unlinkAbort()
		opts.activeAborts.delete(abort)
	}
}

resource_store_declarations.text:
export function getResourceSettingsPath(): string {
	return process.env.KIMCHI_CODING_AGENT_DIR
		? resolve(process.env.KIMCHI_CODING_AGENT_DIR, "settings.json")
		: join(homedir(), ".config", "kimchi", "harness", "settings.json")
}

export function isResourceEnabled(id: string, path = getResourceSettingsPath()): boolean {
	assertResourceId(id)
	const override = getResourceOverride(id, path)
	if (override !== undefined) return override
	if (envEnabledResources().has(id)) return true
	const definition = getResourceDefinition(id)
	const fallback = definition?.defaultEnabled ?? true
	return fallback
}

export function setResourceOverride(id: string, enabled: boolean | undefined, path = getResourceSettingsPath()): void {
	assertResourceId(id)
	const settings = readJson(path)
	const resources = asRecord(settings[SETTINGS_KEY])
	if (enabled === undefined) delete resources[id]
	else resources[id] = enabled

	if (Object.keys(resources).length > 0) {
		settings[SETTINGS_KEY] = resources
	} else {
		delete settings[SETTINGS_KEY]
	}
	writeJson(path, settings)
}

export function resetResourceOverride(id: string, path = getResourceSettingsPath()): void {
	setResourceOverride(id, undefined, path)
}

