kimchi_extensions/daemon/daemon-tool.ts.text:
const daemonSchema = Type.Object({
	command: Type.String({
		description:
			"Bash command line to run as the daemon (compound commands like 'a && b' are fine — the whole line runs in one shell). The returned pid is the process-group leader; a thin shell wrapper may remain if the command doesn't end in exec. Output is redirected to the daemon's log file automatically.",
	}),
	name: Type.Optional(
		Type.String({
			description:
				"Short identifier for the daemon (alphanumerics/dash/underscore only, max 40 chars). Used as a prefix for its id and log files. Pick something meaningful like 'pypi-server' or 'dev-web'.",
		}),
	),
})

export interface DaemonToolOptions {
	/** Override the state dir (tests use a temp dir). */
	stateDir?: string
	/** Override the crash-grace window in ms (tests shrink this). */
	crashGraceMs?: number
}

export function createDaemonToolDefinition(
	options: DaemonToolOptions = {},
): ToolDefinition<typeof daemonSchema, Record<string, unknown>> {
	const stateDir = options.stateDir ?? daemonStateDir()

	return {
		name: DAEMON_TOOL_NAME,
		label: "daemon",
		description: DAEMON_TOOL_DESCRIPTION,
		promptSnippet: "start a detached service that must outlive this session (manage via daemon_control)",
		parameters: daemonSchema,
		async execute(_toolCallId, params, _signal, _onUpdate, ctx) {
			// Coerce empty-string name to undefined so it takes the default
			// `daemon-` prefix instead of producing a `-a1b2c3`-style id.
			const name = params.name === "" ? undefined : params.name
			if (name !== undefined) {
				const nameError = validateDaemonName(name)
				if (nameError) {
					return {
						content: [{ type: "text", text: `Error: ${nameError}` }],
						details: { error: "invalid-name" },
					}
				}
			}

			const outcome = await spawnDaemon({
				command: params.command,
				cwd: ctx.cwd,
				name,
				stateDir,
				crashGraceMs: options.crashGraceMs,
			})

			if (!outcome.ok) {
				return {
					content: [{ type: "text", text: `Error: ${outcome.error}` }],
					details: { error: "spawn-failed" },
				}
			}

			const { record } = outcome
			return {
				content: [
					{
						type: "text",
						text:
							`Daemon started.\n  id:       ${record.id}\n  pid:      ${record.pid}\n  command:  ${record.command}\n  log file: ${record.logFile}\n\n` +
							`It is detached and will keep running after this session ends. Verify it works (e.g. curl / connect) and tell the user how to reach it. Manage with daemon_control: action "status" | "logs" | "stop", id "${record.id}".`,
					},
				],
				details: { id: record.id, pid: record.pid, logFile: record.logFile },
			}
		},
	}
}

kimchi_extensions/daemon/daemon-control-.text:
const daemonControlSchema = Type.Object({
	action: Type.Union([Type.Literal("list"), Type.Literal("status"), Type.Literal("logs"), Type.Literal("stop")], {
		description:
			"'list' shows all live daemons; 'status' checks one daemon's liveness; 'logs' tails its log file; 'stop' terminates it.",
	}),
	id: Type.Optional(
		Type.String({
			description: "Daemon id (returned by the daemon tool). Required for status/logs/stop.",
		}),
	),
	max_bytes: Type.Optional(
		Type.Integer({
			minimum: 1,
			description: "Only valid with action 'logs'. Max bytes to return from the end of the log file (default 8192).",
		}),
	),
})

function formatUptime(startedAt: string): string {
	const ms = Date.now() - new Date(startedAt).getTime()
	if (!Number.isFinite(ms) || ms < 0) return "unknown"
	const s = Math.floor(ms / 1000)
	if (s < 60) return `${s}s`
	const m = Math.floor(s / 60)
	if (m < 60) return `${m}m${s % 60}s`
	const h = Math.floor(m / 60)
	return `${h}h${m % 60}m`
}

export function createDaemonControlToolDefinition(
	options: DaemonControlToolOptions = {},
): ToolDefinition<typeof daemonControlSchema, Record<string, unknown>> {
	const stateDir = options.stateDir ?? daemonStateDir()

	return {
		name: DAEMON_CONTROL_TOOL_NAME,
		label: "daemon_control",
		description: DAEMON_CONTROL_TOOL_DESCRIPTION,
		promptSnippet: "check or stop detached daemons",
		parameters: daemonControlSchema,
		async execute(_toolCallId, params, _signal, _onUpdate, _ctx) {
			const { action, id } = params

			// ── list ────────────────────────────────────────────────────
			if (action === "list") {
				const live = listDaemons(stateDir)
				if (live.length === 0) {
					return {
						content: [{ type: "text", text: "No live daemons." }],
						details: { action, daemons: [] },
					}
				}
				const lines = live.map(
					({ record }) =>
						`${record.id}  pid ${record.pid}  up ${formatUptime(record.startedAt)}\n  ${record.command}\n  log: ${record.logFile}`,
				)
				return {
					content: [{ type: "text", text: `${live.length} live daemon(s):\n\n${lines.join("\n\n")}` }],
					details: {
						action,
						daemons: live.map(({ record }) => ({ id: record.id, pid: record.pid, command: record.command })),
					},
				}
			}

			// status / logs / stop require an id
			if (!id) {
				return {
					content: [
						{
							type: "text",
							text: `Error: action "${action}" requires an 'id' (from the daemon tool or daemon_control list).`,
						},
					],
					details: { action, error: "missing-id" },
				}
			}
			const record = readDaemon(stateDir, id)
			if (!record) {
				return {
					content: [
						{
							type: "text",
							text: `Daemon '${id}' is not recorded (already stopped, or never started here). Run daemon_control action "list" to see live daemons.`,
						},
					],
					details: { action, id, error: "unknown-id" },
				}
			}

			// ── status ──────────────────────────────────────────────────
			if (action === "status") {
				// isPidAlive directly — listDaemons would prune dead records, a
				// surprising side effect from a read-only status query.
				const live = isPidAlive(record.pid)
				return {
					content: [
						{
							type: "text",
							text:
								`Daemon ${record.id}: ${live ? "RUNNING" : "not running"}\n` +
								`  pid:      ${record.pid}\n  command:  ${record.command}\n  cwd:      ${record.cwd}\n` +
								`  started:  ${record.startedAt} (up ${formatUptime(record.startedAt)})\n  log:      ${record.logFile}`,
						},
					],
					details: { action, id, alive: live, pid: record.pid },
				}
			}

			// ── logs ────────────────────────────────────────────────────
			if (action === "logs") {
				const tail = readLogTail(record.logFile, params.max_bytes ?? 8192)
				return {
					content: [
						{
							type: "text",
							text: tail !== undefined ? tail : `(no log output yet — ${record.logFile} is missing or empty)`,
						},
					],
					details: { action, id, logFile: record.logFile },
				}
			}

			// ── stop ────────────────────────────────────────────────────
			// Explicit branch, NOT a fallthrough — if a future action is added
			// above but not handled, we must not silently STOP the daemon.
			if (action === "stop") {
				const { note } = await stopDaemon(record, stateDir)
				return {
					content: [{ type: "text", text: note }],
					details: { action, id, pid: record.pid },
				}
			}

			// Unreachable for the current schema (closed union) — but if a
			// new action is ever added and its branch is missed, nag rather
			// than fall into a destructive default.
			return {
				content: [
					{
						type: "text",
						text: `Unknown daemon_control action "${action}". Valid actions: list, status, logs, stop.`,
					},
				],
				details: { action, error: "unknown-action" },
			}
		},
	}
}

kimchi_extensions/daemon/spawn.ts.text:
export interface SpawnDaemonOptions {
	command: string
	cwd: string
	name?: string
	stateDir: string
	/** Override for tests: crash-detection grace in ms. */
	crashGraceMs?: number
}

function sleep(ms: number): Promise<void> {
	return new Promise((resolve) => setTimeout(resolve, ms))
}

export function readLogTail(logFile: string, maxBytes = 8192): string | undefined {
	if (!existsSync(logFile)) return undefined
	let fd: number | undefined
	try {
		fd = openSync(logFile, "r")
		const size = fstatSync(fd).size
		const from = Math.max(0, size - maxBytes)
		const length = size - from
		if (length <= 0) return ""
		const buf = Buffer.alloc(length)
		readSync(fd, buf, 0, length, from)
		let slice = buf
		// Snap the cut to a UTF-8 code-point boundary — slicing mid-sequence
		// would write replacement characters (mojibake) at the start of the
		// tail. Continuation bytes have the form 10xx xxxx; skip past them.
		let start = 0
		while (start < slice.length && (slice[start] & 0xc0) === 0x80) start++
		if (start > 0) slice = slice.subarray(start)
		return slice.toString("utf8")
	} catch (err) {
		console.error(`daemon: failed to read log ${logFile}:`, err)
		return undefined
	} finally {
		if (fd !== undefined) closeSync(fd)
	}
}

export async function spawnDaemon(opts: SpawnDaemonOptions): Promise<SpawnDaemonOutcome> {
	const { command, cwd, name, stateDir } = opts
	if (command.trim().length === 0) {
		return { ok: false, error: "Empty command — nothing to daemonize." }
	}
	const id = makeDaemonId(name)
	const logFile = `${stateDir}/${id}.log`
	const pidFile = `${stateDir}/${id}.pid`

	// Wrap the user's command behind `bash -c` so exec applies to ONE
	// process: `exec <compound> >> log` would only exec+redirect the first
	// segment and silently drop the rest. shellQuote single-quotes —
	// JSON.stringify (double quotes) is NOT safe here: the outer shell
	// would expand $vars/backticks before the inner bash sees them.
	// Windows (cmd) has no exec/setsid semantics; run plainly there.
	const wrapped =
		process.platform === "win32"
			? `${command} >> "${logFile}" 2>&1`
			: `exec bash -c ${shellQuote(command)} >> ${shellQuote(logFile)} 2>&1`

	const child = spawn(SHELL, SHELL_ARGS(wrapped), {
		cwd,
		// NOT process.env passthrough blind spot: daemons want the same env the
		// user's shell would see; process.env is the sanest default here.
		env: process.env,
		detached: true,
		stdio: "ignore",
		windowsHide: true,
	})

	// `spawn` never rejects for a missing cwd/binary — it emits 'error'
	// asynchronously instead. An unhandled 'error' would throw and kill
	// the kimchi process; capture it and convert to a soft spawn failure.
	let spawnError: Error | undefined
	child.on("error", (err) => {
		spawnError = err
	})
	child.unref()

	if (child.pid === undefined) {
		return { ok: false, error: `Failed to spawn daemon: ${spawnError?.message ?? "no pid assigned"}.` }
	}

	const record: DaemonRecord = {
		id,
		pid: child.pid,
		command,
		cwd,
		name,
		startedAt: new Date().toISOString(),
		logFile,
		pidFile,
	}
	registerDaemon(stateDir, record)

	// Crash-grace: give the daemon a moment to die if it's going to
	// (port-in-use, missing binary, bad flags). The single most common
	// "server started" lie is a command that exits inside the first second.
	const grace = opts.crashGraceMs ?? CRASH_GRACE_MS
	if (grace > 0) await sleep(grace)
	if (!isPidAlive(child.pid)) {
		const tail = readLogTail(logFile, 2048)
		unregisterDaemon(stateDir, id)
		const reason = spawnError
			? `Spawn failed: ${spawnError.message}`
			: `Daemon ${id} (pid ${child.pid}) exited immediately. The command probably failed at startup.`
		return {
			ok: false,
			error: reason + (tail ? `\n\n--- last output ---\n${tail.trimEnd()}` : ""),
		}
	}

	return { ok: true, record }
}

export async function stopDaemon(record: DaemonRecord, stateDir: string): Promise<{ stopped: boolean; note: string }> {
	const { pid } = record
	if (!isPidAlive(pid)) {
		unregisterDaemon(stateDir, record.id)
		return { stopped: false, note: `Daemon ${record.id} (pid ${pid}) was already not running. Record cleaned up.` }
	}

	if (process.platform === "win32") {
		// No POSIX process groups; taskkill /T kills the tree.
		spawnSync("taskkill", ["/T", "/F", "/PID", String(pid)], { stdio: "ignore" })
	} else {
		try {
			process.kill(-pid, "SIGTERM")
		} catch (err) {
			// ESRCH on a disappearing group is fine — the liveness check above
			// raced a natural exit.
			console.error(`daemon: SIGTERM to group -${pid} failed:`, err)
		}
		const deadline = Date.now() + STOP_TERM_GRACE_MS
		while (isPidAlive(pid) && Date.now() < deadline) {
			await sleep(100)
		}
		if (isPidAlive(pid)) {
			try {
				process.kill(-pid, "SIGKILL")
			} catch (err) {
				console.error(`daemon: SIGKILL to group -${pid} failed:`, err)
			}
			// Wait for the kernel to actually reap the process — an instant
			// liveness check would race signal delivery and false-negative
			// (report "still alive" for a process that is dying).
			const killDeadline = Date.now() + STOP_KILL_GRACE_MS
			while (isPidAlive(pid) && Date.now() < killDeadline) {
				await sleep(50)
			}
		}
	}

	const stillAlive = isPidAlive(pid)
	if (stillAlive) {
		// KEEP the record — the daemon is alive but unmanageable without it
		// (unregistering here would orphan a running process group).
		return {
			stopped: false,
			note: `Sent SIGKILL to daemon ${record.id} (pid ${pid}) but it is still alive — manual intervention needed. Record kept for another daemon_control stop attempt.`,
		}
	}
	unregisterDaemon(stateDir, record.id)
	return { stopped: true, note: `Daemon ${record.id} (pid ${pid}) stopped. Log kept at ${record.logFile}.` }
}

kimchi_extensions/daemon/state.ts.text:
export function daemonStateDir(): string {
	return join(homedir(), ".config", "kimchi", "daemons")
}

export function ensureStateDir(dir: string): void {
	mkdirSync(dir, { recursive: true })
}

export function validateDaemonName(name: string): string | undefined {
	if (name.length === 0) return "Daemon name cannot be empty (omit the parameter for the default name)."
	if (name.length > 40) return "Daemon name too long (max 40 chars)."
	if (!/^[a-zA-Z0-9_-]+$/.test(name)) {
		return "Daemon name may only contain letters, digits, dash, and underscore."
	}
	return undefined
}

export function makeDaemonId(name: string | undefined): string {
	const suffix = randomBytes(3).toString("hex")
	return `${name ? name : "daemon"}-${suffix}`
}

export function daemonRecordPath(dir: string, id: string): string {
	return join(dir, `${id}.json`)
}

export function registerDaemon(dir: string, record: DaemonRecord): void {
	ensureStateDir(dir)
	writeFileSync(daemonRecordPath(dir, record.id), JSON.stringify(record, null, 2))
	writeFileSync(record.pidFile, String(record.pid))
}

export function unregisterDaemon(dir: string, id: string): void {
	rmSync(daemonRecordPath(dir, id), { force: true })
	rmSync(join(dir, `${id}.pid`), { force: true })
}

export function isSafeStatePath(dir: string, filePath: string): boolean {
	if (!isAbsolute(filePath)) return false
	const resolvedDir = resolve(normalize(dir)) + sep
	const resolvedPath = resolve(normalize(filePath))
	return resolvedPath.startsWith(resolvedDir)
}

export function readDaemon(dir: string, id: string): DaemonRecord | undefined {
	const path = daemonRecordPath(dir, id)
	if (!existsSync(path)) return undefined
	let raw: unknown
	try {
		raw = JSON.parse(readFileSync(path, "utf8"))
	} catch (err) {
		console.error(`daemon state: malformed record ${id}:`, err)
		return undefined
	}
	if (typeof raw !== "object" || raw === null) return undefined
	const r = raw as Record<string, unknown>
	if (
		typeof r.id !== "string" ||
		typeof r.pid !== "number" ||
		typeof r.command !== "string" ||
		typeof r.logFile !== "string" ||
		typeof r.pidFile !== "string" ||
		typeof r.startedAt !== "string"
	) {
		console.error(`daemon state: record ${id} missing required fields`)
		return undefined
	}
	// Hardening beyond shape: reject values that would be dangerous to act on.
	// - pid must be a positive integer. kill(0, …) targets the CURRENT
	//   process group; -1 signals all processes we may signal — both would
	//   be catastrophic in stop/status paths.
	// - record id must match the filename it was loaded from — a tampered or
	//   corrupted record otherwise launders itself through list/status.
	// - log/pid files must stay inside the state dir; filenames are joins
	//   on our side, but a hand-edited record could redirect a future write.
	if (!Number.isInteger(r.pid) || r.pid <= 0) {
		console.error(`daemon state: record ${id} has invalid pid ${r.pid}`)
		return undefined
	}
	if (r.id !== id) {
		console.error(`daemon state: record ${id} id mismatch (contains "${r.id}")`)
		return undefined
	}
	for (const filePath of [r.logFile, r.pidFile]) {
		if (!isSafeStatePath(dir, filePath)) {
			console.error(`daemon state: record ${id} path escapes state dir: ${filePath}`)
			return undefined
		}
	}
	return {
		id: r.id,
		pid: r.pid,
		command: r.command,
		cwd: typeof r.cwd === "string" ? r.cwd : "",
		name: typeof r.name === "string" ? r.name : undefined,
		startedAt: r.startedAt,
		logFile: r.logFile,
		pidFile: r.pidFile,
	}
}

export function isPidAlive(pid: number): boolean {
	try {
		process.kill(pid, 0)
		return true
	} catch (err: unknown) {
		// EPERM means the process exists but is owned by someone else — alive.
		if (typeof err === "object" && err !== null && "code" in err && (err as { code?: string }).code === "EPERM") {
			return true
		}
		return false
	}
}

export interface DaemonListEntry {
	record: DaemonRecord
	alive: boolean
}

export function listDaemons(dir: string): DaemonListEntry[] {
	if (!existsSync(dir)) return []
	const out: DaemonListEntry[] = []
	for (const file of readdirSync(dir)) {
		if (!file.endsWith(".json")) continue
		const record = readDaemon(dir, file.slice(0, -".json".length))
		if (!record) continue
		const alive = isPidAlive(record.pid)
		if (!alive) {
			unregisterDaemon(dir, record.id)
			continue
		}
		out.push({ record, alive })
	}
	return out
}

kimchi_extensions/daemon/index.ts.text:
function formatDaemonNotice(count: number, firstId: string): string {
	return count === 1
		? `1 detached daemon still running (${firstId}) — it will keep running after kimchi exits. Stop it later with: kimchi, then daemon_control stop ${firstId}`
		: `${count} detached daemons still running (${firstId}, …) — they keep running after kimchi exits. Stop later with daemon_control.`
}

export default function daemonExtension(pi: ExtensionAPI): void {
	// Headless-only steering: without the clause, the model has no reason to
	// suspect `daemon` exists and reaches for `&`/nohup (dead at exit).
	// Kept HERE (not in the questionnaire extension, where it lived briefly):
	// the daemon extension owns its discoverability, and the experimental
	// gate means the clause only appears when the tools actually do.
	pi.on("before_agent_start", (event, ctx: ExtensionContext) => {
		if (ctx.hasUI) return
		if (pi.getFlag?.("ferment-oneshot") === true) return
		if (!isExperimentalFeaturesEnabled()) return
		return { systemPrompt: `${event.systemPrompt}\n\n${LONG_LIVED_SERVICES_CLAUSE}` }
	})

	pi.on("session_start", () => {
		// EXPERIMENTAL: tools require --enable-experimental-features. cli.ts
		// already gates registration; this inner check is defense-in-depth
		// for any path that wires the extension directly (subagent sessions,
		// bespoke entry points).
		if (!isExperimentalFeaturesEnabled()) return
		pi.registerTool(createDaemonToolDefinition())
		pi.registerTool(createDaemonControlToolDefinition())
	})

	pi.on("session_shutdown", (_event: SessionShutdownEvent, ctx) => {
		if (!ctx.hasUI) return
		try {
			const live = listDaemons(daemonStateDir())
			if (live.length === 0) return
			ctx.ui.notify(formatDaemonNotice(live.length, live[0].record.id), "info")
		} catch (err) {
			// Never let a housekeeping notice break session teardown.
			console.error("daemon shutdown notice failed:", err)
		}
	})
}

kimchi_extensions/bash-background/bash-b.text:
export interface BackgroundBashToolDetails extends BashToolDetails {
	display?: ProcessDisplaySnapshot
	/** Handle for the background process; pass to `bash_control`. Omitted on the short-task path. */
	handle?: string
	/** Whether the process has exited. */
	exited?: boolean
	/** Process exit code (null until exit / if killed). */
	exitCode?: number | null
	/** True when this result is a mid-run checkin (process still alive). */
	checkin?: boolean
	/** Reason the process stopped, if any ("stop" | "deadline" | "aborted" | …). */
	reason?: string | null
}

const backgroundBashSchema = Type.Object({
	command: Type.String({ description: "Bash command to execute" }),
	description: Type.Optional(
		Type.String({ maxLength: 120, description: "Short purpose shown beside the command (optional)." }),
	),
	timeout: Type.Optional(
		Type.Number({
			description: "Timeout in seconds. Set this to the realistic maximum the command could need.",
		}),
	),
	checkin_interval: Type.Optional(
		Type.Number({
			description: "Seconds between background checkins for long-running commands. Omit to use the default 15s.",
		}),
	),
})

export interface CreateBackgroundBashToolOptions extends BashToolOptions {
	/** Override the process registry (tests inject a fake). Defaults to a fresh registry. */
	registry?: ProcessRegistry
}

export function createBackgroundBashToolDefinition(
	cwd: string,
	options?: CreateBackgroundBashToolOptions,
): ToolDefinition<typeof backgroundBashSchema, BackgroundBashToolDetails | undefined> {
	// Wrap the upstream definition once — we reuse its description, parameters
	// (as a base), execution mode and shell presentation.
	const wrapped = createBashToolDefinition(cwd, options)
	const registry = options?.registry ?? createProcessRegistry()

	const description =
		wrapped.description +
		" Long-running commands run in the background: you receive a tail-window of output plus a process handle at each checkin (default every 15s, or every checkin_interval seconds when provided), then drive it to completion with the bash_control tool. For commands expected to run several minutes (builds, installs, training), set a longer checkin_interval (e.g. 60–120s) to avoid waking up every 15s; the cadence can also be changed later via bash_control's checkin_interval. Always set a timeout appropriate to the command — do not shorten it artificially."

	async function execute(
		toolCallId: string,
		params: BackgroundBashInput,
		signal: AbortSignal | undefined,
		onUpdate: Parameters<ToolDefinition["execute"]>[3] | undefined,
		ctx: Parameters<ToolDefinition["execute"]>[4],
	): Promise<{
		content: { type: "text"; text: string }[]
		details: BackgroundBashToolDetails | undefined
	}> {
		const { command, timeout, checkin_interval, description } = params
		const resolvedTimeout = timeout ?? DEFAULT_TIMEOUT_SECONDS
		const operations =
			options?.operations ?? createWorkCommitTrackingOperations(ctx, toolCallId, defaultLocalOps(options))

		// ── Short-task path: timeout <= 5 → synchronous run-to-completion. ──
		if (resolvedTimeout <= SHORT_TASK_TIMEOUT_SECONDS) {
			const upstreamParams = { command, timeout: resolvedTimeout }
			const result = await createBashToolDefinition(cwd, { ...options, operations }).execute(
				toolCallId,
				upstreamParams as Static<typeof wrapped.parameters>,
				signal,
				onUpdate as Parameters<typeof wrapped.execute>[3] | undefined,
				ctx as Parameters<typeof wrapped.execute>[4],
			)
			return {
				content: result.content as { type: "text"; text: string }[],
				details: { ...(result.details as BashToolDetails | undefined) },
			}
		}

		// ── Background checkin path. ──
		const intervalSeconds =
			checkin_interval !== undefined && checkin_interval > 0 ? checkin_interval : DEFAULT_CHECKIN_INTERVAL_SECONDS
		// Deadline: use the provided timeout if explicit, else a generous default
		// (the agent can extend via bash_control). Background mode never passes
		// an upstream timeout to ops.exec — the registry owns the deadline.
		const deadlineSeconds = timeout !== undefined && timeout > 0 ? timeout : DEFAULT_TIMEOUT_SECONDS
		const deadlineMs = Date.now() + deadlineSeconds * 1000

		const handle = registry.spawn(
			// Use the upstream-injected operations if provided, else the registry
			// will use its default local backend.
			operations,
			command,
			cwd,
			undefined,
			{ intervalSeconds, deadlineMs, toolCallId, description },
		)

		// Turn abort (ESC) must kill the process tree, same as the sync path.
		const onAbort = () => void registry.kill(handle, "aborted")
		if (signal?.aborted) onAbort()
		else signal?.addEventListener("abort", onAbort, { once: true })

		// Resolve at the first checkin OR process exit, whichever is first.
		let snapshot: TailSnapshot
		try {
			snapshot = await awaitCheckin(
				registry,
				handle,
				intervalSeconds,
				onUpdate
					? (display) =>
							onUpdate({
								content: [{ type: "text", text: display.output }],
								details: {
									handle,
									exited: display.state !== "running",
									exitCode: display.exitCode,
									checkin: display.state === "running",
									reason: display.reason,
									display,
								},
							})
					: undefined,
			)
		} finally {
			signal?.removeEventListener("abort", onAbort)
		}
		const exited = snapshot.state !== "running"
		const display = registry.displaySnapshot(handle)

		// If the process exited between spawn and the checkin, clean up the entry.
		if (exited) {
			const final = registry.finalSnapshot(handle)

			// Mirror upstream's error behavior: throw on non-zero exit or deadline.
			// The wording matters — bash-timeout-guidance.ts matches on
			// /Command timed out after (\d+) seconds/.
			const fullOutput = final?.content ?? snapshot.text
			onUpdate?.({
				content: [{ type: "text", text: fullOutput }],
				details: {
					handle,
					exited: true,
					exitCode: snapshot.exitCode,
					reason: snapshot.reason,
					display,
					...(final?.truncation?.truncated
						? { truncation: final.truncation, fullOutputPath: final.fullOutputPath }
						: {}),
				},
			})
			await registry.remove(handle).catch(() => {})
			throwIfTerminal(snapshot, fullOutput, deadlineSeconds)

			// Success exit — return plain output with truncation details if present.
			const truncated = final?.truncation?.truncated === true
			return {
				content: [
					{
						type: "text",
						text:
							truncated && final?.fullOutputPath
								? `${fullOutput}\n\n[Output truncated. Full output: ${final.fullOutputPath}]`
								: fullOutput,
					},
				],
				details: {
					exited: true,
					exitCode: snapshot.exitCode,
					reason: snapshot.reason,
					display,
					...(truncated ? { truncation: final?.truncation, fullOutputPath: final?.fullOutputPath } : {}),
				},
			}
		}

		// Process still running — return tail window + handle for bash_control.
		const statusLine = `\n\n[Background process running — call bash_control with handle ${handle} to continue or stop]`

		return {
			content: [{ type: "text", text: `${snapshot.text}${statusLine}` }],
			details: {
				handle,
				exited: false,
				exitCode: null,
				checkin: true,
				reason: null,
				display,
			},
		}
	}

	return {
		name: "bash",
		label: wrapped.label,
		description,
		promptSnippet: wrapped.promptSnippet,
		parameters: backgroundBashSchema,
		renderShell: wrapped.renderShell,
		prepareArguments: wrapped.prepareArguments as
			| ToolDefinition<typeof backgroundBashSchema>["prepareArguments"]
			| undefined,
		executionMode: wrapped.executionMode,
		execute: execute as ToolDefinition<typeof backgroundBashSchema, BackgroundBashToolDetails | undefined>["execute"],
		renderCall: renderBashCall,
		renderResult: renderBashResult,
	}
}

function defaultLocalOps(options?: CreateBackgroundBashToolOptions): BashOperations {
	return createLocalBashOperations({ shellPath: options?.shellPath })
}

kimchi_extensions/bash-background/bash-c.text:
const bashControlSchema = Type.Object({
	handle: Type.String({
		description: "Handle of the background bash process to control (returned by the bash tool).",
	}),
	action: Type.Union([Type.Literal("continue"), Type.Literal("stop")], {
		description:
			"'continue' re-arms the next checkin (optionally extend the deadline first); 'stop' kills the process and returns final output.",
	}),
	extend_seconds: Type.Optional(
		Type.Number({
			description:
				"Only valid with action 'continue'. Pushes the process deadline out by this many seconds before re-arming the checkin. Omit or use 0 to keep the existing deadline.",
		}),
	),
	checkin_interval: Type.Optional(
		Type.Number({
			description:
				"Only valid with action 'continue'. Changes the checkin cadence (seconds) for this and subsequent waits. Raise it (e.g. 60–300) for long-running processes to avoid polling every checkin; this is NOT the deadline — use extend_seconds to move the auto-kill time. Omit to keep the current cadence.",
		}),
	),
})

export interface BashControlDetails extends BashToolDetails {
	display?: ProcessDisplaySnapshot
	/** The handle that was controlled. */
	handle: string
	/** Whether the process has exited. */
	exited: boolean
	/** Process exit code (null until exit / if killed without an exit code). */
	exitCode: number | null
	/** The action taken: "continue" | "stop". */
	action: "continue" | "stop"
	/** True when this result is a mid-run checkin (process still alive). */
	checkin?: boolean
	/** Reason the process stopped, if any ("stop" | "deadline" | "aborted" | …). */
	reason?: string | null
}

function terminalDetails(
	handle: string,
	action: BashControlInput["action"],
	snapshot: FinalSnapshot | TailSnapshot,
	display: ProcessDisplaySnapshot | undefined,
): BashControlDetails {
	return {
		handle,
		action,
		exited: true,
		exitCode: snapshot.exitCode,
		reason: snapshot.reason,
		display,
		...("truncation" in snapshot && snapshot.truncation?.truncated
			? { truncation: snapshot.truncation, fullOutputPath: snapshot.fullOutputPath }
			: {}),
	}
}

export function createBashControlToolDefinition(
	getRegistry = getSessionRegistry,
	/** The emitting extension api — used only for the check-in steer telemetry.
	 *  Optional so test harnesses that construct the tool standalone still work. */
	pi?: ExtensionAPI,
): ToolDefinition<typeof bashControlSchema, BashControlDetails> {
	async function execute(
		_toolCallId: string,
		params: BashControlInput,
		signal: AbortSignal | undefined,
		onUpdate: Parameters<ToolDefinition["execute"]>[3] | undefined,
	): Promise<{
		content: { type: "text"; text: string }[]
		details: BashControlDetails
	}> {
		const { handle, action, extend_seconds, checkin_interval } = params
		if (action === "stop" && checkin_interval !== undefined) {
			return {
				content: [
					{
						type: "text",
						text: "Error: checkin_interval is only valid with action 'continue'.",
					},
				],
				details: { handle, exited: false, exitCode: null, action, reason: "invalid-params" },
			}
		}
		if (checkin_interval !== undefined && (!Number.isFinite(checkin_interval) || checkin_interval <= 0)) {
			return {
				content: [
					{
						type: "text",
						text: `Error: checkin_interval must be a positive number of seconds (got ${checkin_interval}).`,
					},
				],
				details: { handle, exited: false, exitCode: null, action, reason: "invalid-params" },
			}
		}
		const registry = getRegistry()
		if (!registry) {
			return {
				content: [
					{
						type: "text",
						text: "Error: no active bash session registry. Start a background bash command first.",
					},
				],
				details: { handle, exited: true, exitCode: null, action, reason: "no-registry" },
			}
		}

		const entry = registry.getEntry(handle)
		if (!entry) {
			const completed = registry.completedSnapshot(handle)
			if (completed) {
				const { final, display, deadlineSeconds } = completed
				const result = {
					content: [{ type: "text" as const, text: final.content }],
					details: terminalDetails(handle, action, final, display),
				}
				onUpdate?.(result)
				if (action === "continue") throwIfTerminal(final, final.content, deadlineSeconds)
				return result
			}
			return {
				content: [
					{
						type: "text",
						text: `Error: unknown handle '${handle}'. The process may have already exited and been removed.`,
					},
				],
				details: { handle, exited: true, exitCode: null, action, reason: "unknown-handle" },
			}
		}

		// ── stop ────────────────────────────────────────────────────────
		if (action === "stop") {
			await registry.kill(handle)
			const final = registry.finalSnapshot(handle)
			const snapshot = registry.snapshotTail(handle)
			const display = registry.displaySnapshot(handle)
			const finalExitCode = snapshot.exitCode
			await registry.remove(handle).catch(() => {})
			const stoppedOutput = final?.content ?? snapshot.text
			const truncated = final?.truncation?.truncated === true
			return {
				content: [
					{
						type: "text",
						text:
							truncated && final?.fullOutputPath
								? `${stoppedOutput}\n\n[Process stopped${finalExitCode !== null ? `; exit code ${finalExitCode}` : ""}. Output truncated. Full output: ${final.fullOutputPath}]`
								: `${stoppedOutput}\n\n[Process stopped${finalExitCode !== null ? `; exit code ${finalExitCode}` : ""}]`,
					},
				],
				details: {
					...terminalDetails(handle, action, final ?? snapshot, display),
					reason: snapshot.reason ?? "stop",
				},
			}
		}

		// ── continue ────────────────────────────────────────────────────
		// If the process already exited (e.g. between the previous checkin and
		// this call), return the final output immediately.
		if (entry.state !== "running") {
			await registry.whenExited(handle)
			const final = registry.finalSnapshot(handle)
			const snapshot = registry.snapshotTail(handle)
			const display = registry.displaySnapshot(handle)
			const fullOutput = final?.content ?? snapshot.text
			const result = {
				content: [{ type: "text" as const, text: fullOutput }],
				details: terminalDetails(handle, action, final ?? snapshot, display),
			}
			onUpdate?.(result)
			await registry.remove(handle).catch(() => {})
			throwIfTerminal(snapshot, fullOutput, entry.deadlineSeconds)
			return result
		}

		// Optionally extend the deadline BEFORE re-arming, so an imminent
		// deadline auto-kill doesn't fire before the next checkin resolves.
		if (extend_seconds !== undefined && extend_seconds > 0) {
			registry.extend(handle, extend_seconds)
		}

		// Optionally change the checkin cadence for this and subsequent waits.
		// entry.intervalSeconds is read fresh at each re-arm (see below), so the
		// new cadence applies immediately.
		if (checkin_interval !== undefined) {
			registry.setIntervalSeconds(handle, checkin_interval)
		}

		// Turn abort (ESC) must kill the process, same as bash-background-tool.
		const onAbort = () => void registry.kill(handle, "aborted")
		if (signal?.aborted) onAbort()
		else signal?.addEventListener("abort", onAbort, { once: true })

		// Re-arm the next checkin (timer vs process exit race). This blocks
		// until the next checkin OR process exit — naturally pacing the loop
		// without relying on the event loop staying alive. Works in -p mode.
		const intervalSeconds = entry.intervalSeconds
		let snapshot: ReturnType<typeof registry.snapshotTail>
		try {
			snapshot = await awaitCheckin(
				registry,
				handle,
				intervalSeconds,
				onUpdate
					? (display) =>
							onUpdate({
								content: [{ type: "text", text: display.output }],
								details: {
									handle,
									action,
									exited: display.state !== "running",
									exitCode: display.exitCode,
									checkin: display.state === "running",
									reason: display.reason,
									display,
								},
							})
					: undefined,
			)
		} finally {
			signal?.removeEventListener("abort", onAbort)
		}
		const exited = snapshot.state !== "running"
		const display = registry.displaySnapshot(handle)
		if (exited) {
			const final = registry.finalSnapshot(handle)
			const fullOutput = final?.content ?? snapshot.text
			const result = {
				content: [{ type: "text" as const, text: fullOutput }],
				details: terminalDetails(handle, action, final ?? snapshot, display),
			}
			onUpdate?.(result)
			await registry.remove(handle).catch(() => {})
			throwIfTerminal(snapshot, fullOutput, entry.deadlineSeconds)
			return result
		}

		// Process still running — return tail window + handle.
		// This is a steer-equivalent nudge ("come back later") delivered on the
		// blocking tool-result path — emit the fire event here so every check-in
		// is measurable. The 15s wake-up is not a steer message, so
		// emitting in bash-control-extension would miss it.
		if (pi && !isSteerDisabled("bash_control_checkin")) {
			emitSteerFired(pi, "bash_control_checkin", "checkin")
		}
		const statusLine = `\n\n[Background process still running — call bash_control again with handle ${handle} to continue or stop]`

		return {
			content: [{ type: "text", text: `${snapshot.text}${statusLine}` }],
			details: {
				handle,
				exited: false,
				exitCode: null,
				action: "continue",
				checkin: true,
				reason: null,
				display,
			},
		}
	}

	return {
		name: BASH_CONTROL_TOOL_NAME,
		label: "bash_control",
		description: BASH_CONTROL_TOOL_DESCRIPTION,
		parameters: bashControlSchema,
		renderShell: "self",
		renderCall: renderBashCall,
		renderResult: renderBashResult,
		execute: execute as ToolDefinition<typeof bashControlSchema, BashControlDetails>["execute"],
	}
}

