		// NOT process.env passthrough blind spot: daemons want the same env the
		// user's shell would see; process.env is the sanest default here.
		env: process.env,
		detached: true,
		stdio: "ignore",
		windowsHide: true,
	})

bash_background_process_calls.text:
registry.spawn(
			// Use the upstream-injected operations if provided, else the registry
			// will use its default local backend.
			operations,
			command,
			cwd,
			undefined,
			{ intervalSeconds, deadlineMs, toolCallId, description },
		)

ops.exec(command, cwd, {
			onData: (data: Buffer) => {
				if (data.length > 0) entry.lastOutputAt = Date.now()
				entry.totalOutputBytes += data.length
				buffer.append(data)
				accumulator.append(data)
				notifyDisplay(handle)
			},
			signal: controller.signal,
			// No upstream timeout: background mode manages its own deadline.
			timeout: undefined,
			env,
		})

daemon_extension_hooks.text:
pi.on("before_agent_start", (event, ctx: ExtensionContext) => {
		if (ctx.hasUI) return
		if (pi.getFlag?.("ferment-oneshot") === true) return
		if (!isExperimentalFeaturesEnabled()) return
		return { systemPrompt: `${event.systemPrompt}\n\n${LONG_LIVED_SERVICES_CLAUSE}` }
	})

pi.on("session_start", () => {
		// EXPERIMENTAL: tools require --enable-experimental-features. cli.ts
		// already gates registration; this inner check is defense-in-depth
		// for any path that wires the extension directly (subagent sessions,
		// bespoke entry points).
		if (!isExperimentalFeaturesEnabled()) return
		pi.registerTool(createDaemonToolDefinition())
		pi.registerTool(createDaemonControlToolDefinition())
	})

pi.on("session_shutdown", (_event: SessionShutdownEvent, ctx) => {
		if (!ctx.hasUI) return
		try {
			const live = listDaemons(daemonStateDir())
			if (live.length === 0) return
			ctx.ui.notify(formatDaemonNotice(live.length, live[0].record.id), "info")
		} catch (err) {
			// Never let a housekeeping notice break session teardown.
			console.error("daemon shutdown notice failed:", err)
		}
	})

background_extension_hooks.text:
pi.on("session_start", (_event: SessionStartEvent, sessionCtx) => {
		panel?.close()
		panel = undefined
		// Fresh registry per session so handles from a previous session
		// can't be reused, and so a resumed/forked session gets a clean
		// process table.
		const registry = createProcessRegistry()
		setSessionRegistry(registry)

		// Re-register `bash` with the background execution definition.
		// The description is the bash-tool-guard steering text so the
		// tool-selection preference still reaches the system prompt even
		// though our registration wins the tool-name slot.
		const tool = createBackgroundBashToolDefinition(sessionCtx.cwd, {
			registry,
		})
		const toolWithSteering = {
			...tool,
			description: bashToolDescription(),
			// The promptSnippet is the one-line "Execute bash commands..."
			// summary used in the Available tools section. Keep the
			// upstream/wrapped snippet so the system prompt still lists bash.
			promptSnippet: tool.promptSnippet,
		}
		pi.registerTool(toolWithSteering)
	})

pi.on("session_shutdown", async (_event: SessionShutdownEvent) => {
		panel?.close()
		panel = undefined
		const registry = getSessionRegistry()
		if (registry) {
			// Unpublish BEFORE draining: shutdown() kills pending processes,
			// which settles their whenExited promises — and a still-published
			// registry would let bashControlExtension's exit watcher emit an
			// "exited on its own" steer into the closing session.
			setSessionRegistry(undefined)
			await registry.shutdown()
		}
	})
